public const string LANG = Lang::IT;
protected const array ID2DESC = [
0=>['No Skill','Empty skill slot','Empty slot'],
1=>['Sigillo della Guarigione','Sigillo. Ottieni 82...172 Punto[i] Salute. Usando questa abilità avrai -40 di armatura.','Sigillo. Salute conseguita: 82...172. Mentre usi quest\'abilità hai -40 di armatura.'],
2=>['Sigillo della Resurrezione','Sigillo. Fai risorgere un membro della squadra con 100% di Salute e 25% di Energia. Questo Sigillo si ricarica solo ottenendo una Spinta Morale.','Sigillo. Fa risorgere il membro della squadra selezionato (Salute: 100%; Energia: 25%). Questo Sigillo si ricarica solo ottenendo una Spinta Morale.'],
3=>['Sigillo della Cattura','Sigillo. Scegli un\'abilità da un boss morto della tua professione. Il Sigillo della Cattura verrà sostituito permanentemente da quell\'abilità. Se si tratta di un\'abilità d\'élite ottieni 250 P.E. per ogni livello acquisito.','Sigillo. Scegli un\'abilità da un boss morto della tua professione. Il Sigillo della Cattura verrà sostituito permanentemente da quell\'abilità. Se si tratta di un\'abilità d\'élite ottieni 250 P.E. per ogni livello acquisito.'],
5=>['Blocco del Potere','Magia d\'Élite. Se l\'obiettivo nemico ha attivato una magia o un canto, l\'abilità e tutte le altre abilità con lo stesso attributo vengono disattivate per 1...12 secondi e l\'abilità viene interrotta.','Magia d\'Élite. Se l\'obiettivo nemico ha attivato una magia o un canto, l\'abilità e tutte le altre abilità con lo stesso attributo vengono disattivate (1...12 secondi) e l\'abilità viene interrotta.'],
6=>['Mantra della Terra','Posizione. Per 30...90 secondo[i], ogni volta che subirai un danno da terra, questo si ridurrà del 26...50% e otterrai 2 Punti Energia.','Posizione. (Secondi: 30...90) Riduzione danni da terra: 26...50%. Energia conseguita quando subisci danni da terra: 2.'],
7=>['Mantra della Fiamma','Posizione. Per 30...90 secondo[i], ogni volta che subirai un danno da fuoco, questo si ridurrà del 26...50% e otterrai 2 Punti Energia.','Posizione. (Secondi: 30...90) Riduzione danni da fuoco: 26...50%. Energia conseguita quando subisci danni da fuoco: 2.'],
8=>['Mantra della Brina','Posizione. Per 30...90 secondo[i], ogni volta che subirai un danno da freddo, questo si ridurrà del 26...50% e otterrai 2 Punti Energia.','Posizione. (Secondi: 30...90) Riduzione danni da freddo: 26...50%. Energia conseguita quando subisci danni da freddo: 2.'],
9=>['Mantra del Fulmine','Posizione. Per 30...90 secondo[i], ogni volta che subirai un danno da fulmine, questo si ridurrà del 26...50% e otterrai 2 Punti Energia.','Posizione. (Secondi: 30...90) Riduzione danni da fulmine: 26...50%. Energia conseguita quando subisci danni da fulmine: 2.'],
10=>['Anti-Fattura','Posizione. Dura 5...80 secondo[i]; la prossima volta che ti sarà lanciata addosso una fattura, non avrà effetto e chi la lancia subirà 10...46 danno[i].','Posizione. (Secondi: 5...80) La prossima fattura lanciata su di te fallisce e chi l\'ha lanciata subisce 10...46 danno[i].'],
11=>['Distorsione','Posizione. Per 1...5 secondo[i] hai il 75% di possibilità di bloccare gli attacchi. Ogni volta che blocchi un attacco in questo modo, o perdi 2 Punto[i] Energia oppure la Distorsione termina.','Posizione. (Secondi: 1...5) Probabilità di blocco: 75%. Costo del blocco: perdi 2 Punto[i] Energia o Distorsione termina.'],
13=>['Mantra del Recupero','Posizione d\'Élite. Per 5...20 secondi la velocità di ricarica delle magie lanciate da te aumenta di un 33%.','Posizione d\'Élite. (Secondi: 5...20). Incremento velocità di ricarica delle tue magie: 33%.'],
14=>['Mantra della Persistenza','Posizione. Per 5...25 secondo[i] tutte le fatture di Magia Illusoria durano un 10...40% in più.','Posizione. (Secondi: 5...25) Incremento durata fatture di Magia Illusoria da te lanciate: 10...40%.'],
15=>['Mantra delle Iscrizioni','Posizione. Per 5...25 secondo[i] i Sigilli da te attivati mentre ti trovi in questa posizione si ricaricano ad una velocità maggiore del 10...40%.','Posizione. (Secondi: 5...25) Incremento velocità di ricarica dei Sigilli da te attivati mentre sei in questa posizione: 10...40%.'],
16=>['Mantra della Concentrazione','Posizione. Dura 1...38 secondo[i]; la prossima volta che un avversario cercherà di interromperti non potrà farlo.','Posizione. (Secondi: 1...38) La prossima volta che un avversario cercherà di interromperti non potrà farlo.'],
17=>['Mantra della Risoluzione','Posizione. Per 30...90 secondo[i] gli avversari non potranno interromperti, ma per ogni tentativo che faranno, o perderai 10...4 Punto[i] Energia oppure il Mantra della Risoluzione terminerà.','Posizione. (Secondi: 30...90) Previene le interruzioni contro di te. Costo di prevenzione: perdi 10...4 Punto[i] Energia o Mantra della Risoluzione termina.'],
18=>['Mantra dei Sigilli','Posizione. Per 10...40 secondi ottieni +3 di armatura per ogni Sigillo equipaggiato. Ogni volta che utilizzi un Sigillo, ottieni 5...60 Punti Salute.','Posizione. (Secondi: 10...40). Armatura ottenuta per ogni Sigillo: +3. Ottieni 5...60 Punti Salute ogni volta che utilizzi un Sigillo.'],
19=>['Fragilità','Fattura. Per 8...20 secondi l\'obiettivo nemico e i nemici adiacenti subiscono 5...20 danni ogni volta che viene loro inflitta una nuova condizione o se ne liberano.','Fattura. Colpisce con una fattura anche i nemici adiacenti all\'obiettivo (8...20 secondi). Danni inferti ai nemici ogni volta che ogni volta che viene loro inflitta una nuova condizione o se ne liberano: 5...20.'],
21=>['Incantesimo Ispirato','Magia. Rimuovi un incantesimo dall\'obiettivo nemico ed ottieni 3...15 Punto[i] Energia. Per 20 secondi l\'incantesimo rimosso si sostituirà all\'Incantesimo Ispirato.','Magia. Rimuove un incantesimo dall\'obiettivo nemico. Effetto della rimozione: ottieni 3...15 Punto[i] Energia. Questa magia viene rimpiazzata con quell\'incantesimo (20 secondi).'],
22=>['Fattura Ispirata','Magia. Elimini una fattura dall\'obiettivo (un alleato o te stesso) ed ottieni 4...10 Punto[i] Energia. Per 20 secondi, la fattura sottratta si sostituirà alla Fattura Ispirata.','Magia. Rimuove una fattura dall\'obiettivo (un alleato o te stesso). Effetto di rimozione: ottieni 4...10 Punto[i] Energia. Questa magia viene rimpiazzata con quella fattura (20 secondi).'],
23=>['Spina del Potere','Magia. Se l\'obiettivo nemico ha attivato una magia o un canto, lo interrompi e gli infliggi 30...120 danni.','Magia. Interrompe una magia o un canto. Effetto dell\'interruzione: 30...120 danni inferti.'],
24=>['Perdita di Potere','Magia. Se l\'obiettivo nemico ha attivato una magia o un canto, l\'abilità viene interrotta e l\'obiettivo perde 3...17 Punti Energia.','Magia. Interrompe una magia o un canto. Effetto dell\'interruzione: perdita di 3...17 Punti Energia.'],
25=>['Calo di Potere','Magia. Se l\'obiettivo nemico ha attivato una magia o un canto, lo interrompi e ottieni 1...31 Punti Energia.','Magia. Interrompe una magia o un canto. Effetto dell\'interruzione: ottieni 1...31 Punto[i] Energia.'],
26=>['Empatia','Fattura. Per 5...15 secondi, ogni volta che l\'obiettivo nemico attacca subisce 10...55 danni e infligge 1...15 danni in meno.','Fattura. (Secondi: 5...15). Riduzione dei danni causati dagli attacchi dell\'obiettivo nemico: 1...15; danni subiti dall\'obiettivo nemico ad ogni attacco: 10...55.'],
27=>['Delusioni Infrante','Magia. Rimuovi una fattura da Ipnotizzatore dal bersaglio nemico. Se rimuovi una fattura, il bersaglio subisce 15...75 danni e tutti i nemici adiacenti subiscono il 75% di quei danni.','Magia. Rimuove una fattura da Ipnotizzatore dal bersaglio nemico. Effetto della rimozione: 15...75 danni al bersaglio e il 75% di quei danni a tutti i nemici adiacenti.'],
28=>['Ritorno di Fiamma','Fattura. Dura 10 secondi; ogni volta che l\'obiettivo nemico compie una magia, subisce 35...140 danno[i].','Fattura. (Secondi: 10) Danni all\'obiettivo nemico ogni volta che lancia una magia: 35...140.'],
29=>['Blackout','Abilità. Dura 2...8 secondo[i]; tutte le abilità dell\'obiettivo nemico toccato vengono disattivate e tutte le tue abilità sono sospese per 5 secondi.','Abilità a Tocco. (Secondi: 2...8) Disattiva le abilità. Le tue abilità vengono disattivate (5 secondi).'],
30=>['Diversione','Fattura. Dura 6 secondi; la prossima volta che l\'obiettivo nemico userà un\'abilità, il suo tempo di ricarica aumenterà di 10...56 secondo[i].','Fattura. (Secondi: 6) Tempo di ricarica della prossima abilità dell\'obiettivo nemico: +10...56 secondo[i].'],
31=>['Evoca Fantasma','Fattura. Per 4...18 secondo[i] l\'obiettivo nemico subirà una Degenerazione della Salute di -5.','Fattura. (Secondi: 4...18) Degenerazione Salute: -5.'],
32=>['Illusione di Debolezza','Incantesimo. Perdi 50...240 Punto[i] Salute. L\'Illusione di Debolezza termina se il danno riduce la tua Salute al di sotto del 25% della Salute massima. Al termine ottieni 50...240 Punto[i] Salute.','Incantesimo. Salute persa: 50...240. Effetto al termine: ottieni 50...240 Punto[i] Salute. Termina se il danno fa calare la tua Salute a meno del 25% di quella massima.'],
33=>['Armamento Illusorio','Incantesimo d\'Élite. Per 30 secondi i tuoi attacchi ravvicinati non colpiscono e non vanno a vuoto. L\'Armamento Illusorio infligge 20...60 danni agli obiettivi per ogni attacco ravvicinato. Ottieni +5 di armatura per ogni abilità di Magia Illusoria equipaggiata.','Incantesimo d\'Élite. (Secondi: 30). Infligge 20...60 danni ai nemici anziché altri danni o effetti provocati dagli attacchi ravvicinati. Armatura ottenuta per ogni abilità di Magia Illusoria equipaggiata: +5. Gli attacchi ravvicinati non colpiscono e non vanno a vuoto.'],
34=>['Aspetto Compassionevole','Incantesimo. Dura 4...10 secondo[i]; ogni volta che l\'obiettivo (un alleato o te stesso) viene colpito da un attacco ravvicinato, tutti i nemici adiacenti perdono tutta l\'adrenalina e 3 Punti Energia.','Incantesimo. (Secondi: 4...10) Tutti i nemici adiacenti perdono tutta l\'adrenalina e 3 Punti Energia ogni volta che l\'obiettivo (un alleato o te stesso) viene colpito da un attacco ravvicinato.'],
35=>['Ignoranza','Fattura. Per 8...20 secondo[i] l\'obiettivo nemico non può usare i Sigilli.','Fattura. (Secondi: 8...20) L\'obiettivo nemico non può usare Sigilli.'],
36=>['Enigma Arcano','Fattura. Per 5...15 secondi il tempo di lancio per le magie dell\'obiettivo nemico e di tutti i nemici adiacenti raddoppia. Al termine della fattura, ottieni 1...7 Punti Energia.','Fattura. Colpisce con una fattura anche i nemici nei dintorni dell\'obiettivo (secondi:5...15). Raddoppia il tempo di lancio delle magie. Effetto al termine: ottieni 1...7 Punti Energia.'],
37=>['Illusione di Velocità','Incantesimo. Per 5...11 secondo[i] la Storpiatura viene rimossa e la tua velocità aumenta del 33%. Quando gli effetti dell\'Illusione di Velocità svaniscono, diventi storpio per 3 secondo[i].','Incantesimo. (Secondo[i]: 5...11) Aumento della tua velocità di movimento: 33%. Effetto iniziale: rimozione della Storpiatura. Effetto al termine: Storpiatura (3 secondo[i]).'],
38=>['Incanalamento','Incantesimo. Dura 8...56 secondo[i]; ogni volta che compi una magia, ottieni 1 Punto Energia per ogni nemico presente nell\'area.','Incantesimo. (Secondi: 8...56) Ottieni 1 Punto Energia per ogni nemico nell\'area ogni volta che lanci una magia.'],
39=>['Flusso di Energia','Magia d\'Élite. Il bersaglio nemico perde 1...10 Energia. Per ogni punto perso di Energia, l\'avversario subisce 7 danni e tutti i nemici vicini subiscono il 75% di quei danni.','Magia d\'Élite. Provoca perdita di Energia pari a 1...10. Per ogni punto perso di Energia, infligge 7 danni al bersaglio e il 75% di quei danni a tutti i nemici vicini.'],
40=>['Banchetto d\'Etere','Magia. L\'obiettivo nemico perde 3 Punti Energia e tu vieni curato di 20...65 punto[i] per ogni Punto Energia perduto dal nemico.','Magia. Perdita Energia: 3. Salute conseguita per ogni Punto Energia perso: 20...65.'],
41=>['Signore dell\'Etere','Fattura. Perdi tutta l\'Energia. Per 5...10 secondo[i], l\'obiettivo nemico subisce -1...3 punto[i] di Degenerazione dell\'Energia e tu benefici di +1...3 punto[i] di Rigenerazione dell\'Energia.','Fattura. Perdi tutta l\'Energia. Degenerazione Energia dell\'obiettivo nemico: -1...3. Rigenerazione tua Energia: +1...3 (5...10 secondo[i]).'],
42=>['Energia Bruciata','Magia. L\'obiettivo nemico perde 1...10 Punto[i] Energia e subisce 9 danno[i] per ogni Punto Energia perduto.','Magia. Perdita Energia: 1...10. Danni inferti per ogni Punto Energia perso: 9.'],
43=>['Goffaggine','Fattura. Per 4 secondo[i], l\'obiettivo e i nemici adiacenti sono colpiti da Goffaggine. La prossima volta che ogni nemico attacca, l\'attacco viene interrotto e quel nemico subisce 10...80 danno[i].','Fattura. (Secondi: 4) Infligge fattura anche ai nemici adiacenti. Interrompe il prossimo attacco. Effetto dell\'interruzione: assesta 10...80 danno[i].'],
44=>['Dolore Fantasma','Fattura. Per 10 secondi, l\'obiettivo nemico subisce di -1...4 punto[i] di Degenerazione della Salute. Quando il Dolore Fantasma termina, il nemico subisce una Ferita Profonda che fa diminuire la sua Salute massima del 20% per 5...20 secondo[i].','Fattura. (Secondi: 10) Degenerazione Salute: -1...4. Effetto al termine: infliggi Ferita Profonda (5...20 secondo[i]).'],
45=>['Fardello Etereo','Fattura. Per 6...12 secondi, i movimenti dell\'obiettivo nemico rallentano del 50%. Quando il Fardello Etereo termina, ottieni 10...18 Punto[i] Energia.','Fattura. (Secondi: 6...12) Rallentamento velocità di movimento dell\'obiettivo nemico: 50%. Effetto al termine: ottieni 10...18 Punto[i] Energia.'],
46=>['Colpa','Fattura. Dura 6 secondo[i]; la prossima volta che l\'obiettivo nemico tenta di lanciare una magia su un nemico, fallisce e tu gli sottrai fino a 5...14 Punto[i] Energia.','Fattura. (Secondi: 6) La prossima magia dell\'obiettivo nemico fallisce e sottrai 5...14 Punto[i] Energia Ha effetto solo se la magia di questo nemico è diretta contro uno dei tuoi alleati.'],
47=>['Inettitudine','Fattura d\'Élite. Per 4 secondi, la prossima volta che l\'obiettivo nemico o i nemici adiacenti attaccano, subiscono 30...135 danni e vengono colpiti da Accecamento per 10 secondi.','Fattura d\'Élite. (Secondi: 4). Colpisce con fattura anche i nemici adiacenti all\'obiettivo. Danni inferti: 30...135. Infligge Accecamento (10 secondi). Nessun effetto se il nemico colpito da fattura non attacca.'],
48=>['Spirito del Fallimento','Fattura. Per 30 secondi, l\'obiettivo nemico ha il 25% di probabilità di mancare il bersaglio quando attacca; tu ottieni 1...3 Punto[i] Energia per ogni suo colpo andato a vuoto.','Fattura. (Secondi: 30) Probabilità che l\'obiettivo nemico manchi il bersaglio: 25%. Ottieni 1...3 Punto[i] Energia ogni volta che questo nemico manca il bersaglio.'],
49=>['Relitto Mentale','Fattura. Per 5...40 secondi, ogni volta che il nemico viene colpito da una qualsiasi delle tue abilità dell\'Ipnotizzatore che non rappresenta una fattura perde 1 Punto Energia e subisce 5...25 danni per ogni Punto Energia perso. Se l\'Energia dell\'obiettivo nemico scende a 0, il Relitto Mentale termina e il nemico subisce 15...100 danni.','Fattura. (Secondi: 5...40). Provoca la perdita di 1 Punto Energia ogni volta che il nemico viene colpito dalle tue abilità dell\'Ipnotizzatore che non rappresentano una fattura. Infligge 5...25 danni per ogni Punto Energia perso. Se l\'Energia dell\'obiettivo nemico scende a 0, questi subisce 15...100 danni e il Relitto Mentale termina.'],
50=>['Preoccupazione del Fannullone','Fattura. Dopo 3 secondi il bersaglio nemico subisce 20...100 danni e tutti i nemici adiacenti subiscono il 75% di quei danni. Se il bersaglio riesce a utilizzare un\'abilità, Wastrel\'s Worry termina prematuramente e non infligge danni.','Fattura. (3 secondi) Fine dell\'effetto: provoca 20...100 danni al bersaglio e il 75% di quei danni ai nemici adiacenti. Nessun effetto; termina prima se il bersaglio usa un\'abilità.'],
51=>['Vergogna','Fattura. Dura 6 secondo[i]; la prossima volta che l\'obiettivo nemico tenta di lanciare una magia su un alleato, fallisce e tu gli sottrai fino a 5...14 Punto[i] Energia.','Fattura. (Secondi: 6) La prossima magia dell\'obiettivo nemico fallisce e sottrai 5...14 Punto[i] Energia Ha effetto solo se la magia di questo nemico era diretta contro uno dei suoi alleati.'],
52=>['Panico','Fattura d\'Élite. Per 1...10 secondi l\'obiettivo nemico e tutti i nemici nei dintorni vengono colpiti da Panico. Quando un nemico colpito da Panico utilizza un\'abilità, tutti gli altri nemici nei dintorni vengono interrotti.','Fattura d\'Élite. Colpisce con una fattura anche i nemici vicini all\'obiettivo (1...10 secondi). Interrompe tutti i nemici nei dintorni ogni volta che un nemico colpito da fattura riesce ad attivare un\'abilità.'],
53=>['Emicrania','Fattura d\'Élite. Per 5...20 secondi l\'obiettivo nemico subisce una Degenerazione Salute di -1...8 e il tempo richiesto per l\'attivazione delle sue abilità aumenta di un 100%.','Fattura d\'Élite. (Secondi: 5...20). Degenerazione Salute causata: -1...8. Raddoppia il tempo di attivazione delle abilità.'],
54=>['Angoscia Paralizzante','Fattura d\'Élite. Per 5...20 secondi la velocità di movimento e di attacco dell\'obiettivo diminuisce di un 50% e l\'obiettivo subisce una Degenerazione Salute di -1...8.','Fattura d\'Élite. (Secondi: 5...20). Rallentamento velocità di movimento e attacco dell\'obiettivo nemico: 50%. Degenerazione Salute subita: -1...8.'],
55=>['Sogni Febbrili','Fattura d\'Élite. Per 10...25 secondo[i], ogni volta che l\'obiettivo nemico subisce una nuova condizione, tutti i nemici nell\'area risentono della stessa condizione e se quel nemico è affetto da due o più condizioni subisce Stordimento per 1...3 secondo[i].','Fattura d\'Élite. (Secondi: 10...25) I nemici nell\'area ricevono le stesse condizioni di cui è affetto l\'obiettivo nemico. Condizione inflitta all\'obiettivo nemico se è affetto già da due o più condizioni: Stordimento (1...3 secondo[i]).'],
56=>['Immagini Rassicuranti','Fattura. Per 8...20 secondi l\'obiettivo nemico e tutti i nemici adiacenti non possono ottenere adrenalina.','Fattura. (Secondi: 8...20). Colpisce con una fattura anche i nemici adiacenti all\'obiettivo, che non possono ottenere Adrenalina.'],
57=>['Grido di Frustrazione','Magia. Se il bersaglio nemico sta usando un\'abilità, egli e tutti i nemici nell\'area vengono interrotti. Il bersaglio subisce 15...75 danni e i nemici nell\'area subiscono il 75% di quei danni.','Magia. Se il bersaglio nemico sta usando un\'abilità, egli e tutti i nemici nell\'area vengono interrotti. Il bersaglio subisce 15...75 danni e i nemici nell\'area subiscono il 75% di quei danni.'],
58=>['Sigillo della Mezzanotte','Sigillo d\'Élite. Tu e l\'obiettivo nemico toccato diventate Ciechi per 15 secondi.','Sigillo d\'Élite a Tocco. (Secondi: 15) Condizione inflitta: Accecamento. Sei colpito da Accecamento (15 secondi).'],
59=>['Sigillo della Stanchezza','Sigillo. L\'obiettivo nemico e tutti i nemici nei dintorni perdono 3...8 Punti Energia e soffrono di Debolezza per 1...12 secondi.','Sigillo. Colpisce anche i nemici nelle vicinanze dell\'obiettivo. Causa la perdita di 3...8 Punti Energia e infligge Debolezza (1...12 secondi).'],
61=>['Sigillo della Sanguisuga','Sigillo. Interrompe l\'azione dell\'obiettivo nemico. Se si tratta di una magia, ottieni 3...15 Punto[i] Energia.','Sigillo. Interrompe un\'azione. Effetto dell\'interruzione: ottieni 3...15 Punto[i] Energia se l\'azione era una magia.'],
62=>['Sigillo dell\'Umiltà','Sigillo. Disattiva l\'abilità d\'élite dell\'obiettivo nemico per 1...16 secondo[i]. Le tue abilità che non appartengono alla classe dell\'Ipnotizzatore vengono disattivate per 4 secondo[i].','Sigillo. Disattiva le abilità d\'élite (secondi: 1...16). Le tue abilità non da Ipnotizzatore vengono disattivate (4 secondo[i]).'],
63=>['Sigillo della Pietra di Volta','Sigillo d\'Élite. Ricarica tutti i tuoi Sigilli tranne il Sigillo della Pietra di Volta. Per 20 secondi, le prossime 0...6 volte in cui utilizzi un Sigillo contro un nemico tutti i nemici adiacenti subiscono 15...60 danni e vengono interrotti.','Sigillo d\'Élite. (Secondi: 20) I tuoi prossimi 0...6 sigilli interrompono l\'azione dell\'obiettivo e infliggono 15...60 danni ai nemici adiacenti al tuo obiettivo. Effetto iniziale: ricarica tutti i tuoi Sigilli.'],
65=>['Mimica Arcana','Magia. Per 20 secondi la Mimica Arcana si trasforma nell\'abilità d\'élite dell\'alleato selezionato (Forme escluse).','Magia. Quest\'abilità si trasforma nell\'abilità d\'élite dell\'obiettivo alleato (20 secondi). Impossibile selezionare se stessi. L\'abilità non può essere una Forma.'],
66=>['Catene Spirituali','Fattura. Per 5...20 secondo[i], l\'obiettivo nemico perde 5 Punti Energia ogni volta che attacca.','Fattura. (Secondi: 5...20) Energia persa dall\'obiettivo nemico ogni volta che attacca: 5.'],
67=>['Spezza Fattura','Magia. Elimini una fattura dall\'obiettivo (un alleato o te stesso) e infliggi 30...120 danno[i] ai nemici nei dintorni.','Magia. Rimuove una fattura dall\'obiettivo (un alleato o te stesso). Effetto della rimozione: 30...120 danno[i] ai nemici vicini a questo alleato.'],
68=>['Prosciuga Incantesimo','Magia. Elimini un incantesimo dall\'obiettivo nemico e ottieni 8...17 Punto[i] Energia e 40...120 Punto[i] Salute.','Magia. Rimuove un incantesimo dall\'obiettivo nemico. Effetto della rimozione: ottieni 8...17 Punto[i] Energia e 40...120 di Salute.'],
69=>['Rompi Incantesimo','Magia. Elimini un incantesimo dall\'obiettivo nemico e gli infliggi 14...100 danno[i].','Magia. Rimuove un incantesimo dall\'obiettivo nemico. Effetto della rimozione: assesta 14...100 danno[i].'],
72=>['Resistenza Elementale','Posizione. Per 30...90 secondo[i] ottieni +40 punti di armatura contro i danni elementali, ma perdi 24...12 punto[i] di armatura contro i danni fisici.','Posizione. (Secondi: 30...90) Armatura contro il danno elementale: +40. Hai -24...12 di armatura contro il danno fisico.'],
73=>['Resistenza Fisica','Posizione. Per 30...90 secondo[i] ottieni +40 punti di armatura contro i danni fisici, ma perdi 24...12 punto[i] di armatura contro i danni elementali.','Posizione. (Secondi: 30...90) Armatura contro il danno fisico: +40. Hai -24...12 di armatura contro il danno elementale.'],
74=>['Eco','Incantesimo d\'Élite. Dura 30 secondo[i]; l\'Eco viene sostituita dall\'abilità successiva da te utilizzata e resta disponibile per 30 secondi.','Incantesimo d\'Élite. (Secondi: 30) L\'Eco si trasforma nella prossima abilità da te usata (30 secondi).'],
75=>['Eco Arcana','Incantesimo. Se nel giro di 20 secondo[i] lanci una magia, l\'Eco Arcana viene sostituita da quella magia per 20 secondi. L\'Eco Arcana termina prematuramente se utilizzi un\'abilità non magica.','Incantesimo. (Secondi: 20) Eco Arcana si trasforma nella prossima magia da te usata (20 secondi). Questo incantesimo termina se usi un\'abilità che non è una magia.'],
76=>['Fardello Immaginario','Fattura. Per 8...20 secondi la velocità di movimento dell\'obiettivo nemico rallenta di un 50%.','Fattura. (Secondi: 8...20). La velocità di movimento dell\'obiettivo nemico rallenta di un 50%.'],
77=>['Tempesta di Caos','Magia. Crea un Tempesta di Caos in corrispondenza dell\'obiettivo nemico che dura almeno 10 secondi. I nemici adiacenti subiscono 5...25 danni e perdono 0...2 Punti Energia al secondo.','Magia. Infligge 5...25 danni e provoca la perdita di 0...2 Punti Energia al secondo (10 secondi). Colpisce i nemici adiacenti alla posizione iniziale dell\'obiettivo.'],
78=>['Epidemia','Magia. Diffondi tutte le condizioni negative, con le loro durate residue, dall\'obiettivo nemico a tutti i nemici a lui adiacenti.','Magia. Le condizioni sull\'obiettivo nemico sono trasferite a quelli adiacenti.'],
79=>['Risucchio Energia','Magia d\'Élite. L\'obiettivo nemico perde 2...9 Punto[i] Energia e tu ottieni 3 Punti Energia per ogni Punto Energia perduto dal nemico.','Magia d\'Élite. Perdita Energia: 2...9. Ottieni 3 Punti Energia per ogni Punto Energia perso.'],
80=>['Fonte di Energia','Magia. L\'obiettivo nemico perde 4...7 Punto[i] Energia e tu ottieni 2 Punti Energia per ogni Punto Energia perduto dal nemico.','Magia. Perdita Energia: 4...7. Ottieni 2 Punti Energia per ogni Punto Energia perso.'],
81=>['Furto Arcano','Magia. Dura 5...35 secondo[i]; una magia a caso dell\'obiettivo nemico viene disattivata e si sostituisce al Furto Arcano.','Magia. (Secondi: 5...35) Disattiva una magia a caso. Questa abilità si trasforma in quella magia.'],
82=>['Mantra del Ricordo','Incantesimo d\'Élite. Dura 20 secondo[i]; non ti offre alcun beneficio, ma quando termina ottieni 10...25 Punto[i] Energia.','Incantesimo d\'Élite. (Secondi: 20) Effetto al termine: ottieni 10...25 Punto[i] Energia.'],
83=>['Anima Orrore d\'Ossa','Magia. Utilizza il cadavere più vicino per animare un Orrore d\'Ossa di livello 1...17.','Magia. Crea un Orrore d\'Ossa di livello 1...17. Utilizza un cadavere sfruttabile.'],
84=>['Anima Demone d\'Ossa','Magia. Utilizza il cadavere più vicino per animare un Demone d\'Ossa di livello 1...17. I Demoni d\'Ossa possono attaccare a distanza.','Magia. Crea un Demone d\'Ossa di livello 1...17 che può attaccare dalla distanza. Utilizza un cadavere sfruttabile.'],
85=>['Anima Sgherri d\'Ossa','Magia. Utilizza il cadavere più vicino per animare due Sgherri d\'Ossa di livello 0...12.','Magia. Crea 2 Orrori d\'Ossa di livello 0...12. Utilizza un cadavere sfruttabile.'],
86=>['Equilibrio di Grenth','Magia d\'Élite. Se la Salute dell\'obiettivo nemico è superiore alla tua, otterrai la metà della differenza (nei limiti della Salute massima) e quel nemico perderà la stessa quantità. Se questo nemico ha meno Salute di te perderai Salute pari alla metà della differenza e il nemico ne otterrà la stessa quantità.','Magia d\'Élite. Ottieni Salute pari alla metà della differenza tra la tua e quella dell\'obiettivo e questo nemico ne perde la stessa quantità. Se questo nemico ha meno Salute di te perdi Salute pari alla metà della differenza e lui ne ottiene la stessa quantità.'],
87=>['Sguardo di Verata','Magia. Se il bersaglio non morto rianimato ha un padrone, il suo legame con esso si spezza, scatenando la sua ostilità contro tutte le altre creature. Se non ha padrone, lo divieni tu, e lo curi di 60...80 (50% di probabilità di fallire con Magia della Morte 4 o inferiore).','Magia. Priva il bersaglio non morto del suo padrone. Se ne è già privo, tu diventi il suo padrone e lo curi di 60...80. 50% di probabilità di fallire se non si possiede almeno 5 in Magia della Morte.'],
88=>['Aura di Verata','Incantesimo. Tutti i morti viventi ostili animati presenti nell\'area si legano a te. L\'Aura di Verata si esaurisce dopo 120...300 secondo[i] facendoti perdere il legame con tutti i morti viventi (50% di probabilità di fallimento usando la Magia della Morte di grado 4 o inferiore).','Incantesimo. (Secondi: 120...300) Diventi padrone di tutti i morti viventi ostili nell\'area. Effetto al termine: i tuoi morti viventi restano senza padrone. Probabilità di fallimento se il grado di Magia della Morte è inferiore a 5: 50%.'],
89=>['Brivido Mortale','Magia. L\'obiettivo nemico subisce 5...50 danno[i] da freddo. Se la Salute del nemico è superiore al 50%, gli infliggi un danno da ombra aggiuntivo di 5...50.','Magia. Danni da freddo inferti: 5...50. Assesta 5...50 danno[i] in più se la Salute dell\'obiettivo nemico era superiore al 50%.'],
90=>['Sacrificio di Verata','Magia. Per 5...10 secondo[i] i morti viventi tuoi alleati ottengono una Rigenerazione della Salute di +10. Tutte le condizioni vengono rimosse da questi alleati e trasferite su di te. Se questa magia va a segno e stai controllando 3 sgherri o meno, il Sacrificio di Verata si ricarica all\'istante.','Magia. (Secondi: 5...10) Rigenerazione Salute di 10 morto[i] vivente[i] alleato[i]: +10. Si ricarica all\'istante se hai il controllo di 3 morti viventi o meno. Trasferisci tutte le condizioni da questi morti viventi a te stesso.'],
91=>['Pozzo del Potere','Pozzo d\'Élite. Sfrutta il cadavere più vicino o sacrifica il 66% della tua salute per creare un Pozzo del Potere in quella posizione. Per 10...30 secondo/i, gli alleati all\'interno dell\'area del Pozzo del Potere ricevono +1...6 rigenerazione della salute e +2 rigenerazione dell\'energia.','Pozzo d\'Élite. (10...30 secondo/i). Gli alleati in questo Pozzo hanno +1...6 rigenerazione della Salute e +2 rigenerazione dell\'Energia. Utilizza un cadavere fresco o sacrifica il 66% della salute.'],
92=>['Pozzo di Sangue','Pozzo. Sfrutta il cadavere più vicino o sacrifica il 66% della tua salute per creare un Pozzo di Sangue alla sua posizione. Per 8...20 secondo/i, gli alleati in quell\'area ricevono +1...6 rigenerazione della salute.','Pozzo. (8...20 secondo/i). Gli alleati in questo Pozzo hanno +1...6 rigenerazione della Salute. Utilizza un cadavere fresco o sacrifica il 66% della salute.'],
93=>['Pozzo delle Sofferenze','Pozzo. Sfrutta il cadavere più vicino o sacrifica il 66% della tua salute per creare un Pozzo delle Sofferenze alla sua posizione. Per 10...30 secondo/i, i nemici in quell\'area soffrono -1...6 degenerazione della salute.','Pozzo. (10...30 secondo/i). I nemici in questo Pozzo hanno -1...6 degenerazione della Salute. Utilizza un cadavere fresco o sacrifica il 66% della Salute.'],
94=>['Pozzo del Profano','Pozzo. Sfrutta il cadavere più vicino o sacrifica il 66% della tua salute per creare un Pozzo del Profano alla sua posizione. Per 8...20 secondo/i, i nemici in quell\'area vengono privati di tutti gli incantesimi e non possono diventare i bersagli di ulteriori incantesimi (50% di probabilità di fallire con Magia della Morte 4 o inferiore).','Pozzo. (8...20 secondo/i). I nemici in questo Pozzo perdono tutti gli incantesimi e non possono diventare bersaglio di nuovi incantesimi. Utilizza un cadavere fresco o sacrifica il 66% della Salute. Probabilità di fallimento del 50% se non si possiede almeno 5 in Magia della Morte).'],
95=>['Esplosione Putrida','Magia. Il cadavere più vicino al tuo obiettivo esplode, sprigionando un\'onda d\'urto che infligge 24...120 danno[i] a tutti i nemici nei dintorni.','Magia. Fa esplodere un cadavere assestando 24...120 danno[i] ai nemici vicini ad esso. Utilizza un cadavere sfruttabile.'],
96=>['Banchetto dell\'Anima','Magia. Utilizza il cadavere più vicino per ottenere 50...280 Punto[i] Salute.','Magia. Salute conseguita: 50...280. Utilizza un cadavere sfruttabile.'],
97=>['Attraversamento Necrotico','Magia. Sfrutta un cadavere a caso o sacrifica il 30...20% di Salute per teletrasportarti nel punto in cui si trova il bersaglio nemico. Ti ammali per 6 secondi e tutti i nemici vicini vengono avvelenati per 5...20 secondo/i.','Magia. Sfrutta un cadavere a caso o sacrifica il 30...20% di Salute per teletrasportarti nel punto in cui si trova il bersaglio nemico. Ti ammali per 6 secondi e tutti i nemici vicini vengono avvelenati per 5...20 secondo/i.'],
98=>['Consuma Cadavere','Magia. Sfrutta un cadavere qualsiasi per teletrasportarti nella posizione corrispondente ed ottenere 25...100 Punto[i] Salute e 5...20 Punto[i] Energia.','Magia. Ti teletrasporti nella posizione di un cadavere. Salute: 25...100. Energia: 5...20. Utilizza un cadavere sfruttabile.'],
99=>['Legame Parassitario','Fattura. Per 20 secondi, l\'obiettivo nemico subisce -1 punto di Degenerazione della Salute. Quando il Legame Parassitario termina, vieni curato di 30...120 punto[i].','Fattura. (Secondi: 20) Degenerazione Salute: -1. Effetto al termine: vieni curato di 30...120 Punti Salute.'],
100=>['Schegge dell\'Anima','Fattura. Dura 30 secondi; l\'obiettivo nemico subisce 15...30 danno[i] se viene colto da un incantesimo o da una fattura.','Fattura. (Secondi: 30) Assesta 15...30 danno[i] quando l\'obiettivo nemico viene colto da un incantesimo o da una fattura.'],
101=>['Punte','Fattura. Dura 30 secondi; l\'obiettivo nemico subisce 4...16 danno[i] se viene colpito da danni fisici.','Fattura. (Secondi: 30) Danni all\'obiettivo nemico ogni volta che riceve danni fisici: 4...16.'],
102=>['Colpo dell\'Ombra','Magia. L\'obiettivo nemico subisce 12...48 danno[i] da ombra. Se la sua Salute è superiore al 50%, gli sottrarrai fino a 12...48 Punto[i] Salute.','Magia. Danni inferti: 12...48. Sottrai fino a 12...48 Punto[i] Salute se la Salute di questo nemico era superiore al 50%.'],
103=>['Prezzo del Fallimento','Fattura. Per 30 secondi, l\'obiettivo nemico ha il 25% di probabilità di sbagliare gli attacchi e subisce 1...46 danno[i] ogni volta che manca l\'obiettivo.','Fattura. (Secondi: 30) Probabilità di mancare il bersaglio: 25%. L\'obiettivo nemico subisce 1...46 danno[i] ogni volta che manca il bersaglio.'],
104=>['Nova della Morte','Incantesimo. Per 30 secondi, se l\'obiettivo alleato muore, tutti i nemici adiacenti subiscono 26...100 danno[i] e vengono avvelenati per 15 secondo[i].','Incantesimo. (Secondi: 30) Danni inferti: 26...100. Condizione inflitta ai nemici adiacenti se l\'obiettivo alleato muore: Veleno (15 secondo[i]).'],
105=>['Sciame Mortale','Magia. Lo Sciame Mortale vola lentamente e infligge 30...90 danno[i] da freddo ad un massimo di tre obiettivi nell\'area.','Magia. Sciame Mortale vola lentamente e assesta 30...90 danno[i] da freddo. Colpisce altri 2 nemici nell\'area.'],
106=>['Carne Putrida','Magia. L\'obiettivo di carne colpito si ammala per 10...25 secondo[i] perdendo lentamente Salute.','Magia. Condizione inflitta: Malattia (10...25 secondo[i]).'],
107=>['Virulenza','Magia d\'Élite. Se l\'obiettivo nemico risente già di una condizione, sarà colpito anche da Malattia, Veleno e Debolezza per 3...15 secondo[i].','Magia d\'Élite. Condizioni inflitte: Malattia, Veleno e Debolezza (3...15 secondo[i]). Ha effetto solo se questo nemico già soffriva di una condizione.'],
108=>['Sofferenza','Fattura. Per 6...30 secondo[i] l\'obiettivo nemico e tutti i nemici nei dintorni subiscono una Degenerazione della Salute di -0...3.','Fattura. Infligge fattura anche ai nemici vicini all\'obiettivo (6...30 secondo[i]). Degenerazione loro Salute: -0...3.'],
109=>['Sifone Vitale','Fattura. Per 12...24 secondo[i], l\'obiettivo nemico subisce una Degenerazione della Salute di -1...3 e tu benefici di una Rigenerazione della Salute di +1...3.','Fattura. (Secondi: 12...24) Degenerazione Salute dell\'obiettivo nemico: -1...3. Rigenerazione tua Salute: +1...3.'],
110=>['Empio Banchetto','Magia. Sottrai fino a 10...65 Punto[i] Salute ad un massimo di 1...4 nemico[i] nell\'area.','Magia. Salute sottratta a 1...4 nemico[i] nell\'area intorno a te: 10...65.'],
111=>['Risveglio del Sangue','Incantesimo. Dura 20...44 secondo[i]; ottieni +2 punti per la Magia del Sangue e +2 punti per le Maledizioni, ma ogni volta che sacrifichi della Salute, ne sacrifichi il 50% in più del normale.','Incantesimo. (Secondi: 20...44) Hai +2 di Magia del Sangue e Maledizioni. Sacrifichi un 50% di Salute in più del normale.'],
112=>['Dissacra Incantesimi','Magia. L\'obiettivo nemico e tutti i nemici nei dintorni subiscono 6...60 danno[i] da ombra e 4...20 danno[i] da ombra per ogni incantesimo presente su di loro.','Magia. Danni all\'obiettivo e ai nemici nei dintorni: 6...60. Assesta 4...20 danno[i] in più per ogni incantesimo presente su di loro.'],
113=>['Carne Infetta','Incantesimo d\'Élite. Per 20...44 secondo/i, gli alleati nell\'area diventano immuni alle malattie, e chiunque li colpisca in mischia si ammala per 3...15 secondo/i.','Incantesimo d\'Élite. (20...44 secondo/i) I nemici che colpiscono gli alleati nell\'area con attacchi in mischia si ammalano (3...15 secondo/i); questo alleato è immune alle malattie.'],
114=>['Aura del Lich','Incantesimo d\'Élite. Tutti i cadaveri a portata d\'orecchio vengono sfruttati animando un Orrore d\'Ossa di livello 1...17 più un altro per ogni cadavere così sfruttato. Per 5...45 secondo[i], il grado di Magia della Morte aumenta di +1.','Incantesimo d\'Élite. Sfrutta tutti i cadaveri a portata d\'orecchio. Anima un Orrore d\'Ossa di livello 1...17 più un altro per ogni cadavere sfruttato. Incremento Magia della Morte: +1 (5...45 secondo[i]).'],
115=>['Rinnovamento del Sangue','Incantesimo. Per 7 secondo[i], ottieni +3...6 di Rigenerazione della Salute. Al termine dell\'effetto di Rinnovamento del Sangue, ottieni 40...190 Punto[i] Salute.','Incantesimo. (Secondi: 7). Rigenerazione Salute: +3...6. Effetto al termine: cura 40...190 Punto[i] Salute.'],
116=>['Aura Oscura','Incantesimo. Per 30 secondi, ogni volta che l\'obiettivo (un alleato o te stesso) sacrifica della Salute, l\'Aura Oscura infligge 5...50 danno[i] da ombra ai nemici adiacenti e tu perdi 5...20 Punto[i] Salute.','Incantesimo. (Secondi: 30) Danni ai nemici adiacenti ogni volta che l\'obiettivo (un alleato o te stesso) sacrifica Salute: 5...50. Costo del danno: perdi 5...20 Punto[i] Salute.'],
117=>['Indebolimento','Magia. L\'obiettivo è colpito dalla Debolezza per 10...30 secondo[i].','Magia. Condizione inflitta: Debolezza (10...30 secondo[i]).'],
118=>['Indebolimento del Sangue','Magia. L\'obiettivo nemico e tutti quelli nei dintorni soffrono di Debolezza per 5...20 secondo[i].','Magia. Condizione inflitta a questo nemico e a quelli nei dintorni: Debolezza (5...20 secondo[i]).'],
119=>['Sangue è Potere','Incantesimo d\'Élite. Per 10 secondi, l\'obiettivo alleato ottiene una Rigenerazione dell\'Energia di +3...6.','Incantesimo d\'Élite. (Secondi: 10) Rigenerazione Energia: +3...6. Impossibile selezionare se stessi.'],
120=>['Sangue del Padrone','Magia. Tutti i tuoi morti viventi alleati vengono curati di 30...116 Punto[i] Salute. Sacrifichi un 2% in più della Salute massima per ogni sgherro curato in questo modo.','Magia. Cura i tuoi morti viventi: 30...116. Costo delle cure: sacrifichi +2% di Salute per ogni morto vivente curato.'],
121=>['Spirito Malevolo','Fattura d\'Élite. Dura 10...25 secondo[i]; se l\'obiettivo nemico attacca o utilizza un\'abilità, lui e tutti i suoi alleati adiacenti ricevono 15...45 danno[i] da ombra.','Fattura d\'Élite. (Secondi: 10...25) Assesta 15...45 danno[i] all\'obiettivo e ai nemici adiacenti ogni volta che questo nemico attacca o usa un\'abilità.'],
122=>['Intervento Maligno','Fattura. Dura 5...20 secondo[i]; l\'obiettivo nemico riceve il 20% in meno delle cure. Se il tuo obiettivo muore mentre è affetto da questa fattura, dal suo cadavere si anima un Orrore d\'Ossa senza padrone di livello 1...17.','Fattura. (Secondi: 5...20) Riduzione cure ricevute dal nemico: -20%. Se muore mentre è affetto da questa fattura si anima un Orrore d\'Ossa senza padrone di livello 1...17.'],
123=>['Parassita Insidioso','Fattura. Per 5...15 secondo[i], ogni volta che un attacco dell\'obiettivo nemico va a segno, gli sottrai fino a 15...45 Punto[i] Salute.','Fattura. (Secondi: 5...15) Ricevi 15...45 Punto[i] Salute ogni volta che l\'obiettivo nemico colpisce con un attacco.'],
124=>['Spasmo Spinale','Fattura. Dura 10...40 secondo[i]; se l\'obiettivo nemico subisce un danno da freddo mentre usa un\'abilità, viene interrotto e tu perdi 8...3 Punto[i] Energia oppure lo Spasmo spinale termina.','Fattura. (Secondi: 10...40) Il danno da freddo interrompe le abilità dell\'obiettivo nemico. Costo dell\'interruzione: perdi 8...3 Punto[i] Energia o Spasmo Spinale termina.'],
125=>['Appassimento','Fattura d\'Élite. Per 5...35 secondo[i], l\'obiettivo nemico subisce una Degenerazione della Salute di -2...4 e una Degenerazione dell\'Energia di -1; se l\'Energia dell\'obiettivo nemico scende a 0, quel nemico subisce 15...75 danno[i] e questa abilità termina.','Fattura d\'Élite. (Secondi: 5...35) Degenerazione Salute: -2...4. Degenerazione Energia: -1. Danni inferti: 15...75 se l\'Energia dell\'obiettivo nemico scende a 0.Termina se l\'Energia di questo nemico scende a 0.'],
126=>['Trasferimento di Vita','Fattura d\'Élite. Per 6...12 secondo[i], l\'obiettivo nemico e i nemici adiacenti subiscono -3...8 punto[i] di Degenerazione della Salute che per te si trasformano in punti di Rigenerazione della Salute.','Fattura d\'Élite. Infligge fattura anche ai nemici adiacenti all\'obiettivo (secondi: 6...12). Degenerazione Salute: -3...8. Rigenerazione tua Salute: +3...8.'],
127=>['Segno della Sovversione','Fattura. Dura 6 secondo[i]; la prossima volta che l\'obiettivo nemico tenta di lanciare una magia su un suo alleato, fallisce e tu sottrai fino a 10...92 Punto[i] Salute a quel nemico.','Fattura. (Secondi: 6) La prossima magia dell\'obiettivo nemico fallisce e sottrai 10...92 Punto[i] Salute Ha effetto solo se la magia di questo nemico era diretta contro uno dei suoi alleati.'],
128=>['Sanguisuga dell\'Anima','Fattura d\'Élite. Dura 10 secondi; ogni volta che l\'obiettivo nemico compie una magia, tu gli sottrai fino a 16...80 Punto[i] Salute.','Fattura d\'Élite. (Secondi: 10) Salute sottratta ogni volta che l\'obiettivo nemico lancia una magia: 16...80.'],
129=>['Contaminazione della Carne','Fattura. Per 5...35 secondo[i], l\'obiettivo nemico ottiene solo due terzi di Salute dalle cure.','Fattura. (Secondi: 5...35) Riduzione cure ricevute dall\'obiettivo nemico: -33%. Ha effetto solo sulle abilità che parlano di "cure".'],
130=>['Carne Demoniaca','Incantesimo. Dura 30...60 secondo[i]; se utilizzi un\'abilità su un obiettivo nemico, tutti i nemici a te adiacenti ricevono 5...20 danno[i] da ombra.','Incantesimo. (Secondi: 30...60) Se utilizzi un\'abilità su un obiettivo nemico, tutti i nemici a te adiacenti ricevono 5...20 danno[i] da ombra.'],
131=>['Sigillo Uncinato','Sigillo. Infliggi Emorragia all\'obiettivo e a tutti i nemici adiacenti per 3...15 secondi.','Sigillo. Condizione inflitta a obiettivo e nemici adiacenti: Emorragia (3...15 secondi).'],
132=>['Sigillo della Peste','Sigillo d\'Élite. Durata residua delle condizioni negative trasferite da te all\'obiettivo nemico: 100...200%. 50% di probabilità di fallimento con Maledizioni di grado 4 o inferiore.','Sigillo d\'Élite. Trasferisce tutte le condizioni, con un 100...200% della loro durata residua, da te all\'obiettivo nemico. 50% di probabilità di fallimento con Maledizioni di livello inferiore a 5.'],
133=>['Patto Oscuro','Magia. Infliggi 20...60 danno[i] da ombra all\'obiettivo nemico.','Magia. Danni inferti: 20...60.'],
134=>['Ordine del Dolore','Incantesimo. Per 5 secondi, ogni volta che un membro della squadra provoca danni fisici al nemico, gli infligge anche +3...16 danno[i].','Incantesimo. Incanta tutti i membri della squadra (5 secondi). 3...16 danno[i] in più ogni volta che questi membri della squadra assestano danni fisici.'],
135=>['Codardia','Fattura. Per 4...18 secondo[i] la velocità d\'attacco dell\'obiettivo nemico rallenta del 50% e quel nemico subisce una Degenerazione della Salute di -1...3.','Fattura. (Secondi: 4...18) Rallentamento velocità d\'attacco dell\'obiettivo nemico: 50%. Degenerazione sua Salute: -1...3.'],
136=>['Ombra della Paura','Fattura. Per i prossimi 5...30 secondo[i] la velocità d\'attacco dell\'obiettivo nemico e di tutti i nemici adiacenti rallenta del 50%.','Fattura. Infligge fattura anche ai nemici adiacenti all\'obiettivo (5...30 secondo[i]). Rallentamento della loro velocità d\'attacco: 50%.'],
137=>['Rigor Mortis','Fattura. Per 8...20 secondo[i] l\'obiettivo nemico non può bloccare.','Fattura. (Secondi: 8...20) L\'obiettivo nemico non può bloccare.'],
138=>['Legame Oscuro','Incantesimo. Per i prossimi 30...60 secondo[i], se subisci un danno, lo sgherro che ti sta più vicino riceverà 75% del danno al posto tuo.','Incantesimo. (Secondi: 30...60) Trasferisce al tuo morto vivente più vicino 75% dei danni diretti verso di te.'],
139=>['Infondi Condizione','Incantesimo. Dura 15...60 secondo[i]; se ricevi una condizione, questa viene trasferita allo sgherro che ti sta più vicino.','Incantesimo. (Secondi: 15...60) Ogni volta che ricevi una condizione viene trasferita al tuo morto vivente più vicino.'],
140=>['Malessere','Fattura. Per 5...35 secondo[i], l\'obiettivo nemico subisce una Degenerazione Energia di -1 e tu una Degenerazione Salute di -1; se l\'Energia dell\'obiettivo nemico scende a 0, quel nemico subisce 5...50 danno[i] e Malessere termina.','Fattura. (Secondi: 5...35) Degenerazione Energia: -1. Danni inferti se l\'Energia dell\'obiettivo nemico scende a 0: 5...50. Degenerazione tua Salute: -1. Termina se l\'Energia di questo nemico scende a 0.'],
141=>['Strappa Incantesimi','Magia. Rimuovi 5...9 incantesimo[i] dall\'obiettivo nemico. Per ogni incantesimo del Mistico rimosso, perdi 55...25 Punto[i] Salute.','Magia. Incantesimi rimossi dall\'obiettivo nemico: 5...9. Costo di rimozione: perdi 55...25 Punto[i] Salute per ogni incantesimo del Mistico rimosso.'],
142=>['Maledizione Persistente','Fattura d\'Élite. Per 6...30 secondo[i] l\'obiettivo nemico e tutti i nemici nei dintorni subiscono una Degenerazione della Salute di -1...4 e ricevono un 25% in meno di cure.','Fattura d\'Élite. (Secondi: 6...30) Degenerazione Salute dell\'obiettivo e di tutti i nemici nei dintorni: -1...4. Riduzione cure ricevute: 25%.'],
143=>['Sottrai Incantesimo','Magia. Rimuovi 0...2 incantesimo[i] dall\'obiettivo nemico. Se riesci a rimuovere un incantesimo, sottrai 5...65 Punto[i] Salute.','Magia. Incantesimi rimossi dall\'obiettivo nemico: 0...2. Effetto della rimozione: sottrai 5...65 di Salute.'],
144=>['Geloni','Magia. Vieni avvelenato per 10 secondi; i nemici nell\'area del tuo obiettivo subiscono 10...44 danno[i] da freddo e perdono 1...2 incantesimo[i].','Magia. Danni da freddo ai nemici nell\'area intorno all\'obiettivo: 10...44. Incantesimi rimossi da questi nemici: 1...2. Sei affetto da Veleno (10 secondi).'],
145=>['Sigillo dell\'Agonia','Sigillo. Soffri di Emorragia per 25 secondi. Tutti i nemici nei dintorni subiscono 10...70 danno[i].','Sigillo. Danni ai nemici vicini a te: 10...70. Sei affetto da Emorragia (25 secondi).'],
146=>['Offerta di Sangue','Magia d\'Élite. Energia conseguita: 8...20.','Magia d\'Élite. Energia conseguita: 8...20.'],
147=>['Furia Oscura','Incantesimo. Per 5 secondi ogni volta che l\'attacco di un membro della squadra va a segno, riceve una dose di adrenalina (50% di probabilità di fallimento con Magia del Sangue di grado 4 o inferiore).','Incantesimo. Incanta i membri della squadra (5 secondi). Ottengono una dose di adrenalina ogni volta che colpiscono con un attacco. Probabilità di fallimento se il grado di Magia del Sangue è inferiore a 5: 50%.'],
148=>['Ordine del Vampiro','Incantesimo d\'Élite. Per 5 secondi, ogni volta che un membro della squadra, che non è affetto da incantesimi di un altro Negromante, infligge danni fisici al nemico, gli sottrae fino a 3...16 Punto[i] Salute.','Incantesimo d\'Élite. Incanta tutti i membri della squadra (5 secondi). Salute sottratta da questi membri della squadra con ogni attacco a danno fisico: 3...16. Non ha effetto sui membri della squadra affetti da un altro incantesimo del Negromante.'],
149=>['Trasmissione della Peste','Magia. Trasferisci 1...3 condizione[i] negativa[e] e la loro durata residua da te all\'obiettivo nemico e a tutti i nemici adiacenti.','Magia. Trasferisci 1...3 condizione[i] e la loro durata residua da te all\'obiettivo nemico e a tutti i nemici adiacenti.'],
150=>['Segno del Dolore','Fattura. Dura 30 secondi; se l\'obiettivo nemico subisce un danno fisico, il Segno del Dolore infligge 10...40 danno[i] da ombra ai nemici adiacenti.','Fattura. (Secondi: 30) Danni ai nemici adiacenti ogni volta che l\'obiettivo nemico subisce danno fisico: 10...40.'],
151=>['Banchetto della Corruzione','Magia d\'Élite. L\'obiettivo nemico e tutti i nemici adiacenti subiscono 16...80 danno[i] da ombra e tu sottrai fino a 8...40 Punto[i] Salute a ogni nemico colpito da fattura.','Magia d\'Élite. Danni all\'obiettivo e ai nemici adiacenti: 16...80. Salute sottratta ad ogni nemico affetto dalla fattura: 8...40.'],
152=>['Sapore della Morte','Magia. Sottrai fino a 100...400 Punto[i] Salute al morto vivente alleato preso di mira.','Magia. Sottrae 100...400 Punto[i] Salute al morto vivente alleato.'],
153=>['Sguardo del Vampiro','Magia. Sottrai fino a 18...60 Punto[i] Salute all\'obiettivo nemico.','Magia. Sottrazione Salute: 18...60.'],
154=>['Tocco della Peste','Abilità. Trasferisci 1...3 condizione[i] negativa[e] e la loro durata residua da te all\'obiettivo nemico toccato.','Abilità a Tocco. Trasferisci 1...3 condizione[i] da te all\'obiettivo nemico.'],
155=>['Tocco Vile','Abilità. Tocca l\'obiettivo nemico per infliggergli 20...65 danno[i].','Abilità a Tocco. Danni inferti: 20...65.'],
156=>['Tocco del Vampiro','Abilità. Tocca l\'obiettivo nemico per sottrargli fino a 29...74 Punto[i] Salute.','Abilità a Tocco. Sottrazione Salute: 29...74.'],
157=>['Rituale del Sangue','Incantesimo. Per 8...14 secondo[i], l\'obiettivo alleato toccato ottiene +3 punti di Rigenerazione dell\'Energia. Il Rituale del Sangue non può essere usato su se stessi.','Incantesimo. (Secondi: 8...14) Rigenerazione Energia: +3. Impossibile selezionare se stessi.'],
158=>['Tocco dell\'Agonia','Abilità. L\'obiettivo nemico toccato subisce 20...58 danno[i] da ombra.','Abilità a Tocco. Danni inferti: 20...58.'],
159=>['Indebolisci Armatura','Magia. L\'obiettivo nemico e i nemici a lui adiacenti soffrono di Armatura Incrinata per 5...20 secondo[i].','Magia. Ha effetto anche sui nemici adiacenti. Condizione inflitta: Armatura Incrinata (5...20 secondo[i]).'],
160=>['Velocità del Vento','Incantesimo. Per 5...13 secondi, la velocità di movimento dell\'obiettivo alleato aumenta del 33%.','Incantesimo. (Secondi: 5...13.) Incremento velocità di movimento dell\'obiettivo alleato: 33%.'],
162=>['Burrasca','Magia. Abbatti l\'obiettivo nemico per 2 secondi. (50% di probabilità di fallimento con Magia dell\'Aria di grado 4 o inferiore.)','Magia. Provoca abbattimento. Probabilità di fallimento se il grado di Magia dell\'Aria è pari o superiore a 5: 50%.'],
163=>['Vortice','Magia. Tutti i nemici adiacenti subiscono 15...75 danni da freddo. I nemici all\'attacco colpiti dal Vortice vengono abbattuti. Se sei sotto Sforzo, questa magia colpisce i nemici nelle vicinanze anziché quelli adiacenti.','Magia. Colpisce i nemici a te adiacenti. Danni da freddo inferti: 15...75. Provoca abbattimento dei nemici all\'attacco. Colpisce i nemici nelle vicinanze anziché quelli adiacenti se sotto Sforzo.'],
164=>['Armonia Elementale','Incantesimo d\'Élite. Per 25...60 secondo/i sei in armonia con l\'Aria, il Fuoco, l\'Acqua e la Terra, e ottieni +1...2 a questi attributi. Ogni volta che usi una magia associata a uno di questi elementi, ottieni 1 punto Energia e il 50% del costo base dell\'Energia delle abilità.','Incantesimo d\'Élite. (25...60 secondo/i) I tuoi attributi elementali aumentano di +1...2. Ottieni 1 più il 50% del costo base dell\'Energia di ogni abilità magica di Aria, Fuoco, Acqua e Terra che usi.'],
165=>['Armatura della Terra','Incantesimo. Per 30 secondi, ottieni 24...60 punti di armatura, ma i tuoi movimenti rallentano del 50...14%.','Incantesimo. (Secondi: 30.) Armatura ottenuta: +24...60. Rallentamento velocità di movimento: 50...14%.'],
166=>['Armatura Cinetica','Incantesimo. Per 12 secondi, ottieni +20...80 armatura. Ogni volta che lanci una magia, Kinetic Armor si rinnova per altri 12 secondi.','Incantesimo. (12 secondi). Ottieni +20...80 armatura. Bonus per rinnovo: lancia una magia.'],
167=>['Eruzione','Magia. Provochi un\'Eruzione nella posizione dell\'obiettivo nemico. Per 5 secondi, i nemici nell\'area subiscono 10...40 danni da terra al secondo, e vengono accecati per 10 secondi.','Magia. Infligge 10...40 danni da terra al secondo (5 secondi). Colpisce i nemici vicini alla posizione iniziale dell\'obiettivo. Infligge Accecamento (10 secondi).'],
168=>['Aura Magnetica','Incantesimo. Per 1...8 secondi blocchi il prossimo attacco rivolto contro di te e infliggi 10...50 danni al tuo attaccante. Se sei sotto Sforzo, tutti i membri della squadra a portata d\'orecchio subiscono la magia.','Incantesimo. (Secondi: 1...8.) Blocchi il prossimo attacco. Danno riflesso all\'attaccante: 10...50 Se sei sotto Sforzo, tutti i membri della squadra a portata d\'orecchio subiscono la magia.'],
169=>['Armonia con la Terra','Incantesimo. Per 36...60 secondi entri in sintonia con la Terra. Recuperi 1 Punto Energia e il 30% del costo di Energia di base dell\'abilità ogni volta che utilizzi una Magia della Terra.','Incantesimo. (Secondi: 36...60.) Ricevi 1 Punto Energia e il 30% del costo energetico usando un\'abilità della Magia della Terra.'],
170=>['Terremoto','Magia. Evochi un Terremoto nella posizione dell\'obiettivo nemico. Tutti i nemici nei dintorni di questa posizione vengono abbattuti e subiscono 26...100 danni da terra.','Magia. Infligge 26...100 danni da terra. Colpisce anche i nemici nelle vicinanze dell\'obiettivo. Provoca abbattimento.'],
171=>['Sassaiola','Magia. Lanci un masso che infligge all\'obiettivo nemico 45...105 danni da terra se va a segno. Se Sassaiola colpisce un nemico affetto da Debolezza, il nemico viene abbattuto.','Magia. Proiettile: infligge 45...105 danni da terra. Provoca abbattimento se l\'obiettivo nemico soffre di Debolezza.'],
172=>['Pugnali di Pietra','Magia. Lanci due Pugnali di Pietra. Ogni Pugnale di Pietra infligge all\'obiettivo nemico 8...33 danni da terra se va a segno. Se sei sotto Sforzo, ogni proiettile infligge Sanguinamento per 1...5 secondi.','Magia. Due proiettili: ognuno infligge 8...33 danni da terra. Condizione inferta se sotto Sforzo: Sanguinamento (Secondi: 1...5).'],
173=>['Morsa della Terra','Fattura. Per 5...20 secondi la velocità di movimento di tutti i nemici nei dintorni diminuisce del 50%.','Fattura. Colpisce con una fattura i nemici vicino a te (secondi: 5...20). I movimenti di questi nemici sono più lenti del 50%.'],
174=>['Postumi dello Shock','Magia. Infligge 15...85 danni da terra ai nemici nelle vicinanze. Infligge 15...85 danni da terra in più ai nemici abbattuti.','Magia. danni da terra ai nemici nei dintorni: 15...85 danni da terra ai nemici abbattuti: +15...85.'],
175=>['Guardia contro gli Elementi','Guardia. Crei una Guardia contro gli Elementi nella tua posizione corrente. Per 8...20 secondi gli alleati nell\'area (Spiriti esclusi) ottengono +24 di armatura contro i danni elementali.','Guardia. (Secondi: 8...20.) Armatura degli alleati in questa Guardia contro i danni elementali: +24. Non ha effetto sugli Spiriti.'],
176=>['Guardia contro gli Attacchi Ravvicinati','Guardia. Crei una Guardia contro gli Attacchi Ravvicinati nella tua posizione corrente. Per 5...20 secondi, gli alleati nell\'area (Spiriti esclusi) hanno il 50% di probabilità di bloccare gli attacchi ravvicinati.','Guardia. (Secondi: 5...20.) Gli alleati in questa Guardia hanno un 50% di probabilità di bloccare gli attacchi ravvicinati. Non ha effetto sugli Spiriti alleati.'],
177=>['Guardia contro i Nemici','Guardia. Crei una Guardia contro i Nemici nella tua posizione corrente. Per 8...20 secondi, i movimenti dei nemici presenti nell\'area (Spiriti esclusi) rallentano del 50%.','Guardia. (Secondi: 8...20.) Rallentamento velocità di movimento dei nemici in questa Guardia: 50%.'],
178=>['Prodigio dell\'Etere','Incantesimo d\'Élite. Perdi tutti gli incantesimi. Per 8...20 secondi ottieni una Rigenerazione dell\'Energia di +6. Quando termina, perdi 2 Punti Salute per ogni punto di Energia che possiedi.','Incantesimo d\'Élite. (Secondi: 8...20.) Hai una Rigenerazione dell\'Energia di +6. Effetto al termine: perdi 2 Punti Salute per ogni punto di Energia che possiedi. Perdi tutti gli incantesimi.'],
179=>['Legami Incendiari','Fattura. Dopo 3 secondi, l\'obiettivo nemico e tutti i nemici nei dintorni subiscono 20...80 danni da fuoco e prendono fuoco per 1...3 secondi. Si attiva prima se l\'obiettivo nemico muore.','Fattura. (Secondi: 3.) Effetto al termine: 20...80 danni da fuoco e provoca Bruciatura (1...3 secondi) ai nemici vicini all\'obiettivo. Si attiva anche in caso di morte del nemico.'],
180=>['Aura del Ripristino','Incantesimo. Per 60 secondi, ottieni 0...1 Punti Energia. Ogni volta che usi una magia vieni curato di un 200...500% del suo costo energetico.','Incantesimo. (Secondi: 60.) Ottieni 0...1 Punti Energia. Ogni volta che usi una magia vieni curato di un 200...500% del suo costo energetico.'],
181=>['Rinnovamento dell\'Etere','Incantesimo d\'Élite. Per 5...20 secondi, ogni volta che lanci una magia, ottieni 1...4 Punti Energia e 5...20 Punti Salute per ogni incantesimo che hai addosso.','Incantesimo d\'Élite. (Secondi: 5...20.) Ogni volta che lanci una magia, ottieni 1...4 Punti di Energia e 5...20 di Salute per ogni incantesimo che hai addosso.'],
182=>['Evoca Fiamma','Incantesimo. Per 60 secondi, se brandisci un\'arma da fuoco, i tuoi attacchi infliggono un danno da fuoco aggiuntivo di 5...20.','Incantesimo. (Secondi: 60.) Danni da fuoco inferti dai tuoi attacchi: +5...20. Ha effetto solo se hai equipaggiato un\'arma per danni da fuoco.'],
183=>['Inferno','Magia. Infligge 30...135 danni da fuoco a tutti i nemici adiacenti.','Magia. Danni da fuoco ai nemici adiacenti a te: 30...135.'],
184=>['Armonia con il Fuoco','Incantesimo. Per 36...60 secondi entri in sintonia con il Fuoco. Recuperi 1 Punto Energia e il 30% del costo di Energia di base dell\'abilità ogni volta che utilizzi una Magia del Fuoco.','Incantesimo. (Secondi: 36...60.) Ricevi 1 Punto Energia e il 30% del costo energetico usando un\'abilità della Magia del Fuoco.'],
185=>['Mente che Brucia','Magia d\'Élite. L\'obiettivo nemico e i nemici adiacenti subiscono 15...60 danni da fuoco. Se ha meno Energia di te, quel nemico e tutti i nemici adiacenti subiscono un danno da fuoco aggiuntivo di 15...60 e prendono fuoco per 1...10 secondi.','Magia d\'Élite. Danni da fuoco inferti: 15...60. Se hai più Energia dell\'obiettivo nemico, assesta 15...60 danni da fuoco in più e provoca Bruciatura (1...10 secondi). Colpisce anche i nemici adiacenti.'],
186=>['Palla di Fuoco','Magia. Scaglia una palla di fuoco che colpisce il bersaglio e tutti i nemici vicini, infliggendo loro 7...112 danni da fuoco.','Magia. Proiettile: infligge 7...112 danni da fuoco al bersaglio e ai nemici vicini.'],
187=>['Meteora','Magia. L\'obiettivo nemico e tutti i nemici adiacenti subiscono 7...112 danni da fuoco e vengono abbattuti.','Magia. Danni da fuoco inferti: 7...112. Provoca abbattimento. Colpisce anche i nemici adiacenti all\'obiettivo.'],
188=>['Fuoriuscita di Fiamme','Magia. Infligge 15...120 danni da fuoco a tutti i nemici nei dintorni.','Magia. Danni da fuoco a tutti i nemici vicini a te: 15...120 .'],
189=>['Invocazione di Rodgort','Magia. L\'obiettivo nemico e tutti i nemici nei dintorni subiscono 15...120 danni da fuoco e prendono fuoco per 1...3 secondi.','Magia. Danni da fuoco inferti: 15...120. Colpisce anche i nemici nelle vicinanze dell\'obiettivo. Condizione inflitta: Bruciatura (1...3 secondi).'],
190=>['Segno di Rodgort','Fattura. L\'obiettivo nemico e tutti i nemici nei dintorni sono sotto gli effetti della fattura Segno di Rodgort. Per 10...35 secondi, ogni volta che il nemico è colpito da danni da fuoco, prende fuoco per 1...4 secondi.','Fattura. Colpisce con una fattura anche i nemici vicini all\'obiettivo (10...35 secondi). Subiscono Bruciatura (1...4 secondi) quando sono colpiti da danni da fuoco.'],
191=>['Immolazione','Magia. L\'obiettivo nemico subisce 20...75 danni da fuoco e prende fuoco per 1...3 secondi.','Magia. Danni da fuoco inferti: 20...75. Condizione inflitta: Bruciatura (1...3 secondi).'],
192=>['Pioggia di Meteore','Magia. Evochi una Pioggia di Meteore nella posizione dell\'obiettivo nemico. Per 9 secondi, i nemici adiacenti a quella posizione subiscono 7...112 danni da fuoco e vengono abbattuti ogni 3 secondi.','Magia. Danni da fuoco: 7...112. Provoca abbattimento ogni 3 secondi (9 secondi). Colpisce i nemici adiacenti alla posizione iniziale dell\'obiettivo.'],
193=>['Fenice','Magia. Una fiera Fenice sorge nella tua posizione e vola verso l\'obiettivo, esplodendo all\'impatto. L\'esplosione colpisce l\'obiettivo e i nemici nei dintorni provocando 10...60 danni da fuoco. Se sei sotto Sforzo, gli alleati nel raggio di impatto vengono curati di 20...80 Punti Salute.','Magia. Proiettile: danni da fuoco inferti all\'obiettivo e a tutti i nemici nei dintorni: 10...60. Cure agli alleati se sotto Sforzo: 20...80.'],
194=>['Bengala','Magia. Lanci un bengala che infligge all\'obiettivo nemico 20...65 danni da fuoco se va a segno. Se sei sotto Sforzo, Bengala colpisce anche i nemici adiacenti.','Magia. Proiettile: danni da fuoco inferti: 20...65. Se sotto Sforzo, colpisce gli adiacenti.'],
195=>['Sorgente di Lava','Magia. Per 5 secondi, i nemici adiacenti alla posizione in cui viene attivata questa magia subiscono 5...50 danni da fuoco al secondo. Se sei sotto Sforzo, questa magia colpisce i nemici nelle vicinanze anziché quelli adiacenti.','Magia. Danni da fuoco inflitti al secondo: 5...50 al secondo (5 secondi). Colpisce i nemici adiacenti alla tua posizione iniziale. Se sotto Sforzo, il raggio si estende alle vicinanze.'],
196=>['Calore Bruciante','Magia. Provochi un Calore Bruciante nella posizione dell\'obiettivo nemico. Per 5 secondi i nemici nelle vicinanze di questa posizione subiscono 10...40 danni da fuoco al secondo. Al termine del Calore Bruciante, i nemici nell\'area d\'effetto prendono fuoco per 3 secondi.','Magia. Infligge 10...40 danni da fuoco al secondo (5 secondi). Colpisce i nemici vicini alla posizione iniziale dell\'obiettivo. Effetto al termine: infligge Bruciatura (3 secondi).'],
197=>['Tempesta di Fuoco','Magia. Evochi una Tempesta di Fuoco nella posizione dell\'obiettivo nemico. Per 10 secondi, i nemici adiacenti a quella posizione subiscono 5...35 danni da fuoco al secondo.','Magia. Infligge 5...35 danni da fuoco al secondo (10 secondi). Colpisce i nemici adiacenti alla posizione iniziale dell\'obiettivo.'],
198=>['Glifo del Potere Elementale','Glifo. Per 25 secondi, i tuoi attributi elementali vengono incrementati di 2 gradi per 10 delle tue magie successive.','Glifo. (Secondi: 25.) Incremento dei tuoi attributi elementali: +2 (valido per 10 magie successive).'],
199=>['Glifo dell\'Energia','Glifo d\'Élite. 1...3 delle tue prossime magie non provocheranno Sforzo e costeranno 10...25 Punti Energia in meno per essere lanciate. Incremento dei tuoi attributi elementali: 1...2.','Glifo d\'Élite. 1...3 delle tue prossime magie non provocheranno Sforzo e costeranno 10...25 Punti Energia in meno. Ottieni 1...2 per tutti gli attributi elementali.'],
200=>['Glifo dell\'Energia Minore','Glifo. Per i prossimi 15 secondi 2 delle tue magie successive costano 10...18 Punti Energia in meno.','Glifo. (Secondi: 15.) Riduzione costo energetico di 2 magie successive: 10...18.'],
201=>['Glifo della Concentrazione','Glifo. Per 15 secondi è impossibile interrompere 1 delle tue magie successive e gli effetti dello Stordimento vengono ignorati.','Glifo. (Secondi: 15.) Impossibile interrompere 1 delle tue magie successive; Stordimento non ha effetto.'],
202=>['Glifo del Sacrificio','Glifo. Per 15 secondi la tua magia successiva viene lanciata istantaneamente, ma richiede 30 secondi in più per ricaricarsi. L\'incantesimo termina prematuramente se utilizzi un\'abilità non magica.','Glifo. (Secondi: 15). Il lancio della prossima magia è istantaneo ma richiede 30 secondi in più per ricaricarsi. Termina se utilizzi un\'abilità non magica.'],
203=>['Glifo del Rinnovamento','Glifo d\'Élite. Per 15 secondi la tua prossima magia si ricaricherà immediatamente.','Glifo d\'Élite. (Secondi: 15.) La ricarica della tua prossima magia è istantanea.'],
204=>['Ruggine','Fattura. Infligge 10...85 danni da freddo all\'obiettivo e ai nemici adiacenti. Per 5...20 secondi, l\'obiettivo nemico e tutti i nemici adiacenti impiegano 2 volte il tempo normale per attivare i Sigilli. Se sei sotto Sforzo, i sigilli dei nemici colpiti da Ruggine vengono interrotti e disattivati per 1...10 secondi.','Fattura. Danni da freddo inferti all\'obiettivo e ai nemici adiacenti: 10...85. Colpisce con una fattura anche i nemici adiacenti (5...20 secondi). Raddoppia il tempo di attivazione dei Sigilli. Tempo di interruzione e disattivazione dei sigilli quando sotto Sforzo: 1...10 secondi.'],
205=>['Marea di Fulmini','Fattura d\'Élite. Dopo 3 secondi, l\'obiettivo nemico viene abbattuto, subisce 14...100 danni da fulmine ed è affetto da Armatura Incrinata per 5...20 secondi. Questa magia ha una penetrazione dell\'armatura del 25%.','Fattura d\'Élite. (Secondi: 3.) Effetto al termine: danni da fulmine inferti: 14...100. Provoca abbattimento. Condizione inflitta: Armatura Incrinata (5...20 secondi). Penetrazione armatura: 25%.'],
206=>['Armatura di Brina','Incantesimo. Per 10...34 secondi, ottieni +40 di armatura contro danni fisici e +1 a Magia dell\'Acqua.','Incantesimo. (Secondi: 10...34.) Ottieni +40 di armatura contro danni fisici e +1 a Magia dell\'Acqua.'],
207=>['Evoca Brina','Incantesimo. Per 60 secondi, se brandisci un\'arma da freddo, i tuoi attacchi infliggono un danno da freddo aggiuntivo di 5...20.','Incantesimo. (Secondi: 60.) Danni da freddo inferti dai tuoi attacchi: +5...20. Ha effetto solo se hai equipaggiato un\'arma per danni da freddo.'],
208=>['Armonia con l\'Acqua','Incantesimo. Per 36...60 secondi entri in sintonia con l\'Acqua. Recuperi 1 Punto Energia e il 30% del costo di Energia di base dell\'abilità ogni volta che utilizzi una Magia dell\'Acqua.','Incantesimo. (Secondi: 36...60.) Ricevi 1 Punto Energia e il 30% del costo energetico usando un\'abilità della Magia dell\'Acqua.'],
209=>['Mente Ghiacciata','Fattura d\'Élite. L\'obiettivo nemico subisce 10...60 danni da freddo. Se ha meno Energia di te, subisce 10...60 danni da freddo in più e i suoi movimenti rallentano del 90% per 1...5 secondi.','Fattura d\'Élite. Danni da freddo inferti: 10...60. Se ha meno Energia di te, quel nemico subisce 10...60 danni da freddo in più e i suoi movimenti rallentano del 90% (1...5 secondi).'],
210=>['Prigione di Ghiaccio','Fattura. Per 8...20 secondi le gambe dell\'obiettivo nemico sono imprigionate nel ghiaccio e la sua velocità diminuisce del 66%.','Fattura. (Secondi: 8...20.) La velocità dell\'obiettivo nemico rallenta del 66%.'],
211=>['Spine di Ghiaccio','Fattura. L\'obiettivo nemico ed i nemici adiacenti subiscono 20...80 danni da freddo ed i loro movimenti rallentano del 66% per 2...6 secondi.','Fattura. Colpisce con una fattura anche i nemici adiacenti all\'obiettivo (2...6 secondi). I movimenti di questi nemici sono più lenti del 66%. Effetto iniziale: danni da freddo inferti: 20...80.'],
212=>['Esplosione di Ghiaccio','Fattura. Tutti i nemici nei dintorni subiscono 10...85 danni da freddo e i loro movimenti rallentano del 66% per 3...8 secondi.','Fattura. Colpisce con una fattura i nemici vicini a te. I movimenti di questi nemici sono più lenti del 66% (3...8 secondi). Effetto iniziale: danni da freddo inferti ai nemici vicini a te: 10...85.'],
213=>['Tempesta di Schegge','Fattura. Lanci un frammento di ghiaccio che infligge all\'obiettivo nemico 10...85 danni da freddo se va a segno e ne rallenta i movimenti del 66% per 2...6 secondi.','Fattura. Proiettile: danni da freddo inferti: 10...85. I movimenti dell\'obiettivo nemico rallentano del 66% (2...6 secondi).'],
214=>['Lancia di Ghiaccio','Incantesimo. Scagli una Lancia di Ghiaccio che infligge all\'obiettivo nemico 10...60 danni da freddo se va a segno. Se sei sotto Sforzo, ottieni una Rigenerazione della Salute di +1...4 per 5 secondi.','Incantesimo. Proiettile: danni da freddo inferti: 10...60. Rigenerazione della Salute ottenuta se sotto Sforzo: +1...4 (Secondi: 5).'],
215=>['Gorgo','Magia. Crei un Gorgo nella posizione dell\'obiettivo nemico. Per 10 secondi, i nemici adiacenti all\'area subiscono 10...25 danni da freddo al secondo. Quando colpisce, interrompe le magie.','Magia. Assesta 10...25 danni da freddo e interrompe magie ogni secondo (10 secondi). Colpisce i nemici adiacenti alla posizione iniziale dell\'obiettivo.'],
216=>['Nebbia d\'acciaio','Incantesimo. Per 8...15 secondo/i, hai +15 armatura. Le tue magie d\'aria che colpiscono un avversario si attivano e si ricaricano il 33% più velocemente, ma subisci 2 punti di affaticamento.','Incantesimo. (8...15 secondo/i). Hai +15 armatura. Le magie d\'aria che colpiscono un avversario si attivano e si ricaricano il 33% più velocemente, ma subisci 2 punti di affaticamento.'],
217=>['Onda di Cristallo','Magia. I nemici adiacenti subiscono 10...70 danni, ma vengono guariti da tutte le condizioni negative. Ogni condizione rimossa infligge 5...15 danni.','Magia. Danni a tutti i nemici adiacenti a te: 10...70. Questi nemici perdono tutte le condizioni e subiscono 5...15 danni per ogni condizione rimossa.'],
218=>['Carne di Ossidiana','Incantesimo d\'Élite. Per 8...20 secondi, ottieni +20 di armatura e non puoi essere colpito dalle magie nemiche, ma non puoi attaccare e subisci una Degenerazione Energia di -2.','Incantesimo d\'Élite. (Secondi: 8...20.) Ottieni +20 di armatura e non puoi essere colpito dalle magie nemiche. Non puoi attaccare e subisci una Degenerazione Energia di -2.'],
219=>['Fiamma di Ossidiana','Magia. Infliggi 22...112 danni all\'obiettivo nemico. Questa magia ignora l\'armatura.','Magia. Danni inferti: 22...112.'],
220=>['Lampo Accecante','Magia. L\'obiettivo nemico viene accecato per 3...8 secondi.','Magia. Condizione inflitta: Accecamento (3...8 secondi).'],
221=>['Evoca Fulmine','Incantesimo. Per 60 secondi, se brandisci un\'arma da fulmine, i tuoi attacchi infliggono un danno da fulmine aggiuntivo di 5...20.','Incantesimo. (Secondi: 60.) Danni da fulmine inferti dai tuoi attacchi: +5...20. Ha effetto solo se hai equipaggiato un\'arma per danni da fulmine.'],
222=>['Colpo di Fulmine','Fattura. L\'obiettivo nemico subisce 10...60 danni da fulmine. Questa magia ha una penetrazione dell\'armatura del 25%. Se sei sotto Sforzo, quel nemico viene colpito da Colpo di Fulmine per 3 secondi. Quando la fattura termina, l\'obiettivo subisce nuovamente danni da fulmine per 20...40 secondi.','Fattura. Danni da fulmine inferti: 10...60. Penetrazione armatura: 25%. Durata fattura se sotto Sforzo: 3 secondi. Effetto al termine: danni da fulmine inferti: 20...40.'],
223=>['Fulmine a Catena','Magia. L\'obiettivo nemico e un massimo di altri due nemici accanto a lui subiscono 10...85 danni da fulmine. Questa magia ha una penetrazione dell\'armatura del 25%.','Magia. Danni da fulmine inferti: 10...85. Colpisce anche due nemici nelle vicinanze dell\'obiettivo. Penetrazione armatura: 25%.'],
224=>['Scarica Snervante','Magia. L\'obiettivo nemico subisce 25...50 danni da fulmine ed è colpito da Debolezza per 5...20 secondi. Questa magia ha una penetrazione dell\'armatura del 25%.','Magia. Danni da fulmine inferti: 25...50. Condizione inflitta: Debolezza (5...20 secondi). Penetrazione armatura: 25%.'],
225=>['Armonia con l\'Aria','Incantesimo. Per 36...60 secondi entri in sintonia con l\'Aria. Recuperi 1 Punto Energia e il 30% del costo di Energia di base dell\'abilità ogni volta che utilizzi una Magia dell\'Aria.','Incantesimo. (Secondi: 36...60.) Ricevi 1 Punto Energia e il 30% del costo energetico usando un\'abilità della Magia dell\'Aria.'],
226=>['Shock Mentale','Magia d\'Élite. L\'obiettivo nemico subisce 10...50 danni da fulmine. Se ha meno Energia di te, subisce un danno da fulmine ulteriore di 10...50 e viene abbattuto. Questa magia ha una penetrazione dell\'armatura del 25%.','Magia d\'Élite. Danni da fulmine inferti: 10...50. Se la tua Energia è superiore a quella dell\'obiettivo, infligge +10...50 danni da fulmine e provoca abbattimento. Penetrazione armatura: 25%.'],
227=>['Segno Scintillante','Fattura d\'Élite. Per 10 secondi, l\'obiettivo nemico e tutti i nemici a lui adiacenti subiscono 5...25 danni al secondo. I nemici che stanno utilizzando abilità d\'attacco vengono accecati per 3 secondi. Questa fattura termina se utilizzi un\'abilità che abbia come bersaglio tale nemico.','Fattura d\'Élite. (Secondi: 10.) Danni al secondo inferti all\'obiettivo e ai nemici adiacenti: 5...25. Infligge Accecamento ai nemici che stanno utilizzando abilità d\'attacco. Questa fattura termina se utilizzi un\'abilità che abbia come bersaglio tale nemico.'],
228=>['Rombo di Tuono','Magia d\'Élite. Crea un\'enorme onda d\'urto nel punto in cui si trova il bersaglio. Infligge 10...50 danni da fulmine al bersaglio e a tutti i nemici vicini. Le azioni degli avversari colpiti vengono interrotte, e questi subiscono Armatura spaccata e Vulnerabilità per 5...20 secondo/i. Questa magia ha il 25% di penetrazione dell\'armatura.','Magia d\'Élite. Infligge 10...50 danni da fulmine. Inoltre, colpisce i nemici vicini. Infligge Armatura spaccata e Vulnerabilità (5...20 secondo/i). Interrompe i nemici. 25% penetrazione dell\'armatura.'],
229=>['Globo del Fulmine','Magia. Lanci un Globo del Fulmine che infligge all\'obiettivo nemico 10...100 danni da fulmine. Questa magia ha una penetrazione dell\'armatura del 25%.','Magia. Proiettile: danni da fulmine inferti: 10...100. Penetrazione armatura: 25%.'],
230=>['Giavellotto del Fulmine','Magia. Lanci un Giavellotto del Fulmine che infligge 15...50 danni da fulmine se va a segno. Giavellotto del Fulmine interrompe l\'azione dei nemici in attacco. Questa magia ha una penetrazione dell\'armatura del 25% e colpisce tutti i nemici fra te e il tuo obiettivo.','Magia. Proiettile: danni da fulmine inferti: 15...50. Interrompe l\'azione se il tuo obiettivo sta attaccando. Penetrazione armatura: 25%. Colpisce tutti i nemici fra te e il tuo obiettivo.'],
231=>['Shock','Abilità. L\'obiettivo nemico toccato viene abbattuto e subisce 10...60 danni da fulmine. Questa abilità ha una penetrazione dell\'armatura del 25%.','Abilità a Tocco. Danni da fulmine inferti: 10...60. Provoca abbattimento. Penetrazione armatura: 25%.'],
232=>['Tocco del Fulmine','Abilità. L\'obiettivo e tutti i nemici adiacenti vengono colpiti da 10...60 danni da fulmine, subiscono Accecamento per 1...4 secondi e Armatura Incrinata per 1...10 secondi. Questa abilità ha una penetrazione dell\'armatura del 25%.','Abilità a Tocco. Danni da fulmine inferti: 10...60. Colpisce anche i nemici adiacenti all\'obiettivo. Infligge Accecamento (1...4 secondi) e Armatura Incrinata (1...10 secondi) a tutti i nemici colpiti. Penetrazione armatura: 25%.'],
233=>['Aura Turbinante','Incantesimo. Per 3...7 secondi subisci l\'incantesimo Aura Turbinante e hai una rigenerazione Salute di 1...6 e il 50% di probabilità di bloccare i proiettili. Se sei sotto Sforzo quando lanci questo incantesimo, anche tutti gli altri membri della squadra a portata d\'orecchio subiscono la magia.','Incantesimo. (Secondi: 3...7.) Rigenerazione della Salute: +1...6. Probabilità di blocco proiettili: 50%. Se sei sotto Sforzo, anche i membri della squadra a portata d\'orecchio subiscono la magia.'],
234=>['Profondo Congelamento','Fattura. Provochi un Profondo Congelamento nella posizione dell\'obiettivo nemico. Tutti i nemici in quest\'area subiscono 10...85 danni da freddo e per 10 secondi i movimenti dei nemici rallentano del 66%.','Fattura. Colpisce con una fattura anche i nemici nell\'area dell\'obiettivo (10 secondi). I movimenti di questi nemici sono più lenti del 66%. Effetto iniziale: danni da freddo inferti: 10...85.'],
235=>['Vista Sfocata','Fattura. Per 4...10 secondi, l\'obiettivo nemico e tutti i nemici adiacenti sono colpiti dalla fattura Vista Sfocata e hanno il 50% di probabilità di fallire gli attacchi.','Fattura. Colpisce con una fattura anche i nemici adiacenti all\'obiettivo (4...10 secondi). Probabilità di far loro mancare l\'obiettivo: 50%.'],
236=>['Forma di Nebbia','Incantesimo d\'Élite. Per 10...45 secondi, subisci un 33% di danni in meno dai nemici sotto gli effetti di una fattura della Magia dell\'Acqua. Quando lanci una magia elementale, tutti gli alleati a portata d\'orecchio (Spiriti esclusi) vengono curati di un 50...250% del costo in Energia della magia.','Incantesimo d\'Élite. (Secondi: 10...45.) Subisci un 33% di danni in meno dai nemici colpiti da Magia dell\'Acqua. Cura gli alleati a portata d\'orecchio (Spiriti esclusi) di un 50...250% del costo in Energia delle tue magie elementali.'],
237=>['Tridente d\'Acqua','Magia d\'Élite. Lanci un rapido Tridente d\'Acqua che infligge all\'obiettivo nemico e fino a due nemici adiacenti 10...90 danni da freddo se va a segno. Se colpisce un nemico in movimento, lo abbatte.','Magia d\'Élite. Proiettile veloce: danni da freddo inferti: 10...90; abbatte i nemici in movimento. Spara due proiettili aggiuntivi verso i nemici adiacenti.'],
238=>['Armatura di Nebbia','Incantesimo. Per 8...20 secondi, ottieni +10...40 di armatura e i tuoi movimenti sono più veloci del 33%.','Incantesimo. (Secondi: 8...20.) Armatura: +10...40. Incremento velocità di movimento: 33%.'],
239=>['Guardia contro le Ferite','Guardia d\'Élite. Crea una Guardia contro le Ferite in questa posizione. Per 5...15 secondi, gli Alleati (Spiriti esclusi) in quest\'area ottengono +1...3 di Rigenerazione della Salute, +12...24 armatura e un +12...24 armatura aggiuntivo contro i danni elementali. Questa magia verrà disabilitata per 20 secondi.','Guardia d\'Élite. (Secondi: 5...15.) Gli alleati in questa Guardia ottengono +1...3 di Rigenerazione della Salute, +12...24 armatura e un +12...24 armatura aggiuntivo contro i danni elementali. Non ha effetto sugli Spiriti. Questa magia verrà disabilitata per 20 secondi.'],
240=>['Castigo','Magia. Questo attacco infligge 10...55 danno[i] sacro[i]; se il tuo obiettivo sta attaccando, riceve 10...35 danno[i] sacro[i] in più.','Magia. Danni sacri inferti: 10...55. Assesta 10...35 danno[i] sacro[i] in più se l\'obiettivo sta attaccando.'],
241=>['Legame Vitale','Incantesimo. Mantenendo questo incantesimo, ogni volta che l\'alleato subisce danni fisici da un attacco, metà dei danni viene deviata su di te. I danni da te subiti in questo modo sono ridotti di 3...30 punto[i].','Incantesimo. Devia su di te la metà dei danni subiti dall\'obiettivo alleato quando viene attaccato. Riduzione del danno deviato: 3...30. Impossibile selezionare se stessi.'],
242=>['Spirito di Balthazar','Incantesimo. Mantenendo questo incantesimo, l\'obiettivo (un alleato o te stesso) ottiene adrenalina ed Energia dopo aver subito danno (la quantità di adrenalina varia a seconda del livello delle Preghiere Punitive).','Incantesimo. L\'obiettivo (un alleato o te stesso) ottiene adrenalina e 1 Punto Energia quando riceve danni.'],
243=>['Forza dell\'Onore','Incantesimo. Mantenendo questo incantesimo, l\'obiettivo (un alleato o te stesso) infligge 5...25 danno[i] in più nel corpo a corpo.','Incantesimo. L\'obiettivo (un alleato o te stesso) assesta 5...25 danno[i] in più nel combattimento ravvicinato.'],
244=>['Armonia con la Vita','Incantesimo. Mantenendo questo incantesimo, l\'obiettivo (un alleato o te stesso) infligge il 30% in meno di danni con gli attacchi, ma ottiene 14...50% di Salute in più quando viene curato.','Incantesimo. Incremento cure ricevute dall\'obiettivo alleato: 14...50%. Riduzione danni assestati dai suoi attacchi: 30%.'],
245=>['Spirito Protettivo','Incantesimo. Dura 5...23 secondo[i]; l\'obiettivo (un alleato o te stesso) non può perdere più del 10% della sua Salute massima per effetto dei danni provocati da un singolo attacco o da una magia.','Incantesimo. (Secondi: 5...23) Il danno in arrivo è ridotto al 10% della Salute massima dell\'obiettivo (un alleato o te stesso).'],
246=>['Intervento Divino','Incantesimo. Per 10 secondi, la prossima volta che l\'obiettivo (un alleato o te stesso) riceve un danno che dovrebbe essere fatale, questo si annulla e l\'alleato viene curato di 26...240 Punto[i] Salute.','Incantesimo. (Secondi: 10) Previene il prossimo danno fatale subito dall\'obiettivo (un alleato o te stesso). Effetto della prevenzione: cura di 26...240.'],
247=>['Simbolo della Collera','Magia. Crea un simbolo d\'ira nel punto in cui si trova il bersaglio. Per 5 secondo/i, i nemici adiacenti vengono colpiti da 10...40 danni sacri al secondo.','Magia. Infligge 10...40 danni sacri al secondo (5 secondi). Colpisce i nemici adiacenti alla posizione iniziale del bersaglio.'],
248=>['Punizione','Incantesimo. Mantenendo questo incantesimo, se l\'obiettivo (un alleato o te stesso) viene attaccato e subisce danni, un 33% dei danni viene trasferito a chi li ha causati (fino a un massimo di 5...20).','Incantesimo. Rimanda alla fonte un 33% del danno causato da ogni attacco (max 5...20).'],
249=>['Collera Sacra','Incantesimo. Per 10...30 secondi, la[e] prossima[e] 1...10 volta[e] in cui un alleato subisce danni da attacco, questo incantesimo rimanda alla fonte un 66% dei danni (max 5...50 danno[i]).','Incantesimo. (Secondo[i]: 10...30). Rimanda alla fonte un 66% del danno causato da ogni attacco (max 5...50). Termina dopo aver inflitto danni 1...10 volta[e]. Impossibile selezionare se stessi.'],
250=>['Legame dell\'Essenza','Incantesimo. Mantenendo questo incantesimo, ogni volta che l\'obiettivo (un alleato o te stesso) subisce danni fisici o elementali ottieni 1 Punto Energia.','Incantesimo. Ottieni 1 Punto Energia ogni volta che l\'obiettivo (un alleato o te stesso) subisce danni fisici o elementali.'],
251=>['Guarigione Flagello','Fattura. Per 30 secondi, ogni volta che l\'obiettivo nemico viene curato, chi lo cura subisce 15...80 danni sacri.','Fattura. (Secondi: 30) Ogni volta che l\'obiettivo nemico viene curato, chi lo cura subisce 15...80 danno[i] sacro[i].'],
252=>['Bando','Magia. L\'obiettivo nemico subisce 20...65 danno[i] sacro[i]. Questa magia infligge il doppio dei danni sulle creature evocate.','Magia. Danni sacri inferti: 20...65. Danno doppio alle creature evocate.'],
253=>['Sacrificio del Flagello','Fattura. Per 8...20 secondo[i], ogni volta che l\'obiettivo nemico e i nemici adiacenti sacrificano dei Punti Salute, ne sacrificano il doppio del normale.','Fattura. Infligge fattura anche ai nemici adiacenti all\'obiettivo (8...20 secondo[i]). Raddoppia il sacrificio di Salute.'],
254=>['Spirito Vigoroso','Incantesimo. Per 30 secondi, ogni volta che l\'obiettivo (un alleato o te stesso) attacca o compie una magia, viene curato di 5...20 Punto[i] Salute.','Incantesimo. (Secondi: 30) Cure ogni volta che l\'obiettivo (un alleato o te stesso) attacca o lancia una magia: 5...20.'],
255=>['Spirito di Guardia','Incantesimo. Mantenendo questo incantesimo, l\'obiettivo (un alleato o te stesso) riceve una Rigenerazione della Salute di +2. L\'obiettivo viene curato di 30...180 Punto[i] Salute quando lo Spirito di Guardia termina.','Incantesimo. Rigenerazione Salute: +2. Effetto al termine: cura di 30...180.'],
256=>['Aura Benedetta','Incantesimo. Mantenendo questo incantesimo, gli incantesimi del Mistico da te lanciati durano un 10...35% in più.','Incantesimo. Incremento durata degli incantesimi del Mistico che lanci: 10...35%.'],
257=>['Egida','Incantesimo. Per 6...15 secondo[i] tutti i membri della squadra a portata d\'orecchio hanno il 50% di probabilità di bloccare gli attacchi.','Incantesimo. (Secondi: 6...15) Incanta tutti i membri della squadra a portata d\'orecchio. Probabilità di blocco: 50%.'],
258=>['Guardiano','Incantesimo. Per 2...7 secondo[i], l\'obiettivo (un alleato o te stesso) ha un 50% di probabilità di bloccare gli attacchi.','Incantesimo. (Secondi: 2...7) Probabilità di bloccare: 50%.'],
259=>['Scudo della Deviazione','Incantesimo d\'Élite. Per 3...10 secondo[i], l\'obiettivo (un alleato o te stesso) ha una probabilità del 75% di bloccare gli attacchi e ottiene 15...30 punto[i] di armatura.','Incantesimo d\'Élite. (Secondi: 3...10) Probabilità di blocco: 75%. Armatura: +15...30.'],
260=>['Aura della Fede','Incantesimo d\'Élite. Per 3 secondo[i], l\'obiettivo (un alleato o te stesso) ottiene un 50...100% di Salute in più quando viene curato e subisce un 5...50% in meno di danni.','Incantesimo d\'Élite. (Secondi: 3) Salute aggiuntiva conseguita dall\'obiettivo alleato con le cure: 50...100%. Riduzione del danno da lui ricevuto: 5...50%.'],
261=>['Scudo della Rigenerazione','Incantesimo d\'Élite. Per 5...13 secondo/i, il bersaglio alleato ottiene +3...10 rigenerazione della Salute e 20...45 armatura.','Incantesimo d\'Élite. (5...13 secondo/i). +3...10 rigenerazione della Salute e +20...45 armatura.'],
262=>['Scudo del Giudizio','Incantesimo d\'Élite. Per 8...20 secondo[i], chiunque colpisca l\'obiettivo (un alleato o te stesso) con un attacco viene buttato a terra e subisce 5...50 danno[i] sacro[i].','Incantesimo d\'Élite. (Secondi: 8...20) Danni sacri ai nemici che attaccano l\'obiettivo alleato: 5...50. Provoca abbattimento.'],
263=>['Legame della Protezione','Incantesimo. Mantenendo questo incantesimo, l\'obiettivo (un alleato o te stesso) non può perdere più del 5% della sua Salute massima per ogni attacco o magia ricevuta. Quando il Legame della Protezione previene i danni, perdi 6...3 Punto[i] Energia oppure la magia termina.','Incantesimo. Salute massima persa dall\'obiettivo alleato per effetto di un singolo attacco o una magia: 5%. Ogni volta che il danno viene ridotto perdi 6...3 Punto[i] Energia o questa magia termina.'],
264=>['Pacifismo','Fattura. Per 4...8 secondo[i], l\'obiettivo nemico non può attaccare; l\'effetto termina se l\'obiettivo subisce danni.','Fattura. (Secondi: 4...8) L\'obiettivo nemico non può attaccare. Termina se questo nemico subisce danni.'],
265=>['Amicizia','Fattura d\'Élite. Per 4...12 secondo[i], i nemici adiacenti non possono attaccare; l\'effetto termina quando l\'obiettivo nemico subisce un danno.','Fattura d\'Élite. (Secondi: 4...12) I nemici adiacenti a te non possono attaccare. Termina su qualsiasi nemico che riceve danni.'],
266=>['Pace e Armonia','Incantesimo d\'Élite. L\'obiettivo (un alleato o te stesso) perde 0...9 condizione[i] e fattura[e]. Per 1...3 secondo[i], le condizioni e le fatture su quell\'alleato si esauriscono con velocità superiore del 90%. Tutte le tue Preghiere Punitive vengono disattivate per 20 secondi.','Incantesimo d\'Élite. L\'obiettivo (un alleato o te stesso) perde 0...9 condizione[i] e fattura[e]. Incremento velocità di esaurimento condizioni e fatture su quell\'alleato: 90% (1...3 secondo[i]). Disattiva le tue Preghiere Punitive (20 secondi).'],
267=>['Sguardo del Giudice','Incantesimo. Per 8...20 secondo[i], gli attacchi dell\'obiettivo (un alleato o te stesso) infliggeranno danni sacri e avranno una penetrazione delle armature del +20%.','Incantesimo. (Secondi: 8...20) Trasforma gli attacchi dell\'obiettivo (un alleato o te stesso) in danno sacro. Penetrazione armatura: +20%.'],
268=>['Aura Inflessibile','Incantesimo d\'Élite. Mentre mantieni questo incantesimo le magie del Mistico impartiscono un +15...60% in più di Salute. Quando questo incantesimo termina, un compagno di squadra a caso risorge con piena Salute ed Energia e viene teletrasportato nella tua posizione.','Incantesimo d\'Élite. Incremento cure impartite dalle tue magie del Mistico: +15...60%. Effetto al termine: un compagno di squadra a caso viene resuscitato con piena Salute ed Energia e teletrasportato nella tua posizione.'],
269=>['Segno della Protezione','Incantesimo d\'Élite. Per 10 secondi, ogni volta che l\'obiettivo (un alleato o te stesso) dovrebbe subire un danno, viene invece curato dello stesso numero di punti, per un massimo di 6...60. Tutte le tue Preghiere Protettive vengono disattivate per 5 secondi.','Incantesimo d\'Élite. (Secondi: 10) Il danno in arrivo si tramuta in cure (max 6...60). Tutte le tue Preghiere Protettive vengono disattivate (5 secondi).'],
270=>['Barriera della Vita','Incantesimo d\'Élite. Mantenendo questo incantesimo, i danni inflitti all\'alleato vengono ridotti di un 20...50%. Se la tua Salute è inferiore a 50% quando l\'alleato subisce danni, la Barriera della Vita termina.','Incantesimo d\'Élite. Riduzione danno: 20...50%. Impossibile selezionare se stessi. Se la tua Salute è inferiore a 50% quando l\'obiettivo subisce danni, Barriera della Vita termina.'],
271=>['Fuoco dello Zelota','Incantesimo. Per 60 secondi, quando usi un\'abilità su un alleato, tutti i nemici adiacenti a quell\'alleato subiscono 5...35 danno[i] da fuoco e tu perdi 1 Punto[i] Energia.','Incantesimo. (Secondi: 60) Quando usi un\'abilità su un alleato, tutti i nemici a lui adiacenti ricevono 5...35 danno[i] da fuoco. Costo del danno: perdi 1 Punto[i] Energia.'],
272=>['Aura di Balthazar','Incantesimo. Per 8 secondi, i nemici adiacenti all\'obiettivo (un alleato o te stesso) subiscono 10...30 danno[i] sacro[i] al secondo.','Incantesimo. (Secondi: 8) Danni sacri al secondo ai nemici adiacenti all\'obiettivo (un alleato o te stesso): 10...30.'],
273=>['Spezza Incantesimo','Incantesimo d\'Élite. Per 5...17 secondo[i], l\'obiettivo alleato non può essere colpito dalle magie nemiche.','Incantesimo d\'Élite. (Secondo[i]: 5...17) L\'obiettivo alleato non può essere colpito dalle magie nemiche.'],
274=>['Seme della Guarigione','Incantesimo. Per 10 secondo[i], se l\'alleato subisce danni, lui e tutti gli alleati adiacenti ottengono 3...30 Punto[i] Salute.','Incantesimo. (Secondi: 10) Salute per l\'obiettivo e gli alleati adiacenti ogni volta che questo alleato riceve danni: 3...30. Impossibile selezionare se stessi.'],
275=>['Cura Condizione','Magia. Rimuove una condizione (Veleno, Malattia, Cecità, Stordimento, Emorragia, Storpiatura, Bruciatura, Debolezza, Armatura Incrinata o Ferita Profonda) dall\'obiettivo (un alleato o te stesso). Se viene rimossa una condizione, l\'alleato viene curato di 5...70 Punti Salute.','Magia. Rimuove una condizione. Effetto rimozione: cura di 5...70. Impossibile selezionare se stessi.'],
276=>['Ripristino Condizione','Magia d\'Élite. Rimuovi tutte le condizioni (Veleno, Malattia, Accecamento, Stordimento, Emorragia, Storpiatura, Bruciatura, Debolezza, Armatura Incrinata e Ferita Profonda) dall\'alleato. Per ogni condizione rimossa, quell\'alleato viene curato di 10...70 Punto[i] Salute.','Magia d\'Élite. Rimuove tutte le condizioni. Effetto della rimozione: cura di 10...70 per ogni condizione rimossa. Impossibile selezionare se stessi.'],
277=>['Cura Malattia','Magia. Rimuovi una condizione (Veleno, Malattia, Accecamento, Stordimento, Emorragia, Storpiatura, Bruciatura, Debolezza, Armatura Incrinata o Ferita Profonda) dall\'obiettivo alleato. Per ogni condizione rimanente, quell\'alleato viene curato di 5...70 Punto[i] Salute.','Magia. Rimuove una condizione. Effetto della rimozione: cura di 5...70 per ogni condizione rimasta.'],
278=>['Purifica Condizioni','Magia. Rimuove tutte le condizioni (Veleno, Malattia, Cecità, Stordimento, Emorragia, Storpiatura, Bruciatura, Debolezza, Armatura Incrinata e Ferita Profonda) dall\'obiettivo (un alleato o te stesso).','Magia. Rimuove tutte le condizioni.'],
279=>['Guarigione Divina','Magia. Curi di 15...60 punto[i] te stesso e i membri della squadra a portata d\'orecchio.','Magia. Cure per te e i membri della squadra a portata d\'orecchio: 15...60.'],
280=>['Cura Area','Magia. Curi te stesso e tutte le creature adiacenti di 30...180 punto[i].','Magia. Cure per te e per alleati e nemici adiacenti: 30...180.'],
281=>['Orazione Curativa','Magia. Curi l\'obiettivo (un alleato o te stesso) di 30...80 Punto[i] Salute.','Magia. Cure: 30...80.'],
282=>['Parola di Guarigione','Magia d\'Élite. Curi l\'obiettivo (un alleato o te stesso) di 5...100 Punto[i] Salute e di altri 30...115 Punto[i] Salute se la sua Salute è inferiore al 50%.','Magia d\'Élite. Cure: 5...100. Cura di 30...115 in più se la Salute dell\'obiettivo (un alleato o te stesso) è inferiore al 50%.'],
283=>['Bacio di Dwayna','Magia. Curi l\'alleato di 20...65 Punto[i] Salute e di altri 15...40 Punto[i] Salute per ogni incantesimo o fattura che ha addosso.','Magia. Cure: 20...65. Cura di 15...40 in più per ogni incantesimo o fattura presente sull\'obiettivo (un alleato o te stesso). Impossibile selezionare se stessi.'],
284=>['Dono Divino','Incantesimo. Mentre mantieni quest\'incantesimo, ogni volta che lanci una Preghiera Protettiva o un Favore Divino su un obiettivo (un alleato o te stesso) lo curi di 15...60 Punti Salute e perdi 1 Punto Energia.','Incantesimo. Cure per l\'obiettivo (un alleato o te stesso) su cui lanci una Preghiera Protettiva o un Favore Divino: 15...60. Costo delle cure: perdi 1 Punto Energia.'],
285=>['Mani Curative','Incantesimo d\'Élite. Per 10 secondo[i], se l\'obiettivo (un alleato o te stesso) subisce danni viene curato di 5...35 Punto[i] Salute.','Incantesimo d\'Élite. (10 secondo[i]). Cura di 5...35 quando l\'obiettivo riceve danni.'],
286=>['Cura Altro','Magia. Curi l\'alleato di 35...180 Punto[i] Salute.','Magia. Cure: 35...180. Impossibile selezionare se stessi.'],
287=>['Cura Squadra','Magia. Curi l\'intera squadra di 30...75 Punto[i] Salute.','Magia. Cure per l\'intera squadra: 30...75.'],
288=>['Brezza di Guarigione','Incantesimo. Per 15 secondo[i], l\'obiettivo (un alleato o te stesso) ottiene una Rigenerazione della Salute di +4...9.','Incantesimo. (Secondi: 15) Rigenerazione Salute: +4...9.'],
289=>['Benedizione Vitale','Incantesimo. Mantenendo questo incantesimo, l\'obiettivo (un alleato o te stesso) ha +40...200 di Salute massima.','Incantesimo. Salute massima: +40...200.'],
290=>['Medicamento','Incantesimo. Mantenendo questo incantesimo, l\'obiettivo (un alleato o te stesso) ottiene una Rigenerazione della Salute di +1...4.','Incantesimo. Rigenerazione Salute: +1...4.'],
291=>['Vita Sostitutiva','Incantesimo. Mantenendo questo incantesimo, ogni volta che l\'obiettivo (un alleato o te stesso) colpisce un nemico, ottieni 2...17 Punto[i] Salute.','Incantesimo. Salute ottenuta ogni volta che l\'obiettivo (un alleato o te stesso) colpisce un nemico: 2...17.'],
292=>['Infondi Salute','Magia. Perdi metà della tua Salute. L\'alleato viene curato del 100...136% della quantità da te persa.','Magia. Cura di un 100...136% della metà della tua Salute attuale. Perdi metà della tua Salute attuale. Impossibile selezionare se stessi.'],
293=>['Sigillo della Devozione','Sigillo. Curi l\'obiettivo (un alleato o te stesso) di 20...120 Punto[i] Salute.','Sigillo. Cure: 20...120.'],
294=>['Sigillo del Giudizio','Sigillo d\'Élite. L\'obiettivo nemico viene buttato a terra e sia lui che tutti i nemici adiacenti subiscono 15...75 danno[i] sacro[i].','Sigillo d\'Élite. Abbatte l\'obiettivo. Danni sacri all\'obiettivo e ai nemici adiacenti: 15...75.'],
295=>['Sigillo della Purificazione','Sigillo. Rimuovi tutte le fatture e le condizioni dall\'obiettivo (un alleato o te stesso) ma perdi 10 Punti Energia per ogni fattura e condizione rimossa.','Sigillo. Rimuove tutte le fatture e le condizioni. Costo di rimozione: perdi 10 Punti Energia.'],
296=>['Sigillo della Sventura','Sigillo. L\'obiettivo nemico subisce 30...60 danno[i] sacro[i]; se stava attaccando, viene abbattuto.','Sigillo. Danni sacri inferti: 30...60. Provoca abbattimento se l\'obiettivo nemico sta attaccando.'],
297=>['Sigillo Benedetto','Sigillo. Per ogni incantesimo da te mantenuto ottieni 3 Punti Energia. Puoi ottenere solo un massimo di 3...24 Punto[i] Energia in questo modo.','Sigillo. Energia conseguita per ogni incantesimo da te mantenuto: 3. Energia massima conseguibile in questo modo: 3...24.'],
298=>['Martire','Magia d\'Élite. Trasferisci tutte le condizioni, con le loro durate residue, dagli alleati a te stesso.','Magia d\'Élite. Trasferisci tutte le condizioni da tutti gli alleati a te stesso.'],
299=>['Mani Scudo','Incantesimo. Per 8 secondi i danni e la sottrazione vita ricevuti dall\'obiettivo (un alleato o te stesso) si riducono di 3...18. Quando l\'effetto delle Mani Scudo svanisce, l\'alleato viene curato di 5...50 Punti Salute.','Incantesimo. (Secondi: 8) Riduzione del danno in arrivo e della sottrazione vita: 3...18. Effetto al termine (cure): 5...50.'],
300=>['Contemplazione della Purezza','Abilità. Perdi tutti gli incantesimi; per ogni incantesimo perso ottieni 0...80 Punto[i] Salute e perdi una fattura e una condizione (max. 1...8 fattura[e] e condizione[i]).','Abilità. Ottieni 0...80 Punto[i] Salute e perdi una fattura e una condizione per ogni incantesimo presente su di te (max 1...8 fattura[e] e condizione[i]). Perdi tutti gli incantesimi.'],
301=>['Rimuovi Fattura','Magia. Rimuovi una fattura dall\'obiettivo (un alleato o te stesso).','Magia. Rimuove una fattura dall\'obiettivo (un alleato o te stesso).'],
302=>['Colpisci Fattura','Magia. Elimina una fattura dall\'obiettivo (un alleato o te stesso). Se ci riesci, i nemici presenti nell\'area subiscono 10...85 danno[i] sacro[i].','Magia. Rimuove una fattura dall\'obiettivo (un alleato o te stesso). Effetto della rimozione: 10...85 danno[i] sacro[i] ai nemici nell\'area dell\'obiettivo.'],
303=>['Converti Fatture','Magia. Rimuovi tutte le fatture dall\'alleato. Per 8...20 secondo[i], l\'alleato ottiene +10 di armatura per ogni fattura del Negromante rimossa.','Magia. Rimuove tutte le fatture. Armatura per ogni fattura del Negromante rimossa: +10 (8...20 secondo[i]). Impossibile selezionare se stessi.'],
304=>['Luce di Dwayna','Magia. Resusciti tutti i membri della squadra morti presenti nell\'area facendoli ritornare in vita con il 25% di Salute e zero Energia.','Magia. Resuscita tutti i membri della squadra morti nell\'area (25% di Salute, zero Energia).'],
305=>['Resurrezione','Magia. Resusciti un membro della squadra facendolo ritornare in vita con il 25% di Salute e zero Energia.','Magia. Fa risorgere il membro della squadra selezionato (Salute: 25%; Energia: 0).'],
306=>['Rinascita','Magia. Resusciti un membro della squadra facendolo ritornare in vita con il 25% di Salute e zero Energia e teletrasportandolo nella tua posizione corrente. Tutte le sue abilità restano inattive per 10...3 secondo[i]. Questa magia consuma tutta la tua Energia residua.','Magia. Fa risorgere il membro della squadra selezionato (Salute: 25%; Energia: 0). Teletrasporta l\'obiettivo nella tua posizione. Disattiva le abilità dell\'obiettivo (10...3 secondo[i]). Perdi tutta l\'Energia.'],
307=>['Rovescio della Fortuna','Incantesimo. Per 8 second[i], la volta successiva in cui l\'obiettivo alleato viene colpito da un attacco che dovrebbe infliggere danni o sottrazione vita, l\'alleato ottiene il corrispettivo in Punti Salute (max 15...80) dei danni o della sottrazione vita.','Incantesimo. (Secondi: 8) Converte il danno in arrivo o la sottrazione vita successivi in Punti Salute (max. 15...80).'],
308=>['Soccorso','Incantesimo. Mantenendo questo incantesimo, l\'alleato ottiene +1 di Rigenerazione della Salute e +1 di Rigenerazione dell\'Energia, ma tu perdi 1 Punto Energia ogni volta che l\'alleato lancia una magia.','Incantesimo. Rigenerazione Salute: +1. Rigenerazione Energia: +1. Impossibile selezionare se stessi. Perdi 1 Punto Energia ogni volta che l\'obiettivo (un alleato o te stesso) lancia una magia.'],
309=>['Sacro Velo','Incantesimo. Mantenendo questo incantesimo, ci vorrà il doppio del tempo per lanciare le fatture sull\'obiettivo alleato. Quando il Sacro Velo termina, viene eliminata una fattura dall\'obiettivo (un alleato o te stesso).','Incantesimo. Raddoppia il tempo di lancio delle fatture dirette contro l\'obiettivo (un alleato o te stesso). Effetto al termine: rimuove una fattura.'],
310=>['Spirito Divino','Incantesimo. Per 1...14 secondo[i], le magie del Mistico ti costano 5 Punti Energia in meno (costo minimo: 1 Punto Energia).','Incantesimo. (Secondi: 1...14) Riduzione del costo energetico delle tue magie del Mistico: 5. Costo minimo: 1 Punto Energia.'],
311=>['Assorbi Condizioni','Magia. Tutte le condizioni negative che hanno colpito l\'alleato vengono trasferite su di te. Per ogni condizione acquisita ottieni 6...26 Punto[i] Salute.','Magia. Trasferisce tutte le condizioni dall\'obiettivo alleato a te stesso. Effetto del trasferimento: ottieni 6...26 Punto[i] Salute per ogni condizione. Impossibile selezionare se stessi.'],
312=>['Colpo Sacro','Abilità. L\'obiettivo nemico toccato subisce 10...55 danno[i] sacro[i]. Se è a terra subisce inoltre 10...55 danno[i] sacro[i].','Abilità a Tocco. Danni sacri inferti: 10...55. Danni sacri aggiuntivi se l\'obiettivo è stato abbattuto: 10...55.'],
313=>['Tocco Curativo','Magia. Curi l\'alleato toccato di 20...80 Punto[i] Salute; raddoppia la quantità di Salute ottenuta con il Favore Divino.','Magia a Tocco. Cure: 20...80. Raddoppia il guadagno di Salute relativo al Favore Divino.'],
314=>['Ripristino Vita','Magia. Tocca il corpo di un membro della squadra caduto per riportarlo in vita con un 20...65% di Punto[i] Salute e 42...90% di Punto[i] Energia.','Magia a Tocco. Fa risorgere il membro della squadra selezionato. (Salute: 20...65%; Energia: 42...90%).'],
315=>['Vendetta','Incantesimo. Riporti in vita un membro della squadra morto, con Salute ed Energia al massimo, che per 30 secondi infligge un 25% di danni in più. Quando questo incantesimo termina, il membro della squadra muore. Morire mentre si è sotto il suo effetto non comporta Debilitazione.','Incantesimo. (Secondi: 30) Fa risorgere il membro della squadra selezionato (piena Salute e piena Energia). Quest\'alleato assesta un 25% in più di danni e non subisce Debilitazione. Effetto al termine: quest\'alleato muore.'],
316=>['All\'Ultimo Sangue!','Urlo. Per ogni nemico a portata d\'orecchio (max 1...6), ottieni una dose di adrenalina. Per 10...20 secondo[i], la tua Salute massima aumenta di 10...60 punto[i].','Urlo. (Secondo[i]: 10...20). Salute massima: +10...60. Effetto iniziale: ottieni una dose di adrenalina per ogni nemico a portata d\'orecchio (max 1...6).'],
317=>['Furia della Battaglia','Posizione d\'Élite. Per 5...20 secondo[i], la tua velocità aumenta di un 33% e ottieni doppia adrenalina dagli attacchi. La Furia della Battaglia termina se utilizzi abilità che non necessitano adrenalina.','Posizione d\'Élite. (Secondi: 5...20) Incremento tua velocità di movimento: 33%. Ottieni il doppio di adrenalina dagli attacchi. Termina se usi abilità che non necessitano adrenalina.'],
318=>['Sfida al Dolore','Abilità d\'Élite. Per 20 secondi ottieni 90...300 Punti Salute in più, 20 punti armatura in più e subisci 1...10 danni in meno.','Abilità d\'Élite. (Secondi: 20) Tua Salute massima: +90...300. Armatura: +20. Riduzione danni subiti: -1...10.'],
319=>['Fretta','Posizione. Per 8...20 secondo[i], la tua velocità aumenta del 25%.','Posizione. (Secondi: 8...20) Incremento tua velocità di movimento: 25%.'],
320=>['Azzoppamento','Attacco con Spada. Se questo attacco va a segno, l\'obiettivo diventa storpio per 3...15 secondo[i] e si muove più lentamente.','Attacco con Spada. Condizione inflitta: Storpiatura (3...15 secondo[i]).'],
321=>['Colpo Selvaggio','Attacco Ravvicinato. Perdi tutta l\'Adrenalina. Se va a segno, questo attacco produce un colpo critico e fa terminare qualsiasi Posizione utilizzata dal tuo obiettivo. Questo attacco non può essere bloccato.','Attacco Ravvicinato. Risulta sempre in un colpo critico. Rimuove una posizione. Non bloccabile.Perdi tutta l\'adrenalina.'],
322=>['Attacco Potente','Attacco Ravvicinato. Se va a segno, infliggi +10...40 danno[i].','Attacco Ravvicinato. Danni inferti: +10...40.'],
323=>['Colpo della Disperazione','Attacco Ravvicinato. Se questo attacco va a segno, infliggi +10...40 danno[i] e l\'obiettivo è affetto da una delle seguenti condizioni: Ferita Profonda (per 20 secondi), Debolezza (per 20 secondi), Emorragia (per 25 secondi) o Storpiatura (per 15 secondi). Dopo aver sferrato il Colpo della Disperazione, cadi a terra.','Attacco Ravvicinato. Danni inferti: +10...40. Provoca una condizione a caso tra le seguenti: Ferita Profonda (20 secondi), Debolezza (20 secondi), Emorragia (25 secondi), Storpiatura (15 secondi). Vieni abbattuto.'],
324=>['Brivido della Vittoria','Attacco Ravvicinato. Se l\'attacco va a segno, infliggi +20...40 di danni. Se la tua Salute è superiore a quella dell\'obiettivo nemico, ottieni 1...2 dose[i] di adrenalina.','Attacco Ravvicinato. Danni inferti: +20...40. Se la tua Salute è superiore a quella dell\'obiettivo, ottieni 1...2 dose[i] di adrenalina.'],
325=>['Colpo Distraente','Attacco Ravvicinato. Agita la tua arma in direzione dell\'obiettivo, senza infliggergli danni ma interrompendo la sua azione corrente (e quella di tutti i nemici a lui adiacenti).','Attacco Ravvicinato. L\'attacco ha effetto anche sui nemici adiacenti al tuo obiettivo. Interrompe un\'azione. Colpisce senza infliggere danni.'],
326=>['Colpo del Protettore','Attacco Ravvicinato. Se questo attacco colpisce un nemico in movimento, infliggi 10...40 danno[i] in più.','Attacco Ravvicinato. Danni aggiuntivi se il nemico si sta muovendo: +10...40.'],
327=>['Colpo del Grifone','Attacco Ravvicinato. Se questo attacco va a segno, infliggi +5...20 danno[i]. Se l\'attacco è bloccato, l\'obiettivo viene abbattuto e subisce 10...34 danno[i].','Attacco Ravvicinato. Danni inferti: +5...20. Provoca abbattimento e infligge 10...34 danno[i] se bloccato.'],
328=>['Colpo Puro','Attacco con Spada. Se il Colpo Puro va a segno, infliggi +1...30 danno[i]. Se non stai utilizzando una Posizione, il Colpo Puro non può essere bloccato.','Attacco con Spada. Danni inferti: +1...30. Non bloccabile, a meno che non ti trovi in una posizione.'],
329=>['Rompi Cranio','Attacco d\'Élite Ravvicinato. Se colpisce, questo attacco interrompe l\'azione in corso del personaggio. Se il nemico sta lanciando un incantesimo, resta stordito per 15 secondi.','Attacco d\'Élite Ravvicinato. Interrompe un\'azione. Se il bersaglio sta lanciando una magia, viene stordito (15 secondi).'],
330=>['Ascia Ciclone','Attacco con Ascia. Effettua un attacco circolare con un\'ascia e infliggi +4...12 danno[i] contro tutti gli avversari adiacenti.','Attacco con Ascia. Danni a tutti i nemici adiacenti a te: +4...12.'],
331=>['Colpo di Martello','Attacco con Martello. Perdi tutta l\'adrenalina. Se il Colpo di Martello va a segno, l\'obiettivo finisce a terra.','Attacco con Martello. Provoca abbattimento. Perdi tutta l\'adrenalina.'],
332=>['Colpo del Toro','Attacco Ravvicinato. Se questo attacco colpisce un nemico in movimento, infliggi +5...30 danno[i] e l\'obiettivo cade.','Attacco Ravvicinato. Assesta +5...30 danno[i] e provoca abbattimento se l\'obiettivo nemico si sta muovendo.'],
333=>['Ti Vendicherò!','Urlo. Per ogni alleato morto, ottieni una Rigenerazione della Salute di +3...7 per 10 secondi e la tua velocità d\'attacco aumenta del 25%.','Urlo. Rigenerazione tua Salute: +3...7. Incremento tua velocità d\'attacco: 25% (10 secondi per ogni alleato morto).'],
334=>['Ascia Rastrello','Attacco con Ascia. Se questo attacco va a segno su un obiettivo nemico affetto dalla Ferita Profonda, infliggi +4...16 danno[i] e il nemico diventa storpio per 15 secondi.','Attacco con Ascia. Danni inferti: +4...16. Condizione inflitta se l\'obiettivo nemico ha una Ferita Profonda: Storpiatura (15 secondi).'],
335=>['Fessura','Attacco d\'Élite con Ascia. Se l\'attacco va a segno, infliggi +10...40 danni e colpisci 1...2 nemico/i adiacente/i con 10...40 danni taglienti.','Attacco d\'Élite con Ascia. Infligge +10...40 danni e colpisce 1...2 nemico/i adiacente/i con 10...40 danni taglienti.'],
336=>['Colpo del Boia','Attacco con Ascia. Se va a segno, infliggi +15...45 danno[i].','Attacco con Ascia. Danni inferti: +15...45.'],
337=>['Smembramento','Attacco con Ascia. Se va a segno, questo colpo d\'ascia infligge una Ferita Profonda all\'obiettivo nemico e la sua Salute massima diminuisce del 20% per 5...20 secondo[i].','Attacco con Ascia. Condizione inflitta: Ferita Profonda (5...20 secondo[i]).'],
338=>['Squartamento','Attacco d\'Élite con Ascia. Se va a segno, infliggi +10...45 danno[i] e una Ferita Profonda; la sua Salute massima diminuisce del 20% per 5...20 secondo[i].','Attacco d\'Élite con Ascia. Danni inferti: +10...45. Condizione inflitta: Ferita Profonda (5...20 secondo[i]).'],
339=>['Colpo Penetrante','Attacco con Ascia. Se va a segno infliggi +10...25 danno[i]. Questo attacco con l\'ascia ha il 20% di capacità di penetrazione delle armature.','Attacco con Ascia. Danni inferti: +10...25. Penetrazione armatura: 20%.'],
340=>['Fendente Dirompente','Attacco con Ascia. Se va a segno, questo attacco interrompe l\'azione corrente dell\'obiettivo; se si trattava di un\'abilità, questa viene disattivata per altri 20 secondi.','Attacco con Ascia. Interrompe un\'azione. Effetto dell\'interruzione: l\'abilità interrotta viene disattivata per +20 secondi.'],
341=>['Fendente Rapido','Attacco con Ascia. Se l\'attacco va a segno, infliggi +1...20 di danni. Se il Fendente Rapido viene bloccato, l\'obiettivo nemico subisce 1...20 danni ed è affetto da Ferita Profonda per 20 secondi.','Attacco con Ascia. Danni inferti: +1...20. Assesta 1...20 danno[i] e provoca Ferita Profonda (20 secondi) se è bloccato.'],
342=>['Manovra d\'Ascia','Attacco con Ascia. Se questo attacco va a segno su un nemico affetto da una Ferita Profonda, infliggi 5...25 danno[i] in più e il nemico viene colpito da Debolezza per 20 secondi.','Attacco con Ascia. Danni inferti: +5...25. Condizione inflitta: Debolezza (20 secondi) se l\'obiettivo nemico ha una Ferita Profonda.'],
343=>['Giustizia è Fatta!','Urlo. Per 20 secondi, ogni volta che consegui Adrenalina ne ottieni un 100% in più.','Urlo. (Secondi: 20) Adrenalina conseguita in più: 100%.'],
344=>['Folata di Colpi','Posizione. Per 5 secondi, la tua velocità d\'attacco aumenta del 33%, ma infliggi il 25% di danni in meno.','Posizione. (Secondi: 5) Incremento tua velocità di attacco: 33%. Provochi un 25% di danni in meno.'],
345=>['Posizione Difensiva','Posizione. Per 1...5 secondo[i] hai un 75% di probabilità di bloccare gli attacchi ravvicinati e proiettile. Al termine dell\'effetto di Posizione Difensiva, ottieni una dose di adrenalina per ogni abilità di attacco ravvicinato che possiedi (max 0...4).','Posizione. (Secondo[i]: 1...5) Probabilità di blocco: 75%. Effetto al termine: ottieni una dose di adrenalina per ogni abilità di attacco ravvicinato che possiedi (max 0...4).'],
346=>['Frenesia','Posizione. Per 8 secondi i tuoi attacchi sono più veloci del 33%, ma subisci il 175...125% dei danni.','Posizione. (8 secondi) I tuoi attacchi sono più veloci del 33%. Subisci il 175...125% dei danni.'],
347=>['Sopporta Dolore','Abilità. Per 7...18 secondo[i] hai 90...300 Punto[i] Salute in più.','Abilità. (Secondi: 7...18) Tua Salute massima: +90...300.'],
348=>['In Guardia!','Urlo. I membri della squadra a portata d\'orecchio ottengono +5...25 di armatura per 10 secondo[i]. Questo urlo termina dopo 10 attacchi in arrivo.','Urlo. (Secondi: 10) Incremento armatura dei membri della squadra a portata d\'orecchio: 5...25. Termina dopo 10 attacchi in arrivo.'],
349=>['Scatto','Posizione. Per 8...14 secondo[i], la tua velocità aumenta del 25%.','Posizione. (Secondi: 8...14) Incremento tua velocità di movimento: 25%.'],
350=>['Spanciata','Attacco con Martello. Se questo attacco colpisce un nemico che si trova a terra, la nube di polvere che si sprigiona acceca i nemici adiacenti per 3...7 secondo[i].','Attacco con Martello. Condizione inflitta ai nemici adiacenti se l\'obiettivo nemico è abbattuto: Accecamento (3...7 secondo[i]).'],
351=>['Colpo Possente','Attacco con Martello. Se va a segno, infliggi +10...40 danno[i].','Attacco con Martello. Danni inferti: +10...40.'],
352=>['Schiacciata','Attacco con Martello. Se questo attacco va a segno, infliggi +1...20 danno[i]. Se colpisci un nemico abbattuto, infliggi una Ferita Profonda che riduce la Salute massima dell\'obiettivo del 20% per 5...20 secondo[i].','Attacco con Martello. Danni inferti: +1...20. Condizione inflitta se l\'obiettivo nemico è abbattuto: Ferita Profonda (5...20 secondo[i]).'],
353=>['Fendente Crudele','Attacco con Martello. Colpisce tutti i nemici adiacenti. Ogni obiettivo nemico colpito subisce +1...20 danno[i].','Attacco con Martello. Attacca tutti i nemici adiacenti infliggendo +1...20 danno[i].'],
354=>['Scuoti-terra','Attacco d\'Élite con Martello. L\'obiettivo nemico e tutti i nemici adiacenti vengono abbattuti (50% di probabilità di fallimento con Abilità col Martello di livello 4 o inferiore).','Attacco d\'Élite con Martello. Abbatte l\'obiettivo e i nemici adiacenti. Probabilità di fallimento: 50% se il grado di Abilità col Martello è inferiore a 5.'],
355=>['Martello Devastante','Attacco d\'Élite con Martello. Se colpisce, l\'obiettivo cade a terra ed è colpito da Debolezza per 5...20 secondo[i].','Attacco d\'Élite con Martello. Provoca abbattimento. Condizione inflitta: Debolezza (5...20 secondo[i]).'],
356=>['Colpo Irresistibile','Attacco con Martello. Se questo attacco va a segno, infliggi +5...20 danno[i]. Se Colpo Irresistibile viene bloccato, il tuo obiettivo finisce a terra e subisce 5...20 danno[i].','Attacco con Martello. Danni inferti: +5...20. Assesta 5...20 danno[i] e provoca abbattimento se bloccato.'],
357=>['Colpo di Rimando','Attacco con Martello. Se colpisce un nemico all\'attacco, lo getta a terra.','Attacco con Martello. Provoca abbattimento se l\'obiettivo nemico sta attaccando.'],
358=>['Spezza-schiena','Attacco d\'Élite con Martello. Se Spezza-schiena va a segno, infliggi +1...20 danno[i] e il nemico va a terra. Se la tua Forza è uguale o superiore a 8, il nemico resta a terra per 4 secondi.','Attacco d\'Élite con Martello. Danni inferti: +1...20. Provoca abbattimento. Il nemico resta a terra per 4 secondi se la tua Forza è uguale o superiore a 8.'],
359=>['Colpo Pesante','Attacco con Martello. Perdi tutta l\'adrenalina. Se colpisci un nemico che soffre di Debolezza, questo viene abbattuto e tu infliggi +1...30 danno[i].','Attacco con Martello. Se l\'obiettivo nemico soffre di Debolezza assesta +1...30 danno[i] e provoca abbattimento. Perdi tutta l\'adrenalina.'],
360=>['Colpo Travolgente','Attacco con Martello. Se questo colpo di martello va a segno, l\'obiettivo viene colpito da Debolezza per 5...20 secondo[i].','Attacco con Martello. Condizione inflitta: Debolezza (5...20 secondo[i]).'],
361=>['Sigillo di Dolyak','Sigillo. Per 8...20 secondo[i], hai +10...40 armatura e non puoi essere abbattuto, ma i tuoi movimenti vengono rallentati del 75%.','Sigillo. (Secondi: 8...20) Armatura: +10...40. Non puoi essere abbattuto. Rallentamento dei tuoi movimenti: 75%.'],
362=>['Astuzia del Guerriero','Abilità. Per 5...11 secondo[i], i tuoi attacchi ravvicinati non possono essere bloccati.','Abilità. (Secondi: 5...11) I tuoi attacchi ravvicinati non sono bloccabili.'],
363=>['Colpo di Scudo','Abilità. Per 5...11 secondo/i, purché impugni uno scudo, blocchi l\'abilità in mischia successiva che subisci, atterri l\'attaccante e la sua abilità viene disattivata per 15 secondi in più.','Abilità. (5...11 secondo/i) Blocchi l\'abilità di attacco successiva. Atterri il nemico e la ricarica della sua abilità aumenta di +15 secondi. Nessun effetto senza scudo.'],
364=>['Carica!','Urlo d\'Élite. Tutti gli alleati a portata d\'orecchio perdono la condizione Storpiatura. Per 5...13 secondo[i], la tua velocità aumenta del 33%.','Urlo d\'Élite. (Secondo[i]: 5...13). La velocità di movimento degli alleati a portata d\'orecchio aumento di un 33%. Effetto iniziale: gli alleati perdono la condizione Storpiatura.'],
365=>['La Vittoria è Mia!','Urlo d\'Élite. Ottieni 10...68 Punto[i] Salute e 3...7 Punto[i] Energia per ogni condizione presente sull\'obiettivo nemico.','Urlo d\'Élite. Salute 10...68 e Energia 3...7 per ogni condizione presente sull\'obiettivo nemico.'],
366=>['Temi la Mia Ira!','Urlo. Tutti i nemici nei dintorni perdono 2...6 Punto[i] Energia. Per 1...15 secondo[i], i tuoi attacchi ravvicinati hanno +5...30% probabilità di assestare un colpo critico contro nemici fermi.','Urlo. (Secondo[i]: 1...15). Hai un +5...30% di probabilità di effettuare un colpo critico con un attacco ravvicinato contro un nemico fermo. Effetto iniziale: i nemici nei dintorni perdono 2...6 Punto[i] Energia.'],
367=>['In Alto gli Scudi!','Urlo. Per 5...11 secondo[i], tu e tutti i membri della squadra a portata d\'orecchio ottenete +60 punto[i] di armatura contro gli attacchi proiettile in arrivo.','Urlo. (Secondi: 5...11) Armatura dei membri della squadra a portata d\'orecchio contro gli attacchi proiettile: +60.'],
368=>['Io Sopravviverò!','Urlo. Ottieni +3 di Rigenerazione della Salute per ogni condizione da cui sei affetto. Questa Rigenerazione si esaurisce dopo 5...11 secondo[i].','Urlo. (Secondi: 5...11) Rigenerazione Salute per ogni condizione presente su di te: +3.'],
370=>['Posizione del Guerriero Furioso','Posizione. Per 8...14 secondo/i, attacchi il 33% più velocemente e ottieni il 100% in più di adrenalina. La posizione Berserker termina se usi un\'abilità.','Posizione. (8...14 secondo/i). Attacchi il 33% più velocemente e ottieni il 100% in più di adrenalina. Termina se usi un\'abilità.'],
371=>['Posizione Bilanciata','Posizione. Per 8...20 secondo[i] non puoi essere abbattuto e non subisci danni extra dagli attacchi critici.','Posizione. (Secondi: 8...20) Non puoi essere abbattuto e non subisci danni extra dai colpi critici.'],
372=>['Difesa del Gladiatore','Posizione d\'Élite. Per 5...11 secondo[i] hai una probabilità del 75% di bloccare gli attacchi in arrivo. Ogni volta che blocchi un attacco ravvicinato in questo modo, l\'attaccante subisce 5...35 danno[i].','Posizione d\'Élite. (Secondi: 5...11) Probabilità di blocco: 75%. Il tuo aggressore subisce 5...35 danno[i] ogni volta che blocchi un attacco in mischia in questo modo.'],
373=>['Devia Frecce','Posizione. Per 1...6 secondo[i] hai un 75% di probabilità di bloccare gli attacchi. Se blocchi un attacco proiettile, i nemici adiacenti subiscono danni da Emorragia per 5...15 secondo[i].','Posizione. (Secondo[i]: 1...6). Probabilità di blocco: 75%. Per 5...15 secondo[i] i nemici adiacenti subiscono danni da Emorragia quando blocchi un attacco proiettile.'],
374=>['Resistenza del Guerriero','Abilità d\'Élite. Per 5...35 secondo[i], ottieni 3 Punti Energia ogni volta che colpisci nel corpo a corpo; la tua Energia non può aumentare al di sopra di 10...25.','Abilità d\'Élite. (Secondi: 5...35) Energia conseguita ogni volta che un tuo attacco in mischia va a segno: 3. Non consegui Energia se ne hai più di 10...25 punto[i].'],
375=>['Posizione di Combattimento del Nano','Posizione d\'Élite. Per 5...11 secondo[i], se utilizzi un martello, attacchi un 33% volta[e] più velocemente, ottieni +40 di armatura e se utilizzi un\'abilità di attacco per colpire un nemico, interrompi la sua azione.','Posizione d\'Élite. (Secondo[i]: 5...11). Attacchi 33% volta[e] più velocemente, ottieni +40 di armatura e se utilizzi un\'abilità di attacco per colpire un nemico, interrompi la sua azione. Ha effetto solo se si è equipaggiati con un martello.'],
376=>['Posizione Disciplinata','Posizione. Per 1...4 secondo[i], ottieni +10 di armatura e hai una probabilità del 75% di bloccare gli attacchi. La Posizione Disciplinata termina se usi un\'abilità che richiede adrenalina.','Posizione. (Secondo[i]: 1...4) Probabilità di blocco: 75% Armatura: +10. Termina se usi un\'abilità che richiede adrenalina.'],
377=>['Posizione di Guardia','Posizione. Per 1...6 secondo[i], blocchi qualsiasi abilità d\'attacco usata contro di te. Per ogni parata effettuata con successo, ottieni adrenalina e 5 Punti Energia; termina se usi un\'abilità.','Posizione. (1...6 secondo[i]). Blocchi le abilità d\'attacco. Ottieni adrenalina e 5 Punti Energia per ogni blocco. Termina se usi un\'abilità.'],
378=>['Posizione dello Scudo','Posizione. Per 1...6 secondo[i], se utilizzi uno scudo, hai un 75% di probabilità di bloccare un attacco in arrivo e il danno viene ridotto di 2 per ogni punto di Forza (riduzione danno max: 15).','Posizione. (Secondo[i]: 1...6). Probabilità di blocco: 75%. Il danno viene ridotto di 2 per ogni punto di Forza (riduzione danno max: 15). Ha effetto solo se si è equipaggiati con uno scudo.'],
379=>['Carica del Toro','Posizione d\'Élite. Per 1...7 secondo/i, ti muovi più velocemente del 50% e se colpisci in mischia un nemico in movimento, quel nemico viene atterrato. La Carica del Toro termina se usi un\'abilità.','Posizione d\'Élite. (1...7 secondo/i). Ti muovi il 50% più velocemente. Se colpisci in mischia un nemico in movimento, lo atterri. Termina se usi un\'abilità.'],
380=>['Difesa di Bonetti','Posizione. Per 5...11 secondo[i] hai il 75% di probabilità di bloccare gli attacchi ravvicinati e proiettili. Ottieni 5 Punti Energia per ogni attacco ravvicinato parato con successo; termina se utilizzi un\'abilità.','Posizione. (Secondi: 5...11) Probabilità di blocco: 75%. Energia conseguita per ogni attacco in mischia bloccato: 5. Termina se usi un\'abilità.'],
381=>['Cento Lame','Abilità d\'Élite. Per 15 second[i], ogni volta che attacchi con una spada, tutti i nemici adiacenti subiscono 10...35 danno[i] da taglio.','Abilità d\'Élite. (Secondo[i]: 15) Danni da taglio inferti a tutti i nemici adiacenti: 10...35 ogni volta che attacchi con una spada.'],
382=>['Arteria Recisa','Attacco con Spada. Se questo attacco va a segno, l\'avversario viene colpito da Emorragia per 5...25 secondo[i] e perde Salute nel tempo.','Attacco con Spada. Condizione inflitta: Emorragia (5...25 secondo[i]).'],
383=>['Fendente di Galrath','Attacco con Spada. Questo attacco infligge +1...40 danno[i] se va a segno.','Attacco con Spada. Danni inferti: +1...40.'],
384=>['Taglio Profondo','Attacco con Spada. Se colpisci un obiettivo nemico che soffre di Emorragia, infliggi 5...20 danno[i] in più e il nemico riceve una Ferita Profonda, che riduce la sua Salute massima del 20% per 5...20 secondo[i].','Attacco con Spada. Danni inferti: +5...20. Condizione inflitta se l\'obiettivo è affetto da Emorragia: Ferita Profonda (5...20 secondo[i]).'],
385=>['Affondo Finale','Attacco con Spada. Perdi tutta l\'adrenalina. Se va a segno, infliggi 5...40 danno[i] in più. Questo danno si raddoppia se l\'obiettivo ha meno del 50% di Salute.','Attacco con Spada. Danni inferti: +5...40. Se la Salute dell\'obiettivo nemico è inferiore al 50% assesta +5...40 danno[i] in più. Perdi tutta l\'adrenalina.'],
386=>['Lama che Cerca','Attacco con Spada. Se questo attacco va a segno, infliggi +1...20 danno[i]. Se Lama che Cerca viene bloccata, il tuo obiettivo inizia a sanguinare per 25 secondi e subisce 1...20 danno[i].','Attacco con Spada. Danni inferti: +1...20. Assesta 1...20 danno[i] e provoca Emorragia (25 secondi) se bloccato.'],
387=>['Replica','Abilità. Per 8 secondi, mentre brandisci una spada, blocchi l\'attacco ravvicinato successivo lanciato contro di te e il tuo aggressore subisce 20...80 danno[i].','Abilità. (Secondi: 8) Blocchi il prossimo attacco in mischia e l\'aggressore subisce 20...80 danno[i]. Ha effetto solo se brandisci una spada.'],
388=>['Replica Mortale','Abilità. Per 8 secondi, mentre brandisci una spada, blocchi l\'attacco ravvicinato successivo lanciato contro di te e il tuo aggressore subisce 15...90 danno[i] e viene colpito da Emorragia per 3...25 secondo[i].','Abilità. (Secondi: 8) Blocchi il prossimo attacco in mischia e l\'aggressore subisce 15...90 danno[i]. Condizione inflitta: Emorragia (3...25 secondo[i]). Ha effetto solo se brandisci una spada.'],
389=>['Fioritura','Abilità d\'Élite. Tutte le tue abilità d\'attacco vengono ricaricate. Ottieni 2...7 Punto[i] Energia per ogni abilità ricaricata dalla Fioritura.','Abilità d\'Élite. Ricarica le tue abilità d\'attacco. Energia conseguita per ogni abilità ricaricata: 2...7.'],
390=>['Fendente Selvaggio','Attacco con Spada. Se questo attacco va a segno, l\'azione dell\'obiettivo nemico viene interrotta. Se tale azione era una magia, infliggi 1...40 danni aggiuntivi.','Attacco con Spada. Interrompe un\'azione. Effetto dell\'interruzione: assesta +1...40 danno[i] se l\'azione era una magia.'],
391=>['Tiro del Cacciatore','Attacco con Arco. Se il Tiro del Cacciatore va a segno, l\'obiettivo inizia a sanguinare per 3...25 secondi.','Attacco con Arco. Condizione inflitta: Emorragia (3...25 secondi).'],
392=>['Inchioda','Attacco con Arco. Se va a segno, l\'obiettivo nemico diventa storpio per 3...15 secondo[i].','Attacco con Arco. Condizione inflitta: Storpiatura (3...15 secondo[i]).'],
393=>['Tiro Azzoppante','Attacco con Arco d\'Élite. Se Tiro Azzoppante va a segno, l\'obiettivo diventa Storpio per 4...14 secondo[i]. Questo attacco non può essere bloccato.','Attacco con Arco d\'Élite. Non bloccabile. Condizione inflitta: Storpiatura (4...14 secondo[i]).'],
394=>['Tiro Potente','Attacco con Arco. Se va a segno, l\'obiettivo nemico subisce 25...50 di danni.','Attacco con Arco. Danni subiti dall\'obiettivo nemico: 25...50.'],
395=>['Raffica','Attacco con Arco d\'Élite. Rimuove tutte le tue Preparazioni. Tira frecce all\'obiettivo nemico e fino a un massimo di 5 nemici adiacenti. Se colpiscono l\'obiettivo, le frecce infliggono +5...20 di danni.','Attacco con Arco d\'Élite. Danni inferti: +5...20. Colpisce 5 nemici adiacenti al tuo obiettivo. Rimuove tutte le tue Preparazioni.'],
396=>['Doppio Tiro','Attacco con Arco. Scocca due frecce simultaneamente contro il nemico. Le frecce infliggono il 25% di danni in meno.','Attacco con Arco. Scocchi due frecce simultanee contro l\'obiettivo nemico. Queste frecce assestano un 25% di danno in meno.'],
397=>['Tiro Rapido','Attacco con Arco d\'Élite. Scocca una freccia che si muove al doppio della velocità.','Attacco con Arco d\'Élite. Scocchi una freccia che si muove al doppio della velocità.'],
398=>['Attacco Penetrante','Attacco con Arco. Se va a segno, questo attacco provoca +5...25 danno[i] e ha un 10% di capacità di penetrazione delle armature.','Attacco con Arco. Danni inferti: +5...25. Penetrazione armatura: 10%.'],
399=>['Tiro Distraente','Attacco con Arco. Se va a segno, interrompe l\'azione dell\'obiettivo nemico, ma infligge solo 1...16 danno[i]. Se l\'azione interrotta era un\'abilità, questa viene disattivata per altri 20 secondi.','Attacco con Arco. Interrompe un\'azione. Effetto dell\'interruzione: l\'abilità interrotta viene disattivata per +20 secondo[i]. Assesta solo 1...16 danno[i].'],
400=>['Tiro di Precisione','Attacco con Arco. Se va a segno, infliggi +3...10 danno[i]; non può essere bloccato ma è facile da interrompere.','Attacco con Arco. Danni inferti: +3...10. Non bloccabile. Facile interruzione.'],
402=>['Tiro Determinato','Attacco con Arco. Se colpisce l\'obiettivo, provoca +5...20 danno[i]. Se manca il bersaglio, tutte le abilità d\'attacco vengono ricaricate.','Attacco con Arco. Danni inferti: +5...20. Ricarica le tue abilità d\'attacco se non va a segno.'],
403=>['Tiro Sicuro','Attacco con Arco. Scocca una freccia 3 volte più veloce che non può essere bloccata.','Attacco con Arco. Scocchi una freccia che viaggia al triplo della velocità. Non bloccabile.'],
404=>['Freccia Avvelenata','Attacco con Arco d\'Élite. Se va a segno, avvelena l\'obiettivo per 5...20 secondo[i].','Attacco con Arco d\'Élite. Condizione inflitta: Veleno (5...20 secondo[i]).'],
405=>['Tiro del Giuramento','Attacco con Arco d\'Élite. Se il Tiro del Giuramento va a segno, tutte le tue abilità tranne Tiro del Guramento vengono ricaricate. Se va a vuoto, tutte le tue abilità vengono disattivate per 10...4 secondi. (50% di probabilità di errore con Esperienza 7 o inferiore).','Attacco con Arco d\'Élite. Ricarica tutte le abilità tranne Tiro del Giuramento se va a segno. Disattiva tutte le abilità se manca l\'obiettivo (10...4 secondi). Probabilità di errore: 50% se il grado di Esperienza è inferiore a 8.'],
406=>['Tiro Debilitante','Attacco con Arco. Se va a segno, il tuo obiettivo perde 1...10 Punto[i] Energia.','Attacco con Arco. Perdita Energia: 1...10.'],
407=>['Tiro Ravvicinato','Attacco con Arco. Scocca una freccia che ha una portata pari a metà del normale ma infligge +10...40 danno[i].','Attacco con Arco a Portata Dimezzata. Danni inferti: +10...40.'],
408=>['Tiro Stordente','Attacco con Arco. Se colpisce il nemico mentre sta compiendo una magia, lo interrompe e causa Stordimento per 5...20 secondo[i]. Questo attacco infligge solo 1...16 danno[i].','Attacco con Arco. Interrompe una magia. Effetto dell\'interruzione: infligge Stordimento (5...20 secondo[i]). Provoca solo 1...16 danno[i].'],
409=>['Tiro Punitivo','Attacco con Arco d\'Élite. Se va a segno, infliggi +10...20 danno[i] e l\'obiettivo viene interrotto.','Attacco con Arco d\'Élite. Danni inferti: +10...20. Interrompe un\'azione.'],
411=>['Incanta Animale','Abilità. Incanta l\'animale selezionato, a meno che questo non ti sia superiore di oltre 4 livelli. Una volta incantata, la mascotte viaggerà insieme a te fino a quando manterrai attivo l\'incantesimo Incanta Animale.','Abilità. Incanta l\'animale selezionato, a meno che questo non ti sia superiore di oltre 4 livelli. Una volta incantata, la mascotte viaggerà insieme a te fino a quando manterrai attivo l\'incantesimo Incanta Animale.'],
412=>['Richiamo della Protezione','Urlo. Per 120 secondi, la tua mascotte ha una capacità di riduzione dei danni di base di 5...20.','Urlo. (Secondi: 120) Riduzione danni della tua mascotte: 5...20.'],
415=>['Richiamo della Fretta','Urlo. Per 30 secondi la velocità d\'attacco della tua mascotte aumenta del 33% e la sua velocità di movimento aumenta del 33%.','Urlo. (Secondi: 30). Incremento velocità di movimento e d\'attacco della tua mascotte: 33%.'],
422=>['Resuscita Animale','Abilità. Riporta in vita tutti i compagni animali alleati all\'interno dell\'area. Ritornano in vita con il 10...94% di salute.','Abilità. Riporta in vita tutti gli animali alleati in quest\'area (10...94% di salute).'],
423=>['Legame Simbiotico','Urlo. Per 120...300 secondo[i], la tua mascotte ottiene una Rigenerazione della Salute di 1...3 e la metà di tutti i danni inflitti a lei vengono deviati su di te.','Urlo. (Secondi: 120...300) Rigenerazione Salute della tua mascotte: +1...3. Metà dei danni subiti dalla tua mascotte vengono trasferiti su di te.'],
424=>['Getta Polvere','Abilità. L\'obiettivo nemico toccato e i nemici adiacenti vengono accecati per 3...15 secondo[i].','Abilità a Tocco. Condizione inflitta: Accecamento (3...15 secondo[i]). Ha effetto anche sui nemici adiacenti all\'obiettivo.'],
425=>['Schivata','Posizione. Per 5...11 secondo[i], la tua velocità aumenta del 33% e hai un 27...75% di probabilità di bloccare i proiettili in arrivo; termina se attacchi.','Posizione. (Secondi: 5...11) Incremento tua velocità di movimento: 33%. Probabilità di blocco degli attacchi proiettili: 27...75%. Termina se attacchi.'],
426=>['Tiro Selvaggio','Attacco con Arco. Se va a segno, l\'azione dell\'obiettivo viene interrotta. Se l\'azione era una magia, infliggi +13...28 danno[i].','Attacco con Arco. Interrompe un\'azione. Effetto dell\'interruzione: assesta +13...28 danno[i] se l\'azione era una magia.'],
427=>['Sigillo dell\'Antidoto','Sigillo. Ti libera da Veleno, Malattia, Accecamento e un\'altra condizione.','Sigillo. Ti libera da Veleno, Malattia, Accecamento e un\'altra condizione.'],
428=>['Frecce Incendiarie','Attacco con Arco d\'Élite. Tiri delle frecce all\'obiettivo nemico e ad un massimo di 2 nemico[i] vicini al tuo obiettivo. Questi nemici prendono fuoco per 1...3 secondo[i].','Attacco con Arco d\'Élite. Nemici colpiti vicino all\'obiettivo: 2. Condizione inflitta: Bruciatura (1...3 secondo[i]).'],
429=>['Frecce di Melandru','Preparazione d\'Élite. Per 18 secondi, se le tue frecce vanno a segno provocano Emorragia per 3...25 secondo[i] e, se colpiscono un obiettivo già sotto incantesimo, infliggono +8...28 danno[i].','Preparazione d\'Élite. (Secondi: 18) Condizione inflitta dalle tue frecce: Emorragia (3...25 secondo[i]). Danno ai nemici sotto incantesimo: +8...28.'],
430=>['Scommessa del Tiratore','Preparazione d\'Élite. Per 18 secondo[i], ottieni 5...10 Punto[i] Energia ogni volta che le tue frecce vanno a segno, ma ne perdi 10 se mancano il bersaglio.','Preparazione d\'Élite. (Secondi: 18) Energia conseguita ogni volta che le tue frecce vanno a segno: 5...10. Perdi 10 Punti Energia ogni volta che non vanno a segno.'],
431=>['Frecce Esplosive','Preparazione. Per 24 secondi, le tue frecce esplodono al contatto, infliggendo 3...18 danno[i] da fuoco all\'obiettivo e a tutti i nemici adiacenti.','Preparazione. (Secondi: 24) Danni da fuoco inferti dalle tue frecce: 3...18 all\'obiettivo e ai nemici a lui adiacenti.'],
432=>['Senti il Vento','Preparazione. Per 24 secondi, le tue frecce si muovono a velocità doppia e infliggono 3...10 danno[i] in più.','Preparazione. (Secondi: 24) Danni inferti: +3...10. La velocità delle tue frecce è raddoppiata.'],
433=>['Frecce Infiammabili','Preparazione. Per 24 secondi, le tue frecce infliggono danni da fuoco e colpiscono per 3...24 danno[i] da fuoco in più.','Preparazione. (Secondi: 24) Danni da fuoco inferti: +3...24. Le tue frecce infliggono danni da fuoco.'],
434=>['Gas Soffocante','Preparazione. Per 1...12 secondo[i] le tue frecce infliggono 1...8 danno[i] in più a tutti i nemici adiacenti ed emetteranno del gas soffocante all\'impatto che interromperà le magie nemiche.','Preparazione. (Secondi: 1...12) Danni inferti: +1...8. Diffonde Gas Soffocante sui nemici adiacenti all\'obiettivo. Gas Soffocante interrompe le magie.'],
435=>['Applica Veleno','Preparazione. Dura 24 secondi; i nemici colpiti dai tuoi attacchi fisici vengono avvelenati per 3...15 secondo[i].','Preparazione. (Secondi: 24) Condizione inflitta dai tuoi attacchi fisici: Veleno (3...15 secondo[i]).'],
436=>['Conforta Animale','Abilità. La tua mascotte viene curata di 40...120 Punti Salute. Se è morta, viene resuscitata con un 10...58% di Salute. Se disponi di Conforta Animale, la mascotte potrà viaggiare insieme a te.','Abilità. Salute ottenuta dalla tua mascotte: 40...120. La mascotte resuscita (Salute: 10...58%). Se disponi di Conforta Animale, la mascotte potrà viaggiare insieme a te.'],
437=>['Balzo Bestiale','Attacco con Mascotte. La tua mascotte si cimenta in un Balzo Bestiale che infligge +5...20 danno[i]; se colpisce un nemico che sta compiendo una magia, lo abbatte.','Attacco con Mascotte. Danni inferti: +5...20. Provoca abbattimento se l\'obiettivo nemico sta lanciando una magia.'],
438=>['Attacco Mutilante','Attacco con Mascotte. Il tuo compagno animale prova a mettere a segno un colpo mutilante che infligge +5...20 danni. Se il nemico viene colpito, diventa azzoppato per 3...15 secondo/i.','Attacco con Mascotte. Infligge +5...20 danni. Se colpisce, infligge la condizione Azzoppato (3...15 secondo/i).'],
439=>['Affondo Selvaggio','Attacco con Mascotte. La tua mascotte si cimenta in un Affondo Selvaggio che infligge +5...35 danno[i]; se colpisce un avversario che sta attaccando, gli provoca un\'Emorragia di 5...25 secondo[i].','Attacco con Mascotte. Danni inferti: +5...35. Condizione inflitta se l\'obiettivo nemico sta attaccando: Emorragia (5...25 secondo[i]).'],
440=>['Attacco Predatore','Attacco con Mascotte. La tua mascotte si cimenta in un Attacco Predatore che infligge +10...25 danno[i]; se colpisce un avversario già affetto da una condizione ottieni 3...15 Punto[i] Energia.','Attacco con Mascotte. Danni inferti: +10...25. Energia conseguita se l\'obiettivo nemico è affetto da una condizione: 3...15.'],
441=>['Assalto di Melandru','Attacco con Mascotte. La tua mascotte si cimenta in un Assalto di Melandru che infligge +5...20 di danni a tutti i nemici nei dintorni.','Attacco con Mascotte. Danni ai nemici nei dintorni: +5...20.'],
442=>['Attacco Ferale','Attacco d\'Élite con Mascotte. La tua mascotte si cimenta in un Attacco Ferale che infligge +13...28 danno[i]; se andrà a segno, otterrai Adrenalina e 3...10 Punto[i] Energia.','Attacco d\'Élite con Mascotte. Danni inferti: +13...28. Ottieni adrenalina e 3...10 Punto[i] Energia.'],
443=>['Balzo Predatore','Attacco con Mascotte. La tua mascotte si cimenta in un Balzo Predatore che infligge +5...35 danno[i]; se va a segno, la tua mascotte recupererà 5...50 Punto[i] Salute.','Attacco con Mascotte. Danni inferti: +5...35. Salute conseguita dalla tua mascotte se questo attacco va a segno: 5...50.'],
444=>['Attacco Brutale','Attacco con Mascotte. La tua mascotte si cimenta in un Attacco Brutale che infligge +5...35 danno[i]; se colpisce un avversario la cui Salute è inferiore al 50%, gli infligge anche +5...35 danno[i].','Attacco con Mascotte. Danni inferti: +5...35. Assesta +5...35 danno[i] in più se la Salute dell\'obiettivo nemico è inferiore al 50%.'],
445=>['Scatto Dirompente','Attacco con Mascotte. La tua mascotte si cimenta in uno Scatto Dirompente che infligge +1...12 danno[i]; se colpisce un avversario che sta usando un\'abilità, lo interrompe disabilitandola per 20 secondo[i] in più.','Attacco con Mascotte. Danni inferti: +1...12. Interrompe un\'abilità. Effetto dell\'interruzione: l\'abilità interrotta viene disattivata per +20 secondo[i].'],
446=>['Unguento dei Troll','Abilità. Per 13 secondi, ottieni +3...10 di Rigenerazione della Salute.','Abilità. (Secondi: 13) Rigenerazione tua Salute: +3...10.'],
447=>['Urlo di Otyugh','Urlo. Per 10...25 secondo[i], la tua mascotte ottiene +24 di armatura e non può essere bloccata.','Urlo. (Secondi: 10...25) La tua mascotte ha +24 di armatura e non può essere bloccata.'],
448=>['Fuga','Posizione d\'Élite. Per 1...8 secondo[i], la tua velocità aumenta del 33% e hai una probabilità del 75% di bloccare gli attacchi.','Posizione d\'Élite. (Secondi: 1...8) Incremento della tua velocità di movimento: 33%. Probabilità di blocco: 75%.'],
449=>['Posizione d\'Esercizio','Posizione d\'Élite. Per 20...35 secondo[i], le tue Preparazioni si ricaricano con una velocità maggiore del 50% e durano un 30...300% in più.','Posizione d\'Élite. (Secondi: 20...35) Incremento velocità di ricarica delle tue preparazioni: 50%; incremento della loro durata: 30...300%.'],
450=>['Vortice Difensivo','Posizione. Per 8...20 secondo[i], hai il 75% di probabilità di bloccare gli attacchi. Se blocchi in questo modo un proiettile, i nemici adiacenti ricevono 5...11 danno[i].','Posizione. (Secondi: 8...20) Probabilità di blocco: 75%. Assesta 5...11 danno[i] ai nemici adiacenti ogni volta che blocchi un attacco proiettile.'],
451=>['Recupero di Melandru','Posizione d\'Élite. Per 8...20 secondo[i], ottieni +4 di Rigenerazione Salute e +1 di Rigenerazione Energia per ogni condizione e fattura ricevuta.','Posizione d\'Élite. (Secondi: 8...20) Rigenerazione Salute +4 e Rigenerazione Energia +1 per ogni condizione e fattura che hai addosso.'],
452=>['Difese del Dryder','Posizione. Per 5...11 secondo[i], hai il 75% di probabilità di bloccare gli attacchi e 34...60 di armatura contro i danni elementali.','Posizione. (Secondi: 5...11) Probabilità di blocco: 75%. Armatura contro il danno elementale: +34...60.'],
453=>['Riflessi Fulminei','Posizione. Per 5...11 secondo[i], hai il 75% di probabilità di bloccare gli attacchi ravvicinati e gli attacchi proiettili e la tua velocità d\'attacco aumenta del 33%.','Posizione. (Secondi: 5...11) Incremento della tua velocità d\'attacco: 33%. Probabilità di blocco: 75%.'],
454=>['Furia della Tigre','Posizione. Tutte le tue abilità sono disattivate per 5 secondi (fatta eccezione per le abilità di attacco). Per 5...11 secondo[i], la tua velocità d\'attacco aumenta del 25%.','Posizione. (Secondi: 5...11) Incremento velocità di attacco: 25%. Le tue abilità (attacchi esclusi) vengono disattivate (5 secondi).'],
455=>['Inseguitore della Tempesta','Posizione. Per 8...20 secondo[i] ti muovi con una velocità superiore del 25% e ottieni 1...5 Punto[i] Energia quando subisci danni elementali.','Posizione. (Secondi: 8...20) Incremento velocità di movimento: 25%. Energia conseguita ogni volta che subisci danni elementali: 1...5.'],
456=>['Velocità del Serpente','Posizione. Per 15...30 secondo[i], i tempi di ricarica delle tue abilità si riducono del 33%; termina se la tua Salute scende al di sotto del 50%.','Posizione. (Secondi: 15...30) Incremento velocità di ricarica delle tue abilità: 33%. Termina se la tua Salute scende al di sotto del 50%.'],
457=>['Trappola di Polvere','Trappola. Quando la Trappola di Polvere viene attivata, ogni secondo, per un totale di 5 secondi, tutti i nemici nei dintorni diventano ciechi per 3...8 secondo[i] e subiscono 10...25 danno[i]. Questa abilità è facile da interrompere; termina dopo 90 secondi.','Trappola. (Secondi: 90) Ha effetto sui nemici nei dintorni. Danni inferti al secondo: 10...25 (5 secondi). Condizione inflitta: Accecamento (3...8 secondo[i]) ogni secondo (5 secondi). Facile interruzione.'],
458=>['Trappola Uncinata','Trappola. Quando la Trappola Uncinata viene attivata, tutti i nemici nei dintorni subiscono 7...23 danno[i] perforante[i], diventano Storpi e sono colpiti da Emorragia per 3...25 secondo[i]. Termina dopo 90 secondi. Mentre attivi questa abilità è facile interromperti.','Trappola. (Secondi: 90) Ha effetto sui nemici nei dintorni. Danni perforanti inferti: 7...23. Condizioni inflitte: Storpiatura ed Emorragia (3...25 secondo[i]). Facile interruzione.'],
459=>['Trappola di Fiamme','Trappola. Quando la Trappola di Fiamme viene attivata, ogni secondo, per un totale di 3 secondi, tutti i nemici nei dintorni subiscono 5...20 danno[i] da fuoco e prendono fuoco per 1...3 secondo[i]. Termina dopo 90 secondi. Mentre attivi questa abilità è facile interromperti.','Trappola. (Secondi: 90) Ha effetto sui nemici nei dintorni. Danni da fuoco inferti al secondo: 5...20 (3 secondi). Condizione inflitta: Bruciatura (1...3 secondo[i]). Facile interruzione.'],
460=>['Sorgente Curativa','Trappola. Per 10 secondi, tutti gli alleati adiacenti vengono curati di 15...60 punto[i] ogni 2 secondi. Mentre attivi questa abilità è facile interromperti.','Trappola. (Secondi: 10) Ha effetto sugli alleati adiacenti. Cure impartite ogni 2 secondi: 15...60. Facile interruzione.'],
461=>['Trappola di Spine','Trappola d\'Élite. Quando la Trappola di Spine viene attivata, tutti i nemici presenti nei dintorni subiscono 10...40 danno[i] perforante[i] al secondo (per un totale di 2 secondi), diventano storpi per 3...25 secondo[i] e vengono abbattuti. Termina dopo 90 secondo[i]. Mentre attivi questa abilità è facile interromperti.','Trappola d\'Élite. (Secondi: 90) Ha effetto sui nemici nei dintorni. Provoca 10...40 danno[i] perforante[i] al secondo (per 2 secondi); provoca abbattimento e infligge Storpiatura (3...25 secondo[i]). Facile interruzione.'],
462=>['Inverno','Rituale della Natura. Crei uno Spirito di livello 1...10. Per le creature nei paraggi, tutti i danni elementali diventano danni da freddo. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Trasforma il danno elementale in danno da freddo per le creature nella portata. Non ha effetto sugli Spiriti.'],
463=>['Vaglio','Rituale della Natura. Crei uno Spirito di livello 1...10. Le creature nella sua portata (Spiriti esclusi) subiscono 4 danni aggiuntivi per ogni danno fisico subito. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Incrementa di +4 il danno fisico per le creature nella portata. Non ha effetto sugli Spiriti.'],
464=>['Limite dell\'Estinzione','Rituale della Natura. Crei uno Spirito di livello 1...10. Ogni volta che una creatura (Spiriti esclusi) nella sua portata muore, il Limite dell\'Estinzione infligge 14...50 danno[i] a tutte le creature simili nei dintorni la cui Salute è inferiore al 90% e che si trovano nella portata dello Spirito. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Assesta 14...50 danno[i] alle creature nella portata ogni volta che muore una creatura della stessa specie. Non ha effetto sugli Spiriti. Nessun danno alle creature con Salute superiore al 90%.'],
465=>['Grande Conflagrazione','Rituale della Natura d\'Élite. Crei uno Spirito di livello 1...10. Per le creature nella sua portata (Spiriti esclusi), tutti i danni fisici diventano danni da fuoco. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura d\'Élite. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Trasforma il danno fisico in danno da fuoco per le creature nella portata. Non ha effetto sugli Spiriti.'],
466=>['Conflagrazione','Rituale della Natura. Crei uno Spirito di livello 1...10. Per le creature nella sua portata (Spiriti esclusi) tutte le frecce che vanno a segno infliggono danni da fuoco. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Tutte le frecce assestano danni da fuoco alle creature nella portata. Non ha effetto sugli Spiriti.'],
467=>['Stagione Fertile','Rituale della Natura. Crei uno Spirito di livello 1...10. Le creature nella sua portata (Spiriti esclusi) ottengono +50...150 di Salute massima e +8 di armatura. Lo Spirito si esaurisce dopo 15...90 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 15...90 secondo[i]). Le creature nella portata hanno +50...150 di Salute massima e +8 di armatura. Non ha effetto sugli Spiriti.'],
468=>['Simbiosi','Rituale della Natura. Crei uno Spirito di livello 1...10. Per ogni incantesimo presente su una creatura nella sua portata (Spiriti esclusi), quella creatura riceve +27...150 di Salute massima. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Le creature nella portata hanno +27...150 di Salute massima per ogni incantesimo su di loro. Non ha effetto sugli Spiriti.'],
469=>['Echi Primordiali','Rituale della Natura. Crei uno Spirito di livello 1...10. Per le creature nella sua portata (Spiriti esclusi), i Sigilli costano 10 Punti Energia. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Costo Sigilli per le creature nella portata: 10 Punti Energia. Non ha effetto sugli Spiriti.'],
470=>['Stagione della Caccia','Rituale della Natura. Crei uno Spirito di livello 1...10. Per le creature nella sua portata (Spiriti esclusi), tutte le cure vengono ridotte del 20%. Se uno dei tuoi attacchi va a segno, ottieni 5 Punto[i] Salute. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Le creature nella portata ricevono un 20% in meno di cure. Le creature ottengono 5 Punti Salute ogni volta che un loro attacco va a segno. Non ha effetto sugli Spiriti.'],
471=>['Terreno Gelato','Rituale della Natura. Crei uno Spirito di livello 1...10. Le creature nella sua portata (Spiriti esclusi) non possono attivare le abilità di resurrezione. Lo Spirito si esaurisce dopo 30...180 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...180 secondo[i]). Le creature nella portata non possono attivare abilità di resurrezione. Non ha effetto sugli Spiriti.'],
472=>['Venti Favorevoli','Rituale della Natura. Crei uno Spirito di livello 1...10. Per le creature nella sua portata (Spiriti esclusi), le frecce lanciate si muovono a velocità doppia e infliggono +6 danni. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Le frecce viaggiano al doppio della velocità e provocano +6 danni alle creature nella portata. Non ha effetto sugli Spiriti.'],
474=>['Vento di Energia','Rituale della Natura. Crei uno Spirito di livello 1...6. Per le creature nella sua portata (Spiriti esclusi), tutte le abilità costano 15 Punti Energia in meno (costo minimo 10 Punti Energia) e le abilità si ricaricano con una velocità inferiore del 25%. Lo Spirito si esaurisce dopo 1...60 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...6 (in vita per 1...60 secondo[i]). Riduzione costo delle abilità: 15 Punti Energia in meno (costo minimo 10). Rallentamento velocità di ricarica delle abilità per le creature nella portata: 25%. Non ha effetto sugli Spiriti.'],
475=>['Zefiro Veloce','Rituale della Natura. Crei uno Spirito di livello 1...10. Per le creature nella sua portata (Spiriti esclusi), tutte le abilità si ricaricano ad una velocità doppia e utilizzarle costa il 30% in più dell\'Energia di base. Lo Spirito si esaurisce dopo 15...90 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 15...90 secondo[i]). Incremento costo delle abilità: 30% di Energia in più. Raddoppiamento velocità di ricarica delle abilità per le creature nella portata. Non ha effetto sugli Spiriti.'],
476=>['Rinnovamento della Natura','Rituale della Natura. Crei uno Spirito di livello 1...10. Per 30...240 secondo[i], gli incantesimi e le fatture delle creature (Spiriti esclusi) impiegano il doppio del tempo per essere lanciate e il dispendio di Energia per mantenere gli incantesimi viene raddoppiato. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Per le creature nella portata, i tempi di lancio di incantesimi e fatture si raddoppiano e il mantenimento degli incantesimi costa il doppio di Energia. Non ha effetto sugli Spiriti.'],
477=>['Terreno Fangoso','Rituale della Natura. Crei uno Spirito di livello 1...10. La velocità di tutte le creature nella sua portata (Spiriti esclusi), diminuisce del 10% e gli incrementi di velocità non hanno effetto. Lo Spirito si esaurisce dopo 30...180 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...180 secondo[i]). Rallentamento movimenti delle creature nella portata: 10%; impedisce anche gli incrementi di velocità. Non ha effetto sugli Spiriti.'],
570=>['Marchio di insicurezza','Fattura d\'Élite. Per 5...25 secondo/i, il bersaglio nemico subisce -1...5 Degenerazione della Salute, e gli incantesimi e le posizioni su di esso terminano il 20...60% più rapidamente. Non puoi usare tutte le tue abilità per 5 secondi (escluse quelle da Assassino).','Fattura d\'Élite. (5...25 secondo/i). Provoca -1...5 degenerazione della Salute. Incantesimi e posizioni su di esso terminano il 20...60% più rapidamente. Non puoi usare le tue abilità per 5 secondi (escluse quelle da Assassino).'],
571=>['Pugnale Dirompente','Magia. Scagli contro l\'obiettivo nemico un Pugnale Dirompente che infligge 10...35 danno[i] da terra. Se l\'obiettivo nemico stava attivando un\'abilità, viene interrotto. La portata di questa magia è la metà del normale.','Magia a Portata Dimezzata. Proiettile. Danni da terra: 10...35. Interrompe un\'abilità.'],
572=>['Paradosso Letale','Posizione. Tutte le tue abilità d\'attacco vengono disattivate per 10 secondo[i]. Per 5...15 secondo[i], le tue abilità da Assassino si attivano e ricaricano ad una velocità maggiore del 33%.','Posizione. (Secondi: 5...15) Incremento velocità di attivazione e ricarica delle tue abilità da Assassino: 33%. Disattiva le tue abilità da attacco (10 secondo[i]).'],
763=>['Sguardo Invidioso','Incantesimo. Rimuovi un incantesimo dall\'obiettivo nemico. Se un incantesimo viene rimosso, per 1...20 secondo[i], il prossimo incantesimo che lancerai sarà 0...1 volta[e] più veloce e costerà 1...10 Punto[i] Energia in meno.','Incantesimo. Rimuove un incantesimo dall\'obiettivo nemico. Effetto della rimozione: la velocità del prossimo incantesimo che lancerai sarà maggiore di 0...1 secondo[i] e costerà 1...10 Punto[i] Energia in meno. (Secondo[i]: 1...20).'],
764=>['Lamento del Fato','Fattura d\'Élite. Per 2...6 secondo[i], tutti gli attributi dell\'obiettivo nemico scendono al grado 0.','Fattura d\'Élite. (Secondi: 2...6) Azzera gli attributi dell\'obiettivo nemico scendono al grado 0.'],
766=>['Sguardo di Disprezzo','Magia. Se la Salute dell\'obiettivo nemico è superiore al 50%, questi perde tutti gli incantesimi.','Magia. Rimuove gli incantesimi dall\'obiettivo nemico. Ha effetto solo se la Salute di questo nemico è superiore a 50%.'],
769=>['Difesa della Vipera','Magia. Tutti i nemici adiacenti vengono avvelenati per 5...20 secondi. Compi un Passo nell\'Ombra verso un punto a caso nei dintorni allontanandoti dall\'obiettivo.','Magia. Condizione inflitta a tutti i nemici adiacenti: Avvelenamento (5...20 secondi). Compi un Passo nell\'Ombra verso un punto a caso nei dintorni allontanandoti dall\'obiettivo.'],
770=>['Ritorno','Magia. Tutti i nemici adiacenti diventano storpi per 3...8 secondo[i] e tu compi un Passo nell\'Ombra nella posizione dell\'obiettivo alleato.','Magia. Condizione inflitta a tutti i nemici a te adiacenti: Storpiatura (3...8 secondo[i]). Compi un Passo nell\'Ombra nella posizione dell\'obiettivo alleato. Impossibile selezionare se stessi.'],
771=>['Aura dello Spostamento','Incantesimo d\'Élite. Utilizzando questa abilità compirai un Passo nell\'Ombra per raggiungere l\'obiettivo nemico; quando smetterai di mantenere l\'Aura dello Spostamento, tornerai nella tua posizione iniziale.','Incantesimo d\'Élite. Compi un Passo nell\'Ombra verso l\'obiettivo nemico. Effetto al termine: torni nel punto di partenza.'],
772=>['Tsungrai era Generoso','Magia Altera-oggetto. Mantieni le ceneri di Tsungrai per un massimo di 15...60 secondo[i] ed ottieni +50...140 di Salute massima; quando le lasci cadere ottieni 100...280 Punto[i] Salute.','Magia Altera-oggetto. (Secondi: 15...60) Tua Salute massima: +50...140. Rilascio: ottieni 100...280 Punto[i] Salute.'],
773=>['Vorizun era Potente','Magia Altera-oggetto. Mantieni le ceneri di Vorizun per un massimo di 15...60 secondo[i]; mentre le mantieni ottieni +15 di armatura e +30 di Energia massima.','Magia Altera-oggetto. (Secondi: 15...60) Armatura: +15. Energia massima: +30.'],
775=>['Fiore della Morte','Attacco Doppio[_]. Deve seguire un attacco con arma secondaria. Se va a segno infligge +20...45 danno[i] all\'obiettivo nemico e tutti i nemici adiacenti ricevono 20...45 danno[i].','Attacco Doppio[_]. Danni inferti: +20...45. Ha effetto anche sui nemici adiacenti all\'obiettivo. Deve seguire un attacco con arma secondaria.'],
776=>['Zanne Ritorte','Attacco Doppio[_]. Deve seguire un attacco con arma secondaria. Se va a segno infligge +10...20 danno[i] e l\'obiettivo nemico colpito per 5...20 secondo[i] inizierà a sanguinare e riceverà una Ferita Profonda.','Attacco Doppio[_]. Danni inferti: +10...20. Condizione inflitta: Emorragia e Ferita Profonda (5...20 secondo[i]). Deve seguire un attacco con arma secondaria.'],
777=>['Corna del Bue','Attacco Doppio[_]. Deve seguire un attacco con arma secondaria. Se va a segno infligge +1...11 danno[i]; se il nemico colpito non è adiacente ad alcun alleato, viene abbattuto.','Attacco Doppio[_]. Danni inferti: +1...11. Provoca abbattimento se l\'obiettivo nemico non è adiacente ad un suo alleato. Deve seguire un attacco con arma secondaria.'],
778=>['Ragno in Caduta','Attacco con Arma Secondaria. Deve colpire un nemico a terra. Se va a segno infligge +15...35 danno[i] e l\'obiettivo nemico viene avvelenato per 5...20 secondo[i].','Attacco con Arma Secondaria. Danni inferti: +15...35. Condizione inflitta: Veleno (5...20 secondo[i]). Ha effetto solo se l\'obiettivo nemico è stato abbattuto.'],
779=>['Colpo del Loto Nero','Attacco con Arma Primaria. Se il Colpo del Loto Nero va a segno, infliggi +10...31 danno[i]; se l\'obiettivo nemico è affetto da una fattura, ottieni 5...13 Punto[i] Energia.','Attacco con Arma Primaria. Danni inferti: +10...31. Energia conseguita se l\'obiettivo nemico è affetto da fattura: 5...13.'],
780=>['Denti di Volpe','Attacco con Arma Secondaria. Deve seguire un attacco con arma primaria. I Denti di Volpe non possono essere bloccati e, se vanno a segno, infliggono +10...35 danno[i].','Attacco con Arma Secondaria. Danni inferti: +10...35. Non bloccabile. Deve seguire un attacco con arma primaria.'],
781=>['Colpo di Moebius','Attacco d\'Élite con Arma Secondaria. Deve seguire un attacco doppio. Se va a segno infligge +10...35 danno[i]; se colpisci un nemico la cui Salute è inferiore al 50%, tutte le altre abilità d\'attacco che hai equipaggiato vengono ricaricate.','Attacco d\'Élite con Arma Secondaria. Danni inferti: +10...35. Tutte le altre abilità d\'attacco che hai si ricaricano se la Salute dell\'obiettivo nemico è inferiore al 50%. Deve seguire un attacco doppio.'],
782=>['Colpo Seghettato','Attacco con Arma Primaria. Se va a segno, l\'obiettivo sanguina per 5...20 secondo[i].','Attacco con Arma Primaria. Condizione inflitta: Emorragia (5...20 secondo[i]).'],
783=>['Colpo Fiducioso','Attacco con Arma Primaria. Se questo attacco va a segno, infliggi +19...31 danno[i]; se la Salute dell\'obiettivo è superiore al 90%, infliggi 15...75 danno[i] in più.','Attacco con Arma Primaria. Danni inferti: +19...31. Assesta 15...75 danno[i] in più se la Salute dell\'obiettivo nemico è superiore al 90%.'],
784=>['Aspide Attanagliante','Magia. Deve seguire un attacco con arma primaria. Abbatte l\'obiettivo nemico e lo avvelena per 5...20 secondo[i].','Magia. Provoca abbattimento. Condizione inflitta: Veleno (5...20 secondo[i]). Deve seguire un attacco con arma primaria.'],
785=>['Segno della Morte','Fattura. Per 4...10 secondo[i], l\'obiettivo nemico riceve un 50% in meno di cure.','Fattura. (Secondi: 4...10) L\'obiettivo nemico ottiene un 50% in meno di cure.'],
786=>['Palmo di Ferro','Abilità. L\'obiettivo nemico toccato subisce 5...50 danno[i] e se è affetto da una fattura o da una condizione viene abbattuto. Il Palmo di Ferro viene considerato un attacco con arma primaria.','Abilità a Tocco. Danni inferti: 5...50. Provoca abbattimento se l\'obiettivo nemico è sotto fattura o è affetto da una condizione. Vale come attacco con arma primaria.'],
787=>['Arma Resiliente','Magia Altera-arma. Per 3...12 secondo[i], l\'obiettivo (un alleato o te stesso) riceve un\'Arma Resiliente. Se è affetto da fattura o condizione, ottiene una Rigenerazione della Salute di +1...6 e +24 di armatura.','Magia Altera-arma. (Secondi: 3...12) Rigenerazione Salute: +1...6. Armatura: +24. Ha effetto solo se l\'obiettivo alleato è sotto fattura o è affetto da una condizione.'],
788=>['Mingson era Cieco','Magia Altera-oggetto. Mantieni le ceneri di Mingson per un massimo di 15...60 secondo[i]; quando le lasci cadere, tutti i nemici nei dintorni vengono accecati per 3...8 secondo[i].','Magia Altera-oggetto. (Secondi: 15...60) Rilascio: provoca Accecamento (3...8 secondo[i]) a tutti i nemici nei dintorni.'],
789=>['Kuurong era Avido','Magia d\'Élite Altera-oggetto. Stringi le ceneri di Kuurong fino a 15...60 secondo/i. Quando le lasci cadere, tutti i nemici nell\'area subiscono 15...75 danni e vengono atterrati.','Magia d\'Élite Altera-oggetto. (15...60 secondo/i). Effetto di rilascio: infligge 15...75 danni e atterra tutti i nemici nell\'area.'],
790=>['Khanhei era Vendicativo','Magia d\'Élite Altera-oggetto. Mantieni le ceneri di Khanhei per 5...11 secondo[i]; ogni volta che un nemico ti colpisce mentre hai le ceneri di Khanhei, gli sottrai 10...45 Punto[i] Salute.','Magia d\'Élite Altera-oggetto. (Secondi: 5...11) Salute sottratta ad ogni nemico che ti colpisce con un attacco: 10...45.'],
791=>['Carne della Mia Carne','Magia. Perdi la metà della Salute. Fai resuscitare il membro della squadra selezionato con la tua Salute attuale e un 5...20% di Energia.','Magia. Resuscita il membro della squadra selezionato con metà della tua Salute attuale e un 5...20% di Energia. Perdi metà della tua Salute.'],
792=>['Arma a Frammentazione','Magia Altera-arma. Per 20 secondi, l\'obiettivo alleato ha un\'Arma a Frammentazione e in 1...5 degli attacchi successivi infliggerà 5...50 danni a un massimo di 4 nemici adiacenti.','Magia Altera-arma. (Secondi: 20) Gli attacchi assestano 5...50 danno[i] a 3 nemici adiacenti. Termina dopo 1...5 attacchi.'],
793=>['Arma della Protezione','Magia Altera-arma. Per 3...8 secondi, l\'obiettivo alleato ottiene un\'Arma della Protezione che gli dà una Rigenerazione della Salute di +2...4 e un 50% di probabilità di blocco.','Magia Altera-arma. (secondi: 3...8) Rigenerazione della Salute: +2...4. Probabilità di blocco: 50%.'],
794=>['Arma del Lamento','Magia Altera-arma. Per 3...14 secondo[i], l\'obiettivo (un alleato o te stesso) ha un\'Arma del Lamento; ogni volta che questa colpisce un nemico all\'attacco, lo interrompe.','Magia Altera-arma. (Secondi: 3...14) Gli attacchi interrompono i nemici all\'attacco.'],
795=>['Arma Incubo','Magia Altera-arma. Per 12 secondo[i], l\'obiettivo (un alleato o te stesso) avrà un\'Arma Incubo; il danno inflitto da lui con [il] 3 attacco[hi] successivo[i] viene ridotto di 10...50 e sottrae fino a 10...50 Punto[i] Salute.','Magia Altera-arma. (Secondi: 12) Gli attacchi dell\'obiettivo alleato sottraggono 10...50 Punto[i] Salute ma assestano 10...50 danno[i] in meno. Termina dopo 3 attacchi.'],
799=>['Foschia Accattivante','Magia d\'Élite. Compi un Passo nell\'Ombra verso l\'obiettivo nemico che viene interrotto e rimane stordito per 3...9 secondo[i].','Magia d\'Élite. Compi un Passo nell\'Ombra verso questo nemico. Condizione inflitta: Stordimento (3...9 secondo[i]).'],
800=>['Tossina Permanente','Fattura. Per 5 secondi, l\'obiettivo nemico subisce una Degenerazione della Salute di -1...5. Se si muove nel momento in cui la Tossina Permanente dovrebbe terminare, il suo effetto continua per altri 5 secondi.','Fattura. (Secondi: 5) Degenerazione Salute: -1...5. Rinnovo: se l\'obiettivo nemico si sta muovendo quando termina.'],
801=>['Coltre del Silenzio','Fattura d\'Élite. Per 15 secondi tutte le tue magie vengono disattivate; per 1...6 secondo[i] l\'obiettivo nemico toccato non può lanciare alcuna magia.','Fattura d\'Élite a Tocco. (Secondi: 1...6) L\'obiettivo nemico non può lanciare magie. Le tue magie vengono disattivate per 15 secondi.'],
802=>['Esponi Difese','Fattura. Per 1...11 secondo[i] l\'obiettivo nemico non può bloccare i tuoi attacchi.','Fattura. (Secondi: 1...11) L\'obiettivo nemico non può bloccare i tuoi attacchi.'],
803=>['Sanguisuga del Potere','Fattura d\'Élite. Se l\'obiettivo nemico ha attivato una magia o un canto, l\'abilità viene interrotta e per 10 secondi sottrai al nemico fino a 5...15 Punti Energia ogni volta che lancia una magia.','Fattura d\'Élite. Interrompe una magia o un canto. Effetto dell\'interruzione: sottrazione di 5...15 Punti Energia quando l\'obiettivo nemico lancia una magia (10 secondi).'],
804=>['Languore Arcano','Fattura d\'Élite. Per 1...10 secondi, tutte le magie lanciate dall\'obiettivo nemico provocano 10 di Sforzo.','Fattura d\'Élite. (Secondi: 1...10.) Sforzo provocato dalle magie dell\'obiettivo nemico: 10.'],
805=>['Anima Orrore Vampirico','Magia. Sfrutta il cadavere più vicino per animare un Orrore Vampirico di livello 1...17. Ogni volta che un Orrore Vampirico sotto il tuo controllo infligge dei danni, ottieni una quantità equivalente di Salute.','Magia. Crea un Orrore Vampirico di livello 1...17. Ottieni Salute pari ai danni che assesta. Utilizza un cadavere sfruttabile.'],
806=>['Fervore dell\'Adepto','Incantesimo d\'Élite. Per 5 secondi (più altri 3 secondi per ogni grado di Sottrazione dell\'Anima) le tue magie da Negromante costano 1...6 Punti Energia in meno ma soffri di Emorragia per 10 secondi ogni volta che ne lanci una.','Incantesimo d\'Élite. (Secondi: 5 più altri 3 secondi per ogni grado di Sottrazione dell\'Anima). Le tue magie da Negromante costano 1...6 Punti Energia in meno. Soffri di Emorragia per 10 secondi ogni volta che lanci una magia da Negromante.'],
808=>['Segno del Mietitore','Fattura d\'Élite. Per 30 secondo[i], l\'obiettivo nemico subisce una Degenerazione della Salute di -1...5. Se muore mentre è affetto dalla fattura Segno del Falciatore, ottieni 5...15 Punto[i] Energia.','Fattura d\'Élite. (Secondi: 30) Degenerazione Salute: -1...5. Ottieni 5...15 Punto[i] Energia se l\'obiettivo nemico muore mentre è affetto da questa fattura.'],
809=>['Frammento di Pietra','Fattura d\'Élite. Il nemico colpito subisce 25...100 danni da freddo, si muove più lento del 66%; inoltre, subisce la fattura Spaccapietra per 3 secondi. Quando l\'abilità termina, quel nemico e tutti quelli nelle vicinanze subiscono 25...100 danni da freddo.','Fattura d\'Élite. (3 secondi) Effetto iniziale: infligge 25...100 danni da freddo e il bersaglio si muove più lento del 66%. Fine dell\'effetto: infligge 25...100 danni da freddo al bersaglio e a tutti i nemici vicini.'],
810=>['Difesa del Protettore','Abilità. Per 5...11 secondo[i], gli alleati adiacenti a te hanno una probabilità del 75% di bloccare gli attacchi. La Difesa del Protettore termina se ti sposti.','Abilità. (Secondi: 5...11) Probabilità di blocco degli alleati adiacenti a te: 75%. Termina se ti muovi.'],
811=>['Corsa Congiunta','Posizione. Per 5...15 secondo[i], la velocità tua e della tua mascotte aumenta del 25%.','Posizione. (Secondi: 5...15) Incremento velocità di movimento tua e della mascotte: 25%.'],
812=>['Xinrae era Insolente','Magia d\'Élite Altera-oggetto. Mantieni le ceneri di Xinrae per un massimo di 15...60 secondo[i]; in quel periodo di tempo non puoi perdere più di un 20% della tua Salute massima per ogni colpo ricevuto. Quando lasci cadere le ceneri sottrai 5...50 Punto[i] Salute a tutti i nemici nei dintorni.','Magia d\'Élite Altera-oggetto. (Secondi: 15...60) Non puoi perdere più di un 20% di Salute massima per ogni colpo ricevuto. Rilascio: sottrai 5...50 di Salute ai nemici nei dintorni.'],
813=>['Aura di Lyssa','Incantesimo d\'Élite. Per 10 secondo[i], hai una Rigenerazione Energia di +0...5. Questo incantesimo si riapplica ogni volta che lanci una magia contro un nemico.','Incantesimo d\'Élite. (Secondi: 10) Rigenerazione tua Energia: +0...5. Rinnovo: ogni volta che lanci una magia contro un nemico.'],
814=>['Cortina d\'Ombra','Incantesimo. Per 6 secondo[i] ottieni una Rigenerazione della Salute di 5...10. Quando la Cortina d\'Ombra termina, vieni curato di 40...100 punto[i] se stai attaccando.','Incantesimo. (Secondi: 6) Rigenerazione tua Salute: +5...10. Effetto al termine: ti cura di 40...100 se stai attaccando.'],
815=>['Cavo dello scorpione','Fattura. Per 8...20 secondo/i, la prossima volta che tu e il bersaglio nemico siete a più di 75\' di distanza, usi Passo nell\'ombra su di esso per atterrarlo. Questa magia ha metà della gittata normale.','Fattura a Portata Dimezzata. (8...20 secondo/i). Usa Passo nell\'ombra per colpire il bersaglio nemico e atterrarlo la prossima volta che si trova a più di 75\' da te.'],
816=>['Posizione a Specchio','Fattura. Dura 10...35 secondo[i]; ogni volta che l\'obiettivo nemico assume una posizione, la assumi anche tu.','Fattura. (Secondi: 10...35) Assumi la stessa Posizione utilizzata dall\'obiettivo nemico.'],
817=>['Discordia','Magia d\'Élite. Se l\'obiettivo nemico soffre di una condizione ed è sotto gli effetti di una fattura o di un incantesimo, quell\'obiettivo subisce 30...110 danno[i].','Magia d\'Élite. Danni inferti: 30...110. Ha effetto solo se l\'obiettivo nemico soffre di una condizione ed è affetto da fattura o incantesimo.'],
818=>['Pozzo della Stanchezza','Pozzo. Sfrutta il cadavere bersagliato o sacrifica il 66% della tua salute per creare un Pozzo della Stanchezza per 10...55 secondo/i. I nemici all\'interno dell\'area del Pozzo della Stanchezza soffrono -1 degenerazione dell\'energia.','Pozzo. (10...55 secondo/i). I nemici in questo Pozzo hanno -1 degenerazione dell\'Energia. Utilizza un cadavere fresco o sacrifica il 66% della Salute.'],
819=>['Spirito Vampirico','Incantesimo d\'Élite. Sottrai fino a 15...60 Punto[i] Salute all\'obiettivo nemico. Per 10 secondo[i], hai una Rigenerazione Salute di +5...10.','Incantesimo d\'Élite. Salute sottratta all\'obiettivo nemico: 15...60. Tua Rigenerazione Salute: +5...10 (10 secondo[i]).'],
820=>['Depravazione','Fattura d\'Élite. Per 5...20 secondo[i], ogni volta che un obiettivo nemico lancia una magia, lui e un altro nemico nei dintorni perdono 1...5 Punto[i] Energia.','Fattura d\'Élite. (Secondi: 5...20) Perdita di Energia ogni volta che l\'obiettivo nemico lancia una magia: 1...5. Anche un nemico vicino al tuo obiettivo perde Energia.'],
821=>['Vene di Ghiaccio','Fattura d\'Élite. L\'obiettivo nemico subisce 10...90 danno[i] da freddo. Per 10...35 secondo[i], se l\'obiettivo nemico muore, tutti i nemici nei dintorni vengono colpiti da 20...110 danno[i] da freddo.','Fattura d\'Élite. (Secondi: 10...35) Danni da freddo ai nemici nei dintorni se l\'obiettivo nemico muore: 20...110. Effetto iniziale: 10...90 danno[i] da freddo.'],
822=>['Ginocchia Molli','Fattura d\'Élite. Per 1...16 secondo[i], l\'obiettivo nemico ha una Degenerazione della Salute di -1...4 e subisce 5...20 danni mentre si muove.','Fattura d\'Élite. (Secondi: 1...16) Degenerazione Salute dell\'obiettivo nemico: -1...4. Danni subiti mentre si muove: 5...20.'],
823=>['Velocità Bruciante','Incantesimo. Per 7 secondi, prendi fuoco e la tua velocità aumenta di un 30...45%. Al termine, tutti i nemici adiacenti prendono fuoco per 3...9 secondi.','Incantesimo. (Secondi: 7). Aumento della velocità di movimento: 30...45%. Soffri di Bruciatura (7 secondi). Effetto al termine: infligge Bruciatura (3...9 secondi) ai nemici adiacenti.'],
824=>['Frecce di Lava','Magia. Le Frecce di Lava vengono lanciate su un massimo di 3 nemici vicini al tuo obiettivo infliggendo 20...65 danni da fuoco se vanno a segno.','Magia. Proiettile: danni da fuoco inferti: 20...65. Effetto bonus: lancia proiettili ad altri 2 nemici vicini al tuo obiettivo.'],
825=>['Letto di Brace','Magia. Crea un Letto di Brace in corrispondenza dell\'obiettivo nemico. Per 5 secondi, i nemici adiacenti all\'obiettivo nemico subiscono 5...29 danni da fuoco al secondo. I nemici che sono stati abbattuti sul Letto di Brace prendono fuoco per 3...7 secondi.','Magia. Danni da fuoco inferti al secondo: 5...29 (5 secondi) in corrispondenza dell\'obiettivo nemico. Colpisce i nemici adiacenti al tuo obiettivo. Condizione inflitta ai nemici abbattuti: Bruciatura (3...7 secondi).'],
826=>['Forma d\'Ombra','Incantesimo d\'Élite. Dura 5...21 secondo[i]; non puoi essere colpito da magie nemiche e ottieni una riduzione del danno di 5 per ogni incantesimo Assassino su di te. Non puoi infliggere più di 5...25 danno[i] con un singolo attacco o una singola abilità.','Incantesimo d\'Élite. (Secondo[i]: 5...21). Non puoi essere bersaglio di magie nemiche. Ottieni una riduzione del danno di 5 per ogni incantesimo Assassino lanciato su di te. Non puoi infliggere più di 5...25 danno[i] con un singolo attacco o una singola abilità.'],
827=>['Sifone della Forza','Fattura d\'Élite. Per 5...20 secondo[i], l\'obiettivo nemico infligge -5...50 danno[i] quando attacca e tutti i tuoi attacchi contro di lui hanno un 50% in più di probabilità di essere colpi critici.','Fattura d\'Élite. (Secondi: 5...20) Riduzione danni assestati dall\'obiettivo nemico: -5...50. Aumento probabilità di assestargli un colpo critico: +50%.'],
828=>['Miasma Vile','Fattura. L\'obiettivo nemico subisce 10...65 danno[i] da freddo; se è affetto da una condizione, viene colpito dalla fattura del Miasma Vile e subisce una Degenerazione della Salute di -1...5 per 10 secondo[i].','Fattura. Degenerazione Salute: -1...5 (10 secondo[i]). Effetto iniziale: 10...65 danno[i] da freddo. La fattura si applica solo se l\'obiettivo nemico ha una condizione.'],
830=>['Raggio del Giudizio','Magia d\'Élite. Invochi un Raggio del Giudizio nella posizione dell\'obiettivo nemico. Per 5 secondo[i], i nemici adiacenti a quella posizione vengono colpiti da 10...50 danno[i] sacro[i] e subiscono Bruciatura di 1...3 secondo[i] per ogni secondo.','Magia d\'Élite. Assesta 10...50 danno[i] sacro[i] e infligge Bruciatura (1...3 second[i]) ogni secondo (5 second[i]). Colpisce i nemici adiacenti alla posizione iniziale dell\'obiettivo.'],
831=>['Ira Primordiale','Posizione d\'Élite. Per 1...9 secondo/i attacchi più veloci del 33%, movimento del 33, ma subisci il 150...125% dei danni.','Posizione d\'Élite. (1...9 secondo/i) Attacchi più veloci del 33%, movimento del 33. Subisci il 150...125% dei danni.'],
832=>['Anima Golem di Carne','Magia d\'Élite. Sfrutta il cadavere più vicino per animare un Golem di carne di livello 3...25. Il Golem lascia 1...4 cadavere/i che puoi sfruttare. Puoi avere un Golem di carne alla volta.','Magia d\'Élite. Crea un Golem di carne di liv. 3...25 che lascia 1...4 cadavere/i fresco/hi quando muore. Sfrutta un cadavere fresco. Puoi avere solo un golem di carne alla volta.'],
834=>['Fretta Avventata','Fattura. Dura 6...12 secondo[i]; l\'obiettivo nemico e tutti i nemici adiacenti sono colpiti dalla Fretta Avventata. Mentre sono affetti da questa fattura, la loro velocità d\'attacco aumenta del 25%, ma hanno un 50% di probabilità di mancare l\'obiettivo se usano gli attacchi.','Fattura. Infligge fattura anche ai nemici adiacenti all\'obiettivo (6...12 secondo[i]). Questi nemici hanno un 50% di probabilità di mancare ma una velocità d\'attacco superiore del 25%.'],
835=>['Legame di Sangue','Fattura. Per 3...12 secondo[i], l\'obiettivo nemico e tutti i nemici adiacenti saranno colpiti dalla fattura Legame di Sangue. Ogni volta che un alleato colpisce l\'obiettivo nemico con un attacco, l\'alleato ottiene 5...20 Punto[i] Salute. Se un nemico muore mentre è attiva la fattura Legame di Sangue, tutti gli alleati adiacenti a quel nemico vengono curati di 20...100 Punto[i] Salute.','Fattura. Colpisce con una fattura anche i nemici adiacenti all\'obiettivo (3...12 secondo[i]). Gli alleati che colpiscono i nemici sui quali è attiva la fattura ottengono 5...20 Punto[i] Salute. Se uno di tali nemici muore durante l\'effetto della fattura, gli alleati adiacenti vengono curati di 20...100.'],
836=>['Cavalca il Fulmine','Magia d\'Élite. Cavalchi il fulmine contro l\'obiettivo. Tutti i nemici adiacenti vengono accecati per 1...5 secondi. Se l\'obiettivo è un nemico, subisce 10...70 danni da fulmine. Questa magia ha una penetrazione dell\'armatura del 25%.','Magia d\'Élite. Danni da fulmine inferti: 10...70. Penetrazione armatura: 25%. Condizione inflitta a tutti i nemici adiacenti: Accecamento (1...5 secondi). Ti sposti all\'istante verso il tuo obiettivo. Gli alleati possono essere un bersaglio.'],
837=>['Soccorso d\'Energia','Incantesimo d\'Élite. Per 36...60 secondi, il Soccorso d\'Energia aumenta la Salute massima tua e dell\'obiettivo alleato di 1...3 per ogni punto dell\'Energia massima di ognuno. La prima volta che questo incantesimo viene applicato, tu e l\'obiettivo ottenete 1...12 Punti Energia. Ottieni 1 Punto Energia aggiuntivo per ogni 2 punti che possiedi nella Riserva d\'Energia.','Incantesimo d\'Élite. (Secondi: 36...60.) La tua Salute massima e quella dell\'obiettivo alleato aumenta di 1...3 per ogni punto dell\'Energia massima. Effetto iniziale: Ottienete entrambi 1...12 Punti Energia. Ottieni +1 di Energia per ogni 2 punti nella Riserva d\'Energia.'],
838=>['Sofferenza di Dwayna','Incantesimo. Per 30 secondo[i], l\'obiettivo (un alleato o te stesso) e tutti gli alleati nei dintorni sono sotto gli effetti dell\'incantesimo Sofferenza di Dwayna. Se un alleato muore mentre è sotto gli effetti di questo incantesimo, la tua squadra viene curata di 5...50 punto[i].','Incantesimo. Incanta gli alleati vicini al tuo obiettivo (30 secondo[i]). Cure alla squadra ogni volta che uno di questi alleati muore: 5...50.'],
839=>['"Ritirata!"','Urlo. Se sono presenti alleati morti a portata d\'orecchio, la velocità della squadra aumenta di un 33% per 5...11 secondo[i].','Urlo. (Secondo[i]: 5...11). La velocità di movimento degli alleati a portata d\'orecchio aumento di un 33%. Non ha effetti se non ci sono alleati morti a portata d\'orecchio.'],
840=>['Cuore Avvelenato','Magia. Tu e tutti i nemici adiacenti venite avvelenati per 5...15 secondi.','Magia. Condizione inflitta ai nemici adiacenti: Avvelenamento (secondi: 5...15). Verrai avvelenato anche tu.'],
841=>['Terreno Fetido','Magia. L\'obiettivo nemico subisce 15...65 danno[i] da freddo; se è stato abbattuto, viene avvelenato per 5...20 secondo[i].','Magia. Danni da freddo inferti: 15...65. Condizione inflitta se l\'obiettivo nemico è abbattuto: Veleno (5...20 secondo[i]).'],
842=>['Fulmine ad Arco','Magia. L\'obiettivo nemico subisce 5...40 danni da fulmine. Se sei sotto Sforzo, due nemici vicino al tuo obiettivo vengono colpiti da 15...85 danni da fulmine. I danni del Fulmine ad Arco hanno il 25% di penetrazione dell\'armatura.','Magia. Danni da fulmine inferti: 5...40. Infligge 15...85 danni da fulmine a due nemici nelle vicinanze se sei sotto Sforzo. Penetrazione armatura: 25%.'],
843=>['Folata','Incantesimo d\'Élite. Per 5...11 secondo/i, tu e il bersaglio alleato vi muovete il 33% più velocemente. Quando lanci questa magia, tutti i nemici adiacenti a te e al tuo bersaglio subiscono 15...70 danni da freddo. I nemici colpiti da Gust mentre attaccano o si muovono vengono atterrati.','Incantesimo d\'Élite. (5...11 secondo/i). Tu e il bersaglio alleato vi muovete il 33% più velocemente. Effetto iniziale: i nemici adiacenti a te e all\'alleato subiscono 15...70 danni da freddo. I nemici che stanno attaccando o muovendo vengono atterrati.'],
844=>['Terra in Fermento','Magia. Crei una Terra in Fermento nella posizione dell\'obiettivo nemico. Per i prossimi 5 secondi, la Terra in Fermento infliggerà 10...40 danni da terra al secondo ai nemici vicino a quella posizione. I nemici colpiti dalla Terra in Fermento che si stanno muovendo con una velocità superiore al normale vengono abbattuti.','Magia. Infligge 10...40 danni da terra al secondo (5 secondi). Colpisce i nemici vicini alla posizione iniziale dell\'obiettivo. Provoca abbattimento ai nemici più veloci del normale.'],
845=>['Fiamma Liquida','Magia. L\'obiettivo nemico subisce 7...112 danni da fuoco. Se il nemico sta attaccando o lanciando una magia, anche i nemici nei dintorni subiscono 7...112 danni da fuoco.','Magia. Danni da fuoco inferti: 7...112. Danni da fuoco ai nemici vicini al tuo obiettivo se questi sta attaccando o lanciando magie: 7...112.'],
846=>['Vapore','Magia. Il nemico colpito subisce 20...60 danni da freddo. Se il bersaglio va a fuoco, viene accecato dal fumo per 5...10 secondo/i e subisce 20...60 danni da fuoco extra.','Magia. Infligge 20...60 danni da freddo. Infligge la condizione Cecità (5...10 secondi) e 20...60 danni da freddo se il bersaglio sta bruciando.'],
847=>['Sigillo del Soccorso','Sigillo d\'Élite. Curi l\'obiettivo (un alleato o te stesso) di 20...80 Punto[i] Salute. La tua prossima magia appartenente all\'attributo delle Preghiere Curative o delle Preghiere Protettive e diretta verso un alleato dona 20...100 Punto[i] Salute in più.','Sigillo d\'Élite. Cure: 20...80. Cure impartite ad un obiettivo alleato dalla tua prossima magia di Preghiere Curative o Preghiere Protettive: 20...100.'],
848=>['Inverti Fattura','Incantesimo. Rimuovi una fattura dall\'obiettivo (un alleato o te stesso). Se rimuovi una fattura tramite questa magia, per 5...10 secondo[i], la prossima volta che l\'obiettivo alleato subirebbe un danno, questo è ridotto di 5...50.','Incantesimo. (Secondi: 5...10) Rimuove una fattura dall\'obiettivo (un alleato o te stesso). Riduzione del prossimo danno ricevuto da questo alleato: 5...50. Ha effetto solo se questo alleato è sotto fattura.'],
849=>['Fendente Lacerante','Attacco con Ascia. Se va a segno, infliggi +5...20 danno[i]; se colpisce un nemico abbattuto, gli infligge Emorragia per 5...20 secondo[i].','Attacco con Ascia. Danni inferti: +5...20. Condizione inflitta se l\'obiettivo nemico è abbattuto: Emorragia (5...20 secondo[i]).'],
850=>['Colpo Feroce','Attacco con Martello. Se Colpo Feroce va a segno, infliggi +5...20 danno[i]. Se l\'obiettivo nemico è affetto da Debolezza, sarà affetto anche da Ferita Profonda per 1...8 secondo[i].','Attacco con Martello. Danni inferti: +5...20. Condizione inflitta se l\'obiettivo nemico è affetto da Debolezza: Ferita Profonda (1...8 secondo[i]).'],
851=>['Fendente Sole e Luna','Attacco con Spada. Attacchi due volte l\'obiettivo nemico. Questi attacchi non possono essere bloccati.','Attacco con Spada. Attacchi l\'obiettivo nemico due volte. Non bloccabile.'],
852=>['Tiro Scheggia','Attacco con Arco. Se Splinter Shot ti colpisce, infliggi +3...15 danni. Se Splinter Shot viene bloccata, tutti i nemici nell\'area del tuo bersaglio subiscono 5...65 danni.','Attacco con Arco. Infligge +3...15 danni. Infligge 5...65 danni ai nemici nell\'area se viene bloccato.'],
853=>['Tiro di Melandru','Attacco con Arco d\'Élite. Se il Tiro di Melandru va a segno, l\'obiettivo inizia a sanguinare per 5...25 secondi. Se colpisce un nemico in movimento o abbattuto, tale nemico subisce 10...25 danni e soffre di Storpiatura per 5...15 secondi.','Attacco con Arco d\'Élite. Condizione inflitta: Emorragia (5...25 secondi). Per obiettivi nemici in movimento o abbattuti: Danni inferti: +10...25. Condizione inflitta: Storpiatura (5...15 secondi).'],
854=>['Tagliola','Trappola. Quando la Tagliola viene fatta scattare, tutti i nemici nei dintorni diventano storpi per 3...15 secondo[i]; termina dopo 90 secondi. Mentre attivi questa abilità è facile interromperti.','Trappola. (Secondi: 90) Ha effetto sui nemici nei dintorni. Condizione inflitta: Storpiatura (3...15 secondo[i]). Facile interruzione.'],
858=>['Pugnali Danzanti','Magia. Scagli tre Pugnali Danzanti contro l\'obiettivo nemico; ogni pugnale infliggerà 5...35 danno[i] da terra se va a segno; la loro portata è la metà del normale. Questa abilità viene considerata un attacco con arma primaria.','Magia a Portata Dimezzata. Tre proiettili. Danni da terra inferti da ognuno: 5...35. Vale come attacco con arma primaria.'],
859=>['Evoca Incubo','Fattura. Per 2...16 secondi l\'obiettivo nemico subirà una Degenerazione Salute di -8.','Fattura. (Secondi: 2...16). Degenerazione Salute: -8.'],
860=>['Sigillo del Disturbo','Sigillo. Se l\'obiettivo nemico sta lanciando una magia, la magia viene interrotta e il nemico subisce 10...51 danni. Se l\'obiettivo nemico è colpito da fattura, il Sigillo del Disturbo interrompe tutte le abilità diverse dalle magie.','Sigillo. Interrompe una magia. Se l\'obiettivo nemico è colpito da fattura, interrompe qualsiasi abilità. Effetto dell\'interruzione: 10...51 danni inferti.'],
862=>['Sguardo Famelico','Magia d\'Élite. Infligge 20...40 danni e sottrae 20...40 Punto[i] Salute dall\'obiettivo nemico e da tutti i nemici nei dintorni.','Magia d\'Élite. Infligge 20...40 danni e sottrae 20...40 Punto[i] Salute dall\'obiettivo nemico e da tutti i nemici nei dintorni.'],
863=>['Ordine dell\'Apostasia','Incantesimo d\'Élite. Per 5 secondi, ogni volta che un membro della tua squadra infligge un danno fisico al nemico gli fa perdere un incantesimo; per ogni incantesimo del Mistico rimosso, perdi un 10...3% della Salute massima.','Incantesimo d\'Élite. Incanta tutti i membri della squadra (5 secondi). Questi membri della squadra rimuovono un incantesimo quando assestano danni fisici. Costo di rimozione: per ogni incantesimo del Mistico perdi un 10...3% di Salute massima.'],
864=>['Sguardo Oppressivo','Magia. L\'obiettivo nemico e i nemici adiacenti subiscono 10...30 danno[i] da ombra. I nemici affetti da una condizione subiscono Avvelenamento e Debolezza per 3...12 secondo[i].','Magia. Danni inferti all\'obiettivo e ai nemici adiacenti: 10...30. Infligge Avvelenamento e Debolezza (3...12 secondo[i] su nemici già affetti da una condizione.'],
865=>['Martello Fulminante','Magia. L\'obiettivo nemico subisce 10...100 danni da fulmine e soffre di Armatura Incrinata per 5...20 secondi. Il Martello Fulminante ha il 25% di penetrazione dell\'armatura.','Magia. Danni da fulmine inferti: 10...100. Condizione inflitta: Armatura Incrinata (5...20 secondi). Penetrazione armatura: 25%.'],
866=>['Lama del Vapore','Magia. L\'obiettivo nemico subisce 15...135 danni da freddo. Se il nemico è sotto l\'effetto di incantesimi, la Lama del Vapore gli infligge la metà dei danni.','Magia. Danni da freddo inferti: 15...135. Danno dimezzato se l\'obiettivo nemico è sotto incantesimo.'],
867=>['Luce di Guarigione','Magia d\'Élite. Curi l\'obiettivo (un alleato o te stesso) di 40...120 Punto[i] Salute; se l\'obiettivo è affetto da un incantesimo ottieni 1...3 Punto[i] Energia.','Magia d\'Élite. Cure: 40...120. Energia conseguita se l\'obiettivo alleato è sotto incantesimo: 1...3.'],
869=>['"Vigliacco!"','Urlo d\'Élite. Se l\'obiettivo nemico si sta muovendo viene abbattuto.','Urlo d\'Élite. Provoca abbattimento se l\'obiettivo nemico si sta muovendo.'],
870=>['Pestilenza','Rituale della Natura. Crei uno Spirito di livello 1...10. Quando una creatura (Spiriti esclusi) nella sua portata muore, le condizioni che aveva addosso si diffondono su tutte le creature nell\'area che sono già affette da una condizione. Questo Spirito si esaurisce dopo 30...180 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...180 secondo[i]). Quando una creatura nella portata muore, le condizioni di cui soffriva si diffondono sulle creature nell\'area già affette da una condizione. Non ha effetto sugli Spiriti.'],
871=>['Canto Ombroso','Rituale Incatenante. Crei uno spirito di livello 1...10. I suoi attacchi infliggono 5...20 danni e provocano Accecamento per 1...6 secondi. Lo spirito muore dopo 30 secondi.','Rituale Incatenante. Crei uno spirito di livello 1...10 (in vita per 30 secondi). Danni inferti: 5...20. Condizione inflitta: Accecamento (1...6 secondi).'],
876=>['Sigillo delle Ombre','Sigillo. L\'obiettivo nemico subisce 5...35 danno[i]; se era stato accecato subisce 15...60 danno[i] in più.','Sigillo. Danni inferti: 5...35. Assesta 15...60 danno[i] in più se l\'obiettivo nemico è affetto da Accecamento.'],
877=>['Equilibrio di Lyssa','Magia. L\'obiettivo nemico perde un incantesimo. Questa abilità non ha effetto se hai addosso più incantesimi dell\'obiettivo nemico.','Magia. Rimuove un incantesimo dall\'obiettivo nemico. Ha effetto solo se hai più incantesimi di questo nemico.'],
878=>['Visioni di Rimpianto','Fattura d\'Élite. Per 10 secondi l\'obiettivo nemico e i nemici adiacenti subiscono 15...45 danni ogni volta che utilizzano un\'abilità e 5...50 danni aggiuntivi se non sono sotto l\'effetto di un\'altra fattura dell\'Ipnotizzatore.','Fattura d\'Élite. Colpisce con una fattura anche i nemici adiacenti all\'obiettivo (10 secondi). Tali nemici subiscono 15...45 danni ogni volta che utilizzano un\'abilità e 5...50 danni aggiuntivi se non sono sotto l\'effetto di un\'altra fattura dell\'Ipnotizzatore.'],
879=>['Illusione del Dolore','Fattura. Per 8 secondi l\'obiettivo nemico subisce una Degenerazione Salute di -3...10 e subisce 3...10 danno[i] al secondo. Quando l\'effetto di Illusione del Dolore svanisce, il nemico viene curato di 36...120 Punto[i] Salute.','Fattura. (Secondi: 8). Degenerazione Salute causata: -3...10. Danno[i] al secondo subiti dall\'obiettivo nemico: 3...10. Effetto al termine: il nemico viene curato di 36...120 Punto[i] Salute.'],
880=>['Velocità Sottratta','Fattura d\'Élite. Per 1...10 secondi il tempo di lancio delle magie dell\'obiettivo nemico e di tutti i nemici adiacenti aumenta di un 100%. Il tempo di lancio delle magie contro tali nemici lanciate da te o dai tuoi alleati si riduce di un 50%.','Fattura d\'Élite. Colpisce con una fattura anche i nemici adiacenti (1...10 secondi). Raddoppia il tempo di lancio delle magie. Riduzione del tempo di lancio delle magie tue e dei tuoi alleati contro i nemici colpiti da fattura: -50%.'],
881=>['Sigillo dell\'Etere','Sigillo. Se la tua Energia è inferiore a 5...10 ottieni 10...20 Punto[i] Energia.','Sigillo. Energia conseguita: 10...20. Ha effetto solo se la tua Energia è inferiore a 5...10.'],
882=>['Sigillo del Disincanto','Sigillo. Perdi tutta l\'Energia. L\'obiettivo nemico perde un incantesimo.','Sigillo. Rimuove un incantesimo. Perdi tutta l\'Energia.'],
883=>['Afonia','Fattura. Per 5...20 secondo[i], l\'obiettivo nemico e tutti i nemici nei dintorni non possono usare le urla o i canti.','Fattura. Infligge fattura anche ai nemici vicini all\'obiettivo (5...20 secondo[i]). Questi nemici non possono usare urla o canti.'],
884=>['Fiamme Scottanti','Magia d\'Élite. L\'obiettivo nemico e tutti i nemici nei dintorni vengono colpiti dalle Fiamme Scottanti. I nemici già affetti da Bruciatura quando questa abilità viene lanciata subiscono 10...100 danni da fuoco. I nemici che ancora non sono infuocati iniziano a bruciare per 1...7 secondi.','Magia d\'Élite. Colpisce i nemici vicini all\'obiettivo. Danni da fuoco inferti ai nemici affetti da Bruciatura: 10...100. Infligge Bruciatura (1...7 secondi) ai nemici non infuocati.'],
885=>['Guardiano Scudo','Incantesimo. Per 2...6 secondi, tutti i membri della squadra a portata d\'orecchio hanno un 75% di probabilità di bloccare gli attacchi. Quando un attacco viene bloccato, tutti gli alleati a portata d\'orecchio vengono curati di 10...40 punti e il Guardiano Scudo termina.','Incantesimo. (Secondi: 2...6.) I membri della squadra a portata d\'orecchio hanno un 75% di probabilità di bloccare gli attacchi. Effetto del blocco: gli alleati a portata d\'orecchio vengono curati di 10...40 punti e il Guardiano Scudo termina.'],
886=>['Brezza Riposante','Incantesimo. Per 8...18 secondo[i], l\'obiettivo (un alleato o te stesso) ha una Rigenerazione della Salute di +10; questo incantesimo termina se quell\'alleato attacca o utilizza un\'abilità.','Incantesimo. (Secondi: 8...18) Rigenerazione Salute: +10. Termina se l\'obiettivo alleato attacca o usa un\'abilità.'],
887=>['Sigillo del Ringiovanimento','Sigillo. Curi l\'obiettivo (un alleato o te stesso) di 15...75 punto[i]; se l\'obiettivo sta compiendo una magia o sta attaccando, viene curato di 15...75 Punto[i] Salute in più.','Sigillo. Cure: 15...75. Cura di 15...75 Punto[i] Salute in più se l\'obiettivo sta lanciando una magia o attaccando.'],
888=>['Ascia Roteante','Attacco d\'Élite con Ascia. Se Ascia Roteante va a segno, infligge +5...20 danno[i] e fa terminare qualsiasi posizione utilizzata dal tuo obiettivo. Questo attacco non può essere bloccato.','Attacco d\'Élite con Ascia. Danni inferti: +5...20. Rimuove una posizione. Non bloccabile.'],
889=>['Colpo Vigoroso','Attacco d\'Élite con Martello. Se Colpo Vigoroso va a segno, infligge +10...30 di danni e rimuove qualsiasi posizione utilizzata dall\'obiettivo nemico. L\'obiettivo è affetto da Debolezza per 5...20 secondo[i]. Questo attacco non può essere bloccato.','Attacco d\'Élite con Martello. Danni inferti: +10...30. Rimuove la posizione dell\'obiettivo nemico. Condizione inflitta: Debolezza (5...20 secondo[i]). Non bloccabile.'],
891=>['"Non si passa!"','Urlo. Tutti i nemici nei dintorni in movimento vengono buttati a terra. Questa abilità si ricarica 1...8 secondo[i] più velocemente per ogni nemico a terra (max 25 secondo[i]).','Urlo. Abbatte tutti i nemici in movimento nei dintorni. Questa abilità si ricarica 1...8 secondo[i] più velocemente per ogni nemico affetto (max 25 secondo[i]).'],
892=>['Lama Fremente','Attacco d\'Élite con Spada. Se Lama Fremente va a segno, infliggi +10...40 danno[i]; se questo attacco colpisce un nemico in movimento gli infligge Stordimento per 10 secondo[i].','Attacco d\'Élite con Spada. Danni inferti: +10...40. Condizione inflitta se l\'obiettivo nemico si stava muovendo: Stordimento (10 secondo[i]).'],
893=>['Frecce Cercanti','Preparazione. Per 3...14 secondo[i], le tue frecce non possono essere bloccate; questa abilità termina se le frecce vanno a vuoto.','Preparazione. (Secondi: 3...14) Le tue frecce non sono bloccabili. Termina se non colpisci.'],
898=>['Sovraccarico','Fattura. Per 5 secondo/i, il bersaglio subisce -1...3 degenerazione della Salute. Se il bersaglio sta usando un\'abilità, subisce 15...75 danni da Overload, e tutti i nemici adiacenti subiscono il 75% di quei danni.','Fattura. (5 secondo/i). Provoca -1...3 degenerazione della Salute. Se il bersaglio sta usando un\'abilità, subisce 15...75 danni, e tutti i nemici adiacenti subiscono il 75% di quei danni.'],
899=>['Immagini del Rimorso','Fattura. Per 5...10 secondo[i], l\'obiettivo nemico subisce una Degenerazione della Salute di -1...3; se stava attaccando subisce 10...52 danno[i].','Fattura. (Secondi: 5...10) Degenerazione Salute: -1...3. Effetto iniziale: 10...52 danno[i] se l\'obiettivo nemico sta attaccando.'],
900=>['Fardello Condiviso','Fattura d\'Élite. Per 5...20 secondo/i, il nemico bersaglio e tutti i nemici nell\'area attaccano, scagliano incantesimi e si muovono del 50% più lentamente.','Fattura d\'Élite. Maledice anche i nemici nell\'area del tuo bersaglio (5...20 secondo/i). Questi nemici attaccano, scagliano incantesimi e si muovono del 50% più lentamente.'],
901=>['Lega Anima','Fattura d\'Élite. Per 30 secondo[i], ogni volta che l\'obiettivo nemico viene curato, chi ha impartito le cure subisce 20...80 danno[i]. Questa fattura termina se l\'obiettivo è affetto da una fattura delle Preghiere Punitive.','Fattura d\'Élite. (Secondi: 30) Ogni volta che l\'obiettivo nemico viene curato, chi ha impartito le cure subisce 20...80 danno[i]. Termina se l\'obiettivo è affetto da una fattura delle Preghiere Punitive.'],
902=>['Sangue dell\'Aggressore','Magia. Sottrai fino a 5...45 Punto[i] Salute all\'obiettivo nemico. Se l\'obiettivo nemico stava attaccando, subisce Debolezza per 3...12 secondo[i].','Magia. Sottrazione Salute: 5...45. Infligge Debolezza (3...12 secondo[i] se l\'obiettivo nemico stava attaccando.'],
903=>['Prisma di Ghiaccio','Magia. L\'obiettivo nemico subisce 15...75 danni da freddo. Se quel nemico ha una fattura Magia dell\'Acqua, Lancia di Ghiaccio infligge +15...75 danni da freddo a tutti i nemici nelle vicinanze.','Magia. Danni da freddo inferti: 15...75. Infligge +15...75 danni da freddo a tutti i nemici nelle vicinanze se l\'obiettivo ha una fattura Magia dell\'Acqua.'],
904=>['Ascia Furiosa','Attacco con Ascia. Se va a segno, infliggi +5...35 danno[i]; se viene bloccata, ottieni 3 dosi di Adrenalina.','Attacco con Ascia. Danni inferti: +5...35. Se bloccato ti dà 3 dosi di adrenalina.'],
905=>['Colpo Propizio','Attacco con Martello. Se Colpo Propizio va a segno, infliggi +5...20 danno[i] e ottieni 3...8 Punto[i] Energia. Se il nemico è affetto da Debolezza, questo attacco non è bloccabile.','Attacco con Martello. Danni inferti: +5...20. Ottieni 3...8 Punto[i] Energia. Non bloccabile se l\'obiettivo nemico è affetto da Debolezza.'],
906=>['"In Ginocchio!"','Urlo. Perdi tutta l\'Adrenalina. Tutte le tue Posizioni si ricaricano se qualche nemico adiacente viene gettato a terra.','Urlo. Ricarica tutte le tue posizioni se sei adiacente ad un nemico abbattuto. Perdi tutta l\'adrenalina.'],
907=>['Fendente del Drago','Attacco d\'Élite con Spada. Se va a segno infliggi +10...40 danno[i] ed ottieni 1...5 dose[i] di Adrenalina.','Attacco d\'Élite con Spada. Danni inferti: +10...40. Ottieni 1...5 dose[i] di adrenalina se va a segno.'],
908=>['Tiro del Brigante','Attacco con Arco. Se va a segno infliggi +25...55 danno[i] e tutte le tue abilità (esclusi gli attacchi) vengono disattivate per 5 secondo[i].','Attacco con Arco. Danni inferti: +25...55. Se questo attacco va a segno le tue abilità (esclusi gli attacchi) sono disattivate (5 secondo[i]).'],
909=>['Tiro Focalizzato','Attacco con Arco. This shot moves three times faster, cannot be blocked, and strikes for +10...40 damage but all of your other attack skills are disabled for 8...4 seconds.','Attacco con Arco. Deals +10...40 damage. Unblockable. This shot moves three times faster.Your other attack skills are disabled (8...4 seconds).'],
910=>['Voragine Fantasma','Magia. Apre una Voragine Fantasma sulla posizione dell\'obiettivo nemico. Dopo 3 secondo[i], tutti i nemici adiacenti ricevono 25...125 danno[i] da fulmine e subiscono Armatura Incrinata per 1...20 secondo[i].','Magia. Dopo 3 secondo[i], colpisce i nemici adiacenti alla posizione iniziale dell\'obiettivo. Danni da fulmine inferti: 25...125. Condizione inflitta: Armatura Incrinata (1...20 secondo[i]).'],
911=>['Unione','Rituale Incatenante. Crea uno spirito di livello 1...12. Ogni volta che un Alleato (Spiriti esclusi) nel suo raggio di azione subisce danni o sottrazione salute, questi vengono ridotti di 15 e lo Spirito subisce 15 di danni. Lo spirito si esaurisce dopo 30...60 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...12 (in vita per 30...60 secondi). Ogni volta che un Alleato (Spiriti esclusi) nel suo raggio di azione subisce danni o sottrazione salute, questi vengono ridotti di 15 e lo Spirito subisce 15 di danni.'],
913=>['Tanasen era Tranquillo','Magia d\'Élite Altera-oggetto. Mantieni le ceneri di Tanasen per un massimo di 5...20 secondo[i]; mentre le mantieni, ottieni +10...25 di armatura ed è impossibile interromperti.','Magia d\'Élite Altera-oggetto. (Secondi: 5...20) Armatura: +10...25. Non puoi essere interrotto.'],
914=>['Consuma Anima','Magia d\'Élite. Rubi 5...70 Salute dal bersaglio nemico. Tutte le creature nemiche evocate a portata d\'orecchio di quel nemico subiscono 25...125 danni.','Magia d\'Élite. Ruba 5...70 Salute. Infligge 25...125 danni alle creature ostili evocate a portata d\'orecchio del nemico bersaglio.'],
915=>['Luce dello Spirito','Magia. L\'obiettivo (un alleato o te stesso) viene curato di 60...180 Punto[i] Salute; se sono presenti degli Spiriti a portata d\'orecchio, non sacrifichi alcuna Salute.','Magia. Cure: 60...180. Non sacrifichi Salute se sei a portata d\'orecchio di qualche Spirito.'],
916=>['Lamento','Fattura. Per 5...20 secondi l\'obiettivo nemico e tutti i nemici nei dintorni subiscono una Degenerazione della Salute di -0...3. Se ti trovi nella portata d\'orecchio di uno spirito o un cadavere quando viene lanciata la fattura, i nemici affetti subiscono 10...50 di danni.','Fattura. La fattura viene lanciata anche sui nemici adiacenti all\'obiettivo (secondi: 5...20). Degenerazione Salute: -0...3. Effetto iniziale: se ti trovi nella portata d\'orecchio di uno spirito o di un cadavere, infligge 10...50 di danni ai nemici adiacenti.'],
917=>['Distruggi Anima','Magia. Distruggi lo Spirito alleato preso di mira. Tutti i nemici nei dintorni subiscono 50...140 danno[i] da fulmine e vengono accecati per 3...12 secondo[i].','Magia. Annienta lo Spirito alleato selezionato. Assesta 50...140 danno[i] da fulmine e provoca Accecamento (3...12 secondo[i]) ai nemici nei dintorni.'],
918=>['Da Spirito a Carne','Magia. Lo Spirito alleato toccato viene annientato. Tutti gli alleati nei dintorni vengono curati di 30...240.','Magia a Tocco. Annienta lo Spirito alleato toccato. Cure per gli alleati nei dintorni: 30...240.'],
919=>['Bruciatura dello Spirito','Magia. L\'obiettivo nemico subisce 5...50 danno[i] da fulmine; se sono presenti degli Spiriti a portata d\'orecchio, la Bruciatura dello Spirito provoca bruciatura per 1...5 secondo[i].','Magia. Danni da fulmine inferti: 5...50. Infligge condizione Bruciatura (1...5 secondo[i] se ti trovi entro la portata d\'orecchio di uno spirito.'],
920=>['Distruzione','Rituale Incatenante. Crea uno spirito di livello 1...14 con 30 secondi di vita. Alla morte dello Spirito, tutti i nemici nell\'area subiscono 5...25 di danno per ogni secondo in cui è rimasto in vita (max 150 di danno).','Rituale Incatenante. Crea uno spirito di livello 1...14 con 30 secondi di vita. Alla morte dello Spirito, tutti i nemici nell\'area subiscono 5...25 di danno per ogni secondo in cui è rimasto in vita (max 150 di danno).'],
921=>['Dissonanza','Rituale Incatenante. Crei uno Spirito di livello 1...12. Lo Spirito provoca 5...20 danno[i] e tutti quelli colpiti dal suo attacco vengono interrotti. Lo Spirito si esaurisce dopo 10...25 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...12 (in vita per 10...25 secondo[i]). Danno inferto dai suoi attacchi: 5...20; interrompe le azioni.'],
923=>['Disincanto','Rituale Incatenante. Crei uno Spirito di livello 1...12. Lo Spirito provoca 5...20 danno[i] e tutti quelli colpiti dal suo attacco perdono un incantesimo. Lo Spirito si esaurisce dopo 10...35 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...12 (in vita per 10...35 secondo[i]). Se attacca assesta 5...20 danno[i] e rimuove un incantesimo.'],
925=>['Richiamo','Incantesimo. Mentre mantieni attivo il Richiamo non accade nulla, ma quando termina compi un Passo nell\'Ombra nella posizione dell\'alleato che avevi preso di mira attivando questa abilità e tutte le tue abilità vengono disattivate per 3 secondo[i].','Incantesimo. Effetto al termine: compi un Passo nell\'Ombra verso l\'obiettivo alleato. Impossibile selezionare se stessi. Quando termina disattiva tutte le tue abilità per 3 secondo[i].'],
926=>['Affila Pugnali','Incantesimo. Per 5...30 secondi i tuoi attacchi con pugnale provocano Emorragia per 5...15 secondi.','Incantesimo. (Secondi: 5...30). Condizione inflitta dagli attacchi con pugnale: Emorragia (secondi: 5...15).'],
927=>['Timore Infame','Fattura. Per 10 secondi, i movimenti dell\'obiettivo nemico aumentano del 10%; per ogni secondo, se l\'obiettivo si muove, subisce 5...20 danno[i].','Fattura. (10 secondo[i]). L\'obiettivo nemico subisce 5...20 danno[i] al secondo mentre si muove ma si muove con velocità superiore del 10%.'],
928=>['Coltre Ombrosa','Fattura d\'Élite. Per 3...9 secondo[i], l\'obiettivo nemico non può essere colpito da alcun incantesimo.','Fattura d\'Élite. (Secondi: 3...9) L\'obiettivo nemico non può ricevere incantesimi.'],
929=>['Ombra della Fretta','Posizione. Per 10...40 secondo[i], la tua velocità aumenta di un 15%. Al termine compi un Passo nell\'Ombra che ti riporta nel punto di partenza.','Posizione. (Secondi: 10...40) Incremento tua velocità di movimento: 15%. Effetto al termine: torni nel punto di partenza.'],
930=>['Incanto Propizio','Incantesimo. Dura 20 secondo[i]; la prossima magia da te lanciata resta disattivata per 10...5 secondo[i] in più e tu ottieni un 110...200% del suo costo energetico.','Incantesimo. (Secondi: 20) La tua prossima magia ti restituisce un 110...200% del suo costo energetico. Quella magia impiega 10...5 secondo[i] in più per ricaricarsi.'],
931=>['Ritorno di Potere','Magia. Se l\'obiettivo nemico ha attivato una magia o un canto, l\'abilità viene interrotta e l\'obiettivo ottiene 10...5 Punti Energia.','Magia. Interrompe una magia o un canto. Effetto dell\'interruzione: l\'obiettivo nemico ottiene 10...5 Punti Energia.'],
932=>['Complicazione','Magia. Se l\'obiettivo nemico ha attivato un\'abilità, questa viene interrotta e disattivata per 5...12 secondi in più per l\'obiettivo nemico e tutti i nemici nei dintorni.','Magia. Interrompe un\'abilità. Effetto dell\'interruzione: disattiva l\'abilità interrotta (+5...12 secondi) per l\'obiettivo nemico e tutti i nemici nei dintorni.'],
933=>['Tempesta Distruttrice','Magia d\'Élite. L\'obiettivo nemico perde tutti gli incantesimi. Per ogni incantesimo così rimosso, la Tempesta Distruttrice viene disattivata per 7 secondo[i] in più.','Magia d\'Élite. Rimuove tutti gli incantesimi. Costo di rimozione: Tempesta Distruttrice viene disattivata per +7 secondo[i] per ogni incantesimo rimosso.'],
934=>['Sigillo Innaturale','Sigillo. L\'obiettivo nemico subisce 15...75 danni. Se è sotto gli effetti di una fattura o di un incantesimo, i nemici adiacenti subiscono 5...50 danni.','Sigillo. Danni inferti: 15...75. Se l\'obiettivo era sotto gli effetti di una fattura o di un incantesimo, infligge 5...50 danni ai nemici adiacenti.'],
935=>['Bile Crescente','Fattura. Per 20 secondi questa fattura non ha alcun effetto. Al termine, l\'obiettivo nemico e tutti i nemici nell\'area subiscono 1...6 danno[i] per ogni secondo in cui la fattura è rimasta attiva.','Fattura. (Secondi: 20) Effetto al termine: assesta 1...6 danno[i] per ogni secondo di attività di Bile Crescente. Danneggia anche gli altri nemici nell\'area.'],
936=>['Avvelena Incantesimi','Magia. L\'obiettivo nemico perde un incantesimo. Per ogni incantesimo residuo l\'obiettivo nemico viene avvelenato per 3...10 secondo[i].','Magia. Rimuove un incantesimo dall\'obiettivo nemico. Condizione inflitta: Veleno (3...10 secondo[i] per ogni incantesimo rimasto su quel nemico).'],
937=>['Onda d\'Urto','Magia d\'Élite. Tutti i nemici nell\'area subiscono 15...60 danni da terra e soffrono di Debolezza per 1...10 secondi. Anche i nemici nei dintorni subiscono +15...60 danni da terra e Armatura Incrinata per 1...10 secondi. I nemici adiacenti soffrono gli effetti precedenti, subiscono +15...60 danni da terra e vengono accecati per 1...10 secondi.','Magia d\'Élite. I nemici nell\'area subiscono 15...60 danni da terra e soffrono di Debolezza (1...10 secondi). Anche i nemici nei dintorni subiscono +15...60 danni da terra e Armatura Incrinata (1...10 secondi). I nemici adiacenti subiscono +15...60 danni da terra e vengono accecati (1...10 secondi).'],
938=>['Guardia della Stabilità','Guardia. Crei una Guardia della Stabilità nella tua posizione attuale. Per 10...25 secondi, gli alleati (Spiriti esclusi) non possono essere abbattuti.','Guardia. (Secondi: 10...25.) Gli alleati in questa Guardia non possono essere abbattuti. Non ha effetto sugli Spiriti alleati.'],
939=>['Catene di Ghiaccio','Fattura d\'Élite. Per 1...10 secondi, la velocità di movimento dell\'obiettivo nemico diminuisce di un 66%. Mentre è sotto gli effetti di un incantesimo, i suoi movimenti si riducono di un 90%.','Fattura d\'Élite. (Secondi: 1...10.) La velocità dell\'obiettivo nemico è ridotta di un 66%. La sua velocità rallenta di un 90% se sotto incantesimo.'],
941=>['Luce Benedetta','Magia d\'Élite. Curi l\'obiettivo (un alleato o te stesso) di 10...120 Punto[i] Salute e rimuovi una condizione ed una fattura.','Magia d\'Élite. Cure: 10...120. Rimuove una condizione e una fattura.'],
942=>['Spezzafatture','Magia d\'Élite. Rimuove tutte le fatture dal bersaglio alleato e dagli alleati adiacenti. Questa magia impiega 2 secondo/i in più per ricaricarsi per ogni fattura rimossa in questo modo (probabilità di fallimento del 50% con Favore divino pari o inferiore a 4).','Magia d\'Élite. Rimuove tutte le fatture. Coinvolge anche gli alleati adiacenti. Costo di rimozione: +2 secondo/i di ricarica per ogni fattura rimossa. Probabilità di fallimento del 50% se non si possiede almeno 5 in Favore divino).'],
943=>['Estinzione','Magia. Rimuovi una condizione da ogni membro della squadra; gli alleati ai quali viene rimossa la Bruciatura ricevono 10...100 Punto[i] Salute.','Magia. Ha effetto su tutti i membri della squadra. Rimuove una condizione. Cure per i membri della squadra ai quali viene rimossa Bruciatura: 10...100.'],
944=>['Sigillo della Forza','Sigillo. Infliggi +5 danno[i] con [il] 1...16 [M]attacco[hi] successivo[i].','Sigillo. I tuoi attacchi infliggono +5 danno[i]. Termina dopo 1...16 attacchi.'],
946=>['Concentrazione del Cacciatore','Preparazione d\'Élite. Per 12...36 secondo[i] mentre poni le trappole non potrai essere facilmente interrotto e il tuo grado di Sopravvivenza nella Natura aumenta di 0...4.','Preparazione d\'Élite. (Secondi: 12...36) Le tue trappole diventano difficili da interrompere. Incremento attributo Sopravvivenza nella Natura: +0...4.'],
947=>['Rovi','Rituale della Natura. Crei uno Spirito di livello 1...10. Le creature nella sua portata (Spiriti esclusi) che vengono abbattute subiscono 5 danni ed iniziano a sanguinare per 5...20 secondo[i]. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Le creature abbattute ricevono 5 danni e soffrono di Emorragia (5...20 secondo[i]). Non ha effetto sugli Spiriti.'],
948=>['Colpo Disperato','Attacco con Arma Primaria. Se la tua Salute è inferiore al 50...80% infliggi +15...60 danno[i].','Attacco con Arma Primaria. Assesta +15...60 danno[i] se la tua Salute è inferiore a 50...80%.'],
949=>['Potere della Volpe','Incantesimo. Per 10...35 secondo[i] sarà impossibile bloccare 1...6 dei tuoi prossimi attacchi.','Incantesimo. (Secondi: 10...35) I tuoi attacchi non sono bloccabili. Termina dopo 1...6 attacchi.'],
950=>['Fardello d\'Ombra','Fattura. Per 3...15 secondo[i], i movimenti dell\'obiettivo nemico rallentano del 25% e, se non è affetto da altre fatture, questi ha 20...30 punto[i] in meno di armatura contro i tuoi attacchi.','Fattura. (Secondi: 3...15) Rallentamento movimenti dell\'obiettivo nemico: 25%. Riduzione sua armatura contro i tuoi attacchi: -20...30 La riduzione dell\'armatura ha effetto solo se il nemico non è affetto da altre fatture..'],
951=>['Velocità risucchiante','Fattura. Per 5...15 secondo/i, il bersaglio nemico si muove più lentamente del 33% e tu più velocemente del 33%. Questa magia si ricarica il 50% più velocemente se lanciato su un avversario in movimento.','Fattura. (5...15 secondo/i). Il bersaglio nemico si muove più lentamente del 33% e tu più velocemente del 33%. Si ricarica il 50% più velocemente se lanciato su un avversario in movimento.'],
952=>['Peso della Morte','Magia. Compi un Passo nell\'Ombra verso l\'obiettivo nemico e se ha più Salute di te, vieni curato di 65...200 punto[i].','Magia. Compi un Passo nell\'Ombra verso l\'obiettivo nemico. Ti curi di 65...200 se questo nemico ha più Salute di te.'],
953=>['Flusso di Potere','Fattura d\'Élite. Se l\'obiettivo nemico ha attivato una magia o un canto, l\'abilità viene interrotta. Il nemico subisce anche una Degenerazione Energia di -2 per 4...10 secondi.','Fattura d\'Élite. Interrompe una magia o un canto. Effetto dell\'interruzione: -2 di Degenerazione Energia (4...10 secondi).'],
954=>['Scaccia Fatture','Magia d\'Élite. Rimuovi fino a 2 fatture dall\'obiettivo (un alleato o te stesso).','Magia d\'Élite. Rimuove 2 fatture dall\'obiettivo (un alleato o te stesso).'],
955=>['Squarcia Incantesimo','Magia. Rimuovi 1 incantesimo[i] dall\'obiettivo nemico. Se un incantesimo viene rimosso, quel nemico soffrirà di Emorragia per 5...25 secondo[i].','Magia. Incantesimi rimossi: 1. Effetto della rimozione: infligge Emorragia (5...25 secondo[i]).'],
957=>['Scudo Magico','Incantesimo. Per 5...20 secondo[i], mentre compi delle magie, i nemici non ti possono lanciare magie. Quando lo Scudo Magico termina, tutte le tue abilità vengono disattivate per 8...4 secondo[i].','Incantesimo. (Secondi: 5...20) Mentre lanci magie non puoi ricevere magie. Effetto al termine: le tue abilità sono disattivate (8...4 secondo[i]).'],
958=>['Sussurro Curativo','Magia. Curi l\'obiettivo alleato di 40...100 punto[i]. La portata di questa magia è la metà del normale.','Magia a Portata Dimezzata. Cure: 40...100. Impossibile selezionare se stessi.'],
959=>['Luce Eterea','Magia. Curi l\'obiettivo (un alleato o te stesso) di 25...100 punto[i]. Questa magia può essere interrotta facilmente.','Magia. Cure: 25...100. Facile interruzione.'],
960=>['Libera Incantesimi','Magia. Perdi tutti gli incantesimi. Ogni membro della squadra viene curato di 5...35 Punto[i] Salute per ogni incantesimo da Mistico perso.','Magia. Rimuove tutti i tuoi incantesimi. Cura tutti i membri della squadra di 5...35 per ogni incantesimo del Mistico rimosso.'],
961=>['Lacerazione','Rituale della Natura d\'Élite. Crei uno Spirito di livello 1...10. Le creature sanguinanti nel suo raggio subiscono una Degenerazione della Salute di -2. Quando lo Spirito si esaurisce, tutte le creature nella sua portata (Spiriti esclusi) che hanno meno del 90% di Salute iniziano a sanguinare per 5...25 secondo[i]. Lo Spirito si esaurisce dopo 30...240 secondo[i].','Rituale della Natura d\'Élite. Crei uno Spirito di livello 1...10 (in vita per 30...240 secondo[i]). Degenerazione Salute delle creature nella portata affette da Emorragia: -2. Effetto al termine: provoca Emorragia (5...25 secondo[i]) alle creature nella portata che hanno meno del 90% di Salute. Non ha effetto sugli Spiriti.'],
962=>['Trasferimento dello Spirito','Magia. Lo Spirito più vicino a te perde 5...50 Punto[i] Salute. L\'obiettivo (un alleato o te stesso) viene curato di 5 punto[i] per ogni Punto Salute perso.','Magia. Salute persa dallo Spirito più vicino a te: 5...50. Cura di 5 l\'obiettivo alleato per ogni Punto Salute perso.'],
963=>['Ripristino','Rituale Incatenante. Crei uno Spirito di livello 1...14. Quando lo Spirito si esaurisce, tutti i membri della squadra nell\'area risorgono con 5...50% Punto[i] Salute e zero Energia. Lo Spirito si esaurisce dopo 30 secondi.','Rituale Incatenante. Crei uno Spirito di livello 1...14 (in vita per 30 secondo[i]). Effetto al termine: resusciti i membri della squadra nell\'area (Salute: 5...50%; Energia: 0).'],
964=>['Arma Vendicatrice','Magia Altera-arma. Per 8 secondi, la volta successiva in cui l\'obiettivo (un alleato o te stesso) subisce danni o sottrazione salute da un nemico, a quest\'ultimo vengono sottratti fino a 15...60 Punti Salute.','Magia Altera-arma. (Secondi: 8) Sottrae 15...60 Punti Salute dal nemico successivo che infligge danni o sottrazione vita a un obiettivo alleato.'],
973=>['Polvere Accecante','Magia. Deve seguire un attacco con arma secondaria. L\'obiettivo nemico e tutti i nemici adiacenti vengono accecati per 3...15 secondo[i].','Magia. Condizione inflitta all\'obiettivo e ai nemici adiacenti: Accecamento (3...15 secondo[i]). Deve seguire un attacco con arma secondaria.'],
974=>['Tocco della mantide','Abilità. Il bersaglio nemico viene azzoppato per 5...20 secondo/i. Questa abilità conta come un attacco con mano secondaria.','Abilità. Infligge la condizione Azzoppato (5...20 secondo/i). Questa abilità conta come un attacco con mano secondaria.'],
975=>['Assalto Estenuante','Attacco Doppio[_]. Deve seguire un attacco con arma primaria. Interrompe l\'azione dell\'obiettivo nemico. Se interrompe il lancio di una magia, l\'obiettivo nemico subisce 10 di Sforzo.','Attacco Doppio[_]. Interrompe un\'azione. Provoca 10 di Sforzo se l\'azione interrotta era una magia. Deve seguire un attacco con arma primaria.'],
976=>['Colpo a Ripetizione','Attacco con Arma Secondaria. Deve seguire un attacco con arma secondaria. Se va a segno, questo attacco infligge +10...30 danno[i]; se va a vuoto impiegherà 15 secondi in più per ricaricarsi.','Attacco con Arma Secondaria. Danni inferti: +10...30. Se manca l\'obiettivo, il tempo di ricarica di questa abilità aumenta di +15. Deve seguire un attacco con arma secondaria.'],
977=>['Potere del Loto','Incantesimo. Dura 20 secondo[i]; la prossima volta che un tuo attacco doppio va a segno, ottieni 5...20 Punto[i] Energia.','Incantesimo. (Secondi: 20) Energia conseguita la prossima volta che metti a segno un attacco doppio: 5...20.'],
978=>['Segno dell\'Instabilità','Fattura. Dura 20 secondo[i]; la prossima volta che colpisci l\'obiettivo nemico con un attacco doppio, lo abbatti.','Fattura. (Secondi: 20) Provoca abbattimento la prossima volta che colpisci l\'obiettivo nemico con un attacco doppio.'],
979=>['Diffidenza','Fattura. Per 6 secondo/i, la prima magia scagliata dal bersaglio su uno dei tuoi alleati manca, e infligge 10...80 a quel nemico e il 75% di quei danni a tutti i nemici vicini.','Fattura. (6 secondo/i). La prima magia scagliata dal bersaglio su uno dei tuoi alleati non va a segno, infliggendo 10...80 a quel nemico e il 75% di quei danni a tutti i nemici vicini.'],
980=>['Banchetto di Anime','Magia. Elimini tutti gli Spiriti creati dagli alleati nei dintorni. Per ogni Spirito distrutto in questo modo, tutti i membri della squadra vengono curati di 50...100 Punto[i] Salute.','Magia. Cura tutti i membri della squadra di 50...100 per ogni Spirito alleato nei dintorni. Tutti gli Spiriti alleati nei dintorni vengono distrutti.'],
981=>['Recupero','Rituale Incatenante. Crei uno Spirito di livello 1...14. Gli alleati nella sua portata (Spiriti esclusi) ottengono una Rigenerazione della Salute di +1...3. Lo Spirito si esaurisce dopo 15...45 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...14 (in vita per 15...45 secondo[i]). Rigenerazione Salute per gli alleati (Spiriti esclusi) nella portata: +1...3.'],
982=>['Riparo','Rituale Incatenante. Crei uno Spirito di livello 1...12. Gli alleati nella sua portata (Spiriti esclusi) non possono perdere più del 10% della loro Salute massima a seguito di un singolo attacco. Quando lo Spirito impedisce il danno, perde 75...45 Punto[i] Salute. Lo Spirito si esaurisce dopo 30...60 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...12 (in vita per 30...60 secondo[i]). Gli alleati (Spiriti esclusi) nella sua portata non possono perdere più del 10% di Salute massima per un singolo attacco. Costo di prevenzione del danno: questo Spirito perde 75...45 Punto[i] Salute.'],
983=>['Arma dell\'Ombra','Magia Altera-arma. Per 1...7 secondi, l\'obiettivo (un alleato o te stesso) ha un\'Arma dell\'Ombra. Ogni volta che l\'alleato viene colpito da un attacco, l\'aggressore diventa cieco per 5 secondi. Le prossime 1...3 volte in cui quell\'alleato colpisce con un attacco, il suo obiettivo viene accecato per 5 secondi.','Magia Altera-arma. (Secondi: 1...7). Condizione inflitta a chiunque attacchi l\'alleato adiacente: Accecamento (5 secondi). Condizione inflitta da 1...3 attacchi successivi dell\'obiettivo alleato: Accecamento (5 secondi) se colpiscono l\'obiettivo.'],
985=>['Triboli','Magia. Target foe and all foes adjacent to your target are Crippled and Bleeding for 5...15 seconds. Caltrops has half the normal range.','Magia a Portata Dimezzata. Inflicts Crippled and Bleeding conditions (5...15 seconds) on target and adjacent foes.'],
986=>['Colpo a Nove Code','Attacco Doppio[_]. Deve seguire un attacco con arma secondaria. Il Colpo a Nove Code non può essere bloccato e, se va a segno, infligge +15...40 danno[i].','Attacco Doppio[_]. Danni inferti: +15...40. Non bloccabile. Deve seguire un attacco con arma secondaria.'],
987=>['Potere del Palmo Vuoto','Incantesimo d\'Élite. Per 5...15 secondo/i, gli attacchi con mano secondaria e con due armi non costano Energia e si ricaricano il 25...50% più rapidamente.','Incantesimo d\'Élite. (5...15 secondo/i). Gli attacchi con mano secondaria e con due armi non costano Energia e si ricaricano il 25...50% più rapidamente.'],
988=>['Colpo alle Tempie','Attacco d\'Élite con Arma Secondaria. Deve seguire un attacco con arma primaria. Se questo attacco va a segno, l\'obiettivo nemico viene stordito ed accecato per 1...10 secondo[i] e se sta lanciando una magia viene interrotto.','Attacco d\'Élite con Arma Secondaria. Interrompe una magia. Condizioni inflitte: Stordimento e Accecamento (1...10 secondo[i]). Deve seguire un attacco con arma primaria.'],
989=>['Colpo della Fenice Dorata','Attacco con Arma Secondaria. Se non sei sotto gli effetti di un incantesimo, l\'abilità non andrà a segno. Se va a segno, il Colpo della Fenice Dorata infligge +10...30 di danni e tutti i nemici adiacenti subiscono 10...30 danni.','Attacco con Arma Secondaria. Danni inferti all\'obiettivo: +10...30. Danni inferti ai nemici adiacenti: 10...30. Funziona solo se sei sotto incantesimo.'],
990=>['Sopprimi Incantesimi','Abilità. L\'obiettivo nemico perde 1 incantesimo. Tutte le altre abilità che hai equipaggiato (fatta eccezione per gli attacchi) vengono disattivate per 8...4 secondo[i]; per ogni abilità così disattivata, l\'obiettivo nemico toccato perde 1 incantesimo in più.','Abilità a Tocco. Rimuove un incantesimo per ogni abilità equipaggiata (attacchi esclusi). Tutte le tue abilità (esclusi gli attacchi) sono disattivate (8...4 secondo[i]).'],
991=>['Nega Fatture','Magia. Rimuovi una fattura dall\'obiettivo alleato e una fattura aggiuntiva per ogni abilità del Favore Divino equipaggiata che si sta ricaricando.','Magia. Rimuovi una fattura dall\'obiettivo alleato e una fattura aggiuntiva per ogni abilità del Favore Divino equipaggiata che si sta ricaricando.'],
992=>['Fendente Triplo','Attacco d\'Élite con Ascia. Attacchi l\'obiettivo nemico ed i nemici adiacenti; ogni attacco che va a segno infligge +10...40 danno[i].','Attacco d\'Élite con Ascia. Danni inferti: +10...40. Colpisce anche i nemici adiacenti.'],
993=>['Percossa Furiosa','Attacco d\'Élite con Martello. Se Percossa Furiosa va a segno ottieni 1...4 dose[i] di adrenalina. Se colpisci un nemico in movimento gli assesti +10...40 danno[i] e il tuo obiettivo viene abbattuto.','Attacco d\'Élite con Martello. Adrenalina se vai a segno: 1...4. Assesta +10...40 danno[i] e provoca abbattimento se il tuo obiettivo era in movimento.'],
994=>['Percossa Rinnovatrice','Attacco con Martello. Se Percossa Rinnovatrice va a segno, infligge +10...40 danno[i]. Se colpisci un nemico a terra, ottieni 3 Punto[i] Energia; questo attacco si ricarica istantaneamente.','Attacco con Martello. Danni inferti: +10...40. Ottieni 3 Punto[i] Energia e questo attacco si ricarica istantaneamente se il nemico è a terra.'],
995=>['Posizione della Tigre','Posizione. Per 4...10 secondo[i] la velocità dei tuoi attacchi aumenta di un 33%; la Posizione della Tigre termina se uno dei tuoi attacchi non va a segno.','Posizione. (Secondi: 4...10) Incremento tua velocità d\'attacco: 33%. Termina se non colpisci.'],
996=>['Fendente in Posizione','Attacco con Spada. Se va a segno infliggi +5...20 danno[i] e 5...20 danno[i] in più se hai attivato una Posizione.','Attacco con Spada. Danni inferti: +5...20. Assesta 5...20 danno[i] in più se ti trovi in posizione.'],
997=>['Carestia','Rituale della Natura d\'Élite. Crei uno Spirito di livello 1...10. Ogni volta che l\'Energia di una creatura nella sua portata (Spiriti esclusi) si azzera, quella creatura subisce 20...70 danno[i]. Lo Spirito si esaurisce dopo 30...180 secondo[i].','Rituale della Natura d\'Élite. Crei uno Spirito di livello 1...10 (in vita per 30...180 secondo[i]). Assesta 20...70 danno[i] alle creature nella portata la cui Energia scende a 0. Non ha effetto sugli Spiriti.'],
1018=>['Occhio Critico','Abilità. Per 10...35 secondo[i], la probabilità di compiere un colpo critico quando attacchi aumenta del 3...15%; mettendo a segno un colpo critico ottieni 1 Punto[i] Energia.','Abilità. (Secondi: 10...35) Aumento probabilità di assestare un colpo critico: +3...15%. Ottieni 1 Punto[i] Energia ogni volta che metti a segno un colpo critico.'],
1019=>['Colpo Critico','Attacco Doppio[_]. Deve seguire un attacco con arma secondaria. Se va a segno infligge +10...30 danno[i], determina un colpo critico e tu ottieni 1...3 Punto[i] Energia.','Attacco Doppio[_]. Danni inferti: +10...30. Colpo critico automatico. Energia conseguita: 1...3. Deve seguire un attacco con arma secondaria.'],
1020=>['Lame d\'Acciaio','Attacco Doppio[_]. Deve seguire un attacco con arma secondaria. Se va a segno infligge +5...16 danno[i] (max. 60) per ogni attacco con pugnale che si sta ricaricando.','Attacco Doppio[_]. Assesta +5...16 danno[i] (max 60) per ogni attacco con pugnale che si sta ricaricando. Deve seguire un attacco con arma secondaria.'],
1021=>['Colpo della Giungla','Attacco con Arma Secondaria. Deve seguire un attacco di apertura. Se colpisce, infligge +10...25 danni. Se viene colpito un nemico Azzoppato, lui e tutti i nemici adiacenti subiscono 1...31 danni.','Attacco con Arma Secondaria. Infligge +10...25 danni. Infligge 1...31 danni al bersaglio e ai nemici adiacenti se il bersaglio è Azzoppato. Deve seguire un attacco di apertura.'],
1022=>['Colpo Selvaggio','Attacco con Arma Secondaria. Deve seguire un attacco con arma primaria. Se va a segno, infligge +10...35 di danni e rimuove qualsiasi posizione utilizzata dall\'obiettivo nemico. Questo attacco non può essere bloccato.','Attacco con Arma Secondaria. Danni inferti: +10...35. Rimuove la posizione dell\'obiettivo nemico. Non può essere bloccato. Deve seguire un attacco con arma primaria.'],
1023=>['Pungiglione della Mantide Saltante','Attacco con Arma Primaria. Se va a segno, l\'obiettivo nemico subisce +5...15 danno[i]; se colpisce un nemico in movimento, lo fa diventare storpio per 3...15 secondo[i].','Attacco con Arma Primaria. Danni inferti: +5...15. Condizione inflitta se l\'obiettivo nemico si sta muovendo: Storpiatura (3...15 secondo[i]).'],
1024=>['Affondo della Mantide Nera','Attacco con Arma Primaria. Se questo attacco va a segno, infliggi +8...20 danno[i]; se l\'obiettivo nemico è affetto da una fattura diventa storpio per 3...15 secondo[i].','Attacco con Arma Primaria. Danni inferti: +8...20. Condizione inflitta se l\'obiettivo nemico è affetto da fattura: Storpiatura (3...15 secondo[i]).'],
1025=>['Pugnalata Dirompente','Attacco con Arma Primaria. Se questo attacco va a segno, interrompe l\'azione dell\'obiettivo nemico; se interrompe una magia, la disattiva per 3...10 secondo[i].','Attacco con Arma Primaria. Interrompe un\'azione. Se interrompe una magia, la disattiva (3...10 secondo[i]).'],
1026=>['Colpo del Loto Dorato','Attacco con Arma Primaria. Se va a segno, questo attacco infligge +5...20 danno[i]. Se ti trovi sotto gli effetti di un incantesimo ottieni 5...8 Punto[i] Energia.','Attacco con Arma Primaria. Danni inferti: +5...20. Ottieni 5...8 Punto[i] Energia se sei affetto da incantesimo.'],
1027=>['Difese Critiche','Incantesimo. Per 4...10 secondo[i] hai un 75% di probabilità di bloccare; ogni volta che metti a segno un colpo critico, le Difese Critiche si rinnovano.','Incantesimo. (Secondi: 4...10) Tua probabilità di blocco: 75%. Rinnovo: ogni volta che assesti un colpo critico.'],
1028=>['Potere della Perfezione','Incantesimo. Per 60 secondi ogni volta che assesti un colpo critico ottieni 10...40 Punti Salute.','Incantesimo. (Secondi: 60). Punti Salute ottenuti dai colpi critici: 10...40.'],
1029=>['Apostasia Oscura','Incantesimo d\'Élite. Per 3...17 secondo[i], ogni volta che assesti un colpo critico rimuovi un incantesimo dal tuo obiettivo; quando riesci a rimuovere un incantesimo in questo modo perdi 10...3 Punto[i] Energia oppure l\'Apostasia Oscura termina.','Incantesimo d\'Élite. (Secondi: 3...17) I tuoi colpi critici rimuovono un incantesimo. Costo di rimozione: perdi 10...3 Punto[i] Energia o Apostasia Oscura termina.'],
1030=>['Furia della Locusta','Incantesimo d\'Élite. Per 10...35 secondo[i] hai un 50% di probabilità in più di compiere un attacco doppio quando utilizzi i pugnali.','Incantesimo d\'Élite. (Secondi: 10...35) Tua probabilità di colpire doppiamente: +50%. Ha effetto solo se brandisci dei pugnali.'],
1031=>['Coltre d\'Angoscia','Incantesimo. Per 30...60 secondi, se la tua Salute è inferiore a un 50% ottieni una Rigenerazione della Salute di +3...8 e un 75% di probabilità di bloccare gli attacchi.','Incantesimo. (Secondi: 30...60). Rigenerazione della Salute: +3...8. Probabilità di blocco: 75%. Ha effetto solo se la tua Salute è inferiore a un 50%.'],
1032=>['Cuore d\'Ombra','Magia. Cure: 30...150. Compi un Passo nell\'Ombra verso un punto a caso nei dintorni allontanandoti dall\'obiettivo.','Magia. Ti curi di 30...150 e compi un Passo nell\'Ombra verso un punto a caso nei dintorni allontanandoti dall\'obiettivo.'],
1033=>['Stilettata','Abilità. Deve seguire un attacco doppio. L\'obiettivo nemico viene colpito da 25...100 danno[i] da terra e subisce una Ferita Profonda per 5...20 secondo[i].','Abilità. Danni da terra inferti: 25...100. Condizione inflitta: Ferita Profonda (5...20 secondo[i]). Deve seguire un attacco doppio.'],
1034=>['Ferita Sanguinante','Fattura d\'Élite. For 1...7 seconds, target foe moves 33% slower. That foe takes 5...25 damage each second while suffering from a condition.','Fattura d\'Élite. (Secondo[i]: 1...7). La velocità dell\'obiettivo nemico è ridotta di un 33%. Tale nemico subisce 5...25 danni al secondo se affetto da una condizione.'],
1035=>['Promessa dell\'Assassino','Fattura d\'Élite. Dura 5...15 secondo[i]; se l\'obiettivo nemico muore, ottieni 5...20 Punto[i] Energia e tutte le tue abilità si ricaricano.','Fattura d\'Élite. (Secondi: 5...15) Ottieni 5...20 Punto[i] Energia e tutte le tue abilità si ricaricano se l\'obiettivo nemico muore.'],
1036=>['Sigillo della Malizia','Sigillo. Perdi una condizione per ogni condizione sofferta dal tuo obiettivo nemico.','Sigillo. Perdi una condizione per ogni condizione sofferta dall\'obiettivo nemico.'],
1037=>['Fuga nell\'Oscurità','Posizione. Per 5...15 secondo[i], la tua velocità aumenta di un 25% e subisci la metà del danno. La Fuga nell\'Oscurità termina se un tuo attacco va a segno.','Posizione. (Secondi: 5...15) Incremento tua velocità di movimento: 25%. Ricevi la metà dei danni. Termina se un tuo attacco va a segno.'],
1038=>['Pugnale Azzoppante','Magia. Scagli contro l\'obiettivo nemico un Pugnale Azzoppante che infligge 15...60 danno[i] da terra se va a segno e rende storpi i nemici in movimento per 3...15 secondo[i]. La portata di questa magia è la metà del normale.','Magia a Portata Dimezzata. Proiettile. Danni da terra: 15...60. Condizione inflitta se l\'obiettivo nemico si sta muovendo: Storpiatura (3...15 secondo[i]).'],
1040=>['Cammino dello Spirito','Magia. Compi un Passo nell\'Ombra verso lo Spirito preso di mira.','Magia. Compi un Passo nell\'Ombra verso lo Spirito preso di mira.'],
1041=>['Furia Invisibile','Posizione. Tutti i nemici adiacenti vengono accecati per 3...10 secondi. Per 10...30 secondi non puoi essere bloccato dai nemici accecati.','Posizione. Condizione inflitta ai nemici adiacenti: Accecamento (secondi: 3...10). Non puoi essere bloccato dai nemici accecati (secondi: 10...30).'],
1042=>['Lame Scintillanti','Posizione d\'Élite. Per 5...30 secondo[i] hai un 75% di probabilità di bloccare gli attacchi in arrivo mentre stai attaccando. Ogni volta che blocchi un attacco in questo modo, l\'aggressore subisce 5...20 danno[i].','Posizione d\'Élite. (Secondi: 5...30) Probabilità di blocco mentre attacchi: 75%. Effetto del blocco: 5...20 danno[i] al tuo aggressore.'],
1043=>['Slancio','Posizione. Per 3 secondo[i], la tua velocità di corsa aumenta di un 50%.','Posizione. (Secondi: 3) Incremento tua velocità di movimento: 50%.'],
1044=>['Prigione Oscura','Fattura. Compi un Passo nell\'Ombra verso l\'obiettivo nemico; per 1...6 secondo[i] la sua velocità rallenta del 33%.','Fattura. Compi un Passo nell\'Ombra verso l\'obiettivo nemico. Rallentamento suoi movimenti: 33% (1...6 secondo[i]).'],
1045=>['Schiaffo','Abilità d\'Élite. L\'obiettivo nemico toccato subisce 10...65 danno[i] ed è affetto da Storpiatura per 1...5 secondo[i]. Quest\'abilità è considerata un attacco con arma secondaria.','Abilità d\'Élite a Tocco. Danni inferti: +10...65. Condizione inflitta: Storpiatura (1...5 secondo[i]). Quest\'abilità è considerata un attacco con arma secondaria.'],
1048=>['Incantesimo Rivelato','Magia. Rimuovi un incantesimo dall\'obiettivo nemico ed ottieni 3...15 Punto[i] Energia. Per 20 secondi l\'incantesimo rimosso si sostituirà all\'Incantesimo Rivelato.','Magia. Rimuove un incantesimo dall\'obiettivo nemico. Effetto della rimozione: ottieni 3...15 Punto[i] Energia. Questa magia viene rimpiazzata con quell\'incantesimo (20 secondi).'],
1049=>['Fattura Rivelata','Magia. Elimini una fattura dall\'obiettivo (un alleato o te stesso) ed ottieni 4...10 Punto[i] Energia. Per 20 secondi, la fattura sottratta si sostituirà alla Fattura Rivelata.','Magia. Rimuove una fattura dall\'obiettivo (un alleato o te stesso). Effetto di rimozione: ottieni 4...10 Punto[i] Energia. Questa magia viene rimpiazzata con quella fattura (20 secondi).'],
1052=>['Dolore Accumulato','Magia. L\'obiettivo nemico subisce 15...75 danno[i]; se è affetto da 2 o più fatture, riceve una Ferita Profonda per 5...20 secondo[i].','Magia. Danni inferti: 15...75. Condizione inflitta se l\'obiettivo è affetto da 2 o più fatture: Ferita Profonda (5...20 secondo[i]).'],
1053=>['Distrazione Psichica','Magia d\'Élite. Tutte le tue altre abilità vengono disattivate per 8 secondi. Se l\'obiettivo nemico sta utilizzando un\'abilità, tale abilità verrà interrotta e disattivata per 5...12 secondi in più.','Magia d\'Élite. Interrompe un\'abilità. Effetto dell\'interruzione: disattiva l\'abilità interrotta (+5...12 secondi). Le tue altre abilità vengono disattivate per 8 secondi.'],
1054=>['Volto dell\'Antenato','Incantesimo. Dura 4...10 secondo[i]; ogni volta che l\'obiettivo (un alleato o te stesso) viene colpito da un attacco ravvicinato, tutti i nemici adiacenti perdono tutta l\'adrenalina e 3 Punti Energia.','Incantesimo. (Secondi: 4...10) Tutti i nemici adiacenti perdono tutta l\'adrenalina e 3 Punti Energia ogni volta che l\'obiettivo (un alleato o te stesso) viene colpito da un attacco ravvicinato.'],
1055=>['Insicurezza Ricorrente','Fattura d\'Élite. Per 5 secondi l\'obiettivo nemico subisce una Degenerazione Salute di -1...6. Se il nemico è sotto gli effetti di un\'altra fattura che si prolunga al termine dell\'Insicurezza Ricorrente, quest\'ultima viene riapplicata.','Fattura d\'Élite. (Secondi: 5). Degenerazione Salute: -1...6. Rinnovo: se l\'obiettivo nemico è sotto gli effetti di un\'altra fattura che si prolunga al termine dell\'Insicurezza Ricorrente.'],
1056=>['Fardello di Kitah','Fattura. Per 6...12 secondi, i movimenti dell\'obiettivo nemico rallentano del 50%. Quando il Fardello di Kitah termina, ottieni 10...18 Punto[i] Energia.','Fattura. (Secondi: 6...12) Rallentamento velocità di movimento dell\'obiettivo nemico: 50%. Effetto al termine: ottieni 10...18 Punto[i] Energia.'],
1057=>['Instabilità Psichica','Magia d\'Élite. Interrompe l\'azione dell\'obiettivo nemico. Se si tratta di un\'abilità, l\'obiettivo nemico e tutti i nemici nei dintorni finiscono a terra per 2...4 secondi (50% di probabilità di fallimento con Lancio Rapido di grado 4 o inferiore).','Magia d\'Élite. Interrompe un\'azione. Effetto dell\'interruzione: se l\'azione è un\'abilità, l\'obiettivo nemico e tutti i nemici nei dintorni finiscono a terra per 2...4 secondi. 50% di probabilità di fallimento con Lancio Rapido inferiore al grado 5.'],
1059=>['Sigillo Mangiafattura','Sigillo. L\'obiettivo alleato toccato e fino a 2...5 alleato[i] adiacente[i] perdono una fattura ciascuno; tu ottieni 1...4 Punto[i] Energia per ogni fattura che viene rimossa in questo modo.','Sigillo a Tocco. Rimuove una fattura dall\'obiettivo e da 2...5 alleato[i] adiacente[i]. Effetto della rimozione: 1...4 Punto[i] Energia per ogni fattura rimossa.'],
1061=>['Retroazione','Magia. L\'obiettivo nemico perde un incantesimo. Se un incantesimo viene rimosso in questo modo, quel nemico perde anche 4...10 Punto[i] Energia.','Magia. Rimuove un incantesimo. Effetto della rimozione: l\'obiettivo nemico perde 4...10 Punto[i] Energia.'],
1062=>['Ruberia Arcana','Magia. Dura 5...35 secondo[i]; una magia a caso dell\'obiettivo nemico viene disattivata e si sostituisce alla Ruberia Arcana.','Magia. (Secondi: 5...35) Disattiva una magia a caso. Questa abilità si trasforma in quella magia.'],
1066=>['Deruba il Vincitore','Fattura d\'Élite. Per 3...15 secondo[i], ogni volta che l\'obiettivo nemico attacca o lancia una magia su una creatura con meno Salute, perde 25...100 Punto[i] Salute.','Fattura d\'Élite. (Secondi: 3...15) Salute persa ogni volta che l\'obiettivo nemico attacca o lancia magie su una creatura con Salute inferiore: 25...100.'],
1067=>['Colpo Devastavita','Magia. L\'obiettivo nemico subisce 12...48 danno[i] da ombra. Se la sua Salute è superiore al 50%, gli sottrarrai fino a 12...48 Punto[i] Salute.','Magia. Danni inferti: 12...48. Salute sottratta se la Salute dell\'obiettivo nemico è superiore al 50%: 12...48.'],
1068=>['Freddo Pungente','Magia. L\'obiettivo nemico subisce 15...60 danno[i] da freddo; se aveva più Salute di te, il Freddo Pungente si ricarica all\'istante.','Magia. Danni da freddo inferti: 15...60. Si ricarica all\'istante se l\'obiettivo nemico aveva più Salute di te.'],
1069=>['Sapore del Dolore','Magia. Se la Salute dell\'obiettivo nemico è inferiore al 50%, ottieni 30...150 Punto[i] Salute.','Magia. Ti cura di 30...150. Ha effetto solo se la Salute dell\'obiettivo nemico è inferiore al 50%.'],
1070=>['Contamina Incantesimi','Magia. L\'obiettivo nemico e tutti i nemici nei dintorni subiscono 6...60 danno[i] da ombra e 4...20 danno[i] da ombra per ogni incantesimo presente su di loro.','Magia. Danni all\'obiettivo e ai nemici nei dintorni: 6...60. Assesta 4...20 danno[i] in più per ogni incantesimo presente su di loro.'],
1071=>['Brividi di Terrore','Fattura. Dura 10...40 secondo[i]; se l\'obiettivo nemico subisce un danno da freddo mentre usa un\'abilità, viene interrotto e tu perdi 8...3 Punto[i] Energia oppure i Brividi di Terrore terminano.','Fattura. (Secondi: 10...40) Il danno da freddo interrompe le abilità dell\'obiettivo nemico. Costo dell\'interruzione: perdi 8...3 Punto[i] Energia o questa fattura termina.'],
1075=>['Sciame Vampirico','Magia. Lo Sciame Vampirico sottrae fino a 15...60 Punti Salute da un massimo di tre nemici nell\'area.','Magia. Sottrazione Salute: 15...60. Colpisce altri 2 nemici nell\'area.'],
1076=>['Bevi Sangue','Magia. Se la tua Salute è superiore al 90%, inizi a sanguinare per 6 secondo[i]; sottrai fino a 20...65 Punto[i] Salute all\'obiettivo nemico.','Magia. Sottrazione Salute: 20...65. Sei affetto da Emorragia (6 secondo[i]) se la sua Salute è superiore a 90%.'],
1077=>['Morso del Vampiro','Abilità. Tocca l\'obiettivo nemico per sottrargli fino a 29...74 Punto[i] Salute.','Abilità a Tocco. Sottrazione Salute: 29...74.'],
1078=>['Morso dello Sguazzatore','Abilità. L\'obiettivo nemico toccato subisce 20...58 danno[i].','Abilità a Tocco. Danni inferti: 20...58.'],
1079=>['Tocco Debilitante','Abilità. L\'obiettivo nemico toccato perde 5...65 Punto[i] Salute e soffre di Debolezza per 5...20 secondo[i].','Abilità a Tocco. Perdita Salute: 5...65. Condizione inflitta: Debolezza (5...20 secondo[i]).'],
1081=>['Vento di Teinai','Magia. L\'obiettivo nemico e i nemici adiacenti subiscono 10...40 danni da freddo. I nemici affetti da Bruciatura che vengono colpiti dal Vento di Teinai subiscono un danno aggiuntivo di 40...80 e la loro azione viene interrotta.','Magia. Danni da freddo inferti: 10...40. Danno subito da nemici affetti da Bruciatura: 40...80. L\'azione di questi nemici viene interrotta. Colpisce anche i nemici adiacenti.'],
1082=>['Freccia dello Shock','Magia. Lanci una Freccia dello Shock che vola rapidamente verso l\'obiettivo nemico infliggendo 5...50 danni da fulmine. Se colpisce un nemico che soffre di Armatura Incrinata, ottieni 5 Punti Energia e 1 Punto Energia per ogni 2 gradi della Riserva di Energia. La Freccia dello Shock ha una penetrazione dell\'armatura del 25%.','Magia. Proiettile rapido: danni da fulmine inferti: 5...50. Energia conseguita se colpisci un nemico con Armatura Incrinata: 5 più 1 per ogni 2 gradi della Riserva di Energia. Penetrazione armatura: 25%.'],
1083=>['Terreno Instabile','Magia d\'Élite. Crei un Terreno Instabile nella posizione dell\'obiettivo nemico. Per 5 secondi i nemici nei dintorni subiscono 10...40 danni da terra al secondo. I nemici all\'attacco colpiti dal Terreno Instabile vengono abbattuti.','Magia d\'Élite. Danni da terra inferti al secondo: 10...40 (5 secondi); provoca abbattimento ai nemici all\'attacco. Colpisce i nemici vicini alla posizione iniziale dell\'obiettivo.'],
1084=>['Armatura Scheggiante','Incantesimo. Per 5...11 secondi, hai un 25...50% di probabilità di bloccare gli attacchi e, se ti viene lanciata contro una magia ostile o un attacco, un nemico nei dintorni subisce 5...35 danni da terra.','Incantesimo. (Secondi: 5...11.) Probabilità di blocco: 25...50%. Infligge 5...35 danni da terra ad un nemico nei dintorni ogni volta che sei il bersaglio di una magia ostile o di un attacco.'],
1085=>['Esplosione di Cenere','Fattura. Infligge 35...65 danni da terra all\'obiettivo e ai nemici adiacenti. I nemici affetti da Bruciatura che vengono colpiti da Esplosione di Cenere subiscono la fattura per 5 secondi e hanno una possibilità del 20...75% di mancare l\'obiettivo.','Fattura. Infligge 35...65 danni da terra. Durata della fattura subita dai nemici con Bruciatura: 5 secondi. Probabilità di mancare l\'obiettivo: 20...75%. Colpisce anche i nemici adiacenti.'],
1086=>['Passo del Drago','Magia. Evochi un Passo del Drago nella posizione dell\'obiettivo nemico. Tutti i nemici nei dintorni di questa posizione vengono abbattuti e subiscono 26...100 danni da terra.','Magia. Infligge 26...100 danni da terra. Provoca abbattimento. Colpisce anche i nemici vicino a questo nemico.'],
1088=>['Seconda Opportunità','Magia d\'Élite. Ottieni 1 Punti Energia e 5 Punti Salute per ogni punto Energia limitato da Sforzo. Perdi tutti gli incantesimi.','Magia d\'Élite. Ottieni 1 Punti Energia e 5 Punti Salute per ogni punto Sforzo. Perdi tutti gli incantesimi.'],
1090=>['Brace Ardente','Fattura. L\'obiettivo nemico subisce 10...70 danni da fuoco. Se sei sotto Sforzo, quel nemico viene raggiunto da Brace Ardente per 3 secondi e subisce 5...25 danni da fuoco aggiuntivi per ogni secondo.','Fattura. Danni da fuoco inferti all\'obiettivo: 10...70. Fattura subita dal nemico se sei sotto Sforzo: 3 secondi. Danni da fuoco aggiuntivi per secondo: 5...25.'],
1091=>['Drago Doppio','Incantesimo d\'Élite. Invochi il potere del Drago. Per 8 secondi, tu e l\'obiettivo alleato siete affetti dall\'incantesimo Drago Doppio. I nemici adiacenti sono colpiti da 10...40 danni da fuoco al secondo. Inoltre, quando tu o il tuo alleato usate abilità per mirare a un nemico, questi prende fuoco per 1...4 secondi.','Incantesimo d\'Élite. (Secondi: 8.) Incanta te e l\'obiettivo alleato. I nemici adiacenti subiscono 10...40 danni da fuoco al secondo. Le abilità che prendono di mira un nemico infliggono anche Bruciatura (1...4 secondi).'],
1093=>['Calore di Teinai','Guardia. Metti una guardia del Calore di Teinai nella tua posizione per 10...15 secondi. Degenerazione Salute dei nemici nell\'area della guardia: 2...5. I nemici indeboliti attaccano più lentamente del 33%. Questa abilità verrà disabilitata per 20 secondi.','Guardia. (Secondi: 10...15). Degenerazione Salute: -2...5. Riduzione velocità dei nemici indeboliti nell\'area della guardia: - 33% Disabilitazione: 20 secondi.'],
1094=>['Alito di Fuoco','Magia. Crei un Alito di Fuoco nella posizione attuale dell\'obiettivo nemico. Per 5 secondi, i nemici adiacenti a quella posizione subiscono 10...40 danni da fuoco al secondo.','Magia. Danni da fuoco inferti al secondo: 10...40 (5 secondi). Colpisce i nemici adiacenti alla posizione iniziale dell\'obiettivo.'],
1095=>['Esplosione Stellare','Magia d\'Élite. L\'obiettivo nemico toccato e tutti i nemici nell\'area subiscono 7...112 danni da fuoco e prendono fuoco per 1...4 secondi. Ottieni 2 Punti Energia per ogni nemico che colpisci.','Magia d\'Élite a Tocco. Danni da fuoco inferti: 7...112. Infligge Bruciatura (1...4 secondi). Ottieni 2 Punti Energia per ogni nemico colpito. Colpisce anche i nemici nell\'area.'],
1096=>['Glifo dell\'Essenza','Glifo. Per 15 secondi la tua prossima magia viene lanciata immediatamente ma ti fa perdere tutta l\'Energia.','Glifo. (Secondi: 15.) Il lancio della tua prossima magia è istantaneo. Perdi tutta l\'Energia.'],
1097=>['Prigione di Teinai','Fattura. Per 1...8 secondi le gambe dell\'obiettivo nemico sono imprigionate nel ghiaccio e la sua velocità diminuisce del 66%. Se quel nemico soffre di Armatura Incrinata, il gelo penetra all\'interno causando una degenerazione Salute di 5...9.','Fattura. (Secondi: 1...8.) Riduzione velocità dell\'obiettivo nemico: -66%. Degenerazione Salute dei nemici con Armatura Incrinata: 5...9.'],
1098=>['Specchio di Ghiaccio','Fattura d\'Élite. Infrangi uno Specchio di Ghiaccio. I nemici vicino a te e all\'obiettivo alleato subiscono 15...70 danni da freddo e la loro velocità diminuisce di un 66% per 2...6 secondi. Se colpisci un nemico sotto l\'effetto di una Magia dell\'Acqua, lo Specchio di Ghiaccio si ricarica più velocemente del 50%.','Fattura d\'Élite. Danni da freddo inferti: 15...70. Rallentamento dei nemici: 66% (2...6 secondi). Colpisce i nemici vicino a te e all\'obiettivo alleato. Si ricarica più velocemente del 50% se colpisce un nemico sotto l\'effetto di una Magia dell\'Acqua.'],
1099=>['Cristalli di Teinai','Magia. L\'obiettivo nemico subisce 20...40 danni. Se l\'obiettivo nemico ha una fattura Magia dell\'Acqua, questo incantesimo colpisce l\'obiettivo e tutti i nemici nei dintorni per un danno aggiuntivo di 20...40 e i nemici nei dintorni soffrono inoltre di Armatura Incrinata per 5...15 secondi.','Magia. Danni inferti all\'obiettivo nemico: 20...40. Danno aggiuntivo al nemico con fattura Magia dell\'Acqua: +20...40. Condizione inflitta ai nemici nei dintorni: Armatura Incrinata (Secondi: 5...15).'],
1113=>['Indignazione del Kirin','Magia. Per 5 secondi, i nemici adiacenti al luogo in cui viene lanciata questa magia subiscono 8...32 danno[i] sacro[i] al secondo.','Magia. Danni sacri inferti al secondo: 8...32 (5 secondi). Colpisce i nemici adiacenti alla tua posizione iniziale.'],
1114=>['Legame dello Spirito','Incantesimo. Dura 8 secondo[i]; ogni volta che l\'obiettivo (un alleato o te stesso) subisce più di 50 danno[i] dai 10 attacchi o magie successivi, viene curato di 30...90 Punto[i] Salute.','Incantesimo. (Secondi: 8) Cura di 30...90 ogni volta che l\'obiettivo alleato riceve più di 50 danno[i]. Termina dopo che quest\'alleato ha subito danni da 10 attacchi o magie.'],
1115=>['Aria dell\'Incantesimo','Incantesimo d\'Élite. Per 4...10 secondo[i] gli incantesimi lanciati su un obiettivo alleato costano 10 Punto[i] Energia in meno (min. 1 Punto[i] Energia).','Incantesimo d\'Élite. (Secondi: 4...10) Riduzione costo energetico degli incantesimi lanciati sull\'obiettivo alleato: 10 (minimo 1 Punto[i] Energia). Impossibile selezionare se stessi.'],
1117=>['Delizia del Paradiso','Magia. Cura te stesso e i membri della squadra a portata d\'orecchio di 15...60 punto[i].','Magia. Cure per te e i membri della squadra a portata d\'orecchio: 15...60.'],
1118=>['Esplosione Guaritrice','Magia d\'Élite. L\'obiettivo alleato viene curato di 20...120 Punti Salute. Tutti i membri della squadra a portata d\'orecchio dell\'obiettivo ottengono i Punti Salute del Favore Divino. Le tue Preghiere Punitive vengono disattivate per 20 secondi.','Magia d\'Élite. Cure: 20...120. Bonus di Punti Salute per i membri della squadra a portata d\'orecchio dell\'obiettivo: Favore Divino. <c x="SkillDull">Condizione disattivata: Preghiere Punitive (secondi: 20).'],
1119=>['Circolo Guaritore di Karei','Magia. Curi te stesso e tutte le creature adiacenti di 30...180 punto[i].','Magia. Ti cura di 30...180. Cura anche le creature adiacenti.'],
1120=>['Sguardo di Jamei','Magia. Curi l\'alleato di 35...180 Punto[i] Salute.','Magia. Cure: 35...180. Impossibile selezionare se stessi.'],
1121=>['Dono della Salute','Magia. Tutte le altre abilità che hai equipaggiato associate alle Preghiere Curative vengono disattivate per 10...5 secondo[i]; l\'obiettivo alleato viene curato di 15...150 Punto[i] Salute.','Magia. Cure: 15...150. Disattiva le altre abilità dell\'attributo Preghiere Curative (10...5 secondo[i]). Impossibile selezionare se stessi.'],
1123=>['Preserva Vita','Incantesimo d\'Élite. Condizioni rimosse dall\'obiettivo alleato: 0...2. Per 8 secondi, la volta successiva in cui l\'alleato viene colpito da un attacco che dovrebbe infliggere danni o sottrazione vita, ottiene il corrispettivo in punti Salute (max. 20...100) dei danni o della sottrazione vita.','Incantesimo d\'Élite. (Secondi: 8) Converte il danno in arrivo o la sottrazione vita successivi in Punti Salute (max. 20...100). Effetto iniziale: rimuove 0...2 condizioni.'],
1126=>['Rimozione Empatica','Magia d\'Élite. Tu e l\'obiettivo alleato perdete 1 condizione e 1 fattura e venite curati di 50.','Magia d\'Élite. Rimuove una condizione e una fattura dall\'obiettivo alleato e da te stesso. Cure: 50. Impossibile selezionare se stessi.'],
1128=>['Salmodia di Resurrezione','Magia. Resusciti l\'obiettivo alleato con un massimo di Salute equivalente alla tua Salute attuale ed un 5...35% della tua Energia. La portata di questa magia è la metà del normale.','Magia a Portata Dimezzata. Resuscita il membro della squadra preso di mira con la tua Salute attuale e un 5...35% di Energia.'],
1129=>['Parola di Biasimo','Magia d\'Élite. Il nemico bersaglio subisce 30...130 di danni sacri. Se il tuo obiettivo aveva meno del 50% di Salute, Parola di Biasimo ci mette 20 secondo/i extra per ricaricarsi.','Magia d\'Élite. Infligge 30...130 di danni sacri. Tempo di ricarica di +20 se la Salute del nemico bersaglio è sotto al 50%.'],
1130=>['Lancia di Luce','Magia. La Lancia di Luce vola verso l\'obiettivo nemico e, se va a segno, infligge 26...56 danno[i] sacro[i]; se colpisce un nemico all\'attacco gli infligge +15...60 danno[i].','Magia. Proiettile. Danni sacri: 26...56. Assesta 15...60 danno[i] in più se l\'obiettivo nemico sta attaccando.'],
1131=>['Colpo di Stonesoul','Abilità. L\'obiettivo nemico toccato subisce 10...55 danno[i] sacro[i]. Se è a terra subisce 10...55 danno[i] sacro[i] in più.','Abilità a Tocco. Danni sacri inferti: 10...55. Danni sacri aggiuntivi se l\'obiettivo nemico è stato abbattuto: 10...55.'],
1133=>['Colpo Ebbro','Attacco Ravvicinato. Se questo attacco va a segno, infliggi +10...40 danno[i] e l\'obiettivo è affetto da una delle seguenti condizioni: Ferita Profonda (per 20 secondi), Debolezza (per 20 secondi), Emorragia (per 25 secondi) o Storpiatura (per 15 secondi). Dopo aver sferrato il Colpo Ebbro, cadi a terra.','Attacco Ravvicinato. Danni inferti: +10...40. Provoca una condizione a caso tra le seguenti: Ferita Profonda (20 secondi), Debolezza (20 secondi), Emorragia (25 secondi), Storpiatura (15 secondi). Vieni abbattuto.'],
1134=>['Colpo del Leviatano','Attacco Ravvicinato. Se questo attacco va a segno, infliggi +5...20 danno[i]; se viene bloccato, l\'obiettivo viene abbattuto e subisce 10...34 danno[i].','Attacco Ravvicinato. Danni inferti: +5...20. Provoca abbattimento e infligge 10...34 danno[i] se bloccato.'],
1135=>['Colpo di Jaizhenju','Attacco con Spada. Se il Colpo di Jaizhenju va a segno, infliggi +1...30 danno[i]. Se non stai utilizzando una Posizione, il Colpo di Jaizhenju non può essere bloccato.','Attacco con Spada. Danni inferti: +1...30. Non bloccabile, a meno che non ti trovi in una posizione.'],
1136=>['Fendente Penetrante','Attacco con Ascia. Se va a segno infliggi +10...25 danno[i]. Questo attacco con l\'ascia ha il 20% di capacità di penetrazione delle armature.','Attacco con Ascia. Danni inferti: +10...25. Penetrazione armatura: 20%.'],
1137=>['Percossa dello Yeti','Attacco con Martello. Perdi tutta l\'adrenalina. Colpisce tutti i nemici adiacenti. Se questo attacco colpisce un nemico affetto da una condizione, il nemico va a terra. (50% di probabilità di fallimento con Abilità col Martello di grado 4 o inferiore).','Attacco con Martello. Colpisce tutti i nemici adiacenti. I nemici affetti da una condizione vanno a terra. Perdi tutta l\'adrenalina. 50% di probabilità di fallimento con Abilità col Martello di grado 5 o superiore.'],
1141=>['"Morirai!"','Urlo. Se la Salute del nemico bersaglio è meno del 90%, ottieni 1...3 colpo/i da adrenalina.','Urlo. Ottieni 1...3 colpo/i da adrenalina. Nessun effetto a meno che il nemico non abbia meno del 90% della Salute.'],
1142=>['Parata Propizia','Posizione d\'Élite. Per 8 secondo[i], il prossimo attacco a te diretto viene bloccato. Ottieni 1...4 dose[i] di adrenalina al termine di questa posizione.','Posizione d\'Élite. (Secondo[i]: 8). Blocca un attacco. Effetto al termine: ottieni 1...4 dose[i] di adrenalina.'],
1144=>['Fendente di Aladargento','Attacco con Spada. Questo attacco infligge +1...40 danno[i] se va a segno.','Attacco con Spada. Danni inferti: +1...40.'],
1146=>['Spintone','Abilità d\'Élite. Il bersaglio nemico che tocchi subisce 15...75 danni, perde la propria posizione e viene atterrato.','Abilità d\'Élite a Tocco. Il bersaglio nemico che tocchi subisce 15...75 danni, perde la propria posizione e viene atterrato.'],
1191=>['Attacco della Separazione','Attacco con Arco. Se va a segno, questo attacco provoca +5...25 danno[i] e ha un 10% di capacità di penetrazione delle armature.','Attacco con Arco. Danni inferti: +5...25. Penetrazione armatura: 10%.'],
1192=>['Tiro di Zojun','Attacco con Arco. Scocca una freccia che ha una portata pari a metà del normale, ma infligge +10...40 danno[i].','Attacco con Arco a Portata Dimezzata. Danni inferti: +10...40.'],
1194=>['Legame Predatore','Urlo. Per 5...20 secondi gli attacchi della tua mascotte sono più veloci di un 25%. Gli attacchi messi a segno ti curano di 1...31 Punti Salute.','Urlo. (Secondi: 5...20). Aumento della velocità degli attacchi della tua mascotte: 25%. Punti Salute ottenuti ogni volta che la tua mascotte mette a segno un attacco: 1...31.'],
1195=>['Guarigione Congiunta','Abilità d\'Élite. Per 15 secondo[i], la tua mascotte sottrae 1...20 Punto[i] Salute quando un suo attacco va a segno. Tu e la tua mascotte venite curati di 20...104 Punto[i] Salute. Se la tua mascotte è morta, viene resuscitata con un 50% di Salute. Se sei equipaggiato di questa abilità, la mascotte potrà viaggiare insieme a te.','Abilità d\'Élite. (Secondo[i]: 15). Gli attacchi della tua mascotte sottraggono 1...20 Punto[i] Salute. Effetto iniziale: cure per te e la tua mascotte: 20...104; resuscita la tua mascotte (50% Salute), se morta. Se sei equipaggiato di questa abilità, la mascotte potrà viaggiare insieme a te.'],
1196=>['Fretta di Zojun','Posizione. Per 5...11 secondo[i], la tua velocità aumenta del 33% e hai un 27...75% di probabilità di bloccare i proiettili in arrivo. La Fretta di Zojun termina se attacchi.','Posizione. (Secondi: 5...11) Incremento tua velocità di movimento: 33%. Probabilità di blocco proiettili: 27...75%. Termina se attacchi.'],
1197=>['Tiro Pungente','Attacco con Arco. Il Tiro Pungente infligge solo 10...30 di danni e ha una velocità superiore a quella standard. Se colpisce un nemico con Salute inferiore a un 50%, si ricarica all\'istante. Le altre abilità di attacco di cui disponi vengono disattivate per 2 secondi.','Attacco con Arco. Freccia veloce. Danni inferti: 10...30. Si ricarica all\'istante se la Salute dell\'obiettivo nemico è inferiore al 50%. Le altre abilità di attacco di cui disponi vengono disattivate (2 secondi).'],
1198=>['Freccia a Punta Larga','Attacco con Arco d\'Élite. Lanci una freccia a punta larga che si muove più lentamente del normale; se va a segno, l\'obiettivo nemico viene stordito per 5...20 secondo[i] e se sta lanciando una magia, questa viene interrotta.','Attacco con Arco d\'Élite. Freccia lenta. Interrompe una magia. Condizione inflitta: Stordimento (5...20 secondo[i]).'],
1199=>['Frecce di Vetro','Preparazione d\'Élite. Per 10...35 secondo[i] le tue frecce infliggono +6...20 danno[i] se vanno a segno e provocano Emorragia per 10...20 secondo[i] se vengono "bloccate".','Preparazione d\'Élite. (Secondi: 10...35) Danni inferti dalle tue frecce: +6...20. Condizione inflitta se bloccato: Emorragia (10...20 secondo[i]).'],
1200=>['Sigillo dell\'Arciere','Sigillo d\'Élite. Per 1...24 secondo[i] le condizioni da te applicate mentre impugni l\'arco durano un 150% in più.','Sigillo d\'Élite. (Secondi: 1...24) Incremento durata delle condizioni da te applicate mentre impugni l\'arco: 150%.'],
1201=>['Balzo Selvaggio','Attacco con Mascotte. La tua mascotte si cimenta in un Balzo Selvaggio che infligge +5...20 danno[i]; se colpisce un nemico che sta compiendo una magia, lo abbatte.','Attacco con Mascotte. Danni inferti: +5...20. Provoca abbattimento se l\'obiettivo nemico sta lanciando una magia.'],
1202=>['Guizzo Furioso','Attacco d\'Élite con Mascotte. La tua mascotte si cimenta in un Guizzo Furioso che causa una Ferita profonda all\'obiettivo nemico per 5...20 secondi e infligge +10...50 di danni.','Attacco d\'Élite con Mascotte. Condizione inflitta: Ferita Profonda (secondi: 5...20). Danni inflitti: +10...50.'],
1203=>['Lacerazione Bestiale','Attacco con Mascotte. La tua mascotte si cimenta in una Lacerazione Bestiale che infligge +5...20 danno[i]. Se colpisce un avversario a terra lo stordisce per 4...10 secondo[i].','Attacco con Mascotte. Danni inferti: +5...20. Condizione inflitta se l\'obiettivo nemico è abbattuto: Stordimento (4...10 secondo[i]).'],
1205=>['Morso Velenoso','Attacco con Mascotte. La tua mascotte si cimenta in un Morso Velenoso che avvelena l\'obiettivo nemico per 5...20 secondi.','Attacco con Mascotte. Condizione inflitta: Avvelenamento (secondi: 5...20).'],
1206=>['Balzo','Attacco con Mascotte. Il prossimo attacco della tua mascotte sarà un Balzo che infligge +5...20 danno[i]; se colpisce un nemico in movimento, lo abbatte.','Attacco con Mascotte. Danni inferti: +5...20. Provoca abbattimento se l\'obiettivo nemico si sta muovendo.'],
1209=>['Furia Bestiale','Posizione. Tutte le tue abilità sono disattivate per 5 secondi (fatta eccezione per le abilità di attacco). Per 5...11 secondo[i], la tua velocità d\'attacco aumenta del 25%.','Posizione. (Secondi: 5...11) Incremento velocità di attacco: 25%. Le tue abilità (attacchi esclusi) sono disattivate (5 secondi).'],
1211=>['Nido di Vipera','Trappola. Crei un Nido di Vipera. Quando viene attivato, tutti i nemici nei dintorni vengono colpiti da 5...35 danno[i] perforanti e vengono avvelenati per 5...20 secondo[i]. Il Nido di Vipera termina dopo 90 secondo[i]. Questa trappola viene facilmente interrotta.','Trappola. (Secondi: 90) Ha effetto sui nemici nei dintorni. Danni perforanti: 5...35. Condizione inflitta: Veleno (5...20 secondo[i]). Facile interruzione.'],
1212=>['Equinozio','Rituale della Natura d\'Élite. Crei uno spirito di livello 1...10. Le magie che provocano Sforzo lanciate nel suo raggio procureranno 10 di Sforzo in più. Lo spirito si esaurisce dopo 30...240 secondi.','Rituale della Natura d\'Élite. Crei uno spirito di livello 1...10 (in vita per 30...240 secondi). Le magie che causano Sforzo lanciate nel raggio procureranno 10 di Sforzo in più.'],
1213=>['Tranquillità','Rituale della Natura. Crei uno Spirito di livello 1...10. Gli incantesimi lanciati dalle creature nella sua portata (Spiriti esclusi) si esauriscono un 20...50% più velocemente. Lo Spirito si esaurisce dopo 15...120 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 15...120 secondo[i]). Riduzione durata degli incantesimi sulle creature nella portata: 20...50%. Non ha effetto sugli Spiriti.'],
1215=>['Clamore delle Anime','Magia d\'Élite. L\'obiettivo nemico e tutti i nemici nei dintorni subiscono 10...65 danno[i] da fulmine. Se ti trovi a portata d\'orecchio di uno Spirito o stai trasportando un carico ottieni 10 Punto[i] Energia.','Magia d\'Élite. Danni da fulmine all\'obiettivo e ai nemici nei dintorni: 10...65. Energia conseguita se sei a portata di orecchio di uno Spirito o stai trasportando un carico: 10.'],
1217=>['Lord Rituale','Abilità d\'Élite. Per 5...35 secondo[i], i tuoi attributi di Ritualista aumentano di 2...4 per la prossima abilità. Se tale abilità è un Rituale Incatenante, si ricarica di un 10...60% più velocemente e Lord Rituale si ricarica istantaneamente.','Abilità d\'Élite. (Secondo[i]: 5...35). Ottieni +2...4 a tutti gli attributi di Ritualista per la prossima abilità. Se tale abilità è un Rituale Incatenante, si ricarica di un 10...60% più velocemente e Lord Rituale si ricarica istantaneamente.'],
1218=>['Daoshen era Crudele','Magia Altera-oggetto. Mantieni le ceneri di Kaolai per un massimo di 15...60 secondo[i]. Mentre mantieni le ceneri di Kaolai, tutte le abilità Ritualista ricevono +10% di penetrazione armatura. Quando rilasci le ceneri, tutti i nemici nei dintorni subiscono 15...85 danno[i] da fulmine.','Magia Altera-oggetto. (Secondo[i]: 15...60). Le tue abilità Ritualista aumentano di +10% di penetrazione armatura. Rilascio: danno da fulmine a tutti i nemici nei dintorni: 15...85.'],
1219=>['Kaolai era Protettivo','Magia Altera-oggetto. Mantieni le ceneri di Kaolai per un massimo di 15...60 secondo[i]; mentre le mantieni, ottieni +20 di armatura. Quando le lasci cadere, tutti i membri della squadra vengono curati di 20...95 Punto[i] Salute.','Magia Altera-oggetto. (Secondi: 15...60) Armatura: +20. Rilascio: tutti i membri della squadra vengono curati di 20...95.'],
1220=>['Songkai era in Sintonia','Magia d\'Élite Altera-oggetto. Mantieni le ceneri di Songkai per un massimo di 45 secondo[i]; mentre le mantieni, le tue magie e i tuoi Rituali Incatenanti costano -5...50% dell\'Energia di base per essere lanciati.','Magia d\'Élite Altera-oggetto. (Secondi: 45) Riduzione del costo energetico delle tue magie e rituali incatenanti: -5...50%.'],
1221=>['Xiko era Determinata','Magia Altera-oggetto. Mantieni le ceneri di Xiko per un massimo di 5...20 secondo[i]; ottieni una Rigenerazione della Salute di +3 per ogni fattura o condizione dalla quale sei affetto mentre hai le sue ceneri. Lasciando cadere le ceneri perdi 1...4 condizione[i].','Magia Altera-oggetto. (Secondi: 5...20) Rigenerazione Salute per ogni fattura o condizione presente su di te: +3. Rilascio: perdi 1...4 condizione[i].'],
1222=>['Naomei era Vivace','Magia Altera-oggetto. Mantieni le ceneri di Naomei per un massimo di 45 secondo[i]; quando le lasci cadere, tutti i membri della squadra nell\'area vengono resuscitati con un 15...75% di Salute e zero Energia.','Magia Altera-oggetto. (Secondi: 45) Rilascio: resusciti i membri della squadra nell\'area (Salute: 15...75%; Energia: 0).'],
1223=>['Lingwah era Tormentata','Magia Altera-oggetto. Mantieni le ceneri di Kaolai per un massimo di 10...60 secondo[i]. Menrte mantieni le ceneri, le tue fatture Ritualista costano 1...5 Punto[i] Energia in meno e durano un 50% in più. Quando rilasci le ceneri, tutte le tue fatture Ritualista si ricaricano.','Magia Altera-oggetto. (Secondo[i]: 10...60). Le tue fatture Ritualista costano 1...5 Punto[i] Energia in meno e durano un 50% in più. Rilascio: tutte le tue fatture Ritualista si ricaricano.'],
1224=>['Trascina Spirito','Magia. Teletrasporti nella tua posizione lo Spirito alleato preso di mira.','Magia. Teletrasporti nella tua posizione lo Spirito alleato selezionato.'],
1225=>['Colpo Incanalato','Magia. L\'obiettivo nemico subisce 5...95 danno[i] da fulmine; se hai in mano un oggetto, quel nemico subisce 5...35 danno[i] da fulmine in più.','Magia. Danni da fulmine inferti: 5...95. Assesta 5...35 danno[i] da fulmine in più se hai in mano un oggetto.'],
1226=>['Colpo di Soccorso dello Spirito','Magia. L\'obiettivo nemico subisce 20...65 danno[i] da fulmine e tutti gli Spiriti vicini a te ottengono 20...65 Punto[i] Salute.','Magia. Danni da fulmine inferti: 20...65. Gli Spiriti sotto il tuo controllo a portata d\'orecchio ottengono 20...65 Punto[i] Salute.'],
1227=>['Colpo dell\'Essenza','Magia. L\'obiettivo nemico subisce 15...60 danno[i] da fulmine; se sono presenti degli Spiriti a portata d\'orecchio, ottieni 1...9 Punto[i] Energia.','Magia. Danni da fulmine inferti: 15...60. Energia conseguita se ci sono Spiriti a portata d\'orecchio: 1...9.'],
1228=>['Sifone dello Spirito','Magia. Lo spirito più vicino a te perde tutta l\'energia. Ottieni un 30...60% di quell\'Energia.','Magia. Lo spirito più vicino a te perde tutta l\'energia. Ottieni un 30...60% di quell\'Energia.'],
1229=>['Crescita Esplosiva','Incantesimo. Dura 15...60 secondo[i]; ogni volta che crei una creatura, fino a 5 nemico[i] vicini ad essa subiscono 20...65 danno[i] da fulmine.','Incantesimo. (Secondi: 15...60) Assesta 20...65 danno[i] da fulmine a 5 nemico[i] vicino[i] a te ogni volta che crei una creatura.'],
1230=>['Soccorso della Creazione','Incantesimo. Per 15...60 secondo[i], ogni volta che dai vita ad una creatura, ottieni 5...50 Punto[i] Salute e 1...6 Punto[i] Energia.','Incantesimo. (Secondi: 15...60) Consegui 5...50 Punto[i] Salute e 1...6 Punto[i] Energia ogni volta che dai vita ad una creatura.'],
1231=>['Incanalamento dello Spirito','Incantesimo d\'Élite. Per 12 secondo[i] ottieni una Rigenerazione dell\'Energia di +1...6. Se ti trovi nella portata d\'orecchio di uno spirito quando lanci questa magia, ottieni 3...12 Punti Energia.','Incantesimo d\'Élite. (Secondo[i]: 12). Rigenerazione Energia: +1...6. Effetto iniziale: Ottieni 3...12 Punto[i] Energia se ti trovi nella portata d\'orecchio di uno Spirito.'],
1232=>['Armatura dell\'Insensibile','Abilità. Per 10...35 secondi i tuoi spiriti a portata d\'orecchio subiscono un 50% di danni in meno e sono immuni agli attacchi critici.','Abilità. (Secondi: 10...35). I tuoi spiriti a portata d\'orecchio subiscono un 50% di danni in meno e sono immuni agli attacchi critici.'],
1233=>['Ricordi Rassicuranti','Magia. Curi l\'obiettivo (un alleato o te stesso) di 10...100 Punto[i] Salute; se hai tra le mani un oggetto ottieni 3 Punto[i] Energia.','Magia. Cure: 10...100. Ottieni 3 Punto[i] Energia se hai in mano un oggetto.'],
1234=>['Cura Corpo e Anima','Magia. L\'obiettivo alleato viene curato di 20...115 Punti Salute. Tale alleato perde una condizione per ogni Spirito a portata d\'orecchio.','Magia. Cure: 20...115. Rimuove una condizione per ogni Spirito a portata d\'orecchio.'],
1235=>['Arma Smussata','Fattura. Per 5...20 secondo[i], l\'obiettivo nemico e tutti i nemici nei dintorni non possono mettere a segno un colpo critico e infliggono 3...20 danno[i] in meno.','Fattura. Colpisce con una fattura anche i nemici adiacenti all\'obiettivo (5...20 secondo[i]). Rimuove la capacità di mettere a segno colpi critici. Riduzione del danno: 3...20.'],
1236=>['Catene Vincolanti','Fattura. Per 3 secondo[i] la velocità dell\'obiettivo nemico e dei nemici nei dintorni diminuisce di un 90% e i nemici subiscono 1...30 danno[i] al secondo se in movimento.','Fattura. Colpisce con una fattura i nemici adiacenti all\'obiettivo (3 secondo[i]). I nemici rallentano di un 90% e subiscono 1...30 danno[i] al secondo mentre ti muovi.'],
1237=>['Legame Doloroso','Fattura. Dura 10...20 secondo[i]; l\'obiettivo nemico e tutti i nemici nei dintorni subiscono gli effetti della fattura Legame Doloroso e 8...20 danno[i] ogni volta che vengono colpiti da uno Spirito.','Fattura. Infligge fattura anche ai nemici vicini all\'obiettivo (10...20 secondo[i]). Incremento del danno assestato dagli Spiriti contro questi nemici: 8...20.'],
1238=>['Sigillo della Creazione','Sigillo. Ottieni 4 Punto[i] Energia per ogni creatura evocata sotto il tuo controllo e a portata d\'orecchio (max 3...12 Punto[i] Energia).','Sigillo. Ottieni 4 Punto[i] Energia (max 3...12) per ogni creatura evocata sotto il tuo controllo e a portata d\'orecchio.'],
1239=>['Sigillo degli Spiriti','Sigillo d\'Élite. Crea tre spiriti di livello 1...12. I loro attacchi infliggono 5...20 danni gli spiriti si esauriscono dopo 60 secondi.','Sigillo d\'Élite. Crea tre spiriti di livello 1...12 (in vita per 60 secondi). I loro attacchi infliggono 5...20 danni.'],
1240=>['Distorsione dell\'Anima','Abilità d\'Élite. Per 5...45 secondo[i], il tuo Rituale Incatenante costa 15 Punto[i] Energia in meno (min 5) e si ricarica istantaneamente. Distorsione dell\'Anima termina dopo 1...3 Rituale[i] Incatenante[i].','Abilità d\'Élite. (Secondo[i]: 5...45). Il tuo Rituale Incatenante costa 15 Punto[i] Energia in meno (min 5) e si ricarica istantaneamente. Distorsione dell\'Anima termina dopo 1...3 Rituale[i] Incatenante[i].'],
1244=>['Fretta Spettrale','Incantesimo. Per 5...30 secondo[i] le magie lanciate mentre ti trovi nella portata d\'orecchio di uno Spirito si ricaricano con una velocità maggiore del 25%.','Incantesimo. (Secondi: 5...30) Incremento velocità di ricarica delle tue magie: 25%. Ha effetto solo se sei a portata d\'orecchio di uno Spirito.'],
1245=>['Sguardo dall\'Aldilà','Magia. L\'obiettivo nemico subisce 20...65 danno[i] da fulmine. Se ti trovi entro la portata d\'orecchio di uno spirito, l\'obiettivo nemico viene accecato per 2...6 secondo[i].','Magia. Danni da fulmine inferti: 20...65. Infligge condizione Accecamento (2...6 secondo[i] se ti trovi entro la portata d\'orecchio di uno spirito.'],
1246=>['Ira degli Antenati','Abilità. Per 1 secondo[i], non si verificano effetti. Al termine dell\'abilità, tutti i nemici adiacenti all\'obiettivo alleato subiscono 5...110 danno[i] da fulmine.','Abilità. (Secondi: 1) Effetto al termine: assesta 5...110 danno[i] da fulmine ai nemici adiacenti all\'obiettivo alleato.'],
1247=>['Dolore','Rituale Incatenante. Crei uno Spirito di livello 1...12 i cui attacchi infliggono 5...30 danno[i]. Lo Spirito si esaurisce dopo 30...150 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...12 (in vita per 30...150 secondo[i]). I suoi attacchi assestano 5...30 danno[i].'],
1249=>['Spostamento','Rituale Incatenante. Crei uno Spirito di livello 1...14. Tutti gli alleati (Spiriti esclusi) nella sua portata hanno un 75% di probabilità di bloccare gli attacchi in arrivo; ogni volta che un attacco viene bloccato in questo modo, lo Spirito subisce 60 danno[i]. Questo Spirito si esaurisce dopo 30...60 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...14 (in vita per 30...60 secondo[i]). Probabilità di blocco per gli alleati (Spiriti esclusi) nella portata: 75%. Effetto del blocco: questo Spirito riceve 60 danno[i].'],
1250=>['Preservazione','Rituale Incatenante d\'Élite. Crei uno Spirito di livello 1...14. Ogni 4 secondi questo Spirito cura un alleato nell\'area (Spiriti esclusi) di 10...115 Punto[i] Salute. Lo Spirito si esaurisce dopo 90 secondo[i].','Rituale Incatenante d\'Élite. Crei uno Spirito di livello 1...14 (in vita per 90 secondo[i]). Ogni 4 secondi questo Spirito cura un alleato (Spiriti esclusi) di 10...115.'],
1251=>['Vita','Rituale Incatenante. Crei uno Spirito di livello 1...14. Quando si esaurisce, tutti gli alleati nella sua portata (Spiriti esclusi) vengono curati di 1...7 Punto[i] Salute per ogni secondo di vita dello Spirito. Questo Spirito si esaurisce dopo 20 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...14 (in vita per 20 secondo[i]). Ha effetto sugli alleati (Spiriti esclusi) nella portata. Effetto al termine: cura di 1...7 per secondo di vita di questo Spirito.'],
1252=>['Legaterra','Rituale Incatenante. Crei uno Spirito di livello 1...14. Tutti i nemici abbattuti nella sua portata (Spiriti esclusi) restano a terra per almeno 3 secondi. Ogni volta che ciò accade, lo Spirito perde 50...25 Punto[i] Salute. Lo Spirito si esaurisce dopo 15...45 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...14 (in vita per 15...45 secondo[i]). Ogni volta che i nemici (Spiriti esclusi) nella portata vengono abbattuti restano a terra per almeno 3 secondi. Costo dell\'abbattimento: questo Spirito perde 50...25 Punto[i] Salute.'],
1253=>['Canto Sanguinario','Rituale Incatenante. Crei uno Spirito di livello 1...12 che si esaurisce dopo 30...150 secondo[i]; i suoi attacchi sottraggono fino a 5...25 Punto[i] Salute.','Rituale Incatenante. Crei uno Spirito di livello 1...12 (in vita per 30...150 secondo[i]). Salute sottratta dai suoi attacchi: 5...25.'],
1255=>['Spirito Vagabondo','Rituale Incatenante d\'Élite. Crei uno Spirito di livello 1...12. Ogni volta che i suoi attacchi colpiscono un nemico fermo, lo abbattono e lo Spirito perde 70...50 Punto[i] Salute. Questo Spirito si esaurisce dopo 30...60 secondo[i].','Rituale Incatenante d\'Élite. Crei uno Spirito di livello 1...12 (in vita per 30...60 secondo[i]). I suoi attacchi contro i nemici fermi provocano abbattimento. Costo dell\'abbattimento: questo Spirito perde 70...50 Punto[i] Salute.'],
1257=>['Arma della Luce dello Spirito','Magia d\'Élite Altera-arma. Per 10 secondo[i], l\'obiettivo (un alleato o te stesso) ottiene 5...25 Punto[i] Salute al secondo e 5...25 Punto[i] Salute in più al secondo se si trova a portata d\'orecchio di uno Spirito.','Magia d\'Élite Altera-arma. (Secondi: 10) Salute ottenuta ogni secondo dall\'obiettivo (un alleato o te stesso): 5...25. Cure aggiuntive al secondo se c\'è uno Spirito nella portata d\'orecchio: 5...25.'],
1258=>['Arma Brutale','Magia Altera-arma. Dai all\'obiettivo (un alleato o te stesso) un\'Arma Brutale per 10...40 secondo[i]; chi la riceve potrà infliggere +5...15 danno[i] purché non sia sotto l\'effetto di incantesimi.','Magia Altera-arma. (Secondi: 10...40) Danni inferti dagli attacchi: +5...15. Non ha effetto mentre l\'obiettivo alleato è sotto incantesimo.'],
1259=>['Arma Guidata','Magia Altera-arma. Per 4...10 secondo[i], gli attacchi dell\'obiettivo (un alleato o te stesso) non possono essere bloccati.','Magia Altera-arma. (Secondi: 4...10) Gli attacchi non sono bloccabili.'],
1260=>['Mansuetudine','Fattura. Per 5...30 secondo[i], la velocità d\'attacco dell\'obiettivo nemico e di tutti i nemici nell\'area diminuisce di un 50%.','Fattura. Infligge fattura anche ai nemici nell\'area dell\'obiettivo (5...30 secondo[i]). Rallentamento velocità d\'attacco di questi nemici: 50%.'],
1261=>['Armatura Glaciale','Incantesimo. Per 10...25 secondi, hai +10...40 di armatura contro il danno fisico e non subisci Bruciatura.','Incantesimo. (Secondi: 10...25.) Armatura contro il danno fisico: +10...40; sei immune dalla Bruciatura.'],
1262=>['Circolo della Guarigione','Magia. Cura le creature adiacenti di 30...180 Punto[i] Salute. Chi lo lancia non riceve cure.','Magia. Cure per gli alleati e i nemici adiacenti: 30...180. Chi lancia non riceve cure.'],
1263=>['Rinnova Vita','Magia. Resusciti l\'obiettivo morto toccato con il 50% di Salute e un 5...20% di Energia. Quel compagno e tutti gli alleati a portata d\'orecchio vengono curati di 55...130 Punto[i] Salute.','Magia a Tocco. Fa risorgere il membro della squadra selezionato (Salute: 50%; Energia: 5...20%). Cura gli alleati a portata d\'orecchio: 55...130.'],
1264=>['Fato','Magia. Infliggi all\'obiettivo nemico 10...60 danno[i] da fulmine (max. 135) per ogni rituale incatenante equipaggiato che si sta ricaricando.','Magia. Assesta 10...60 danno[i] da fulmine (max 135) per ogni rituale incatenante che si sta ricaricando.'],
1265=>['Soccorso del Portatore','Magia. Curi l\'obiettivo (un alleato o te stesso) di 15...60 punto[i]; se l\'obiettivo è affetto da una magia altera-arma, viene curato di 15...75 Punto[i] Salute in più.','Magia. Cure: 15...60. Cura di 15...75 in più se questo alleato è affetto da una magia altera-arma.'],
1266=>['Rasserenamento','Rituale Incatenante. Crei uno Spirito di livello 1...12. Tutti i nemici nel suo raggio d\'influenza impiegano il doppio di tempo per generare Adrenalina. Lo Spirito si esaurisce dopo 15...45 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...12 (in vita per 15...45 secondo[i]). Il tempo di acquisizione adrenalina si raddoppia per i nemici nella portata.'],
1267=>['Arma Vitale','Magia Altera-arma. Per 5...30 secondo[i], l\'obiettivo (un alleato o te stesso) ottiene un\'Arma Vitale e +40...175 di Salute massima.','Magia Altera-arma. (Secondi: 5...30) Salute massima: +40...175.'],
1268=>['Arma dell\'Accelerazione','Magia d\'Élite Altera-arma. Per 5...25 secondo[i], l\'obiettivo (un alleato o te stesso) ottiene un\'Arma dell\'Accelerazione che fa ricaricare ad una velocità maggiore del 33% le magie e i rituali incatenanti.','Magia d\'Élite Altera-arma. (Secondi: 5...25) Incremento velocità di ricarica di magie e rituali incatenanti: 33%.'],
1269=>['Sigillo dell\'Ira','Sigillo. L\'obiettivo nemico subisce 5...50 danno[i] sacro[i] e +5...10 danno[i] sacro[i] per ogni abilità d\'adrenalina che ha equipaggiato.','Sigillo. Danni sacri inferti: 5...50. Assesta 5...10 danno[i] sacro[i] in più per ogni abilità da adrenalina dell\'obiettivo nemico.'],
1333=>['Prolunga Condizioni','Magia d\'Élite. Diffondi tutte le condizioni dall\'obiettivo nemico a tutti i nemici vicini a lui. Incremento durata di queste condizioni: 5...100% (max 30 secondi).','Magia d\'Élite. Diffondi tutte le condizioni dall\'obiettivo nemico a tutti i nemici vicini a lui. Incremento durata di queste condizioni: 5...100% (max 30 secondi).'],
1334=>['Ipocondria','Magia. Trasferisci all\'obiettivo nemico tutte le condizioni da cui sono affetti tutti nemici nell\'area.','Magia. Trasferisce all\'obiettivo nemico tutte le condizioni da cui sono affetti i nemici nell\'area.'],
1335=>['Dipartita del Fannullone','Fattura. Per 5 secondi l\'obiettivo nemico è sotto gli effetti della fattura Dipartita del Fannullone. Per ogni secondo in cui l\'obiettivo nemico è sotto gli effetti della fattura, lui e tutti i nemici adiacenti subiscono 1...10 danni e 1...10 danni in più per ogni secondo in cui è attiva la fattura. Se il nemico ha attivato un\'abilità, la Fattura termina prematuramente.','Fattura. (Secondi: 5). Danni subiti dall\'obiettivo nemico e da tutti i nemici adiacenti per ogni secondo in cui l\'obiettivo è sotto gli effetti della fattura: 1...10. Danni subiti dai nemici per ogni secondo in cui è attiva la fattura: +1...10. Termina prematuramente se l\'obiettivo nemico ha attivato un\'abilità.'],
1336=>['Dolore Spirituale','Magia. Danni subiti dall\'obiettivo nemico: 15...75. Tutte le creature ostili evocate nell\'area del nemico subiscono 25...125 danni.','Magia. Danni inferti: 15...75. Danni inferti alle creature ostili invocate nell\'area dell\'obiettivo nemico: 25...125.'],
1337=>['Prosciuga Delusioni','Magia. Rimuovi una fattura dell\'Ipnotizzatore dall\'obiettivo nemico. Se riesci a rimuoverla in questo modo, quel nemico perde 1...5 Punto[i] Energia e tu ottieni 4 Punto[i] Energia per ogni punto perduto.','Magia. Rimuove una fattura dell\'Ipnotizzatore dall\'obiettivo nemico. Perdita Energia: 1...5. Ottieni 4 Punto[i] Energia per ogni punto perso. Ha effetto solo se una fattura era stata rimossa.'],
1338=>['Persistenza della Memoria','Incantesimo. Per 5...20 secondo[i], ogni volta che una magia da te lanciata viene interrotta, questa si ricarica all\'istante.','Incantesimo. (Secondi: 5...20) Le tue magie interrotte si ricaricano all\'istante.'],
1339=>['Simboli dell\'Ispirazione','Abilità d\'Élite. Per 6...40 secondo/i questa l\'abilità diventa l\'élite del nemico colpito. Le abilità élite lanciate usano l\'attributo Lancio rapido al posto del loro normale attributo.','Abilità d\'Élite. (6...40 secondo/i) Questa l\'abilità diventa l\'élite del nemico colpito. Le abilità élite usano l\'attributo Lancio rapido al posto del loro normale attributo.'],
1340=>['Celerità Simbolica','Incantesimo. Per 36...60 secondi tutti i tuoi Sigilli usano l\'attributo Lancio Rapido anziché il loro attributo normale.','Incantesimo. (Secondi: 36...60). I tuoi Sigilli usano l\'attributo Lancio Rapido.'],
1341=>['Frustrazione','Fattura. Per 5...20 secondi la velocità di lancio delle magie dell\'obiettivo nemico si riduce di un 50% e il nemico subisce 5...50 danni quando viene interrotto. Se viene interrotta un\'abilità, la Frustrazione infligge il doppio dei danni.','Fattura. (Secondi: 5...20). Rallentamento velocità di lancio delle magie: 50%. L\'obiettivo nemico subisce 5...50 danni quando viene interrotto. Infligge il doppio dei danni per le abilità interrotte.'],
1342=>['Burla','Magia d\'Élite. Se l\'obiettivo nemico ha attivato un\'abilità, lui e gli altri nemici nell\'area vengono interrotti e tu sottrai 0...5 Punti Energia a tutti i nemici nell\'area.','Magia d\'Élite. Interrompe un\'abilità. Effetto dell\'interruzione: interrompe anche gli altri nemici nell\'area e tu sottrai 0...5 Punti Energia a tutti i nemici nell\'area.'],
1343=>['Fantasma Etereo','Fattura. Per 10 secondi l\'obiettivo nemico ha una Degenerazione dell\'Energia di -1. Se questa fattura viene rimossa prematuramente, il nemico perde 1...5 Punto[i] Energia.','Fattura. (Secondi: 10) Degenerazione Energia: -1. Perdita Energia se questa fattura termina prematuramente: 1...5.'],
1344=>['Rete del Disturbo','Fattura. Interrompi l\'obiettivo nemico. Per 10 secondo[i] l\'obiettivo nemico è affetto dalla fattura della Rete del Disturbo. Quando questa fattura termina, quel nemico viene interrotto nuovamente.','Fattura. (Secondi: 10) Effetto iniziale: interrompe un\'abilità. Effetto al termine: interrompe un\'abilità.'],
1345=>['Enigma dell\'Incantatore','Fattura d\'Élite. Per 10 secondo/i, il bersaglio lancia incantesimi il 100...200% più lentamente. Se il bersaglio non è sotto l\'effetto di un incantesimo quando viene colpito dalla fattura, subisce 10...100 danni e tutti i nemici adiacenti subiscono il 75% di quei danni.','Fattura d\'Élite. Lancio degli incantesimi 100...200% più lento (10 secondo/i). Effetto iniziale: se il bersaglio non è influenzato da incantesimi, subisce 10...100 danni, e i nemici adiacenti subiscono il 75% di quei danni.'],
1346=>['Sigillo delle Illusioni','Sigillo d\'Élite. La tua prossima 1...3 magia/e, purché non sia un\'illusione, sfrutta l\'attributo Illusione al posto del suo normale attributo.','Sigillo d\'Élite. La tua prossima 1...3 magia/e, purché non sia un\'illusione, sfrutta l\'attributo Illusione al posto del suo normale attributo.'],
1347=>['Congeda Incantesimo','Magia. Rimuovi un incantesimo dall\'obiettivo nemico. Se quel nemico è sotto gli effetti di una fattura, questa abilità si ricarica con una velocità maggiore del 20...50%.','Magia. Rimuove un incantesimo dall\'obiettivo nemico. Aumento del tempo di ricarica se quel nemico era sotto fattura: 20...50%.'],
1348=>['Vortice Mangiafattura','Magia d\'Élite. Rimuovi un maleficio da un alleato bersaglio. Se un maleficio viene rimosso in questo modo, i nemici nell\'area dell\'alleato subiscono 30...90 danni e perdono un incantamento.','Magia d\'Élite. Rimuove un maleficio da un alleato bersaglio. Effetti della rimozione: infligge 30...90 danni e rimuove un incantesimo dai nemici nell\'area dell\'alleato.'],
1349=>['Specchio del Disincanto','Magia. Rimuovi un incantesimo dall\'obiettivo nemico. Quello stesso incantesimo viene rimosso anche da tutti i suoi compagni.','Magia. Rimuove un incantesimo dall\'obiettivo nemico. Anche i suoi compagni di squadra perdono lo stesso incantesimo.'],
1350=>['Furto Semplice','Magia d\'Élite. Interrompi l\'azione dell\'obiettivo nemico; se si trattava di un\'abilità viene disattivata per 5...20 secondo[i] e si sostituisce al Furto Semplice.','Magia d\'Élite. Interrompe un\'azione. Effetto dell\'interruzione: se era un\'abilità la disattiva ed essa si sostituisce a Furto Semplice (5...20 secondo[i]).'],
1351=>['Anima Orrore Storpio','Magia. Sfrutti il cadavere più vicino per creare un orrore storpio di livello 1...17. Quando muore viene rimpiazzato da un orrore seghettato di livello 0...15 che provoca Emorragia ad ogni attacco.','Magia. Crea un Orrore Storpio di livello 1...17. Quando muore viene rimpiazzato da un Orrore Seghettato di livello 0...15 che infligge Emorragia con ogni attacco. Utilizza un cadavere sfruttabile.'],
1352=>['Ordine della Non-morte','Magia d\'Élite. Per 5 secondo[i], i tuoi sgherri infliggono +3...16 danno[i] ma tu perdi il 2% della tua Salute massima ogni volta che uno degli attacchi dei tuoi sgherri va a segno.','Magia d\'Élite. (Secondi: 5) Danni assestati dai tuoi sgherri: +3...16. Effetto risultante se il colpo dello sgherro va a segno: perdi un 2% della tua Salute massima.'],
1353=>['Carne Putrefatta','Magia. Distruggi uno dei tuoi sgherri morti viventi animati presi di mira. Tutti i nemici vicini a quella creatura si ammalano per 5...15 secondo[i].','Magia. Distrugge uno dei tuoi morti viventi. Condizione inflitta ai nemici vicini a questo morto vivente: Malattia (5...15 secondo[i]).'],
1354=>['Banchetto per i Morti','Magia. Distruggi il morto vivente alleato animato preso di mira. Tutti gli altri morti viventi alleati animati vengono curati di 10...100 Punto[i] Salute.','Magia. Distrugge uno dei tuoi morti viventi. Cure per i tuoi morti viventi: 10...100.'],
1355=>['Ossa Seghettate','Incantesimo d\'Élite. Per 60 secondo[i], quando il morto vivente selezionato muore, viene rimpiazzato da un orrore seghettato di livello 0...15 che provoca Emorragia con ogni attacco.','Incantesimo d\'Élite. (Secondi: 60) Quando il morto vivente selezionato muore, viene rimpiazzato da un Orrore Seghettato di livello 0...15 i cui attacchi infliggono Emorragia.'],
1356=>['Contagio','Incantesimo d\'Élite. Per 60 secondo[i], ogni volta che subisci una nuova condizione, tutti i nemici nell\'area risentono della stessa condizione e tu sacrifichi un 10...5% della Salute massima.','Incantesimo d\'Élite. (Secondi: 60) Ogni volta che ricevi una condizione, tutti i nemici nell\'area ottengono la stessa. Sacrifichi un 10...5% della Salute massima ogni volta che accade.'],
1358=>['Polmoni Ulcerosi','Fattura. Per 10...30 secondo[i] l\'obiettivo nemico e tutti i nemici nei dintorni subiscono una Degenerazione dell\'Energia di -4 quando affetti da Emorragia e sanguinano per 5...20 secondo[i] ogni volta che usano un urlo o un canto.','Fattura. Infligge fattura anche ai nemici vicini all\'obiettivo (10...30 secondo[i]). Degenerazione Salute di uno qualsiasi dei nemici affetti da Emorragia: -4. Condizione inflitta ogni volta che i nemici usano un urlo o un canto: Emorragia (5...20 secondo[i]).'],
1359=>['Dolore del Disincanto','Magia d\'Élite. L\'obiettivo nemico perde 1...3 incantesimo[i]. Se un incantesimo viene perso in questo modo, quel nemico e tutti i nemici adiacenti perdono 10...100 Punto[i] Salute.','Magia d\'Élite. Incantesimi persi dall\'obiettivo nemico: 1...3. Effetto della rimozione: quel nemico e tutti i nemici adiacenti perdono 10...100 di Salute.'],
1360=>['Segno della Furia','Fattura. (Secondi: 5) Qualsiasi alleato colpisca l\'obiettivo nemico ottiene 0...2 dose[i] di adrenalina. Al termine della fattura, tale nemico subisce Armatura Incrinata per 1...15 secondo[i].','Fattura. (Secondo[i]: 5). Tu o qualsiasi alleato ottenete 0...2 dose[i] di adrenalina. Effetto al termine: Condizione inflitta: Armatura Incrinata (1...15 secondo[i]).'],
1362=>['Corrompi Incantesimo','Fattura d\'Élite. Rimuovi un incantesimo dall\'obiettivo nemico. Se riesci a rimuovere un incantesimo in questo modo, quel nemico subisce una Degenerazione della Salute di -1...8 per 10 secondi.','Fattura d\'Élite. Rimuove un incantesimo dall\'obiettivo nemico. Effetto della rimozione: Degenerazione Salute -1...8 (10 secondi).'],
1363=>['Sigillo del Rimpianto','Sigillo. L\'obiettivo nemico subisce 15...75 danno[i]; se si trova vicino ad un cadavere o la sua mascotte è morta, l\'abilità si ricarica all\'istante.','Sigillo. Danni inferti: 15...75. Si ricarica all\'istante se l\'obiettivo nemico si trova vicino ad un cadavere o ha una mascotte morta.'],
1364=>['Sigillo della Sofferenza','Sigillo d\'Élite. Soffri di Emorragia per 6 secondi. La prossima abilità del Negromante utilizzata contro un nemico provoca Emorragia per 2...16 secondi.','Sigillo d\'Élite. Condizione subita: Emorragia (6 secondi). Condizione inflitta all\'obiettivo della tua prossima abilità del Negromante: Emorragia (2...16 secondi).'],
1365=>['Sigillo delle Anime Smarrite','Sigillo. Se la Salute dell\'obiettivo nemico è inferiore al 50%, ottieni 10...100 Punto[i] Salute e 1...10 Punto[i] Energia.','Sigillo. Ottieni 10...100 Punto[i] Salute e 1...10 Punto[i] Energia se la Salute dell\'obiettivo nemico è inferiore al 50%.'],
1366=>['Pozzo dell\'Oscurità','Pozzo. Sfrutta il cadavere più vicino o sacrifica il 66% della tua salute per creare un Pozzo dell\'Oscurità per 5...50 secondo/i. I nemici maledetti nell\'area del Pozzo dell\'Oscurità mancano il bersaglio il 50% delle volte.','Pozzo. (5...50 secondo/i). I nemici colpiti da fattura in questo Pozzo hanno una probabilità del 50% di mancare. Utilizza un cadavere fresco o sacrifica il 66% della Salute.'],
1367=>['Flusso Accecante','Magia d\'Élite. L\'obiettivo nemico subisce 5...50 danni da fulmine. Quel nemico e tutti i nemici adiacenti vengono accecati per 3...8 secondi. Questa magia ha una penetrazione dell\'armatura del 25%. Se colpisce un nemico all\'attacco, vengono colpiti anche tutti i nemici adiacenti e questa magia infligge il 50% di danni in più.','Magia d\'Élite. Danni da fulmine inferti: 5...50. Infligge Accecamento all\'obiettivo e ai nemici adiacenti (secondi: 3...8). Penetrazione armatura: 25%. Se l\'obiettivo stava attaccando, colpisce anche i nemici adiacenti e infligge il 50% di danni in più.'],
1368=>['Venti Gelidi','Fattura. L\'obiettivo nemico e i nemici adiacenti subiscono 30...60 danni da freddo. Per 10 secondi, la prossima fattura di Magia dell\'Acqua lanciata contro un nemico con fattura ha una durata superiore di un 25...100%.','Fattura. (Secondi: 10.) Durata della prossima fattura d\'Acqua sull\'obiettivo nemico: +25...100%. Effetto iniziale: 30...60 danni da freddo. Colpisce anche i nemici adiacenti.'],
1369=>['Saetta','Magia. Lanci una Saetta che infligge 5...50 danni da fulmine se va a segno. Se colpisce un nemico in movimento, gli infligge 5...50 danni da fulmine in più. Questa magia ha una penetrazione dell\'armatura del 25%.','Magia. Proiettile: danni da fulmine inferti: 5...50. Danni da fulmine aggiuntivi se l\'obiettivo nemico si sta muovendo: 5...50. Penetrazione armatura: 25%.'],
1370=>['Fretta del Djinn della Tempesta','Incantesimo. Per 10...25 secondi, la tua velocità di movimento aumenta di un 25%. Per ogni secondo in cui ti muovi perdi 1 Punti Energia.','Incantesimo. (Secondi: 10...25.) Aumento della velocità di movimento: 25%. Perdi 1 Punti Energia per ogni secondo in cui ti muovi.'],
1371=>['Battitore di Pietra','Incantesimo. Per 5...30 secondi, ogni volta che subisci o infliggi un danno elementale o fisico, questo si trasforma in un danno da terra.','Incantesimo. (Secondi: 5...30.) Trasforma i danni elementali e fisici che subisci o assesti in danni da terra.'],
1372=>['Tempesta di Sabbia','Magia d\'Élite. Crei una Tempesta di Sabbia nella posizione dell\'obiettivo nemico. Per 10 secondi, i nemici nei dintorni subiscono 20...40 danni da terra al secondo e i nemici all\'attacco subiscono 10...30 danni da terra in più al secondo.','Magia d\'Élite. Danni da terra inferti al secondo: 20...40 (10 secondi). Colpisce i nemici vicini alla posizione iniziale dell\'obiettivo nemico. Colpisce i nemici all\'attacco con 10...30 danni da terra in più al secondo.'],
1373=>['Guaina di Pietra','Incantesimo d\'Élite. Per 5...20 secondi, tu e l\'obiettivo alleato ottenete +1...30 di armatura e siete immuni agli attacchi critici. Quando lanci questa magia, tutti i nemici vicino a te e al tuo obiettivo subiscono 15...70 danni da terra e soffrono di Debolezza per 5...20 secondi.','Incantesimo d\'Élite. (Secondi: 5...20.) Tu e l\'obiettivo alleato ottenete +1...30 di armatura e siete immuni agli attacchi critici. Effetto iniziale: I nemici vicino a te e all\'obiettivo alleato subiscono 15...70 danni da terra e soffrono di Debolezza (5...20 secondi).'],
1374=>['Falco d\'Ebano','Magia. Lanci un proiettile che colpisce l\'obiettivo nemico infliggendo 10...85 danni da terra. Se va a segno, provoca Debolezza per 5...15 secondi.','Magia. Proiettile: danni da terra inferti: 10...85. Condizione inflitta: Debolezza (secondi: 5...15).'],
1375=>['Aura di Carne di Pietra','Incantesimo. Per 5...15 secondi, il danno che ricevi si riduce di 1...31 e sei immune dagli attacchi critici.','Incantesimo. (Secondi: 5...15.) Riduce di 1...31 il danno che ricevi e diventi immune dagli attacchi critici.'],
1376=>['Glifo del Ripristino','Glifo. Per 15 secondi, le tue 2 magie successive ti curano di 30...105 Punti Salute e vieni curato di un 150...400% del costo di Energia di ogni magia.','Glifo. (Secondi: 15.) Cure ricevute dalle tue 2 magie successive: 30...105. Vieni curata di un 150...400% del costo energetico di ogni magia.'],
1377=>['Prisma dell\'Etere','Abilità d\'Élite. Per 3 secondi, tutti i danni che subisci vengono ridotti di un 75%. Quando l\'effetto del Prisma dell\'Etere svanisce, ottieni 5...20 Punti Energia.','Abilità d\'Élite. (Secondi: 3.) Riduzione di tutti i danni subiti: 75%. Effetto al termine: ottieni 5...20 Punti Energia.'],
1378=>['Maestro di Magia','Incantesimo d\'Élite. Per 1...61 secondo/i tutti gli attributi elementali salgono a 8...14, e le magie elementali restituiscono 1 punto energia più il 30% del loro costo.','Incantesimo d\'Élite. (1...61 secondo/i) Tutti gli attributi elementali salgono a 8...14, e le magie elementali restituiscono 1 punto energia più il 30% del loro costo.'],
1379=>['Sguardo Luminoso','Magia. L\'obiettivo nemico subisce 5...50 danni da fuoco. Se quel nemico è affetto da Bruciatura, ottieni 5 Punti Energia e 1 Punto Energia per ogni 2 gradi della Riserva di Energia.','Magia. Danni da fuoco inferti: 5...50. Energia conseguita se l\'obiettivo nemico è affetto da Bruciatura: 5 più 1 per ogni 2 gradi della Riserva di Energia.'],
1380=>['Calore della Savana','Magia d\'Élite. Crei Calore della Savana nella posizione dell\'obiettivo nemico. Per 5 secondi, tutti i nemici nei dintorni subiscono 5...20 danni da fuoco per ogni secondo di attività della magia.','Magia d\'Élite. Assesta 5...20 danni da fuoco per ogni secondo successivo al lancio della magia (5 secondi). Colpisce i nemici vicini alla posizione iniziale dell\'obiettivo.'],
1381=>['Fretta del Djinn della Fiamma','Incantesimo. Infligge 15...120 danni da fuoco a tutti i nemici adiacenti. Per 8...14 secondi, la tua velocità di movimento aumenta di un 25%. Fretta del Djinn della Fiamma si ricarica a velocità superiore del 50% se un nemico è stato colpito da questa magia.','Incantesimo. (Secondi: 8...14.) Aumento della velocità di movimento: 25%. Effetto iniziale: danni da fuoco ai nemici adiacenti a te: 15...120. Incremento velocità di ricarica se si assestano danni a un nemico con questa magia: 50%.'],
1382=>['Folata Congelante','Fattura. Se l\'obiettivo nemico è sotto gli effetti di una fattura della Magia dell\'Acqua subisce 20...80 danni da freddo. Altrimenti si muove con una velocità inferiore di un 66% per 1...5 secondi.','Fattura. Danni da freddo se l\'obiettivo nemico è affetto da una fattura dell\'Acqua: 20...80. Altrimenti i suoi movimenti rallentano di un 66% (1...5 secondi).'],
1390=>['Intervento del Giudice','Incantesimo. Per 10 secondi, la prossima volta che l\'obiettivo (un alleato o te stesso) riceve un danno che dovrebbe essere fatale, questo si annulla e un nemico nei dintorni subisce 30...180 danno[i] sacro[i].','Incantesimo. (Secondi: 10) Previene il prossimo danno fatale. Effetto della prevenzione: 30...180 danno[i] sacro[i] ad un nemico vicino all\'obiettivo alleato.'],
1391=>['Spirito Sostenitore','Incantesimo. Dura 5...23 secondo[i]; ogni volta che l\'obiettivo (un alleato o te stesso) subisce dei danni mentre si trova a terra, sarà curato di 5...50 Punto[i] Salute.','Incantesimo. (Secondi: 5...23) Cure impartite ogni volta che l\'obiettivo alleato subisce danni mentre è abbattuto: 5...50.'],
1392=>['Attenta Guarigione','Incantesimo. Per 10 secondi, l\'obiettivo (un alleato o te stesso) ottiene +1...4 di Rigenerazione della Salute. Se questa abilità termina prematuramente quell\'alleato ottiene 30...120 Punto[i] Salute.','Incantesimo. (Secondi: 10) Rigenerazione Salute: +1...4. Salute conseguita se questo incantesimo termina prematuramente: 30...120.'],
1393=>['Soccorso del Guaritore','Incantesimo d\'Élite. Per 10...55 secondo[i], le magie appartenenti alle Preghiere Curative hanno una velocità di lancio superiore del 50% e donano un 50% in più di Salute.','Incantesimo d\'Élite. (Secondi: 10...55) Incremento velocità di lancio delle magie attribuite a Preghiere Curative: 50%. Incremento cure da esse donate: 50%.'],
1394=>['Patto del Guaritore','Incantesimo d\'Élite. Mantenendo questo incantesimo, le magie appartenenti alle Preghiere Curative doneranno un 20% in meno di Salute, ma costeranno -1...4 Punto[i] Energia.','Incantesimo d\'Élite. Riduzione del costo energetico delle tue magie attribuite a Preghiere Curative: 1...4. Riduzione percentuale di cure di queste magie: 20%.'],
1395=>['Pendolo di Balthazar','Incantesimo d\'Élite. Dura 5...25 secondo[i]; la prossima volta che l\'obiettivo alleato sarebbe stato abbattuto da un nemico, quel nemico viene abbattuto al suo posto.','Incantesimo d\'Élite. (Secondi: 5...25) Abbattimento del prossimo nemico che tenta di abbattere l\'obiettivo alleato.'],
1396=>['Parole di Conforto','Magia. Curi l\'obiettivo (un alleato o te stesso) di 20...65 Punto[i] Salute e di altri 20...50 Punto[i] Salute se è affetto da una condizione.','Magia. Cure: 20...65. Cura di 20...50 in più se l\'obiettivo (un alleato o te stesso) soffre di una condizione.'],
1397=>['Luce di Liberazione','Magia d\'Élite. Tutti i membri della squadra vengono curati di 5...70 Punto[i] Salute.','Magia d\'Élite. Cure per l\'intera squadra: 5...70.'],
1398=>['Incantesimo Flagello','Fattura. Dura 30 secondo[i]; ogni volta che l\'obiettivo nemico è il bersaglio di un incantesimo, chi lancia tale incantesimo subisce 15...75 danno[i].','Fattura. (Secondi: 30) Danni a chiunque stia lanciando un incantesimo sull\'obiettivo nemico: 15...75.'],
1399=>['Scudo dell\'Assorbimento','Incantesimo. Per 3...7 secondo[i], il danno ricevuto dall\'obiettivo alleato viene ridotto di 5 ogni volta che l\'alleato viene colpito mentre si trova sotto gli effetti di questo incantesimo.','Incantesimo. (Secondi: 3...7) Riduce di 5 i danni in arrivo ogni volta che l\'obiettivo (un alleato o te stesso) subisce danni.'],
1400=>['Rovescio del Danno','Incantesimo. Per 8 secondi, la prossima volta che l\'obiettivo (un alleato o te stesso) dovrebbe subire dei danni, il nemico che ha inflitto il danno lo subisce al suo posto (max 5...75 danno[i]).','Incantesimo. (Secondi: 8) Impedisce il prossimo danno e colpisce la fonte con la stessa quantità (max 5...75).'],
1401=>['Tocco Riparatore','Magia. L\'alleato toccato perde due condizioni e viene curato di 15...60 Punto[i] Salute per ogni condizione così rimossa.','Magia a Tocco. Rimuove due condizioni. Cura di 15...60 per ogni condizione rimossa.'],
1402=>['Fendente Critico','Attacco con Ascia. Se questo attacco va a segno, infliggi +5...20 danno[i]; se risulta in un attacco critico l\'obiettivo nemico viene interrotto.','Attacco con Ascia. Danni inferti: +5...20. Interrompe un\'azione se assesti un colpo critico.'],
1403=>['Fendente Agonizzante','Attacco con Ascia. Quando questo attacco va a segno, infliggi +5...20 danno[i]; se l\'obiettivo nemico è affetto da una Ferita Profonda interrompi la sua azione.','Attacco con Ascia. Danni inferti: +5...20. Interrompe un\'azione se l\'obiettivo nemico ha una Ferita Profonda.'],
1404=>['Flagellazione','Posizione. Per 1...15 secondo[i], la tua velocità d\'attacco aumenta di un 33%, ma la tua velocità di movimento rallenta di un 33%.','Posizione. (Secondi: 1...15) Incremento tua velocità d\'attacco: 33%. Rallentamento dei tuoi movimenti: 33%.'],
1405=>['Colpo con Carica','Posizione d\'Élite. Per 1...10 secondo[i], la tua velocità di corsa aumenta di un 33%; il tuo prossimo colpo ravvicinato messo a segno infligge +10...90 danno[i] e la posizione termina. Questa posizione termina se utilizzi un\'abilità.','Posizione d\'Élite. (Secondi: 1...10) Incremento velocità di movimento: 33%. Danni inferti dal tuo prossimo attacco ravvicinato: +10...90. Termina se colpisci o usi un\'abilità.'],
1406=>['Testata','Abilità d\'Élite. L\'obiettivo nemico toccato subisce 40...100 danno[i]. Tu vieni stordito per 10 secondo[i].','Abilità d\'Élite a Tocco. Danni inferti: 40...100. Sei affetto da Stordimento (10 secondo[i]).'],
1407=>['Conforto del Leone','Abilità. Tutti i tuoi Sigilli vengono disattivati per 12 secondi. Vieni curato di 50...110 Punto[i] Salute ed ottieni 0...3 dose[i] di adrenalina.','Abilità. Cure per te: 50...110. Adrenalina: 0...3. Disattiva i tuoi Sigilli (12 secondi).'],
1408=>['Impeto dello Ntouka','Abilità d\'Élite. Ottieni 1...7 dose[i] di adrenalina. Per 8 secondo[i], ogni volta che attivi un\'abilità che richiede adrenalina, quella abilità si ricarica per 3 secondo[i].','Abilità d\'Élite. Adrenalina conseguita: 1...7. Per 8 secondo[i] le abilità di adrenalina si ricaricano in 3 secondo[i] quando vengono usate.'],
1409=>['Percossa del Mokele','Attacco con Martello. Se questo attacco va a segno infliggi +5...20 danno[i] ed ottieni 2 dose[i] di Adrenalina.','Attacco con Martello. Danni inferti: +5...20. Adrenalina conseguita: 2.'],
1410=>['Percossa Prepotente','Attacco con Martello. Se l\'attacco va a segno, infliggi +1...20 di danni. Se l\'obiettivo nemico finisce a terra, viene colpito da Stordimento per 1...8 secondi.','Attacco con Martello. Danni inferti: +1...20. Condizione inflitta all\'obiettivo nemico se finisce a terra: Stordimento (secondi: 1...8).'],
1411=>['Sigillo della Resistenza','Sigillo. Ottieni +50...300 di Salute massima. Questo Sigillo termina se metti a segno un attacco.','Sigillo. Tua Salute massima: +50...300. Termina se un tuo attacco va a segno.'],
1412=>['"Sei Rimasto Solo!"','Urlo d\'Élite. Se l\'obiettivo nemico non è vicino ad un alleato subisce Storpiatura e Debolezza per 8 secondo[i].','Urlo d\'Élite. Condizioni inflitte: Storpiatura e Debolezza (8 secondo[i]). Non ha effetto se l\'obiettivo nemico è vicino ad uno dei suoi alleati.'],
1413=>['Scarica di Aggressione','Posizione. Per 2...10 secondo[i] attacchi con una velocità superiore di un 33%. Quando questa posizione termina perdi tutta l\'adrenalina.','Posizione. (Secondi: 2...10) Incremento tua velocità d\'attacco: 33%. Effetto al termine: perdi tutta l\'adrenalina.'],
1414=>['Carica Infuriante','Posizione. Per 5...15 secondi la tua velocità aumenta di un 25%. La Carica Infuriante termina quando colpisci un obiettivo e ti conferisce 0...3 dosi di adrenalina per il tuo prossimo attacco in mischia andato a segno.','Posizione. (Secondi: 5...15). Aumento della tua velocità di movimento: 25%. Dosi di adrenalina ottenute dal tuo prossimo attacco in mischia: +0...3. <c x="SkillDull">Termina dopo il tuo prossimo attacco andato a segno.'],
1415=>['Fendente Azzoppante','Attacco d\'Élite con Spada. Se questo attacco va a segno, l\'obiettivo nemico diventa storpio per 5...15 secondo[i] ed inizia a sanguinare per 10...25 secondo[i].','Attacco d\'Élite con Spada. Condizioni inflitte: Storpiatura (5...15 secondo[i]) ed Emorragia (10...25 secondo[i]).'],
1416=>['Squarcio Barbarico','Attacco con Spada. Se questo attacco va a segno, infliggi +5...30 danno[i]; se al momento non stai utilizzando una posizione infliggi anche Emorragia per 5...15 secondo[i].','Attacco con Spada. Danni inferti: +5...30. Condizione inflitta se non sei in posizione: Emorragia (5...15 secondo[i]).'],
1465=>['Tiro Preparato','Attacco con Arco d\'Élite. Se questo attacco va a segno, infliggi +10...25 danno[i]. Se ti trovi sotto gli effetti di una Preparazione ottieni 1...9 Punto[i] Energia.','Attacco con Arco d\'Élite. Danni inferti: +10...25. Energia conseguita se hai una preparazione attiva: 1...9.'],
1466=>['Freccia Bruciante','Attacco con Arco d\'Élite. Se questo attacco va a segno infliggi +10...30 danno[i] e provochi Bruciatura per 2...8 secondo[i].','Attacco con Arco d\'Élite. Danni inferti: +10...30. Condizione inflitta: Bruciatura (2...8 secondo[i]).'],
1467=>['Tiro Parabolico','Attacco con Arco. Se questa freccia va a segno infligge +10...35 danno[i]. Questa freccia non può essere bloccata, ma si muove ad una velocità inferiore del 50%.','Attacco con Arco. Danni inferti: +10...35. Non bloccabile. Rallentamento della velocità di questa freccia: 50%.'],
1468=>['Colpo Congiunto','Urlo d\'Élite. La tua mascotte si muove immediatamente verso il tuo obiettivo e con il suo attacco successivo infligge Emorragia per 5...15 secondo[i]. La prossima volta che un tuo attacco va a segno l\'obiettivo nemico subisce Storpiatura per 5...15 secondo[i].','Urlo d\'Élite. La tua mascotte si muove immediatamente verso il tuo obiettivo e con il suo attacco successivo infligge Emorragia (5...15 secondo[i]). Condizione da te inflitta la prossima volta che un tuo attacco va a segno: Storpiatura (5...15 secondo[i]).'],
1469=>['Fuoco Incrociato','Attacco con Arco. Se questo attacco colpisce l\'obiettivo nemico, infligge +5...20 danno[i]. Se quel nemico si trova vicino ad uno qualsiasi dei tuoi alleati, questo attacco non può essere bloccato.','Attacco con Arco. Danni inferti: +5...20. Non bloccabile se l\'obiettivo nemico si trova vicino ad un tuo alleato.'],
1470=>['Frecce Appuntite','Preparazione. Per 24 secondo[i] le tue frecce provocano Emorragia per 3...15 secondo[i]. Mentre attivi questa abilità la tua armatura si riduce di -40.','Preparazione. (Secondi: 24) Condizione inflitta dalle tue frecce: Emorragia (3...15 secondo[i]). Riduzione armatura mentre attivi quest\'abilità: -40.'],
1471=>['Concentrazione dello Sciacallo','Abilità d\'Élite. Per 10 secondo[i], se colpisci un nemico affetto da una condizione ottieni 3...12 Punto[i] Energia.','Abilità d\'Élite. (Secondi: 10) Energia conseguita se colpisci un nemico affetto da una condizione: 3...12.'],
1472=>['Tossicità','Rituale della Natura. Crei uno Spirito di livello 1...10. Le creature affette da Veleno o Malattia nella sua portata subiscono una Degenerazione della Salute di -2. Lo Spirito si esaurisce dopo 30...180 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...180 secondo[i]). Degenerazione Salute delle creature nella portata affette da Veleno o Malattia: -2.'],
1473=>['Sabbie Mobili','Rituale della Natura d\'Élite. Crei uno Spirito di livello 1...10. Tutte le creature nella sua portata (Spiriti esclusi) perdono 1 Punto Energia ogni volta che attaccano o utilizzano un\'abilità. Lo Spirito si esaurisce dopo 30...180 secondo[i].','Rituale della Natura d\'Élite. Crei uno Spirito di livello 1...10 (in vita per 30...180 secondo[i]). Energia persa dalle creature ogni volta che attaccano o usano un\'abilità: 1. Non ha effetto sugli Spiriti.'],
1474=>['Abbraccio della Tempesta','Posizione. Per 10 secondi, la tua velocità di movimento aumenta di un 25%. Questa posizione si rinnova ogni volta che subisci danni elementali.','Posizione. (Secondi: 10) Incremento tua velocità di movimento: 25%. Rinnovo: ogni volta che ricevi danni elementali.'],
1475=>['Velocità dell\'Intrappolatore','Posizione. Per 5...30 secondo[i], le velocità di ricarica delle tue trappole aumenta di un 25% e la velocità di attivazione aumenta di un 25%. Questa posizione termina se un tuo attacco va a segno.','Posizione. (Secondi: 5...30) Incremento velocità di ricarica delle trappole: 25%; incremento velocità di attivazione: 25%. Termina se un tuo attacco va a segno.'],
1476=>['Aziona-trappola','Trappola. Quando l\'Aziona-trappola viene attivato, tutti i nemici nei dintorni subiscono 5...20 danno[i] perforante[i]; i nemici storpi vengono abbattuti. L\'Aziona-trappola termina dopo 90 secondi. Mentre attivi questa abilità è facile interromperti.','Trappola. (Secondi: 90) Danni perforanti ai nemici nei dintorni: 5...20. Provoca abbattimento dei nemici affetti da Storpiatura. Facile interruzione.'],
1478=>['Impeto Rinnovante','Fattura. Per 8 secondo[i] l\'obiettivo nemico riceve 2...12 danno[i] al secondo. Al termine della fattura, ottieni 1...8 Punto[i] Energia.','Fattura. (Secondo[i]: 8). Danni inferti: 2...12 al secondo. Effetto al termine: Energia ottenuta: 1...8.'],
1479=>['Offerta dello Spirito','Magia d\'Élite. Ottieni 8...17 Punto[i] Energia. Se sono presenti degli Spiriti a portata d\'orecchio, non sacrifichi alcuna Salute.','Magia d\'Élite. Energia conseguita: 8...17. Non sacrifichi Salute se c\'è uno Spirito a portata d\'orecchio.'],
1480=>['Dono dello Spirito','Incantesimo. Per 60 secondo[i], ogni volta che dai vita ad una creatura, tutti gli alleati vicini ad essa ottengono 5...50 Punto[i] Salute e perdono 1 condizione.','Incantesimo. (Secondi: 60) Ogni volta che dai vita ad una creatura, tutti gli alleati nei dintorni ottengono 5...50 Punto[i] Salute e perdono una condizione.'],
1481=>['Sigillo del Patto Mortale','Sigillo. Fai resuscitare il membro della squadra selezionato con Salute equivalente alla tua Salute attuale e 15...100% di Energia massima; la prossima volta che quell\'alleato muore nel giro di 120 secondo[i], morirai anche tu.','Sigillo. Resuscita il membro della squadra selezionato con la tua Salute attuale e un 15...100% di Energia massima. Per 120 secondo[i] potresti morire se questo membro della squadra muore.'],
1482=>['Reclama Essenza','Magia d\'Élite. Tutti i tuoi Spiriti muoiono. Ottieni 5...20 Punto[i] Energia e tutti i tuoi Rituali Incatenanti si ricaricano se uno Spirito è morto in questo modo.','Magia d\'Élite. Tutti i tuoi Spiriti muoiono. Energia conseguita se uno Spirito muore in questo modo: 5...20. Tutti i tuoi Rituali Incatenanti si ricaricano.'],
1483=>['Colpo Esorcizzante','Attacco Ravvicinato. Se questo attacco va a segno, infligge 10...60 danni sacri. Infligge danno doppio alle creature evocate.','Attacco Ravvicinato. Danni sacri inferti: 10...60. Infligge danno doppio alle creature evocate.'],
1484=>['Falciata Mistica','Attacco Ravvicinato. Se l\'attacco va a segno, infligge +3...12 danni. Se sei sotto incantesimo, questo attacco infligge inoltre +3...12 danni.','Attacco Ravvicinato. Danni inferti: +3...12. Danni aggiuntivi inferti: +3...12 se sei sotto incantesimo.'],
1485=>['Attacco dell\'Eremita','Attacco con Falce. Se l\'attacco va a segno, infligge +1...10 danni e rimuove un Incantesimo del Derviscio. Se un incantesimo viene rimosso, infliggi un danno aggiuntivo di +1...10 e colpisci tutti i nemici adiacenti.','Attacco con Falce. Danni inferti: +1...10 e rimuove un Incantesimo del Derviscio. Effetto della rimozione: infligge un danno aggiuntivo di +1...10 e colpisce tutti i nemici adiacenti.'],
1486=>['Sottrai Impurità','Attacco Ravvicinato. Se l\'attacco va a segno, infliggi +3...15 di danni. Ogni nemico colpito perde 1 condizione. Per ogni nemico che perde una condizione, tutti i nemici adiacenti subiscono 10...40 danni sacri.','Attacco Ravvicinato. Danni inferti: +3...15. Il nemico colpito perde 1 condizione. Effetto della rimozione: tutti i nemici adiacenti agli obiettivi colpiti subiscono 10...40 danni sacri.'],
1487=>['Falciata della Luna Gemella','Attacco Ravvicinato. Perdi 1 Incantesimo del Derviscio e ottieni 10...50 Punti Salute. Se un incantesimo è stato perso in questo modo, non puoi essere bloccato[f:"bloccata"], colpisci due volte e ottieni +10...70 Punti Salute.','Attacco Ravvicinato. Rimuove uno dei tuoi Incantesimi del Derviscio. Punti Salute ottenuti: 10...50. Effetto della rimozione: non bloccabile, attacco doppio e +10...70 Punti Salute.'],
1488=>['Falciata Vittoriosa','Attacco Ravvicinato. Se l\'attacco va a segno, infliggi +5...25 di danni. Se la Salute dell\'obiettivo nemico è inferiore alla tua, ottieni 30...80 Punto[i] Salute.','Attacco Ravvicinato. Danni inferti: +5...25. Salute conseguita per ogni nemico da te colpito con meno Salute di te: 30...80.'],
1489=>['Falciata Irresistibile','Attacco con Falce. Danni inferti: +3...15 e perdi un Incantesimo del Derviscio. Se un incantesimo viene perso in questo modo, la Falciata Irresistibile non può essere bloccata, rimuove una posizione e infligge +3...15 danni.','Attacco con Falce. Danni inferti: +3...15. Incantesimi del Derviscio rimossi: 1. Effetto della rimozione: non bloccabile, rimuove una posizione e infligge +3...15 danni.'],
1490=>['Assalto Pio','Attacco Ravvicinato. Se l\'attacco va a segno, infligge +10...20 danni e rimuove un Incantesimo del Derviscio. Se un Incantesimo del Derviscio è stato rimosso, questa abilità si ricarica più velocemente di un 75% e tutti i nemici adiacenti subiscono 15...40 danni.','Attacco Ravvicinato. Danni inferti: +10...20. Rimuove uno dei tuoi Incantesimi del Derviscio. Effetto della rimozione: l\'abilità si ricarica più velocemente di un 75% e tutti i nemici adiacenti subiscono 15...40 danni.'],
1491=>['Tornado Mistico','Magia. Danni da freddo a tutti i nemici nei dintorni : 10...60. Se sei sotto incantesimo, questo attacco infligge inoltre +10...60 di danni da freddo.','Magia. Danni da freddo a tutti i nemici nei dintorni : 10...60. Danni da freddo inferti: +10...60 se sei sotto incantesimo.'],
1493=>['Dita di Grenth','Incantesimo Lampo. Infligge 10...40 danni da freddo a tutti i nemici nei dintorni. Per 30 secondi i tuoi attacchi infliggono danni da freddo. Al termine dell\'incantesimo, trasferisci 1...2 condizioni a tutti i nemici nei dintorni.','Incantesimo Lampo. (Secondi: 30). I tuoi attacchi assestano danni da freddo. Effetto iniziale: danni da freddo inflitti ai nemici nei dintorni: 10...40. Effetto al termine: condizioni trasferite ai nemici nei dintorni: 1...2.'],
1495=>['Aura di Spine','Incantesimo Lampo. Tutti i nemici nei dintorni soffrono di Emorragia per 5...15 secondi. Per 30 secondi, questo incantesimo non ha effetto. Al termine dell\'incantesimo, tutti i nemici nei dintorni diventano storpi per 3...8 secondi.','Incantesimo Lampo. (Secondi: 30.) Effetto iniziale: condizione inflitta: Emorragia (5...15 secondi) ai nemici nei dintorni. Effetto al termine: condizione inflitta: Storpiatura (3...8 secondi) ai nemici nei dintorni.'],
1496=>['Ira di Balthazar','Incantesimo Lampo. Tutti i nemici nei dintorni prendono fuoco per 1...3 secondi. Per 20 secondi successivi, questo incantesimo non sortisce effetti. Al termine dell\'incantesimo, ottieni 1...2 dosi di adrenalina se ci sono nemici a portata d\'orecchio.','Incantesimo Lampo. (Secondi: 20). Effetto iniziale: infligge Bruciatura (1...3 secondi) ai nemici nei dintorni. Effetto al termine: dosi di adrenalina ricevute se ci sono nemici a portata d\'orecchio: 1...2.'],
1497=>['Mantello della Polvere','Incantesimo Lampo. Infligge 10...40 danni da terra a tutti i nemici nei dintorni. Per 30 secondi i tuoi attacchi infliggono danni da terra. Quando quest\'incantesimo termina, tutti i nemici nei dintorni vengono accecati per 1...4 secondi.','Incantesimo Lampo. (Secondi: 30). I tuoi attacchi assestano danni da terra. Effetto iniziale: Danni da terra ai nemici nei dintorni: 10...40. Effetto al termine: Condizione inflitta: Accecamento (1...4 secondi) ai nemici dei dintorni.'],
1498=>['Forza Travolgente','Incantesimo Lampo. Infligge 10...40 danni da terra a tutti i nemici nei dintorni. Per 30 secondi i tuoi attacchi infliggono danni da terra. Al termine dell\'incantesimo, tutti i nemici nei dintorni subiscono Armatura Incrinata per 1...10 secondi.','Incantesimo Lampo. (Secondi: 30). I tuoi attacchi assestano danni da terra. Effetto iniziale: 10...40 danni da terra ai nemici nei dintorni. Effetto al termine: Condizione inflitta: Armatura Incrinata (1...10 secondi) ai nemici dei dintorni.'],
1499=>['Rinnovamento Pio','Incantesimo Lampo d\'Élite. Per 8 secondi non si verificano effetti. Al termine dell\'incantesimo, Rinnovamento Pio si ricarica e ottieni 0...5 Punti Energia e 0...30 Punti Salute.','Incantesimo Lampo d\'Élite. (Secondi: 8). Effetto al termine: si ricarica e ottieni 0...5 Punti Energia e 0...30 Punti Salute.'],
1500=>['Mantello del Miraggio','Incantesimo Lampo. Per 20 secondi hai una probabilità del 40% di bloccare e un 4...10% extra per ogni incantesimo aggiuntivo (max 80%). Tutti i nemici nelle vicinanze subiscono 10...40 danni di terra ogni volta che perdi un incantesimo da Derviscio.','Incantesimo Lampo. (20 secondo/i) Probabilità del 40% di bloccare e un 4...10% extra per ogni incantesimo aggiuntivo. I nemici nelle vicinanze subiscono 10...40 danni di terra quando perdi un incantesimo da Derviscio.'],
1502=>['Zelo Arcano','Incantesimo d\'Élite. Per 10 secondi, ogni volta che compi una magia, ottieni 2 Punti Energia per ogni incantesimo che hai addosso (max. 2...7 Punti Energia).','Incantesimo d\'Élite. (Secondi: 10). Energia conseguita per ogni incantesimo su di te ogni volta che lanci una magia: 2 (max 2...7).'],
1503=>['Vigore Mistico','Incantesimo. Per 20 secondo[i], ogni volta che un tuo attacco va a segno, ottieni 3...15 Punto[i] Salute per ogni incantesimo che hai addosso (max. 25 Punto[i] Salute).','Incantesimo. (Secondi: 20) Salute conseguita per ogni incantesimo che hai addosso ogni volta che colpisci con un attacco: 3...15 (max 25).'],
1504=>['Intervento Vigile','Incantesimo. Per 60 secondo[i], la prossima volta che il danno fa scendere la Salute dell\'obiettivo (un alleato o te stesso) al di sotto del 25%, quell\'alleato viene curato di 50...200 Punto[i] Salute.','Incantesimo. (Secondi: 60) Cure impartite la prossima volta che il danno fa calare la Salute dell\'obiettivo alleato al di sotto di un 25%: 50...200.'],
1505=>['Voto della Pietà','Incantesimo. Per 20 secondi ottieni +24 di armatura e +1...4 di Rigenerazione della Salute. Il Voto della Pietà si rinnova ogni volta che un incantesimo presente su di te termina.','Incantesimo. (Secondi: 20). Armatura: +24. Rigenerazione Salute: +1...4. Rinnovo: ogni volta che un incantesimo presente su di te termina.'],
1506=>['Dono Vitale','Incantesimo. Per 20 secondo[i], la tua Salute massima aumenta di +40...100. Quando questo incantesimo termina vieni curato di 75...200 Punto[i] Salute.','Incantesimo. (Secondi: 20) Tua Salute massima: +40...100. Effetto al termine: ti cura di 75...200.'],
1507=>['Cuore della Fiamma Sacra','Incantesimo Lampo. Tutti i nemici nei dintorni subiscono 5...30 danni sacri. Per 30 secondi successivi i tuoi attacchi infliggono danni sacri. Al termine dell\'incantesimo, tutti i nemici nei dintorni vengono incendiati per 2...5 secondi.','Incantesimo Lampo. (Secondi: 30). I tuoi attacchi assestano danni sacri. Effetto iniziale: Danni sacri inferti ai nemici nei dintorni: 5...30. Effetto al termine: Condizione inflitta ai nemici nei dintorni: Bruciatura (2...5 secondi).'],
1508=>['Prolunga Incantesimi','Abilità. Dura 10 secondi; il tuo prossimo Incantesimo del Derviscio ha una durata prolungata di un 10...150%.','Abilità. (10 secondi). Il tuo prossimo Incantesimo del Derviscio ha una durata prolungata di un 10...150%.'],
1509=>['Intervento Fedele','Incantesimo. Se il danno fa scendere la tua Salute al di sotto del 50%, l\'Intervento Fedele termina. Quando ciò accade vieni curato di 30...150 Punto[i] Salute.','Incantesimo. Salute conseguita la prossima volta che il danno fa calare la tua Salute al di sotto di 50%: 30...150.'],
1510=>['Granelli di Sabbia','Incantesimo Lampo. Per 30 secondo/i la/e prossima/e 1...5 volta/e che colpisci con una falce, tutti i nemici adiacenti subiscono 10...60 danni di terra.','Incantesimo Lampo. (30 secondo/i) Infligge 10...60 danni di terra a tutti i nemici adiacenti ogni volta che li colpisci con la falce. Termina dopo 1...5 colpo/i.'],
1512=>['Fretta di Lyssa','Incantesimo Lampo. Per 3...15 secondi i tuoi Incantesimi del Derviscio si ricaricano con una velocità maggiore del 33%. Quando attivi questo incantesimo, tutti i nemici adiacenti vengono interrotti. Al termine di questo incantesimo, tutti i nemici adiacenti vengono interrotti. 50% di probabilità di fallimento con Preghiere del Vento inferiori al grado 5.','Incantesimo Lampo. (Secondi: 3...15). Incremento velocità di ricarica dei tuoi Incantesimi del Derviscio: 33%. Effetto iniziale: interrompe tutti i nemici adiacenti. Effetto al termine: interrompe tutti i nemici adiacenti. (50% di probabilità di fallimento con Preghiere del Vento inferiori al grado 5.)'],
1513=>['Mani Guidate','Incantesimo. Per 20 secondi sarà impossibile bloccare 0...3 dei tuoi prossimi attacchi. Quando attiva, questa abilità rimuove Accecamento.','Incantesimo. (Secondi: 20). 0...3 dei tuoi prossimi attacchi non possono essere bloccati. Effetto iniziale: rimuove Accecamento.'],
1514=>['Stabilità Effimera','Incantesimo Lampo. Per 4...10 secondi, la tua velocità di attacco aumenta di un 25% e non puoi finire a terra. L\'incantesimo finisce prematuramente se impedisce un abbattimento.','Incantesimo Lampo. (Secondi: 4...10). Aumento velocità di attacco: 25% e non puoi finire a terra. Termina se viene impedito un abbattimento.'],
1515=>['Armatura di Santità','Incantesimo. Tutti i nemici adiacenti vengono colpiti da Debolezza per 5...15 secondi. Per 15 secondi subisci 5...20 danno["danni"] in meno dai nemici affetti da una condizione.','Incantesimo. Condizione inflitta a tutti i nemici adiacenti: Debolezza (secondi: 5...15). Riduzione del danno che subisci dai nemici affetti da una condizione: 5...20 (secondi: 15).'],
1516=>['Rigenerazione Mistica','Incantesimo. Per 5...20 secondi ottieni una Rigenerazione della Salute di +1...4 per ogni incantesimo presente su di te (max 8 incantesimi).','Incantesimo. (Secondi: 5...20). Rigenerazione tua Salute per ogni incantesimo presente su di te (max 8): +1...4.'],
1517=>['Voto del Silenzio','Incantesimo d\'Élite. Per 5...10 secondi non puoi essere l\'obiettivo delle magie e non puoi lanciare magie.','Incantesimo d\'Élite. (Secondi: 5...10). Non puoi essere bersaglio di magie. Non puoi lanciare magie.'],
1518=>['Apparizione di Balthazar','Forma d\'Élite. Per 10...90 secondi, ottieni +20 di armatura contro danni fisici, ottieni adrenalina il 25% più velocemente, i tuoi attacchi infliggono danni sacri e, ogni volta che perdi un Incantesimo da Derviscio, i nemici nei dintorni prendono fuoco per 1...3 secondi. Questa abilità verrà disabilitata per 45 secondi.','Forma d\'Élite. (Secondi: 10...90.) Ottieni +20 di armatura contro danni fisici, ottieni adrenalina il 25% più velocemente, i tuoi attacchi infliggono danni sacri e, ogni volta che perdi un Incantesimo da Derviscio, ai nemici nei dintorni viene inflitta Bruciatura per 1...3 secondi. Questa abilità verrà disabilitata per 45 secondi.'],
1519=>['Apparizione di Dwayna','Forma d\'Élite. Per 10...90 secondi i tuoi attacchi infliggono danni sacri. Quando utilizzi un\'abilità d\'attacco del Derviscio perdi 1 fattura. Quando perdi un Incantesimo del Derviscio, tutti gli alleati a portata d\'orecchio vengono curati di 5...50 Punti Salute. Questa abilità verrà disabilitata per 45 secondi.','Forma d\'Élite. (Secondi: 10...90.) Infliggi danni sacri. Fatture perse utilizzando un\'abilità d\'attacco del Derviscio: 1. Curi gli alleati a portata d\'orecchio di 5...50 Punti Salute quando perdi un Incantesimo del Derviscio. Questa abilità verrà disabilitata per 45 secondi.'],
1520=>['Apparizione di Grenth','Forma d\'Élite. Per 10...90 secondi i tuoi attacchi con la Falce infliggono danni da oscurità e sottraggono 0...12 Punti Salute. Sei immune da Malattia e quando perdi un Incantesimo del Derviscio infliggi Malattia a tutti i nemici adiacenti per 3 secondi. L\'abilità viene disattivata per 45 secondi.','Forma d\'Élite. (Secondi: 10...90). I tuoi attacchi con la Falce infliggono danni da oscurità e sottraggono 0...12 Punti Salute. Sei immune da Malattia. Condizione inflitta a tutti i nemici adiacenti quando perdi un Incantesimo del Derviscio: Malattia (3 secondi). L\'abilità viene disattivata per 45 secondi.'],
1521=>['Apparizione di Lyssa','Forma d\'Élite. Per 10...90 secondi, i tuoi Incantesimi del Derviscio si ricaricano con una velocità maggiore del 50% e i tuoi attacchi infliggono danni da caos. Quando perdi un Incantesimo del Derviscio sottrai 1 Punti Energia a tutti i nemici nei dintorni. L\'abilità viene disattivata per 45 secondi.','Forma d\'Élite. (Secondi: 10...90). Velocità di ricarica Incantesimi del Derviscio: +50% e infliggi danni da caos con gli attacchi. Punti Energia sottratti a tutti i nemici nei dintorni quando perdi un Incantesimo del Derviscio: 1. L\'abilità viene disattivata per 45 secondi.'],
1522=>['Apparizione di Melandru','Forma d\'Élite. Per 10...90 secondi, ottieni +150 Punti Salute, +30 armatura contro gli attacchi elementali e i tuoi attacchi infliggono danni da terra. Quando perdi un Incantesimo del Derviscio, tutti i membri della squadra a portata d\'orecchio perdono 1 condizione. L\'abilità viene disattivata per 45 secondi.','Forma d\'Élite. (Secondi: 10...90). Hai +150 Salute massima, +30 armatura contro gli attacchi elementali e i tuoi attacchi infliggono danni da terra. Condizioni curate a tutti i membri della squadra a portata d\'orecchio quando perdi un Incantesimo del Derviscio: 1. L\'abilità viene disattivata per 45 secondi.'],
1523=>['Meditazione','Incantesimo. Perdi tutta l\'adrenalina. Per 20 secondi, ottieni 1...4 Punti Energia ogni volta che termina un incantesimo su di te.','Incantesimo. (Secondi: 20). Perdi tutta l\'adrenalina. Ottieni 1...4 Punti Energia ogni volta che un incantesimo presente su di te termina.'],
1524=>['Zelo dell\'Eremita','Incantesimo. Ottieni 1...3 Punti Energia (max 8) per ogni nemico a portata d\'orecchio. Per 10 secondi successivi, questo incantesimo non sortisce effetti. Al termine dell\'incantesimo, ottieni 1...3 Punti Energia (max 8) per ogni nemico a portata d\'orecchio.','Incantesimo. (Secondi: 10). Effetto iniziale: ottieni 1...3 Punti Energia (max 8) per ogni nemico a portata d\'orecchio. Effetto al termine: ottieni 1...3 Punti Energia (max 8) per ogni nemico a portata d\'orecchio.'],
1525=>['Cura Naturale','Magia. Vieni curata di 50...170 Punti Salute. Se non sei sotto incantesimo, questo incantesimo si attiva più velocemente di un 50%.','Magia. Cura 50...170 Punti Salute. Questa abilità si attiva di un 50% più velocemente se non sei sotto incantesimo.'],
1526=>['Instilla Salute','Magia. L\'obiettivo alleato viene curato del 5...50% della tua Salute attuale (max. 300 Punto[i] Salute).','Magia. Cura di un 5...50% della tua Salute attuale (max 300). Impossibile selezionare se stessi.'],
1527=>['Cura Mistica','Magia. Vieni curata di 5...65 Punti Salute. Cura anche tutti i membri della squadra sotto incantesimo di 5...65 Punti Salute.','Magia. Ti cura di 5...65 Punti Salute. Punti Salute curati per tutti i membri della squadra sotto incantesimo: 5...65.'],
1528=>['Tocco di Dwayna','Magia. L\'obiettivo alleato toccato viene curato di 60 Punto[i] Salute per ogni incantesimo che hai addosso (max. 60...240).','Magia a Tocco. Cure per ogni incantesimo che hai addosso: 60 (max 60...240).'],
1529=>['Ripristino Pio','Magia. Ottieni 80...150 Punti Salute e perdi 1 Incantesimo del Derviscio. Fatture perse se un incantesimo è stato rimosso in questo modo: 1...3.','Magia. Ottieni 80...150 Punti Salute e perdi 1 Incantesimo del Derviscio. Effetto della rimozione: perdi 1...3 fatture.'],
1530=>['Sigillo di Luce Pia','Sigillo. Rimuove 1 Incantesimo del Derviscio. L\'obiettivo alleato viene curato di 30...150 Punti Salute. Se un incantesimo è stato rimosso in questo modo, questo sigillo si ricarica più velocemente di un 75%.','Sigillo. Cura: 30...150 Punti Salute. Rimuove uno dei tuoi Incantesimi del Derviscio. Effetto della rimozione: ricarica più veloce del 75%.'],
1531=>['Aura Intimidatoria','Incantesimo. Per 60 secondi, hai +40...100 Salute massima e subisci 1...10 danni in meno da nemici con meno Salute di te.','Incantesimo. (Secondi: 60). Hai +40...100 Salute massima e subisci -1...10 danni da nemici con meno Salute di te.'],
1532=>['Tempesta di Sabbia Mistica','Magia. Crei una Tempesta di Sabbia nella tua posizione che dura 3 secondi. Per ogni secondo, i nemici nei dintorni di questa posizione subiscono 10...40 danni da terra. I nemici in attacco subiscono 10...20 danni aggiuntivi. Se sei sotto incantesimo quando lanci questa magia, durerà il doppio del tempo.','Magia. (Secondi: 3). Danni da terra inferti: 10...40 al secondo. Infligge 10...20 danni in più ai nemici in attacco. Colpisce i nemici nelle vicinanze della tua posizione iniziale. Dura il doppio del tempo se sei sotto incantesimo.'],
1533=>['Venti del Disincanto','Magia. Rimuove uno dei tuoi Incantesimi del Derviscio. Se un incantesimo è stato rimosso, tutti i nemici nei dintorni perdono 1 incantesimo e subiscono 20...80 danni da freddo.','Magia. Rimuove uno dei tuoi Incantesimi del Derviscio. Effetto della rimozione: tutti i nemici nei dintorni perdono 1 incantesimo e subiscono 20...80 danni da freddo.'],
1534=>['Tocco lacerante','Magia. Infligge 15...65 danni da freddo al bersaglio nemico. Perdi 1 incantesimo da Derviscio. Se un incantesimo viene rimosso, il bersaglio nemico perde 1 incantesimo e tu ottieni 2 colpo/i da adrenalina.','Magia a Tocco. Infligge 15...65 danni da freddo. Perdi 1 incantesimo da Derviscio. Effetto di rimozione: il bersaglio nemico perde 1 incantesimo e tu ottieni 2 colpo/i da adrenalina.'],
1535=>['Falciata Azzoppante','Attacco con Falce. Se questo attacco colpisce un nemico, gli provoca Storpiatura per 3...12 secondi. Questa abilità infligge +3...15 di danno se quel nemico è in movimento.','Attacco con Falce. (Secondi: 3...12). Infligge Storpiatura. Danni inflitti ai nemici in movimento: +3...15.'],
1536=>['Colpo Lesionante','Attacco d\'Élite con Falce. Se l\'attacco va a segno, infliggi +5...20 danni, l\'obiettivo nemico soffre di Emorragia per 5...20 secondi e perdi 1 Incantesimo del Derviscio. Se un incantesimo viene rimosso, l\'obiettivo nemico è affetto inoltre da Ferita Profonda per 5...20 secondi.','Attacco d\'Élite con Falce. Danni inferti: +5...20. Condizione inflitta: Emorragia (5...20 secondi). Rimuove 1 Incantesimo del Derviscio. Effetto della rimozione: Condizione inflitta: Ferita Profonda (5...20 secondi).'],
1537=>['Colpo Stancante','Attacco con Falce. Rimuovi 1 Incantesimo del Derviscio. Se un incantesimo è stato rimosso, infliggi Ferita Profonda per 3...10 secondi. Se un incantesimo non è stato rimosso soffri di Debolezza per 10 secondi.','Attacco con Falce. Rimuove 1 Incantesimo del Derviscio. Effetto della rimozione: Condizione inflitta: Ferita Profonda (3...10 secondi). Soffri di Debolezza (10 secondi) se un incantesimo non è stato rimosso.'],
1538=>['Assalto di Lyssa','Attacco con Falce. Se va a segno, questo attacco interrompe un\'azione. Se sei sotto incantesimo, qualsiasi abilità tu interrompa viene disattivata per 1...10 secondi in più. Questo attacco infligge un 50% di danno normale.','Attacco con Falce. Interrompe un\'azione. Disattivazione dell\'abilità interrotta se sei sotto incantesimo: +1...10 secondi. Questo attacco infligge un 50% di danno normale.'],
1539=>['Vittoria Gelante','Attacco con Falce. Se va a segno, infligge +3...15 di danni. Per ogni nemico colpito, che abbia meno Salute di te, quel nemico e i nemici adiacenti saranno colpiti con 10...30 danni da freddo.','Attacco con Falce. Danni inferti: +3...15. Infligge 10...30 danni da freddo all\'obiettivo e ai nemici adiacenti, ogni volta che quest\'attacco colpisce un nemico con meno Salute di te.'],
1540=>['Convinzione','Incantesimo Lampo. Per 10 secondi ottieni +10 di armatura se hai una condizione e ottieni 1...3 Rigenerazione della Salute per ogni condizione di cui soffri. Al termine dell\'incantesimo vieni curato[f:"curata"] da 1...2 condizioni.','Incantesimo Lampo. (Secondi: 10). Armatura ottenuta quando hai una condizione: + 10. Salute rigenerata per ogni condizione su di te: 1...3. Effetto al termine: condizioni rimosse: 1...2.'],
1541=>['Fretta Incantata','Incantesimo Lampo. Per 7 secondi, la tua velocità di movimento aumenta di un 25%. Se questo incantesimo termina prematuramente, perdi 1 condizioni.','Incantesimo Lampo. (Secondi: 7). Aumento della tua velocità di movimento: 25%. Perdi 1 condizioni se questo incantesimo termina prematuramente.'],
1542=>['Concentrazione Pia','Posizione. Per 5...20 secondi diventa impossibile interromperti, ma per ogni tentativo di interruzione contro di te perderai 1 Incantesimo del Derviscio, oppure la Concentrazione Pia terminerà.','Posizione. (Secondi: 5...20). Previene l\'interruzione. Costo della prevenzione: perdi un Incantesimo del Derviscio o Concentrazione Pia termina.'],
1543=>['Fretta Pia','Posizione. Rimuovi 1 Incantesimo del Derviscio e per 1...7 secondi ti muovi più velocemente di un 25%. Invece, se un incantesimo non è stato rimosso, corri più velocemente di un 50%.','Posizione. (Secondi: 1...7). Perdi 1 Incantesimo del Derviscio e ti muovi più velocemente di un 25%. Effetto della rimozione: Corsa più veloce: 50%'],
1544=>['Carica Vorticosa','Incantesimo Lampo. Per 1...6 secondi, la tua velocità di movimento aumenta di un 33%. La prossima volta che colpisci un nemico, tutti i nemici nei dintorni subiscono 10...60 danni da freddo e questo incantesimo termina.','Incantesimo Lampo. (Secondi: 1...6). Aumento della tua velocità di movimento: 33%. Danni da freddo inferti a tutti i nemici nei dintorni la prossima volta che colpisci un nemico: 10...60 e l\'incantesimo termina.'],
1545=>['Prova di Fede','Magia. Infligge 15...75 danni da freddo e sottrae 1 incantesimo all\'obiettivo nemico. Se quel nemico non è sotto incantesimo, subisce Stordimento per 2...6 secondi.','Magia a Tocco. Danni da freddo inferti: 15...75 e rimuove un incantesimo. Condizione subita dall\'obiettivo nemico se non è sotto incantesimo: Stordimento (2...6 secondi).'],
1546=>['Lancia Ardente','Attacco con Lancia. Se questo attacco va a segno infliggi +5...25 danno[i] e l\'obiettivo prende fuoco per 1...3 secondo[i].','Attacco con Lancia. Danni inferti: +5...25. Condizione inflitta: Bruciatura (1...3 secondo[i]).'],
1547=>['Lancio Potente','Attacco con Lancia. La velocità della tua lancia viene triplicata. Se va a segno infliggi +10...40 danno[i].','Attacco con Lancia. Danni inferti: +10...40. La velocità di movimento di questa lancia si triplica.'],
1548=>['Lancia Crudele','Attacco d\'Élite con Lancia. Se questo attacco va a segno, infliggi +10...50 danno[i]; se colpisci un nemico fermo, gli infliggi una Ferita Profonda per 5...20 secondo[i].','Attacco d\'Élite con Lancia. Danni inferti: +10...50. Condizione inflitta se l\'obiettivo non si sta muovendo: Ferita Profonda (5...20 secondo[i]).'],
1549=>['Lancio del Predatore','Attacco con Lancia. Se questo attacco va a segno, infliggi +5...20 danno[i]; se colpisci un nemico in movimento, gli infliggi 5...40 danno[i] in più.','Attacco con Lancia. Danni inferti: +5...20. Assesta 5...40 danno[i] in più se l\'obiettivo si sta muovendo.'],
1550=>['Lancio Inarrestabile','Attacco con Lancia. Se va a segno infliggi +10...40 danno[i]. Questo attacco non può essere bloccato.','Attacco con Lancia. Danni inferti: +10...40. Non bloccabile.'],
1551=>['Lancia del Fulmine','Attacco con Lancia. Colpisce tutti i nemici che si trovano tra te e il bersaglio. Se l\'attacco va a segno, infligge +10...20 danni da fulmine. Questo attacco ha una penetrazione dell\'armatura del 25%.','Attacco con Lancia. Infligge +10...20 danni da fulmine. Penetrazione dell\'armatura del 25%. Colpisce tutti i nemici tra te e il bersaglio.'],
1552=>['Lancia Stancante','Attacco con Lancia. Se va a segno infliggi +10...40 danno[i] e subisci debolezza per 5 secondo[i].','Attacco con Lancia. Danni inferti: +10...40. Sei affetto da Debolezza (5 secondo[i]).'],
1553=>['Inno della Furia','Canto d\'Élite. Per 10 secondo[i], tutti i membri della squadra a portata d\'orecchio ottengono 2...5 dose[i] di adrenalina la prossima volta che utilizzano un\'abilità d\'attacco.','Canto d\'Élite. (Secondi: 10) Adrenalina ottenuta dai membri della squadra a portata d\'orecchio con la loro abilità d\'attacco successiva: 2...5.'],
1554=>['Inno Azzoppante','Canto d\'Élite. Dura 10 secondo[i]; la prossima abilità d\'attacco utilizzata da ogni alleato a portata d\'orecchio provoca storpiatura per 5...15 secondo[i].','Canto d\'Élite. (Secondi: 10) Condizione inflitta dagli alleati a portata d\'orecchio con la loro abilità d\'attacco successiva: Storpiatura (5...15 secondo[i]).'],
1555=>['Inno Difensivo','Canto d\'Élite. Per 4...10 secondo[i], ogni membro della squadra a portata d\'orecchio ha un 50% di probabilità di bloccare gli attacchi in arrivo. Questo canto termina se il compagno di squadra mette a segno un\'abilità d\'attacco.','Canto d\'Élite. (Secondi: 4...10) Probabilità di bloccare dei membri della squadra a portata d\'orecchio: 50%. Termina se colpisci con un\'abilità d\'attacco.'],
1556=>['Buon Viaggio','Urlo. Per 5...20 secondo[i], i movimenti di tutti gli alleati a portata d\'orecchio aumentano di un 25% quando sono sotto gli effetti di un incantesimo.','Urlo. (Secondi: 5...20) Incremento velocità di movimento degli alleati sotto incantesimo a portata d\'orecchio: 25%.'],
1557=>['Inno della Fiamma','Canto. Per 10 secondo[i] la prossima abilità d\'attacco utilizzata da ogni membro della squadra a portata d\'orecchio provoca anche Bruciatura per 1...5 secondo[i].','Canto. (Secondi: 10) Condizione inflitta dai membri della squadra a portata d\'orecchio con la loro abilità d\'attacco successiva: Bruciatura (1...5 secondo[i]).'],
1558=>['"Punta gli Occhi!"','Urlo. Dura 10 secondo[i]; la prossima volta che ogni alleato a portata d\'orecchio compie un attacco ci sarà un 30...100% di probabilità che sia critico.','Urlo. (Secondi: 10) Aumento probabilità degli alleati a portata d\'orecchio di assestare un colpo critico con il loro attacco successivo: +30...100%.'],
1559=>['Inno dell\'Invidia','Canto. Dura 10 secondo[i]; la prossima abilità d\'attacco utilizzata da ogni alleato a portata d\'orecchio infligge +10...25 danno[i] ai nemici con Salute superiore al 50%.','Canto. (Secondi: 10) Danni inferti dagli alleati a portata d\'orecchio con la loro abilità d\'attacco successiva: +10...25. Il danno extra si applica solo ai nemici con più del 50% di Salute.'],
1560=>['Canto del Potere','Canto. Per 5...20 secondo[i], ogni alleato a portata d\'orecchio ottiene una Rigenerazione dell\'Energia di 4 finché l\'alleato non utilizza un\'abilità.','Canto. (Secondi: 5...20) Rigenerazione Energia degli alleati a portata d\'orecchio: +4. Termina usando un\'abilità.'],
1561=>['Inno Zelante','Canto. Per 10 secondo[i], la prossima volta che ogni alleato a portata d\'orecchio utilizza un\'abilità d\'attacco, ottiene 1...8 Punto[i] Energia.','Canto. (Secondi: 10) Energia ottenuta dagli alleati a portata d\'orecchio con l\'abilità d\'attacco successiva: 1...8.'],
1562=>['Aria dello Zelo','Canto. Dura 10 secondo[i]; la prossima volta che ogni alleato a portata d\'orecchio utilizza una magia, ottiene 1...6 Punto[i] Energia.','Canto. (Secondi: 10) Energia ottenuta dagli alleati a portata d\'orecchio con la magia successiva: 1...6.'],
1563=>['Lirica dello Zelo','Canto. Per 10 secondo[i], la prossima volta che ogni alleato a portata d\'orecchio utilizza un Sigillo, ottiene 1...8 Punto[i] Energia.','Canto. (Secondi: 10) Energia ottenuta dagli alleati a portata d\'orecchio con il Sigillo successivo: 1...8.'],
1564=>['Ballata del Ripristino','Canto. Per 10 secondo[i], la prossima volta che ogni membro della squadra a portata d\'orecchio subisce danni, ottiene 15...75 Punto[i] Salute.','Canto. (Secondi: 10) Salute ottenuta dai membri della squadra a portata d\'orecchio la prossima volta che subiscono danni: 15...75.'],
1565=>['Coro del Ripristino','Canto. Per 10 secondo[i], la prossima volta che ogni alleato a portata d\'orecchio utilizza un urlo o un canto, viene curato di 30...90 Punto[i] Salute.','Canto. (Secondi: 10) Gli alleati a portata d\'orecchio vengono curati di 30...90 con il prossimo urlo o canto.'],
1566=>['Aria del Ripristino','Canto. Per 10 secondo[i], la prossima volta che ogni membro della squadra a portata d\'orecchio usa una magia, ottiene 30...90 Punto[i] Salute.','Canto. (Secondi: 10) Salute conseguita dai membri della squadra a portata d\'orecchio con la magia successiva: 30...90.'],
1567=>['Canzone della Concentrazione','Canto. Per 10 secondo[i] la prossima abilità utilizzata da ogni alleato a portata d\'orecchio non può essere interrotta.','Canto. (Secondi: 10) Gli alleati a portata d\'orecchio non possono subire interruzione della magia successiva.'],
1568=>['Inno della Guida','Canto d\'Élite. Per 10 secondo[i] la prossima abilità utilizzata da ogni membro della squadra a portata d\'orecchio non può essere bloccata.','Canto d\'Élite. (Secondi: 10) I membri della squadra a portata d\'orecchio non possono essere bloccati con l\'abilità d\'attacco successiva.'],
1569=>['Coro Energizzante','Canto. Dura 10 secondo[i]; il prossimo urlo o canto utilizzato da ogni alleato a portata d\'orecchio costa 3...7 Punto[i] Energia in meno.','Canto. (Secondi: 10) Riduzione costo energetico del prossimo canto o urlo per gli alleati a portata d\'orecchio: 3...7.'],
1570=>['Canzone della Purificazione','Canto d\'Élite. Per 20 secondo[i], ogni alleato a portata d\'orecchio con [il] [F]prossima[e] 1...6 abilità rimuove 1 condizione da se stesso.','Canto d\'Élite. (Secondi: 20) Gli alleati a portata d\'orecchio perdono una condizione con 1...6 abilità successiva[e].'],
1571=>['Aria Anti-Fattura','Canto. Per 10 secondo[i], la prossima volta che ogni alleato a portata d\'orecchio lancia una magia, quell\'alleato perde 1 fattura.','Canto. (Secondi: 10) Energia a portata d\'orecchio perdono una fattura con la magia successiva.'],
1572=>['"Preparatevi!"','Urlo. Per 5...15 secondi i colpi che provocherebbero l\'abbattimento dell\'alleato infliggeranno 15...75 danni a tutti i nemici nei dintorni.','Urlo. (Secondi: 5...15). Previene il prossimo abbattimento; assesta 15...75 danni a tutti i nemici vicino all\'obiettivo alleato. Impossibile selezionare se stessi.'],
1573=>['Soggezione','Abilità. Se quest\'abilità colpisce un nemico atterrato, questi resta stordito per 5...15 secondo/i.','Abilità. Condizione inflitta: Stordimento (5...15 secondo[i]). Ha effetto solo se l\'obiettivo è stato abbattuto.'],
1574=>['Armonia Permanente','Eco. Per 10...35 secondo[i] i canti e le urla durano un 50% in più sull\'obiettivo alleato (Spiriti esclusi).','Eco. (Secondi: 10...35) Incremento durata di canti e urla sull\'obiettivo alleato: 50%. Impossibile selezionare gli Spiriti.'],
1575=>['Finale Ardente','Eco. Dura 10...35 secondo[i]; ogni volta che un canto o un urlo termina sull\'obiettivo alleato (Spiriti esclusi) tutti i nemici adiacenti a quell\'alleato prendono fuoco per 1...7 secondo[i].','Eco. (Secondi: 10...35) Condizione inflitta ai nemici adiacenti ogni volta che un canto o urlo termina sull\'obiettivo alleato: Bruciatura (1...7 secondo[i]). Impossibile selezionare gli Spiriti.'],
1576=>['Ritornello Bruciante','Eco. Dura 20 secondo[i]; se l\'obiettivo alleato (Spiriti esclusi) colpisce un nemico che ha più Salute di lui, quel nemico prende fuoco per 1...3 secondo[i]. Questa eco si rinnova ogni volta che un canto o un urlo termina su quell\'alleato.','Eco. (Secondi: 20) Condizione inflitta se l\'obiettivo alleato colpisce un nemico con più Salute: Bruciatura (1...3 secondo[i]). Rinnovo: ogni volta che un canto o un urlo termina su quell\'alleato. Impossibile selezionare gli Spiriti.'],
1577=>['Finale del Ripristino','Eco. Per 10...35 secondi, ogni volta che un canto o un urlo termina sull\'obiettivo (un alleato o te stesso, Spiriti esclusi) questi viene curato di 15...75 Punti Salute.','Eco. (Secondi: 10...35). Punti Salute conseguiti dall\'obiettivo (un alleato o te stesso) ogni volta che un canto o un urlo termina su di lui: 15...75. Impossibile selezionare gli Spiriti.'],
1578=>['Ritornello Riparatore','Eco. Per 15 secondo[i], l\'obiettivo alleato (Spiriti esclusi) ha una Rigenerazione della Salute di +2...3. Questa eco si rinnova ogni volta che un canto o un urlo termina su quell\'alleato.','Eco. (Secondi: 15) Rigenerazione Salute dell\'obiettivo alleato: +2...3. Rinnovo: ogni volta che un canto o un urlo termina su quell\'alleato. Impossibile selezionare gli Spiriti.'],
1579=>['Finale Purificante','Eco. Per 10...35 secondo[i], l\'obiettivo alleato (Spiriti esclusi) perde 1 condizione ogni volta che un canto o un urlo termina su quell\'alleato.','Eco. (Secondi: 10...35) L\'obiettivo (un alleato o te stesso) si libera di una condizione ogni volta che un canto o un urlo termina su di lui. Impossibile selezionare gli Spiriti.'],
1580=>['Ritornello Ruotalama','Eco. Per 20 secondi l\'obiettivo alleato (spiriti esclusi) ha un 5...20% di probabilità di bloccare gli attacchi. Questa eco si rinnova ogni volta che un canto o un urlo finisce su quell\'alleato.','Eco. (Secondi: 20). L\'obiettivo alleato ha un 5...20% di probabilità di blocco. Rinnovo: ogni volta che un canto o un urlo termina su quell\'alleato. Impossibile selezionare gli spiriti.'],
1581=>['Sigillo Luminoso','Sigillo. Se l\'obiettivo nemico è affetto da Bruciatura ottieni 5...15 Punto[i] Energia.','Sigillo. Energia conseguita se l\'obiettivo nemico è affetto da Bruciatura: 5...15.'],
1583=>['Zelo del Condottiero','Abilità. Per ogni alleato nei dintorni ottieni 2...4 Punto[i] Energia (max. 8...12 Punto[i] Energia).','Abilità. Ottieni 2...4 Punto[i] Energia (max 8...12) per ogni alleato nei dintorni.'],
1584=>['Conforto del Leader','Abilità. Ottieni 30...75 Punto[i] Salute. Per ogni alleato a portata d\'orecchio ottieni anche +10...20 Punto[i] Salute (max. 140).','Abilità. Salute conseguita: 30...75. Salute aggiuntiva conseguita per ogni alleato presente a portata d\'orecchio: +10...20 (max 140).'],
1585=>['Sigillo della Sinergia','Sigillo. Curi l\'obiettivo di 40...100 Punto[i] Salute; se non sei affetto da un incantesimo vieni anche curato di 40...100 Punto[i] Salute.','Sigillo. Salute per l\'obiettivo (un alleato o te stesso): 40...100. Vieni curato anche di 40...100 se non sei sotto incantesimo. Impossibile selezionare se stessi.'],
1586=>['Protezione Angelica','Abilità. Dura 10 secondo[i]; ogni volta che l\'obiettivo alleato subisce più di 250...80 danno[i] al secondo, viene curato per qualsiasi danno superiore a tale quantità.','Abilità. (Secondi: 10) Ogni secondo in cui l\'obiettivo alleato subisce danni superiori a 250...80, l\'eccedenza si trasforma per lui in cure. Impossibile selezionare se stessi.'],
1587=>['Legame Angelico','Abilità d\'Élite. Per 10 secondo[i], la prossima volta che un alleato a portata d\'orecchio dovrebbe subire un danno fatale, quel danno si annulla e l\'alleato riceve 20...200 Punto[i] Salute. Il Legame Angelico termina su tutti gli altri alleati.','Abilità d\'Élite. (Secondi: 10) La prossima volta che un alleato a portata d\'orecchio dovrebbe subire un danno fatale, quel danno si annulla e l\'alleato riceve 20...200 di Salute. Termina su tutti gli altri alleati.'],
1588=>['Sigillo della Cauterizzazione','Sigillo d\'Élite. Tutti i membri in squadra perdono tutte le condizioni. Tu prendi fuoco per 1 secondo per ogni condizione rimossa in questo modo.','Sigillo d\'Élite. Tutti i membri della squadra si liberano di tutte le condizioni. Sei affetto da Bruciatura (un secondo per ogni condizione rimossa).'],
1589=>['"Non Muovetevi!"','Urlo. Per 5...20 secondo[i], tutti i membri della squadra a portata d\'orecchio ottengono +24 di armatura quando restano fermi.','Urlo. (Secondi: 5...20) Armatura dei membri della squadra quando restano fermi: +24.'],
1590=>['"Guidaci!"','Urlo. La velocità di movimento dell\'obiettivo (un alleato o te stesso) aumenta del 25%; questo urlo dura 1...5 secondo[i] per ogni alleato a portata d\'orecchio (max. 30 secondo[i]).','Urlo. Incremento della velocità di movimento dell\'obiettivo (un alleato o te stesso) per ogni alleato a portata d\'orecchio: 25% per 1...5 secondo[i] (max 30).'],
1591=>['"In fretta!"','Urlo. Per 5...20 secondo[i], la velocità di movimento dell\'obiettivo alleato aumenta del 33%. Questa abilità termina se un attacco di quell\'alleato va a segno.','Urlo. (Secondi: 5...20) Incremento velocità di movimento dell\'obiettivo: 33%. Termina se l\'obiettivo alleato colpisce con un attacco. Impossibile selezionare se stessi.'],
1592=>['"Torneremo!"','Urlo. Tutti i membri della squadra a portata d\'orecchio vengono resuscitati con un 25...50% di Salute e un 5...20% di Energia.','Urlo. Tutti i membri della squadra a portata d\'orecchio vengono resuscitati (25...50% di Salute e 5...20% di Energia).'],
1593=>['"Non Datevi per Vinti!"','Urlo. Tutti gli alleati a portata d\'orecchio con Salute inferiore al 75% ottengono 1...10 Punto[i] Energia.','Urlo. Energia per gli alleati a portata d\'orecchio: 1...10. Ha effetto solo sugli alleati con Salute inferiore a 75%.'],
1594=>['"Aiuto!"','Urlo. Il bersaglio alleato (purché non sia uno spirito) ottiene 15...90 Salute. Per 1...10 secondo/i, le magie degli altri alleati indirizzate su quel personaggio vengono lanciate il 50% più velocemente.','Urlo. (1...10 secondo/i). Il bersaglio alleato non spirito ottiene 15...90 Salute, le magie degli altri alleati indirizzate su quel personaggio vengono lanciate il 50% più velocemente.'],
1595=>['"Ripieghiamo!"','Urlo. Per 4...10 secondo[i], tutti gli alleati a portata d\'orecchio ottengono 5...15 Punto[i] Salute al secondo mentre si muovono e la loro velocità di movimento aumenta del 33%. Questa abilità termina su un alleato affetto da questo urlo se questi mette a segno un attacco.','Urlo. (Secondi: 4...10) Salute ottenuta dagli alleati a portata d\'orecchio al secondo mentre si muovono: 5...15; incremento della loro velocità: 33%. Termina per un alleato se un suo attacco va a segno.'],
1596=>['"Arrivano!"','Urlo d\'Élite. Per 4...10 secondi la velocità di movimento di tutti gli alleati a portata d\'orecchio aumenta di un 33% e tali alleati ottengono 5...15 Punti Salute al secondo mentre si muovono.','Urlo d\'Élite. (Secondi: 4...10). Incremento velocità di movimento di tutti gli alleati a portata d\'orecchio: 33%. Punti Salute al secondo ottenuti in movimento: 5...15.'],
1597=>['"Bruciano!"','Urlo. Per 10 secondo[i], i membri della squadra a portata d\'orecchio subiscono 5...35% danno[i] in meno dai nemici che soffrono di Bruciatura.','Urlo. (Secondi: 10) Riduzione dei danni assestati dai nemici che soffrono di Bruciatura e subiti dai membri della squadra a portata d\'orecchio: 5...35%.'],
1598=>['"Mai Arrendersi!"','Urlo. Per 15 secondo[i], tutti i membri della squadra a portata d\'orecchio con Salute inferiore al 75% ottengono una Rigenerazione della Salute di +1...5.','Urlo. (Secondi: 15) Rigenerazione Salute dei membri della squadra a portata d\'orecchio: +1...5. Ha effetto solo sui membri della squadra con Salute inferiore a 75%.'],
1599=>['È Solo una Ferita Superficiale.','Urlo d\'Élite. L\'obiettivo alleato perde tutte le condizioni. Se una condizione viene rimossa in questo modo, la velocità di quell\'alleato aumenta di un 25% per 1...10 secondo[i].','Urlo d\'Élite. Rimuove tutte le condizioni dall\'obiettivo alleato. Incremento velocità di movimento dell\'alleato se viene rimossa una condizione: 25% (1...10 secondo[i]). Impossibile selezionare se stessi.'],
1600=>['Lancia Appuntita','Attacco con Lancia. Se questo attacco va a segno, l\'obiettivo inizia a sanguinare per 5...20 secondo[i].','Attacco con Lancia. Condizione inflitta: Emorragia (5...20 secondo[i]).'],
1601=>['Attacco Dispettoso','Attacco con Lancia. Se questo attacco va a segno, infliggi +5...20 danno[i]; se si rivela critico, l\'obiettivo nemico subisce una Ferita Profonda per 5...15 secondo[i].','Attacco con Lancia. Danni inferti: +5...20. Condizione inflitta con un colpo critico: Ferita Profonda (5...15 secondo[i]).'],
1602=>['Colpo Stordente','Attacco d\'Élite con Lancia. Se questo attacco va a segno, infliggi +10...50 danno[i]; se colpisce un nemico affetto da una condizione lo stordisce anche per 4...10 secondo[i].','Attacco d\'Élite con Lancia. Danni inferti: +10...50. Condizione inflitta se l\'obiettivo soffre di una condizione: Stordimento (4...10 secondo[i]).'],
1603=>['Lancia Implacabile','Attacco con Lancia. Se questo attacco colpisce un nemico con Salute inferiore al 50%, questi è affetto da una Ferita Profonda per 5...20 secondo[i].','Attacco con Lancia. Condizione inflitta: Ferita Profonda (5...20 secondo[i]). Ha effetto solo se la Salute dell\'obiettivo è inferiore a 50%.'],
1604=>['Lancio Dirompente','Attacco con Lancia. Se questo attacco colpisce un nemico affetto da una condizione lo interrompe.','Attacco con Lancia. Interrompe le azioni. Ha effetto solo se l\'obiettivo soffre di una condizione.'],
1605=>['Lancio Selvaggio','Attacco con Lancia. Se questo attacco va a segno, infligge +5...20 danni e fa terminare qualsiasi posizione utilizzata dal tuo obiettivo. Questo attacco non può essere bloccato. Tutte le tue altre abilità non legate agli attacchi con la lancia vengono disattivate per 3 secondi.','Attacco con Lancia. Danno: +5...20. Non bloccabile. Fa terminare la posizione assunta dall\'obiettivo.Disattiva le abilità non legate agli attacchi con la lancia per 3 secondi.'],
1633=>['Colpo Maligno','Attacco Ravvicinato. Se questo attacco va a segno su un nemico affetto da una condizione gli infliggi +10...30 danno[i] e l\'attacco diventa un colpo critico.','Attacco Ravvicinato. Se l\'obiettivo nemico è affetto da una condizione, questo attacco assesta +10...30 danno[i] e risulta in un colpo critico.'],
1634=>['Assalto Frantumante','Attacco Doppio[_] d\'Élite. Deve seguire un attacco con arma secondaria. Se va a segno, infliggi 5...50 danno[i] e l\'obiettivo nemico perde un incantesimo. Questo attacco non può essere bloccato.','Attacco Doppio[_] d\'Élite. Danni inferti: 5...50. Rimuove un incantesimo. Non bloccabile. Deve seguire un attacco con arma secondaria.'],
1635=>['Colpo del Teschio Dorato','Attacco d\'Élite con Arma Secondaria. Se ti trovi sotto gli effetti di un incantesimo e questo attacco va a segno, l\'obiettivo nemico viene stordito per 1...12 secondo[i].','Attacco d\'Élite con Arma Secondaria. Condizione inflitta: Stordimento (1...12 secondo[i]). Ha effetto solo se sei sotto incantesimo.'],
1636=>['Colpo del Ragno Nero','Attacco con Arma Secondaria. Deve colpire un avversario sotto fattura. Se va a segno, questo attacco infligge +5...20 danno[i] e l\'obiettivo nemico viene avvelenato per 5...20 secondo[i].','Attacco con Arma Secondaria. Danni inferti: +5...20. Condizione inflitta: Veleno (5...20 secondo[i]). Deve colpire un nemico sotto fattura.'],
1637=>['Colpo della Volpe Dorata','Attacco con Arma Primaria. Se questo attacco va a segno, l\'obiettivo nemico subisce +10...30 danno[i]. Se ti trovi sotto gli effetti di un incantesimo, questo attacco non può essere bloccato.','Attacco con Arma Primaria. Danni inferti: +10...30. Non bloccabile se sei sotto incantesimo.'],
1638=>['Fretta Letale','Incantesimo. Per 10...35 secondo[i], le magie con metà della portata normale hanno un tempo di lancio superiore del 5...50% e si ricaricano con una velocità superiore del 5...60%.','Incantesimo. (Secondi: 10...35) Le tue magie con metà della portata normale hanno un tempo di lancio superiore del 5...50% e si ricaricano con una velocità superiore del 5...60%.'],
1639=>['Rimedio dell\'Assassino','Incantesimo. Per 30 secondo[i], con [il] 1...10 [F]abilità d\'attacco successiva[e] usata[e] rimuovi una condizione.','Incantesimo. (Secondi: 30) 1...10 abilità d\'attacco che usi in seguito rimuovono una condizione.'],
1640=>['Promessa della Volpe','Incantesimo d\'Élite. Per 5...20 secondo[i], i tuoi attacchi con pugnali non possono essere bloccati; questo incantesimo termina la prossima volta che un tuo attacco va a vuoto.','Incantesimo d\'Élite. (Secondi: 5...20) I tuoi attacchi con pugnali non sono bloccabili. Termina la prossima volta che manchi l\'obiettivo.'],
1641=>['Neutralità Simulata','Incantesimo. Per 4...10 secondo[i], hai una Rigenerazione della Salute di +7 e +80 di armatura. Questo incantesimo termina se metti a segno un attacco o utilizzi un\'abilità.','Incantesimo. (Secondi: 4...10) Rigenerazione Salute: +7. Armatura: +80. Termina se colpisci con un tuo attacco o usi un\'abilità.'],
1642=>['Triboli Nascosti','Fattura d\'Élite. Non puoi usare le tue abilità per 3 secondi (escluse quelle da Assassino). Per 1...10 secondo/i, il bersaglio nemico si muove più lento del 50%. Quando la fattura finisce, il nemico resta Azzoppato per 1...15 secondo/i.','Fattura d\'Élite. (Secondi: 1...10) Rallentamento movimenti: 50%. Effetto al termine: infligge Storpiatura (1...15 secondo[i]). Le tue abilità non da Assassino vengono disattivate (10 secondi).'],
1643=>['Assalta Incantesimi','Abilità d\'Élite. Deve seguire un attacco doppio. L\'obiettivo nemico perde tutti gli incantesimi.','Abilità d\'Élite. Rimuove tutti gli incantesimi. Deve seguire un attacco doppio.'],
1644=>['Crollo del Fannullone','Abilità d\'Élite. Compi un Passo dell\'Ombra verso l\'obiettivo nemico che, se non sta usando alcuna abilità, viene abbattuto. Tutte le tue abilità d\'attacco che non utilizzano i pugnali vengono disattivate per 10 secondo[i].','Abilità d\'Élite. Compi un Passo nell\'Ombra verso l\'obiettivo nemico. Provochi abbattimento se non sta usando abilità. Disattiva le tue abilità d\'attacco che non utilizzano i pugnali (10 secondo[i]).'],
1645=>['Leva Incantesimo','Abilità. Se l\'obiettivo nemico toccato è in terra perde un incantesimo.','Abilità a Tocco. Rimuove un incantesimo. Ha effetto solo se l\'obiettivo nemico viene abbattuto.'],
1646=>['Presagio di Morte','Fattura. Dura 5...35 secondo[i]; la prossima volta che il danno farebbe calare la Salute dell\'obiettivo nemico al di sotto del 50%, infliggi una Ferita Profonda per 5...20 secondo[i] e compi un Passo nell\'Ombra verso quel nemico. La portata di questa magia è la metà del normale.','Fattura a Portata Dimezzata. (Secondi: 5...35) Condizione inflitta: Ferita Profonda (5...20 secondo[i]); compi un Passo nell\'Ombra verso l\'obiettivo nemico la prossima volta che il danno farebbe calare la sua Salute al di sotto del 50%.'],
1647=>['Sigillo dello Shock Tossico','Sigillo. Se l\'obiettivo nemico soffre di avvelenamento, subisce 10...100 danno[i].','Sigillo. Danni inferti: 10...100. Ha effetto solo se l\'obiettivo nemico è affetto da Veleno.'],
1648=>['Sigillo del Tramonto','Sigillo. Il nemico perde un incantesimo per ogni fattura presente su di lui.','Sigillo. Rimuove un incantesimo per ogni fattura presente sull\'obiettivo nemico.'],
1649=>['Potere dell\'Assassino','Posizione d\'Élite. Per 20 secondo[i] successivo[i], mentre brandisci i pugnali, la tua velocità d\'attacco aumenta di un 5...20% e hai +5...35% di probabilità di assestare un colpo critico.','Posizione d\'Élite. (Secondi: 20) Aumento tua velocità d\'attacco mentre brandisci i pugnali: 5...20%. Probabilità di mettere a segno un colpo critico: +5...35%.'],
1650=>['Passeggiata dell\'Ombra','Posizione. Compi un Passo nell\'Ombra verso l\'obiettivo nemico. Per 15 secondi non si verificano effetti. Le tue abilità vengono disattivate per 1 secondo e i tuoi incantesimi e le tue posizioni vengono disattivati per 10 secondi. Quando questa posizione termina ritorni al punto di partenza.','Posizione. (Secondi: 15). Compi un Passo nell\'Ombra verso l\'obiettivo nemico. Effetto al termine: torni nella posizione di partenza. Disattiva le tue abilità d\'attacco per 1 secondo. Disattiva i tuoi incantesimi e le tue posizioni per 10 secondi.'],
1651=>['Ritirata della Morte','Magia. Compi un Passo nell\'Ombra verso l\'obiettivo alleato e se hai meno Salute di lui, ti curi di 40...130 Punto[i] Salute.','Magia. Salute: 40...130 se ne hai meno dell\'obiettivo alleato. Effetto iniziale: compi un Passo nell\'Ombra verso questo alleato. Impossibile selezionare se stessi.'],
1652=>['Prigione d\'Ombra','Fattura d\'Élite. Compi un Passo nell\'Ombra verso l\'obiettivo nemico; per 1...7 secondo[i] la sua velocità rallenta del 66%.','Fattura d\'Élite. Compi un Passo nell\'Ombra verso l\'obiettivo nemico. Rallentamento suoi movimenti: 66% (1...7 secondo[i]).'],
1653=>['Scambio','Magia. Tu e la creatura evocata presa di mira effettuate un Passo nell\'Ombra scambiandovi di posto.','Magia. Tu e la creatura evocata presa di mira effettuate un Passo nell\'Ombra scambiandovi di posto.'],
1654=>['Fusione con l\'Ombra','Incantesimo d\'Élite. Compi un Passo nell\'Ombra verso l\'obiettivo alleato. Quando smetti di mantenere questo incantesimo torni nella posizione iniziale.','Incantesimo d\'Élite. Compi un Passo nell\'Ombra verso l\'obiettivo alleato. Effetto al termine: torni nel punto di partenza. Impossibile selezionare se stessi.'],
1655=>['Prezzo dell\'Orgoglio','Fattura. Per 5 secondo[i], la prossima volta che l\'obiettivo nemico utilizza un\'abilità d\'élite perde 3...15 Punto[i] Energia.','Fattura. (Secondi: 5) Provoca una perdita di 3...15 Punto[i] Energia la prossima volta che l\'obiettivo nemico usa un\'abilità d\'élite.'],
1656=>['Aria del Disincanto','Fattura d\'Élite. Rimuovi un incantesimo dall\'obiettivo nemico e tutti i nemici nei dintorni. Per 5...20 secondo[i] gli incantesimi su questi nemici durano un 150...300% in meno.','Fattura d\'Élite. Infligge fattura anche ai nemici vicini al tuo obiettivo (5...20 secondo[i]). Rimuovi un incantesimo dall\'obiettivo e dai nemici nei dintorni. Incremento velocità di esaurimento degli incantesimi su questi nemici: 150...300%.'],
1657=>['Sigillo della Goffaggine','Sigillo. Se l\'obiettivo nemico sta attaccando, lui e tutti i nemici nei dintorni vengono interrotti e subiscono 15...60 danni. Tutti i nemici che utilizzano abilità d\'attacco finiscono a terra.','Sigillo. Interrompe un attacco dell\'obiettivo nemico e di tutti i nemici adiacenti. Effetto dell\'interruzione: infligge 15...60 danni e fa finire a terra i nemici che hanno attivato abilità d\'attacco.'],
1658=>['Postura Simbolica','Posizione. Per 5...20 secondo[i] il prossimo Sigillo da te attivato si ricarica ad una velocità maggiore del 20...80%.','Posizione. (Secondi: 5...20) Incremento velocità di ricarica del prossimo Sigillo: 20...80%.'],
1659=>['Freddo Tossico','Magia d\'Élite. L\'obiettivo nemico subisce 15...75 danno[i] da freddo; se è affetto da fattura o incantesimo viene avvelenato per 10...25 secondo[i].','Magia d\'Élite. Danni da freddo inferti: 15...75. Condizione inflitta se l\'obiettivo nemico è sotto fattura o incantesimo: Veleno (10...25 secondo[i]).'],
1660=>['Pozzo del Silenzio','Pozzo. Sfrutta il cadavere bersagliato o sacrifica il 66% della tua salute per creare un Pozzo del Silenzio per 10...30 secondo/i. I nemici all\'interno dell\'area del pozzo non possono usare urla o canti e soffrono -1...4 degenerazione della salute.','Pozzo. (10...30 secondo/i). I nemici in questo Pozzo non possono usare urla e canti e hanno -1...4 degenerazione della Salute. Utilizza un cadavere fresco o sacrifica il 66% della Salute.'],
1661=>['Pietra Fluorescente','Magia. Lanci un proiettile che infligge 5...50 danni da fuoco se va a segno. Se questa magia colpisce un nemico indebolito ottieni 5 Punti Energia e 1 Punto Energia per ogni 2 gradi della Riserva di Energia.','Magia. Proiettile: infligge 5...50 danni da terra. Energia conseguita se l\'obiettivo nemico è affetto da Debolezza: 5 più 1 per ogni 2 gradi della Riserva di Energia.'],
1662=>['Esplosione Mentale','Magia d\'Élite. L\'obiettivo nemico subisce 15...60 danni da fuoco. Se la tua Energia è superiore a quella dell\'obiettivo nemico, ottieni 1...8 Punti Energia.','Magia d\'Élite. Danni da fuoco inferti: 15...60. Se hai più Energia dell\'obiettivo nemico, ottieni 1...8 Punti Energia.'],
1663=>['Fiamma Elementale','Incantesimo. Per 10...35 secondi, ogni volta che una fattura Elementale termina sull\'obiettivo nemico, questi prende fuoco per 1...5 secondi.','Incantesimo. (Secondi: 10...35.) Condizione inflitta ogni volta che una fattura Elementale viene applicata all\'obiettivo nemico: Bruciatura (secondi: 1...5).'],
1664=>['Invoca Fulmine','Magia d\'Élite. L\'obiettivo nemico e un massimo di altri due nemici accanto a lui subiscono 10...90 danni da fulmine. Questa magia ha una penetrazione dell\'armatura del 25%.','Magia d\'Élite. Danni da fulmine inferti: 10...90. Colpisce due nemici vicini all\'obiettivo. Penetrazione armatura: 25%.'],
1683=>['Guardiano Pensoso','Incantesimo. Per 5...11 secondo[i], l\'obiettivo (un alleato o te stesso) ha una probabilità del 50% di bloccare gli attacchi dei nemici sotto incantesimo.','Incantesimo. (Secondi: 5...11) Probabilità di bloccare i nemici sotto incantesimo: 50%.'],
1684=>['Intuito dello Scriba','Incantesimo d\'Élite. Per 10...35 secondo[i], ogni volta che utilizzi un Sigillo ottieni 3 Punto[i] Energia.','Incantesimo d\'Élite. (Secondi: 10...35) Energia conseguita ogni volta che usi un Sigillo: 3.'],
1685=>['Fretta Sacra','Incantesimo. Per 1...60 secondo[i] la tua velocità di lancio delle magie associate alle Preghiere Curative aumenta di un 50%. Questo incantesimo termina se lanci un altro incantesimo.','Incantesimo. (Secondi: 1...60) Incremento velocità di lancio delle tue magie attribuite a Preghiere Curative: 50%. Termina se lanci un incantesimo.'],
1686=>['Barlume di Luce','Magia d\'Élite. Curi l\'obiettivo (un alleato o te stesso) di 10...115 Punto[i] Salute.','Magia d\'Élite. Cure: 10...115.'],
1687=>['Benedizione Zelante','Magia d\'Élite. Curi l\'obiettivo (un alleato o te stesso) di 30...180 Punto[i] Salute; se la Salute dell\'obiettivo era inferiore al 50% ottieni 7 Punto[i] Energia.','Magia d\'Élite. Cure: 30...180. Energia conseguita se la Salute dell\'obiettivo (un alleato o te stesso) è inferiore al 50%: 7.'],
1688=>['Zelo del Difensore','Fattura d\'Élite. Per 10...30 secondo[i], ogni volta che un attacco dell\'obiettivo nemico va a segno, ottieni 2 Punto[i] Energia.','Fattura d\'Élite. (Secondi: 10...30) Energia conseguita ogni volta che l\'obiettivo nemico colpisce con un attacco: 2.'],
1689=>['Sigillo della Collera Mistica','Sigillo. L\'obiettivo nemico subisce 25 danno[i] sacro[i] per ogni incantesimo presente su di te (max. 30...120 danno[i] sacro[i]).','Sigillo. Danni sacri inferti per ogni incantesimo su di te: 25 (max 30...120).'],
1690=>['Sigillo della Rimozione','Sigillo d\'Élite. Se l\'obiettivo alleato è sotto gli effetti di un incantesimo, perde una fattura e una condizione.','Sigillo d\'Élite. Rimuove una fattura e una condizione. Ha effetto solo se l\'obiettivo alleato è sotto incantesimo.'],
1691=>['Congeda Condizione','Magia. Rimuovi una condizione dall\'obiettivo alleato; se quell\'alleato è sotto gli effetti di un incantesimo viene curato di 15...75 Punto[i] Salute.','Magia. Rimuove una condizione. Cura di 15...75 se l\'obiettivo alleato è sotto incantesimo.'],
1692=>['Diversione Fatture','Magia d\'Élite. Elimini fino a 1...3 fattura[e] dall\'obiettivo alleato. Per ogni fattura così rimossa, quell\'alleato perde una condizione ed ottiene 15...75 Punto[i] Salute.','Magia d\'Élite. Fatture rimosse: 1...3. Per ogni fattura rimossa, l\'obiettivo alleato perde una condizione ed ottiene 15...75 Punto[i] Salute.'],
1693=>['Contrattacco','Attacco Ravvicinato. Se questo attacco va a segno, infliggi +5...35 danno[i]. Se colpisci un nemico che sta attaccando ottieni 2...6 Punto[i] Energia.','Attacco Ravvicinato. Danni inferti: +5...35. Energia conseguita se l\'obiettivo nemico sta attaccando: 2...6.'],
1694=>['Colpo Cacciamaghi','Attacco d\'Élite Ravvicinato. Se questo attacco colpisce, infliggi +7...25 danno[i]; se l\'obiettivo è affetto da un incantesimo, questo attacco non può essere bloccato.','Attacco d\'Élite Ravvicinato. Danni inferti: +7...25. Non bloccabile se l\'obiettivo nemico è sotto incantesimo.'],
1695=>['Colpo del Soldato','Attacco Ravvicinato. Se questo attacco colpisce, infliggi +10...40 danno[i]; se sei sotto gli effetti di un canto o un urlo, questo attacco non può essere bloccato.','Attacco Ravvicinato. Danni inferti: +10...40. Non bloccabile se sei affetto da un urlo o un canto.'],
1696=>['Decapitazione','Attacco d\'Élite con Ascia. You lose all adrenaline and all Energy. This attack is unblockable, you deal +5...80 damage, and cause a Deep Wound for 5...20 seconds. This attack is always critical and if foe is killed, nearby foes are Weakened for 8 seconds.','Attacco d\'Élite con Ascia. Deals +5...80 damage. Inflicts Deep Wound condition (5...20 seconds). Automatic critical hit. If foe is killed, nearby foes are Weakened (8 seconds). You lose all adrenaline and Energy.'],
1697=>['Percossa Cacciamaghi','Attacco d\'Élite con Martello. Se questo attacco colpisce, l\'obiettivo nemico viene abbattuto; se è affetto da un incantesimo, questo attacco non può essere bloccato.','Attacco d\'Élite con Martello. Provoca abbattimento. Non bloccabile se l\'obiettivo nemico è sotto incantesimo.'],
1698=>['Posizione del Soldato','Posizione d\'Élite. Per 5...15 secondo[i] hai un 75% di probabilità di bloccare gli attacchi. Incremento velocità d\'attacco mentre sei sotto gli effetti di un urlo o un canto: 33%.','Posizione d\'Élite. (Secondo[i]: 5...15). Probabilità di blocco: 75%. Incremento velocità d\'attacco mentre sei sotto gli effetti di un urlo o un canto: 33%.'],
1699=>['Difesa del Soldato','Posizione. Per 1...6 secondo[i], hai un 75% di probabilità di bloccare gli attacchi mentre sei sotto l\'influenza di un urlo o un canto. Ottieni 1 dose di adrenalina per ogni attacco bloccato.','Posizione. (Secondo[i]: 1...6). Incremento velocità d\'attacco mentre sei sotto gli effetti di un urlo o un canto: 75%. Effetto del blocco: ottieni 1 dose di adrenalina.'],
1700=>['Difesa Frenetica','Posizione. Per 8 secondo[i] hai un 75% di probabilità di bloccare gli attacchi diretti contro di te ma subisci il doppio dei danni.','Posizione. (Secondi: 8) Tua probabilità di blocco: 75%. Subisci il doppio dei danni.'],
1701=>['Posizione Salda','Posizione d\'Élite. Dura 10 secondi. La prossima volta che un avversario cercherà di abbatterti, non potrà farlo e otterrai 1...4 dosi di Adrenalina e 1...7 Punti Energia.','Posizione d\'Élite. (Secondi: 10) La prossima volta che saresti abbattuto ottieni 1...4 dose[i] di adrenalina e 1...7 di Energia.'],
1702=>['Fendente Zanna d\'Acciaio','Attacco con Spada. Se questo attacco va a segno, infliggi +1...31 danno[i]; se colpisci un nemico in terra, ottieni 1...5 dose[i] di Adrenalina.','Attacco con Spada. Danni inferti: +1...31. Adrenalina conseguita se l\'obiettivo nemico è stato abbattuto: 1...5.'],
1719=>['Tiro Urlante','Attacco con Arco. Se va a segno infliggi +10...25 danno[i]; se il tuo obiettivo è a portata d\'orecchio, inizia a sanguinare per 5...20 secondo[i].','Attacco con Arco. Danni inferti: +10...25. Condizione inflitta se l\'obiettivo nemico è a portata d\'orecchio: Emorragia (5...20 secondo[i]).'],
1720=>['Freccia Affilata','Attacco con Arco. Se questo attacco va a segno, infliggi +5...20 danno[i]; se metti a segno un attacco critico infliggi anche +5...25 danno[i].','Attacco con Arco. Danni inferti: +5...20. Assesta +5...25 danno[i] in più se metti a segno un colpo critico.'],
1721=>['Furore Congiunto','Abilità d\'Élite. Per 3...15 secondo[i], tu e la tua mascotte attaccate ad una velocità maggiore del 33% e la vostra velocità di movimento aumenta di un 25%.','Abilità d\'Élite. (Secondi: 3...15) Incremento velocità d\'attacco tua e della mascotte: 33%; incremento velocità di movimento: 25%. Ha effetto solo se la tua mascotte è viva.'],
1722=>['Freccia Forcuta','Attacco con Arco. Scocca due frecce simultaneamente contro l\'obiettivo nemico. Se ti trovi sotto gli effetti di un incantesimo o di una fattura lancerai solo una freccia.','Attacco con Arco. Scocchi due frecce simultanee. Ne scocchi solo una se sei sotto incantesimo o fattura..'],
1723=>['Accuratezza Dirompente','Preparazione. Per 36 secondo[i], ogni volta che una delle tue frecce provoca un colpo critico interrompe anche l\'obiettivo.','Preparazione. (Secondi: 36) Interrompe un\'azione ogni volta che le tue frecce sono critiche.'],
1724=>['Destrezza dell\'Esperto','Posizione d\'Élite. Per 1...20 secondo[i] hai una velocità d\'attacco superiore di un 33% e il grado dell\'attributo Precisione aumenta di 2.','Posizione d\'Élite. (Secondi: 1...20) Aumento tua velocità d\'attacco: 33%. Incremento grado dell\'attributo Precisione: +2.'],
1725=>['Venti Impetuosi','Rituale della Natura. Crei uno Spirito di livello 1...10. I canti e le urla costano 1...5 Punto[i] Energia in più. Lo Spirito si esaurisce dopo 30...180 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 30...180 secondo[i]). Incremento del costo energetico di canti e urla per le creature nella portata: 1...5.'],
1726=>['Tiro Rovinamaghi','Attacco con Arco d\'Élite. Se questo attacco va a segno, interrompe l\'azione dell\'obiettivo nemico; se interrompe una magia, la disattiva per 10 secondo[i] in più. Questo attacco non può essere bloccato.','Attacco con Arco d\'Élite. Interrompe un\'azione. Effetto dell\'interruzione: una magia interrotta viene disattivata per +10 secondo[i]. Non bloccabile.'],
1727=>['Falcata Naturale','Posizione. Per 1...8 secondo[i], la tua velocità di corsa aumenta di un 33% e hai un 50% di probabilità di bloccare gli attacchi in arrivo. La Falcata Naturale termina se sei colpito da fattura o incantesimo.','Posizione. (Secondi: 1...8) Incremento tua velocità di movimento: 33%. Probabilità di blocco: 50%. Termina se sei affetto da fattura o incantesimo.'],
1728=>['Furore dell\'Ecate','Posizione. Per 5...11 secondo[i] la velocità dei tuoi attacchi aumenta di un 33%; questa posizione termina se utilizzi un\'abilità d\'attacco.','Posizione. (Secondi: 5...11) Incremento tua velocità d\'attacco: 33%. Termina se usi un\'abilità d\'attacco.'],
1729=>['Trappola di Fumo','Trappola d\'Élite. Quando Trappola fumogena viene attivata, i nemici nell\'area restano accecati e storditi per 5...10 secondo/i. Trappola fumogena termina dopo 90 secondi. Mentre attivi questa abilità puoi essere interrotto facilmente.','Trappola d\'Élite. (90 secondi). Infligge le condizioni accecato e stordito (5...10 secondo/i) ai nemici nell\'area. Si può interrompere facilmente.'],
1730=>['Calore Infuriante','Rituale della Natura d\'Élite. Crei uno Spirito di livello 1...10. Le creature nella sua portata (Spiriti esclusi) ottengono Adrenalina a velocità doppia. Lo Spirito si esaurisce dopo 30...120 secondo[i].','Rituale della Natura d\'Élite. Crei uno Spirito di livello 1...10 (in vita per 30...120 secondo[i]). Raddoppia l\'adrenalina conseguita dalle creature nella portata.'],
1731=>['Sogolon era Sonoro','Magia Altera-oggetto. Per 60 secondo[i] tutte le urla e i canti che usi durano un 20...50% in più.','Magia Altera-oggetto. (Secondi: 60) Incremento durata dei tuoi canti e urla: 20...50%.'],
1732=>['Glaive era Distruttiva','Magia d\'Élite Altera-oggetto. Mantieni le ceneri di Glaive per un massimo di 30...60 secondo[i]. Mentre mantieni le ceneri di Glaive, tutte le abilità Ritualista ricevono 20% di penetrazione armatura. Quando rilasci le ceneri, tutti i nemici nell\'area subiscono 15...85 danno[i] da fulmine.','Magia d\'Élite Altera-oggetto. (Secondo[i]: 30...60). Le tue abilità Ritualista aumentano di 20% di penetrazione armatura. Rilascio: Danni da fulmine inferti a tutti i nemici nell\'area: 15...85.'],
1733=>['Colpo del Portatore','Magia. L\'obiettivo nemico subisce 10...60 danno[i] da fulmine. Se sei affetto da una magia altera-arma infliggi 10...50 danno[i] da fulmine in più.','Magia. Danni da fulmine inferti: 10...60. Assesta 10...50 danno[i] da fulmine in più se sei sotto gli effetti di una magia altera-arma.'],
1734=>['Sguardo della Furia','Rituale Incatenante. Distruggi lo Spirito preso di mira e crei un Spirito della Furia di livello 1...14 i cui attacchi infliggono 5...20 danno[i]. Lo Spirito si esaurisce dopo 30...60 secondo[i].','Rituale Incatenante. Annienta uno Spirito. Crei uno Spirito di livello 1...14 (in vita per 30...60 secondo[i]). Danni inferti dai suoi attacchi: 5...20.'],
1736=>['Forza dello Spirito','Incantesimo d\'Élite. Per 15...60 secondo[i], i tuoi attacchi infliggono 5...35 danno[i] in più mentre sei sotto l\'influenza di una magia altera-arma.','Incantesimo d\'Élite. (Secondi: 15...60) I tuoi attacchi assestano +5...35 danno[i] se sei sotto gli effetti di una magia altera-arma.'],
1737=>['Zelo del Portatore','Incantesimo d\'Élite. Dura 10...40 secondo[i]; ogni volta che lanci una magia altera-arma su un alleato ottieni 1...5 Punto[i] Energia.','Incantesimo d\'Élite. (Secondi: 10...40) Energia conseguita ogni volta che lanci una magia altera-arma: 1...5.'],
1738=>['Vista Oltre la Vista','Incantesimo. Per 8...20 secondo[i] non puoi essere accecato.','Incantesimo. (Secondi: 8...20) Sei immune dall\'Accecamento.'],
1739=>['Rinnovamento dei Ricordi','Incantesimo. Per 5...20 secondo[i], mentre hai in mano un oggetto, qualsiasi magia altera-arma o altera-oggetto da te lanciata costa un 5...35% in meno di Energia.','Incantesimo. (Secondi: 5...20) Riduzione del costo energetico delle magia altera-arma e altera-oggetti: 5...35%. Ha effetto solo se hai in mano un oggetto.'],
1740=>['Rimedio del Portatore','Incantesimo. Per 10...30 secondo/i, quando lanci un incantesimo sulle armi di un alleato, questi perde 2 condizioni.','Incantesimo. (10...30 secondo/i). Quando lanci una magia sulle armi di un alleato, questi perde due condizioni.'],
1741=>['Luce dello Specchio Fantasma','Magia. L\'obiettivo alleato viene curato di 15...90 Punto[i] Salute; se ti trovi a portata d\'orecchio di uno Spirito, anche tu vieni curato di 15...90 Punto[i] Salute.','Magia. Cure: 15...90. Ottieni 15...90 Punto[i] Salute se ti trovi nella portata d\'orecchio di uno Spirito. Impossibile selezionare se stessi.'],
1742=>['Sigillo della Potenza Spettrale','Sigillo d\'Élite. Per 5...20 secondo[i] tutti gli Spiriti a portata d\'orecchio sotto il tuo controllo attaccano a velocità superiore di un 33% e assestano +5...10 danno[i].','Sigillo d\'Élite. (Secondi: 5...20) Incremento velocità d\'attacco di tutti gli Spiriti a portata d\'orecchio sotto il tuo controllo: 33%. Danni da loro assestati: +5...10.'],
1743=>['Sigillo di Incatenamento','Sigillo. Perdi 200...50 Punti Salute e ottieni il controllo dello Spirito del nemico. (50% di probabilità di fallimento con Riti Sacrificali di grado 4 o inferiore).','Sigillo. Punti salute persi: 200...50. Ottieni il controllo dello Spirito del nemico. <c x="SkillDull">Probabilità di fallimento se il grado di Riti Sacrificali è inferiore a 5: 50%.'],
1744=>['Carica del Custode','Magia d\'Élite. L\'obiettivo nemico subisce 20...85 danno[i] da fulmine; se hai tra le mani un oggetto ottieni 7 Punti Energia e 5...50 Punto[i] Salute.','Magia d\'Élite. Danni da fulmine inferti: 20...85. Ottieni 7 Punto[i] Energia e 5...50 di Salute se hai in mano un oggetto.'],
1745=>['Angoscia','Rituale Incatenante. Crei uno Spirito di livello 1...11 i cui attacchi infliggono 5...20 danno[i] e il doppio del danno ai nemici sotto fattura. Lo Spirito si esaurisce dopo 15...45 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...11 (in vita per 15...45 secondo[i]). Danni inferti dai suoi attacchi: 5...20. Danno doppio ai nemici affetti da fattura.'],
1747=>['Autorizzazione','Rituale Incatenante. Crei uno Spirito di livello 1...14. Tutti gli alleati nella sua portata che hanno in mano un oggetto ottengono 15...45 Punto[i] di Salute massima e 10 di Energia massima. Questo Spirito si esaurisce dopo 15...60 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...14 (in vita per 15...60 secondo[i]). Gli alleati nella portata con in mano un oggetto ottengono 15...45 di Salute massima e 10 di Energia massima.'],
1748=>['Ripresa','Rituale Incatenante. Crei uno Spirito di livello 1...14. Le condizioni che affliggono gli alleati nella portata di questo Spirito si esauriscono ad una velocità maggiore del 20...50%. Lo Spirito si esaurisce dopo 30...60 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...14 (in vita per 30...60 secondo[i]). Incremento velocità di esaurimento delle condizioni sugli alleati nella portata: 20...50%.'],
1749=>['Arma della Furia','Magia d\'Élite Altera-arma. Per 5...20 secondo[i], l\'obiettivo (un alleato o te stesso) ottiene un 100% in più di Adrenalina e 1 Punto Energia ogni volta che riesce a mettere a segno un attacco.','Magia d\'Élite Altera-arma. (Secondi: 5...20) Incremento acquisizione adrenalina: 100%; Energia +1 ogni volta che l\'obiettivo alleato colpisce con un attacco.'],
1750=>['Arma di Xinrae','Magia d\'Élite Altera-arma. Dura 8 secondo[i]; la prossima volta che l\'obiettivo (un alleato o te stesso) riceverà danni da un nemico non potrà riceverne una quantità superiore ad un 5% della propria Salute massima e sottrarrà a quel nemico fino a 20...80 Punto[i] Salute.','Magia d\'Élite Altera-arma. (Secondi: 8) Quantità massima di danni ricevuta dall\'obiettivo alleato la prossima volta che viene attaccato: 5% della propria Salute massima. Salute sottratta dall\'obiettivo alleato a quel nemico: fino a 20...80.'],
1751=>['Arma del Guerrafondaio','Magia Altera-arma. Dura 3...13 secondo[i]; se l\'obiettivo alleato attacca un nemico che non sta attaccando, lo interrompe.','Magia Altera-arma. (Secondi: 3...13) Gli attacchi interrompono un\'azione. Non interrompe i nemici all\'attacco.'],
1752=>['Arma del Rimedio','Magia d\'Élite Altera-arma. Per 8 secondo/i, la prossima volta che il bersaglio alleato subisce danni o sottrae vita a un nemico, sottrae fino a 20...80 Salute da quel nemico e perde 2 condizioni.','Magia d\'Élite Altera-arma. (8 secondo/i). La prossima volta che il bersaglio alleato subisce danni o sottrae vita a un nemico, sottrae 20...80 Salute da quel nemico e perde 2 condizioni.'],
1753=>['Falciata Strappante','Attacco con Falce. Infliggi +5...20 danno e perdi un Incantesimo del Derviscio. Se un incantesimo viene perso, ogni nemico da te colpito perde un incantesimo.','Attacco con Falce. Danni inferti: +5...20. Incantesimi del Derviscio persi: 1. Effetto della rimozione: il nemico colpito perde un incantesimo.'],
1754=>['Assalto Violento','Incantesimo Lampo d\'Élite. Dura 3...15 secondi; la tua velocità d\'attacco e di movimento e la tua dose di adrenalina aumentano di un 25%.','Incantesimo Lampo d\'Élite. (Secondi: 3...15). La tua velocità d\'attacco e di movimento e la tua dose di adrenalina aumentano di un 25%.'],
1755=>['Corruzione Mistica','Incantesimo Lampo. Tutti i nemici adiacenti vengono colpiti da Malattia per 1...10 secondi. Per 20 secondi non si verificano effetti. La durata della Malattia è raddoppiata se sei sotto incantesimo quando attivi questa abilità. Al termine dell\'incantesimo, tutti i membri della squadra a portata d\'orecchio sono curati da Malattia.','Incantesimo Lampo. (Secondi: 20). Effetto iniziale: tutti i nemici adiacenti vengono colpiti da Malattia (1...10 secondi). La durata è doppia se sei già sotto incantesimo. Effetto al termine: i membri della squadra a portata d\'orecchio sono curati da Malattia.'],
1756=>['Stretta di Grenth','Incantesimo Lampo d\'Élite. For 20 seconds, your attack skills also Cripple that foe for 1...11 seconds and you transfer 1...3 conditions from yourself to that foe.','Incantesimo Lampo d\'Élite. (20 seconds.) Inflict Cripple (1...11 seconds) with your attack skills and transfer 1...3 conditions.'],
1757=>['Velo di Spine','Incantesimo Lampo. Quando lanci questo incantesimo, tutti i nemici nei dintorni subiscono 5...50 danni perforanti. Per 5...25 secondi i tuoi danni da incantesimi subiti diminuiscono di un 5...35%.','Incantesimo Lampo. (Secondi: 5...25). Riduzione danni da incantesimo: 5...35%. Effetto iniziale: infligge 5...50 danni perforanti a tutti i nemici nei dintorni.'],
1758=>['Stretta del Predatore','Incantesimo Lampo. Dura 5...20 secondi; gli attacchi contro i nemici in movimento provocano anche Storpiatura per 2...9 secondi. Quando lanci questo incantesimo, vieni curato[f:"curata"] da Storpiatura e 1 altra condizione. Questo incantesimo termina dopo che avrai utilizzato 1...3 volte Storpiatura.','Incantesimo Lampo. (Secondi: 5...20.) Gli attacchi ai nemici in movimento li rendono anche storpi. Effetto iniziale: vieni curato[f:"curata"] da Storpiatura e 1 altra condizione. Termina dopo che avrai utilizzato 1...3 volte Storpiatura.'],
1759=>['Voto della Forza','Incantesimo d\'Élite. Secondi: 15. Ogni volta che attacchi un nemico con la Falce, infliggi 10...25 danni da taglio a tutti i nemici adiacenti.','Incantesimo d\'Élite. (Secondi: 15). Danni da taglio inferti a tutti i nemici adiacenti ogni volta che attacchi con la Falce: 10...25.'],
1760=>['Aura della Polvere d\'Ebano','Incantesimo Lampo d\'Élite. Quando lanci quest\'incantesimo, tutti i nemici nei dintorni vengono accecati per 1...7 secondi. Per 30 secondi, se brandisci un\'arma da terra, i tuoi attacchi ravvicinati infliggono +3...30 danni da terra. Al termine dell\'incantesimo vieni curato[f:"curata"] da Cecità.','Incantesimo Lampo d\'Élite. (Secondi: 30). Danni da terra inflitti in attacchi ravvicinati: +3...30. Effetto iniziale: condizione inflitta ai nemici nei dintorni: Cecità (1...7 secondi). Effetto al termine: rimuove Cecità. Ha effetto solo se si brandisce un\'arma di terra.'],
1761=>['Voto Zelante','Incantesimo d\'Élite. Per 20 secondo[i], hai una Rigenerazione dell\'Energia di -2 e ottieni 1...6 Punto[i] Energia ogni volta che un tuo attacco va a segno.','Incantesimo d\'Élite. (Secondi: 20) Energia conseguita ogni volta che un tuo attacco va a segno: 1...6. Rigenerazione Energia: -2.'],
1762=>['Cuore della Furia','Posizione. Dura 2...10 secondi; la tua velocità d\'attacco aumenta di 25%.','Posizione. (Secondi: 2...10). Incremento della tua velocità d\'attacco: 25%.'],
1763=>['Rinnovamento Zelante','Incantesimo Lampo. Tutti i nemici nei dintorni subiscono 5...30 danni sacri. Per 5...25 secondi hai una Rigenerazione dell\'Energia di -1 e consegui 1 Punto Energia ogni volta che colpisci un nemico. Se l\'incantesimo termina prematuramente ottieni 1...5 Punti Energia.','Incantesimo Lampo. (Secondi: 5...25). Effetto iniziale: danni sacri inflitti ai nemici nei dintorni: 5...30. Hai una Rigenerazione dell\'Energia di -1 e consegui 1 Punto Energia quando colpisci. Punti Energia ottenuti se l\'incantesimo termina prematuramente: 1...5 .'],
1764=>['Intuito dell\'Attaccante','Incantesimo Lampo. Per 3...10 secondi, hai un 50% di probabilità di bloccare gli attacchi. Al termine dell\'incantesimo, infliggi Debolezza a tutti i nemici adiacenti per 3...15 secondi.','Incantesimo Lampo. (Secondi: 3...10). Possibilità di blocco in attacco: 50% Effetto al termine: Condizione inflitta ai nemici adiacenti: Debolezza (3...15 secondi).'],
1765=>['Aura Strappante','Incantesimo Lampo. Quando lanci quest\'incantesimo, tutti i nemici nei dintorni subiscono 10...40 danni da freddo. Per 30 secondi, le tue abilità d\'attacco rimuovono incantesimi dai nemici abbattuti. Al termine dell\'incantesimo, tutti i nemici nei dintorni subiscono Armatura Incrinata per 1...10 secondi.','Incantesimo Lampo. (Secondi: 30). Le tue abilità d\'attacco rimuovono incantesimi dai nemici abbattuti. Effetto iniziale: Danni da freddo inflitti a tutti i nemici nei dintorni: 10...40. Effetto al termine: Condizione inflitta ai nemici nei dintorni: Armatura Incrinata (per 1...10 secondi).'],
1766=>['Grazia del Piedelieve','Incantesimo. Per 5...20 secondo[i], la tua velocità di movimento aumenta di un 25% e le condizioni si esauriscono con una velocità superiore del 50%.','Incantesimo. (Secondi: 5...20) Incremento tua velocità di movimento: 25%. Incremento dei tempi di esaurimento delle condizioni: 50%.'],
1767=>['Falciata del Mietitore','Attacco d\'Élite con Falce. Se questo attacco va a segno, infliggi Storpiatura per 3...15 secondi. Perdi 1 Incantesimo del Derviscio. Se un incantesimo è stato rimosso, questo attacco abbatte per 2...3 secondi.','Attacco d\'Élite con Falce. (Secondi: 3...15). Infligge Storpiatura. Incantesimi del Derviscio persi: 1. Effetto della rimozione: causa abbattimento per 2...3 secondi.'],
1768=>['Fretta del Predatore','Incantesimo Lampo. Per 2...8 secondi, la tua velocità di movimento aumenta di un 25% ed infliggi +3...12 danni contro i nemici in movimento.','Incantesimo Lampo. (Secondi: 2...8). Incremento velocità di movimento: 25%. Danni inferti ai nemici in movimento: +3...12.'],
1769=>['Rabbia Focalizzata','Abilità d\'Élite. Per 45 secondo[i], ottieni un 0...150% in più di Adrenalina.','Abilità d\'Élite. (Secondi: 45) Adrenalina conseguita in più: 0...150%.'],
1770=>['Indole Naturale','Abilità. Per 4...15 secondo[i], ottieni un 33% in più di Adrenalina mentre non sei sotto gli effetti di un incantesimo.','Abilità. (Secondi: 4...15) Adrenalina conseguita in più: 33%. Non ha effetto se sei sotto incantesimo.'],
1771=>['Canto del Ripristino','Canto d\'Élite. Per 10 secondo[i], la prossima volta che ogni membro della squadra a portata d\'orecchio usa un\'abilità, ottiene 45...110 Punto[i] Salute.','Canto d\'Élite. (Secondi: 10) Salute conseguita dai membri della squadra a portata d\'orecchio con l\'abilità successiva: 45...110.'],
1772=>['Lirica di Purificazione','Canto. Per 5...20 secondo[i], la prossima volta che ogni alleato a portata d\'orecchio utilizza un Sigillo, perde 1 condizione.','Canto. (Secondi: 5...20) Gli alleati a portata d\'orecchio perdono una condizione con il Sigillo successivo.'],
1773=>['Furia del Soldato','Eco d\'Élite. Per 10...35 secondo[i], se ti trovi sotto gli effetti di un canto o di un urlo, la tua velocità d\'attacco aumenta di un 33% e ottieni un 33% in più di adrenalina, ma hai -20 di armatura.','Eco d\'Élite. (Secondo[i]: 10...35). Incremento della tua velocità d\'attacco: 33%. Incremento di adrenalina se sei sotto gli effetti di un urlo o un canto: 33%. Hai -20 di armatura'],
1774=>['Ritornello Aggressivo','Eco. Per 5...25 secondo[i] la tua velocità d\'attacco aumenta di un 25% ma hai -20 di armatura. L\'eco si rinnova ogni volta che un canto o un urlo termina su di te.','Eco. (Secondo[i]: 5...25). Incremento della tua velocità d\'attacco: 25%. Rinnovo: ogni volta che un canto o un urlo termina su di te. Hai -20 di armatura.'],
1775=>['Finale Energetico','Eco. Per 10...35 secondo[i], ogni volta che un canto o un urlo termina sull\'obiettivo alleato (Spiriti esclusi), questi ottiene 1...2 Punto[i] Energia.','Eco. (Secondi: 10...35) Energia conseguita dall\'obiettivo (un alleato o te stesso) quando un urlo o un canto termina su di lui. Impossibile selezionare gli Spiriti.'],
1776=>['Sigillo dell\'Aggressione','Sigillo. Se sei sotto gli effetti di un Urlo o di un Canto, ottieni 2 dose[i] di adrenalina.','Sigillo. Adrenalina: 2 se sei affetto da un urlo o un canto.'],
1777=>['Sigillo del Rimedio','Sigillo. Perdi 1 condizione.','Sigillo. Ti liberi di una condizione.'],
1778=>['Sigillo del Ritorno','Sigillo. Resusciti il compagno di squadra preso di mira con un 5...20% di Salute e un 1...4% di Energia per ogni membro della squadra a portata d\'orecchio.','Sigillo. Resuscita il membro della squadra preso di mira (5...20% di Salute e 1...4% di Energia per ogni membro della squadra a portata d\'orecchio).'],
1779=>['"Perdurate!"','Urlo. Ottieni 2 colpi da adrenalina per ogni membro della squadra a portata d\'orecchio (massimo 1...8 adrenalina).','Urlo. Ottieni 2 adrenaline (massimo 1...8) per ogni membro della squadra a portata d\'orecchio.'],
1780=>['"Vietato Toccare!"','Urlo. Per 20 secondi 1...5 delle prossime abilità di tocco usate contro gli alleati a portata d\'orecchio falliranno.','Urlo. (Secondi: 20). 1...5 delle prossime abilità di tocco usate contro gli alleati a portata d\'orecchio falliranno.'],
1781=>['"Scopri la Loro Debolezza!"','Urlo. Dura 5...20 secondi. La prossima volta che l\'obiettivo alleato sferra un attacco infligge +5...50 di danni e provoca una Ferita Profonda per 5...20 secondi.','Urlo. (Secondi: 5...20). Danni inferti dall\'obiettivo alleato: +5...50. Condizione inflitta con l\'attacco successivo: Ferita Profonda (5...20 secondi).'],
1782=>['"Il Potere è nelle Tue Mani!"','Urlo d\'Élite. Per 2...4 secondo[i], tutti gli alleati a portata d\'orecchio ottengono una Rigenerazione Energia di 1...2.','Urlo d\'Élite. (Secondi: 2...4) Rigenerazione Energia alleati a portata d\'orecchio: 1...2.'],
1783=>['Lancia dell\'Assassino','Attacco con Lancia. Se questo attacco va a segno, infliggi +5...25 danno[i]; se quel nemico ha più Salute di te subisce una Ferita Profonda per 5...20 secondo[i].','Attacco con Lancia. Danni inferti: +5...25. Condizione inflitta se l\'obiettivo ha più Salute di te: Ferita Profonda (5...20 secondo[i]).'],
1784=>['Giavellotto Rapido','Attacco con Lancia. Se questo attacco va a segno, infligge +5...20 danno[i]; se sei sotto gli effetti di un incantesimo, questa lancia vola a velocità doppia e non può essere bloccata.','Attacco con Lancia. Danni inferti: +5...20. Questa lancia si muove a velocità doppia e non è bloccabile se sei sotto incantesimo.'],
1814=>['Sguardo del Portatore della Luce','Abilità. Il servitore di Abaddon preso di mira subisce 100 danno[i] sacro[i] e viene interrotto. Questa abilità colpisce un nemico in più nell\'area per ogni grado di Portatore della Luce conseguito. Questa abilità viene disattivata per 15 secondi dopo essere stata usata.','Abilità. Il servitore di Abaddon preso di mira subisce 100 danno[i] sacro[i] e viene interrotto. Questa abilità colpisce un nemico in più nell\'area per ogni grado di Portatore della Luce conseguito. Questa abilità viene disattivata (15 secondi).'],
1815=>['Sigillo del Portatore della Luce','Sigillo. Se ti trovi nell\'area di un servitore di Abaddon ottieni 3...5 dose[i] di adrenalina e 16...24 Punto[i] Energia.','Sigillo. Se ti trovi nell\'area di un servitore di Abaddon ottieni 3...5 dose[i] di adrenalina e 16...24 Punto[i] Energia.'],
1816=>['Sigillo di Rinascita della Lancia del Sole','Sigillo. Resusciti nella tua posizione il membro della squadra morto selezionato con piena Salute e il 10% di Energia per ogni grado della Lancia del Sole conseguito. Questo Sigillo può essere usato solo una volta durante l\'avventura a meno che non venga ricaricato da una Spinta Morale.','Sigillo. Resusciti nella tua posizione il membro della squadra morto selezionato con piena Salute e il 10% di Energia per ogni grado della Lancia del Sole conseguito. Questo Sigillo si ricarica solo ottenendo una Spinta Morale.'],
1948=>['Santuario dell\'Ombra','Incantesimo. Vieni accecato per 5 secondo[i]. Per 10 secondi ottieni +7...10 di Rigenerazione Salute e +40 di armatura.','Incantesimo. (Secondi: 10) Rigenerazione tua Salute: +7...10. Armatura: +40. Sei affetto da Accecamento (5 secondo[i]).'],
1949=>['Incubo Etereo','Fattura. L\'obiettivo nemico perde 5...8 Punto[i] Energia. Per ogni Punto Energia perduto in questo modo, l\'obiettivo e tutti i nemici nell\'area subiscono -1 di Degenerazione Salute per 10 secondo[i].','Fattura. Perdita Energia: 5...8. Degenerazione Salute dell\'obiettivo e dei nemici nell\'area per ogni punto di Energia perso: -1 (10 secondo[i]).'],
1950=>['Sigillo della Corruzione','Sigillo. L\'obiettivo nemico e tutti i nemici nei dintorni subiscono 20...30 danno[i]; per ogni nemico affetto da una condizione o da una fattura ottieni 2 Punto[i] Energia (max. 12...20 Punto[i] Energia).','Sigillo. Danni all\'obiettivo e ai nemici nei dintorni: 20...30. Energia ottenuta per ognuno di questi nemici affetti da condizione o fattura: 2 (max 12...20).'],
1951=>['Lord Elementale','Incantesimo. Per 40...60 secondi i tuoi attributi elementali vengono incrementati di 1. Ogni volta che lanci una magia, ottieni 1 Punto Energia per ogni 10 gradi di Riserva di Energia e vieni curato[f:"curata"] di un 100...300% del costo energetico della magia.','Incantesimo. (Secondi: 40...60.) I tuoi attributi elementali vengono incrementati di 1. Ogni volta che lanci una magia, ottieni 1 Punto Energia per ogni 10 gradi di Riserva di Energia e vieni curato[f:"curata"] di un 100...300% del costo energetico della magia.'],
1952=>['Spirito Altruista','Incantesimo. Per 15...20 secondi il dispendio di Energia delle magie lanciate su un altro alleato viene ridotto di 3.','Incantesimo. (Secondi: 15...20). Riduzione del dispendio di Energia per le magie lanciate su un altro alleato: 3.'],
1953=>['Tiro Triplo','Attacco con Arco. Scocca 3 frecce simultaneamente contro il nemico. Le frecce infliggono un 40...25% di danni in meno.','Attacco con Arco. Scocca 3 frecce simultanee contro l\'obiettivo nemico. Percentuale di danno in meno di queste frecce: 40...25%.'],
1954=>['"Mettetevi In Salvo!"','Urlo. Per 4...6 secondi tutti gli altri membri della squadra ottengono +100 di armatura.','Urlo. (Secondi: 4...6) Armatura aggiuntiva per tutti gli altri membri della squadra: +100.'],
1955=>['Aura della Potenza Sacra','Incantesimo. Per 45 secondi, quando perdi un Incantesimo del Derviscio assesti 20...25 danni sacri a tutti i nemici adiacenti.','Incantesimo. (Secondi: 45). Quando perdi un Incantesimo del Derviscio, i nemici adiacenti subiscono 20...25 danni sacri.'],
1957=>['Lancia della Furia','Attacco con Lancia. Questo attacco infligge +30...40 danno[i]; se colpisce un nemico affetto da una condizione ottieni 3...6 dose[i] di adrenalina.','Attacco con Lancia. Danni inferti: +30...40. Adrenalina conseguita se infliggi una condizione ad un nemico: 3...6.'],
1986=>['Assalto Vampirico','Attacco Doppio[_]. Deve seguire un attacco con arma secondaria. Se va a segno sottrai 10...40 Punto[i] Salute.','Attacco Doppio[_]. Sottrazione Salute se quest\'attacco va a segno: 10...40. Deve seguire un attacco con arma secondaria.'],
1987=>['Colpo del Loto','Attacco con Arma Secondaria. Deve seguire un attacco con arma primaria. Se questo attacco va a segno, infligge +10...25 danno[i] e tu ottieni 5...20 Punto[i] Energia.','Attacco con Arma Secondaria. Danni: +10...25. Ottieni 5...20 Punto[i] Energia. Deve seguire un attacco con arma primaria.'],
1988=>['Colpo della Zanna Dorata','Attacco con Arma Secondaria. Deve seguire un attacco con arma primaria. Se sei sotto gli effetti di un incantesimo e questo attacco va a segno, l\'obiettivo nemico soffre di Ferita Profonda per 5...20 secondo[i].','Attacco con Arma Secondaria. Condizione inflitta se sei sotto incantesimo: Ferita Profonda (5...20 secondo[i]). Deve seguire un attacco con arma primaria.'],
1990=>['Colpo del Loto in Caduta','Attacco con Arma Secondaria. Deve colpire un avversario abbattuto. Se va a segno infligge +15...35 danno[i] e tu ottieni 1...12 Punto[i] Energia.','Attacco con Arma Secondaria. Danni: +15...35. Ottieni 1...12 Punto[i] Energia. Ha effetto solo se l\'obiettivo nemico è stato abbattuto.'],
1991=>['Sigillo del Sadico','Sigillo. Ottieni 10...45 Punto[i] Salute per ogni condizione presente sull\'obiettivo nemico.','Sigillo. Ottieni 10...45 Punto[i] Salute per ogni condizione presente sull\'obiettivo nemico.'],
1992=>['Sigillo della Distrazione','Sigillo. Se l\'obiettivo nemico sta lanciando una magia, viene interrotta e disattivata per 1...5 secondi per ogni Sigillo equipaggiato.','Sigillo. Interrompe una magia. Effetto dell\'interruzione: la magia dell\'obiettivo nemico viene disattivata per 1...5 secondi per ogni Sigillo equipaggiato.'],
1993=>['Sigillo del Richiamo','Sigillo. Per 6 secondo[i], hai una Rigenerazione dell\'Energia di -4. Quando questo effetto termina ottieni 13...20 Punto[i] Energia.','Sigillo. (Secondi: 6) Rigenerazione tua Energia: -4. Effetto al termine: ottieni 13...20 Punto[i] Energia.'],
1994=>['Chiusura del Potere','Magia. Se l\'obiettivo nemico ha attivato una magia o un canto, l\'abilità viene interrotta e disattivata per 5...13 secondi in più.','Magia. Interrompe una magia o un canto. Effetto dell\'interruzione: la magia o il canto interrotti vengono disattivati per +5...13 secondi.'],
1995=>['Risparmio è Guadagno','Magia. Se l\'obiettivo nemico non sta lanciando una magia o attaccando ottieni 8...13 Punto[i] Energia.','Magia. Energia conseguita se l\'obiettivo nemico non sta attaccando né lanciando una magia: 8...13.'],
1996=>['Somma di Tutte le Paure','Fattura. Per 4...12 secondo[i] i movimenti, gli attacchi e il lancio di magie dell\'obiettivo nemico rallentano di un 33%.','Fattura. (Secondi: 4...12) Rallentamento movimenti, attacchi e lancio magie del nemico: 33%.'],
1997=>['Aura Avvizzente','Incantesimo. Per 5...20 secondo[i], gli attacchi ravvicinati dell\'obiettivo (un alleato o te stesso) provocano Debolezza per 5...20 secondo[i].','Incantesimo. (Secondi: 5...20) Condizione inflitta dagli attacchi ravvicinati dell\'obiettivo alleato: Debolezza (5...20 secondo[i]).'],
1998=>['Cacofonia','Fattura. Per 15 secondo[i], ogni volta che l\'obiettivo nemico usa un Urlo o un Canto, subisce 30...105 danno[i].','Fattura. (Secondi: 15) Danni inferti ogni volta che l\'obiettivo nemico usa un urlo o canto: 30...105.'],
1999=>['Abbraccio dell\'Inverno','Fattura. Per 2...6 secondi la velocità dell\'obiettivo nemico diminuisce di un 66% e questi subisce 5...15 danni mentre si muove.','Fattura. (Secondi: 2...6.) Rallentamento dell\'obiettivo nemico: 66%. Danni subiti in movimento: 5...15.'],
2000=>['Catene di Terra','Fattura. Per 3 secondi la velocità dell\'obiettivo nemico e di tutti i nemici nei dintorni diminuisce di un 90%. Al termine, Catene di Terra provoca Debolezza per 5...20 secondi.','Fattura. (Secondi: 3.) Diminuzione velocita obiettivo e nemici nei dintorni: 90%. Debolezza inflitta al termine: 5...20 secondi.'],
2001=>['Guardia della Debolezza','Guardia. Crei una Guardia della Debolezza nella tua posizione corrente. Per 5...20 secondi, i nemici in quest\'area soffrono di Debolezza per 5...20 secondi ogni volta che subiscono danni elementali.','Guardia. (Secondi: 5...20.) Condizione inflitta ai nemici che subiscono danni elementali in questa Guardia: Debolezza (5...20 secondi).'],
2002=>['Glifo della Rapidità','Glifo. Per 15 secondi, la velocità di ricarica di 1...5 delle tue magie successive aumenta di un 25% e i proiettili da esse provenienti hanno una velocità superiore del 200%.','Glifo. (Secondi: 15.) Incremento velocità di ricarica di 1...5 delle tue magie successive: 25%. Incremento velocità dei proiettili risultanti: 200%.'],
2003=>['Cura Fattura','Magia. Rimuovi una fattura dall\'obiettivo (un alleato o te stesso). Se ci riesci quell\'alleato viene anche curato di 30...100 Punto[i] Salute.','Magia. Rimuove una fattura. Effetto rimozione: cura di 30...100.'],
2004=>['Colpisci Condizione','Magia. Rimuovi una condizione dall\'obiettivo (un alleato o te stesso). Se ci riesci, i nemici presenti nell\'area subiscono 10...60 danno[i] sacro[i].','Magia. Rimuove una condizione. Effetto della rimozione: 10...60 danno[i] sacro[i] ai nemici nell\'area dell\'obiettivo alleato.'],
2005=>['Soccorso del Punitore','Incantesimo. Per 30 secondo[i], il bonus di Favore Divino per le tue Preghiere Punitive viene raddoppiato.','Incantesimo. (Secondi: 30) Raddoppia il bonus di cura del Favore Divino per le Preghiere Punitive.'],
2006=>['Sigillo della Castigazione','Sigillo. L\'obiettivo nemico subisce 26...56 danno[i] sacro[i]; se stava attaccando ottieni 4...14 Punto[i] Energia.','Sigillo. Danni sacri inferti: 26...56. Energia conseguita se l\'obiettivo nemico sta attaccando: 4...14.'],
2007=>['Velo Purificante','Incantesimo. Mentre mantieni quest\'incantesimo la velocità di esaurimento delle condizioni presenti sull\'obiettivo alleato aumenta di un 5...50%. Quando quest\'incantesimo termina una condizione viene rimossa da quell\'alleato.','Incantesimo. Riduzione durata delle condizioni sull\'obiettivo alleato: 5...50%. Effetto al termine: rimuove una condizione.'],
2008=>['Percossa Polverizzante','Attacco con Martello. Se colpisci un nemico abbattuto gli procuri Debolezza e Ferita Profonda per 5...20 secondo[i].','Attacco con Martello. Condizioni inflitte se l\'obiettivo nemico è abbattuto: Debolezza e Ferita Profonda (5...20 secondo[i]).'],
2009=>['Fendente Affilato','Attacco con Ascia. Se va a segno, questo attacco risulta sempre in un colpo critico.','Attacco con Ascia. Risulta sempre in un colpo critico.'],
2010=>['Taglia Ginocchia','Attacco con Spada. Se questo attacco colpisce un nemico affetto da Storpiatura ottieni 2...7 Punto[i] Energia e 1...3 dose[i] di Adrenalina.','Attacco con Spada. Ottieni 2...7 di Energia e 1...3 di adrenalina se l\'obiettivo nemico soffre di Storpiatura.'],
2011=>['Abbranca','Abilità. Tu e l\'obiettivo nemico toccato andate a terra. Perdi la posizione corrente.','Abilità a Tocco. Provoca abbattimento. Inoltre, vai a terra. La tua posizione corrente termina.'],
2012=>['Falce Radiante','Attacco con Falce. Questo attacco provoca +1 danni per ogni Punto Energia presente su di te (max. 5...30 danni). Ottieni 1...7 Punti Energia se l\'attacco va a segno.','Attacco con Falce. Danni inferti per ogni Punto Energia che possiedi: +1 (max 5...30). Ottieni 1...7 Punti Energia.'],
2013=>['Aura di Grenth','Incantesimo Lampo. Per 20 secondi, infliggi 5...25 danni in meno e sottrai 5...25 Punti Salute quando attacchi con la Falce. Quando lanci questo incantesimo sottrai 5...25 Punti Salute a tutti i nemici adiacenti.','Incantesimo Lampo. (Secondi: 20). Infliggi 5...25 danni in meno e sottrai 5...25 Punti Salute quando attacchi con la Falce. Effetto iniziale: sottrai 5...25 Punti Salute a tutti i nemici adiacenti.'],
2014=>['Sigillo del Ritegno Pio','Sigillo. Rimuove 1 incantesimo da Derviscio. Il nemico bersagliato viene azzoppato per 5...15 secondo/i. Se viene rimosso un incantesimo, vengono azzoppati anche tutti i nemici nell\'area del tuo bersaglio e questo sigillo si ricarica del 75% più velocemente.','Sigillo. Azzoppa per 5...15 secondo/i. Rimuove 1 dei tuoi incantesimi da Derviscio. Effetto della rimozione: azzoppa anche i nemici nell\'area del tuo bersaglio e si ricarica del 75% più velocemente.'],
2015=>['Falce del Contadino','Attacco con Falce. Se questo attacco va a segno provochi +5...20 danno[i]. Se colpisci più di un nemico questo attacco si ricarica all\'istante.','Attacco con Falce. Danni inferti: +5...20. Si ricarica all\'istante se colpisci più di un nemico.'],
2016=>['Lee Sa era Energetica','Magia Altera-oggetto. Mantieni le ceneri di Lee Sa per 5...15 secondo[i]; mentre le mantieni, ottieni una Rigenerazione dell\'Energia di +2. Quando le lasci cadere ricevi +1...10 Punto[i] Energia.','Magia Altera-oggetto. (Secondi: 5...15) Rigenerazione Energia: +2. Rilascio: +1...10 Punto[i] Energia.'],
2017=>['Inno della Stanchezza','Canto. Per 8 secondo[i] la prossima abilità d\'attacco utilizzata da ogni alleato a portata d\'orecchio provoca anche Debolezza per 1...16 secondo[i].','Canto. (Secondi: 8) Condizione inflitta dagli alleati a portata d\'orecchio con la prossima abilità d\'attacco: Debolezza (1...16 secondo[i]).'],
2018=>['Inno del Disturbo','Canto. Per 1...10 secondo[i] la prossima abilità d\'attacco usata da ogni alleato a portata d\'orecchio interrompe anche un\'azione.','Canto. (Secondi: 1...10) Gli alleati a portata d\'orecchio interrompono un\'azione con l\'abilità d\'attacco successiva.'],
2051=>['Invoca Spiriti','Magia. Tutti gli Spiriti da te controllati compiono un Passo nell\'Ombra verso la tua posizione e ottengono 60...100 Punto[i] Salute.','Magia. Gli Spiriti da te controllati compiono un Passo nell\'Ombra verso la tua posizione e ottengono 60...100 Punto[i] Salute.'],
2052=>['Zanna dell\'Ombra','Fattura. Compi un Passo nell\'Ombra verso l\'obiettivo nemico. Per 10 secondo[i] questa fattura non ha effetto. Quando termina ritorni al punto di partenza e quel nemico soffre di Ferita Profonda per 5...20 secondo[i].','Fattura. Compi un Passo nell\'Ombra verso l\'obiettivo nemico. Effetto al termine dopo 10 secondo[i]: infligge Ferita Profonda (5...20 secondo[i]). Torni nella posizione di partenza.'],
2053=>['Rischio Calcolato','Fattura. Per 3...24 secondi gli attacchi dell\'obiettivo nemico infliggono +10 danni, ma c\'è un 50% di probabilità che i danni assestati con ogni attacco si ripercuotano su di lui (danni massimi: 15...100).','Fattura. (Secondi: 3...24). Gli attacchi dell\'obiettivo nemico infliggono +10 danni. Per ogni attacco c\'è un 50% di probabilità che il danno (massimo 15...100) venga inflitto al nemico.'],
2054=>['Armatura Infeltrita','Fattura. Per 10 secondo[i] l\'obiettivo nemico subisce una Degenerazione della Salute di -1...4. Quando questa fattura termina quel nemico soffre di Armatura Incrinata per 5...20 secondo[i].','Fattura. (Secondi: 10) Degenerazione Salute: -1...4. Effetto al termine: infligge Armatura Incrinata (5...20 secondo[i]).'],
2055=>['Aneurisma','Magia. L\'obiettivo nemico recupera tutta l\'Energia. Per ogni Punto Energia ottenuto in questo modo, il nemico subisce 1...3 danni e tutti i nemici adiacenti perdono 1 Punto Energia (Punti Energia massimi persi: 1...30).','Magia. L\'obiettivo nemico recupera tutta l\'Energia. Per ogni Punto Energia ottenuto, l\'obiettivo nemico subisce 1...3 danni e tutti i nemici adiacenti perdono 1 Punto Energia (massimo 1...30).'],
2056=>['Occhio Vagante','Fattura. Dura 4 secondo[i]; la prossima volta che l\'obiettivo nemico attacca viene interrotto e tutti i nemici nei dintorni subiscono 30...110 danno[i].','Fattura. (Secondi: 4) Interrompe il prossimo attacco dell\'obiettivo nemico. Effetto dell\'interruzione: 30...110 danno[i] ai nemici nei dintorni.'],
2057=>['Banchetto Ripugnante','Magia. Tutte le condizioni vengono trasferite dall\'obiettivo alleato a te stesso. Per ogni condizione così acquisita ottieni 0...45 Punti Salute e 2...4 Punti Energia. Questa abilità si ricarica nella metà del tempo se rimuovi la Malattia dal tuo obiettivo.','Magia. Trasferisce tutte le condizioni dall\'obiettivo alleato a te stesso. Ottieni 0...45 Punti Salute e 2...4 Punti Energia per ogni condizione trasferita. Ricarica dimezzata se rimuovi Malattia. Impossibile selezionare se stessi.'],
2058=>['Bile Putrefatta','Fattura. Per 5...25 secondo[i], l\'obiettivo nemico subisce una Degenerazione della Salute di -1...3. Se muore mentre è affetto da questa fattura, tutti i nemici nei dintorni subiscono 25...85 danno[i].','Fattura. (Secondi: 5...25) Degenerazione Salute: -1...3. Danni inferti a tutti i nemici nei dintorni se l\'obiettivo nemico muore: 25...85.'],
2059=>['Psicosi Traumatica','Magia. L\'obiettivo nemico subisce 10...30 danni da fulmine e soffre di Armatura Incrinata per 5...20 secondi. Questa magia ha una penetrazione dell\'armatura del 25%. Se sei sotto Sforzo, questa magia colpisce i nemici adiacenti.','Magia. Danni da fulmine inferti: 10...30. Condizione inflitta: Armatura Incrinata (5...20 secondi). Penetrazione armatura: 25%. Se sotto Sforzo, colpisce gli adiacenti.'],
2060=>['Glifo dell\'Immolazione','Glifo. Per 15 secondi, con 1...4 delle tue magie successive dirette contro un obiettivo nemico provochi anche Bruciatura per 1...4 secondi.','Glifo. (Secondi: 15.) Condizione inflitta da 1...4 delle tue magie successive dirette contro un obiettivo nemico: Bruciatura (1...4 secondi).'],
2061=>['Spirito Paziente','Incantesimo. Per 2 secondi l\'obiettivo (un alleato o te stesso) è affetto dall\'incantesimo Spirito Paziente. Se questo incantesimo non termina prematuramente, l\'alleato viene curato di 30...120 Punti Salute al termine dell\'incantesimo.','Incantesimo. (Secondi: 2). Effetto al termine: cure: 30...120. Non ha effetto se termina prematuramente.'],
2062=>['Nastro di Guarigione','Magia. L\'obiettivo alleato viene curato di 20...110 Punto[i] Salute; un massimo di 2 alleati nei dintorni di questo alleato ricevono 10...100 Punto[i] Salute.','Magia. Cure: 20...110. Cure per due alleati in più vicino all\'obiettivo alleato: 10...100. Impossibile selezionare se stessi.'],
2063=>['Aura della Stabilità','Incantesimo. Per 3...8 secondo[i] l\'obiettivo alleato non può essere abbattuto.','Incantesimo. (Secondi: 3...8) Impossibile abbattere l\'obiettivo alleato. Impossibile selezionare se stessi.'],
2064=>['Mente Candida','Incantesimo. Per 1...15 secondo[i] l\'obiettivo alleato perde una fattura ogni 5 secondo[i].','Incantesimo. (Secondi: 1...15) Rimuove una fattura ogni 5 secondo[i]. Impossibile selezionare se stessi.'],
2065=>['Anima Candida','Incantesimo. Per 1...15 secondo[i] l\'obiettivo alleato perde una condizione ogni 3 secondo[i].','Incantesimo. (Secondi: 1...15) Rimuove una condizione ogni 3 secondo[i]. Impossibile selezionare se stessi.'],
2066=>['Disarmo','Attacco con Spada. Interrompi l\'azione dell\'obiettivo nemico; se si trattava di un attacco, tutte le sue abilità d\'attacco vengono disattivate per 0...3 secondo[i].','Attacco con Spada. Interrompe l\'obiettivo nemico. Effetto dell\'interruzione: disattiva le abilità d\'attacco di questo nemico (0...3 secondo[i]) se l\'azione era un attacco.'],
2067=>['"Tutto Calcolato!"','Urlo. Se vieni abbattuto ottieni 1...6 dose[i] di adrenalina.','Urlo. Adrenalina ottenuta se sei abbattuto: 1...6.'],
2068=>['Fuoco Rapido','Preparazione. Per 5...25 secondo[i] la tua velocità d\'attacco aumenta di un 33% mentre utilizzi un arco.','Preparazione. (Secondi: 5...25) Incremento tua velocità d\'attacco mentre utilizzi un arco: 33%.'],
2069=>['Tiro del Cacciatore Indolente','Attacco con Arco. Se questo attacco va a segno l\'obiettivo nemico subisce +10...25 danno[i]; se non sta usando un\'abilità, il Tiro del Cacciatore Indolente provoca +10...35 danno[i] aggiuntivo[i].','Attacco con Arco. Danni inferti: +10...25. Danni inferti se l\'obiettivo nemico non sta usando un\'abilità: +10...35.'],
2070=>['Affetta Aura','Attacco Ravvicinato. Se questo attacco va a segno, infliggi Emorragia per 5...15 secondi. Se sei sotto incantesimo, infliggi inoltre Armatura Incrinata per 1...10 secondi.','Attacco Ravvicinato. Condizione inflitta: Emorragia (5...15 secondi). Infligge inoltre Armatura Incrinata (1...10 secondi) se sei sotto incantesimo.'],
2071=>['Falciata Zelante','Attacco con Falce. Se l\'attacco va a segno, infliggi +5...20 danni. Ottieni 3 Punti Energia e 1 dose di adrenalina per ogni nemico colpito.','Attacco con Falce. Danni inferti: +5...20. Ottieni 3 Punti Energia e 1 dose di adrenalina per ogni nemico colpito.'],
2072=>['Li Ming era Pura','Magia Altera-oggetto. Mantieni le ceneri di Li Ming per 5...20 secondo[i]; mentre le mantieni, la velocità di esaurimento delle condizioni aumenta di un 10...50%. Quando le lasci cadere tutti gli alleati a portata d\'orecchio perdono 1...4 condizione[i].','Magia Altera-oggetto. (Secondi: 5...20) Riduzione durata delle condizioni su di te: 10...50%. Rilascio: rimuove 1...4 condizione[i] dagli alleati a portata d\'orecchio.'],
2073=>['Arma dell\'Aggressione','Magia Altera-arma. Per 5...15 secondo[i] la tua velocità d\'attacco aumenta di un 25%.','Magia Altera-arma. (Secondi: 5...15) Incremento velocità di attacco: 25%.'],
2074=>['Batti Torace','Attacco con Lancia. Se questo attacco colpisce un nemico affetto da Armatura Incrinata gli provoca Ferita Profonda per 5...20 secondo[i].','Attacco con Lancia. Condizione inflitta se l\'obiettivo nemico soffre di Armatura Incrinata: Ferita Profonda (5...20 secondo[i]).'],
2075=>['Ritornello Frettoloso','Eco. Per 8...20 secondo[i] la velocità di movimento dell\'obiettivo (un alleato o te stesso) aumenta di un 25%. Questa eco si rinnova ogni volta che un canto o un urlo finisce su quell\'alleato.','Eco. (Secondi: 8...20) Incremento velocità di movimento dell\'obiettivo (un alleato o te stesso): 25%. Rinnovo: ogni volta che un canto o un urlo termina su quest\'alleato.'],
2091=>['Santuario dell\'Ombra','Incantesimo. Vieni accecato per 5 secondo[i]. Per 10 secondi ottieni +7...10 di Rigenerazione Salute e +40 di armatura.','Incantesimo. (Secondi: 10) Rigenerazione tua Salute: +7...10. Armatura: +40. Sei affetto da Accecamento (5 secondo[i]).'],
2092=>['Incubo Etereo','Fattura. L\'obiettivo nemico perde 5...8 Punto[i] Energia. Per ogni Punto Energia perduto in questo modo, l\'obiettivo e tutti i nemici nell\'area subiscono -1 di Degenerazione Salute per 10 secondo[i].','Fattura. Perdita Energia: 5...8. Degenerazione Salute dell\'obiettivo e dei nemici nell\'area per ogni punto di Energia perso: -1 (10 secondo[i]).'],
2093=>['Sigillo della Corruzione','Sigillo. L\'obiettivo nemico e tutti i nemici nei dintorni subiscono 20...30 danno[i]; per ogni nemico affetto da una condizione o da una fattura ottieni 2 Punto[i] Energia (max. 12...20 Punto[i] Energia).','Sigillo. Danni all\'obiettivo e ai nemici nei dintorni: 20...30. Energia ottenuta per ognuno di questi nemici affetti da condizione o fattura: 2 (max 12...20).'],
2094=>['Lord Elementale','Incantesimo. Per 40...60 secondi i tuoi attributi elementali vengono incrementati di 1. Ogni volta che lanci una magia, ottieni 1 Punto Energia per ogni 10 gradi di Riserva di Energia e vieni curato[f:"curata"] di un 100...300% del costo energetico della magia.','Incantesimo. (Secondi: 40...60.) I tuoi attributi elementali vengono incrementati di 1. Ogni volta che lanci una magia, ottieni 1 Punto Energia per ogni 10 gradi di Riserva di Energia e vieni curato[f:"curata"] di un 100...300% del costo energetico della magia.'],
2095=>['Spirito Altruista','Incantesimo. Per 15...20 secondi il dispendio di Energia delle magie lanciate su un altro alleato viene ridotto di 3.','Incantesimo. (Secondi: 15...20). Riduzione del dispendio di Energia per le magie lanciate su un altro alleato: 3.'],
2096=>['Tiro Triplo','Attacco con Arco. Scocca 3 frecce simultaneamente contro il nemico. Le frecce infliggono un 40...25% di danni in meno.','Attacco con Arco. Scocca 3 frecce simultanee contro l\'obiettivo nemico. Percentuale di danno in meno di queste frecce: 40...25%.'],
2097=>['"Mettetevi In Salvo!"','Urlo. Per 4...6 secondo[i] tutti gli altri membri della squadra ottengono +100 di armatura.','Urlo. (Secondi: 4...6) Armatura aggiuntiva per tutti gli altri membri della squadra: +100.'],
2098=>['Aura della Potenza Sacra','Incantesimo. Per 45 secondi, quando perdi un Incantesimo del Derviscio assesti 20...25 danni sacri a tutti i nemici adiacenti.','Incantesimo. (Secondi: 45). Quando perdi un Incantesimo del Derviscio, i nemici adiacenti subiscono 20...25 danni sacri.'],
2099=>['Lancia della Furia','Attacco con Lancia. Questo attacco infligge +30...40 danno[i]; se colpisce un nemico affetto da una condizione ottieni 3...6 dose[i] di adrenalina.','Attacco con Lancia. Danni inferti: +30...40. Adrenalina conseguita se infliggi una condizione ad un nemico: 3...6.'],
2100=>['Invoca Spiriti','Magia. Tutti gli Spiriti da te controllati compiono un Passo nell\'Ombra verso la tua posizione e ottengono 60...100 Punto[i] Salute.','Magia. Gli Spiriti da te controllati compiono un Passo nell\'Ombra verso la tua posizione e ottengono 60...100 Punto[i] Salute.'],
2101=>['Agilità Critica','Incantesimo. Per 4 secondo[i] e 1 secondo per ogni grado di Colpi Critici, la tua velocità d\'attacco aumenta di un 33% e ottieni +15...25 di armatura. Questa abilità si rinnova ogni volta che metti a segno un colpo critico.','Incantesimo. (4 secondo[i] più 1 per ogni grado di Colpi Critici) Incremento tua velocità d\'attacco: 33%. Armatura: +15...25. Rinnovo: ogni volta che assesti un colpo critico.'],
2102=>['Grido di Dolore','Magia. Interrompi l\'abilità dell\'obiettivo nemico. Se è sotto l\'effetto di una fattura dell\'Ipnotizzatore, lui e tutti i nemici nell\'area subiscono 25...50 danni e una Degenerazione Salute di 3...5 per 10 secondi.','Magia. Interrompe un\'abilità. Se l\'obiettivo nemico è sotto l\'effetto di una fattura dell\'Ipnotizzatore assesta 25...50 danni all\'obiettivo e ai nemici nell\'area e causa Degenerazione della Salute di -3...5 (10 secondi).'],
2103=>['Necrosi','Abilità. Se l\'obiettivo nemico è affetto da una condizione o da una fattura subisce 60...90 danno[i].','Abilità. Assesta 60...90 danno[i] se l\'obiettivo nemico ha una condizione o una fattura.'],
2104=>['Intensità','Abilità. Per 10 secondi, la prossima volta che infliggi un danno elementale tramite incantesimo a un obiettivo, assesti anche un 60...70% di quel danno a tutti i nemici nell\'area.','Abilità. (Secondi: 10.) La prossima volta che infliggi un danno elementale con un incantesimo, gli altri obiettivi nell\'area subiscono un 60...70% di quel danno.'],
2105=>['Seme della Vita','Incantesimo. Per 2...5 secondi, ogni volta che l\'obiettivo alleato subisce danni tutti i membri della squadra vengono curati di 2 Punti Salute per ogni grado di Favore Divino.','Incantesimo. (Secondi: 2...5). Punti Salute ottenuti dai membri della squadra per ogni grado di Favore Divino ogni volta che l\'obiettivo alleato subisce danni: 2. Impossibile selezionare se stessi.'],
2107=>['Attacco Vortice','Attacco Ravvicinato. Attacchi l\'obiettivo e i nemici adiacenti; ogni attacco che va a segno infligge +13...20 danno[i].','Attacco Ravvicinato. Attacca l\'obiettivo e i nemici adiacenti assestando +13...20 danno[i].'],
2108=>['Mai Infierire da Soli','Abilità. Per 18...25 secondo[i], la tua velocità d\'attacco e quella della tua mascotte aumentano di un 25% e hai una Rigenerazione della Salute di +1...3.','Abilità. (Secondi: 18...25) Incremento velocità degli attacchi tuoi e della mascotte: 25%. Rigenerazione Salute: +1...3.'],
2109=>['Aura Eterna','Incantesimo. Salute massima: +100. Al termine dell\'incantesimo, tutti i membri della squadra nell\'area vengono resuscitati con un 40...50% di Punti Salute e un 20...30% di Punti Energia.','Incantesimo. Salute massima: +100. Effetto al termine: tutti i membri della squadra nell\'area vengono resuscitati con un 40...50% di Punti Salute e un 20...30% di Punti Energia.'],
2110=>['Vampirismo','Rituale Incatenante. Crei uno Spirito di livello 4...14 che si esaurisce dopo 75...150 secondo[i]; i suoi attacchi sottraggono fino a 10...20 Punto[i] Salute e tu vieni curato di 10...20 Punto[i] Salute.','Rituale Incatenante. Crei uno Spirito di livello 4...14 (in vita per 75...150 secondo[i]). Salute sottratta dai suoi attacchi: 10...20. Vieni curato di: 10...20.'],
2112=>['"Non c\'è Nulla da Temere!"','Urlo. Per 4 secondo[i] e 1 secondo per ogni 2 gradi di Leadership, tutti i membri della squadra a portata d\'orecchio subiscono un 20...35% di danni in meno; quando questo urlo termina i membri della squadra affetti vengono curati di 35...60 Punto[i] Salute.','Urlo. (Secondi: 4 più 1 per ogni 2 gradi di Leadership) Riduzione danni subiti dai membri della squadra a portata d\'orecchio: 20...35%. Effetto al termine: cura di 35...60.'],
2116=>['Attacco Subdolo','Attacco Ravvicinato. Se questo attacco va a segno, l\'obiettivo nemico soffre di Accecamento per 5...8 secondo[i]. Vale come attacco con arma primaria.','Attacco Ravvicinato. Condizione inflitta: Accecamento (5...8 secondo[i]). Vale come attacco con arma primaria.'],
2135=>['Bue Calpestante','Attacco Doppio[_]. Deve seguire un attacco con arma secondaria. Se va a segno, infliggi +5...20 danno[i]; se colpisce un nemico affetto da Storpiatura lo abbatte.','Attacco Doppio[_]. Danni inferti: +5...20. Provoca abbattimento se l\'obiettivo nemico è affetto da Storpiatura. Deve seguire un attacco con arma secondaria.'],
2136=>['Difesa della Polvere di Fumo','Posizione. Per 8 secondi, la prossima volta che sarai colpito subirai la metà del danno e tutti i nemici adiacenti verranno accecati per 2...6 secondi.','Posizione. (Secondi: 8). La prossima volta che vieni colpito subirai la metà del danno e infliggerai Cecità ai nemici adiacenti per 2...6 secondi.'],
2137=>['Immagini Svianti','Fattura. Per 2...10 secondi l\'obiettivo nemico impiegherà il doppio del tempo per l\'attivazione delle abilità (attacchi esclusi).','Fattura. (Secondi: 2...10). L\'obiettivo nemico impiegherà il doppio del tempo per l\'attivazione delle abilità (attacchi esclusi).'],
2138=>['Vigore del Fattucchiere','Incantesimo. Per 10 secondi ottieni una Rigenerazione Salute di +1...8. Il Vigore del Fattucchiere termina se utilizzi un\'abilità che non rappresenta una fattura.','Incantesimo. (Secondi: 10). Rigenerazione Salute: +1...8. Termina se utilizzi un\'abilità che non rappresenta una fattura.'],
2139=>['Masochismo','Incantesimo. Per 10...40 secondi incrementi i tuoi attributi Magia della Morte e Sottrazione dell\'Anima di +2 e sacrifichi un ulteriore 5...3% della tua Salute massima quando lanci una magia.','Incantesimo. (Secondi: 10...40). Incremento Magia della Morte e Sottrazione dell\'Anima: +2. Quando lanci una magia, sacrifichi un ulteriore 5...3% della tua Salute massima.'],
2140=>['Trappola Perforante','Trappola. Quando la Trappola Perforante viene attivata, tutti i nemici nei dintorni subiscono 5...50 danni perforanti. Infligge 15...60 danni da fuoco ulteriori a tutti i nemici con Armatura Incrinata che si trovano nei dintorni. La Trappola Perforante termina dopo 90 secondi. Quando si attiva questa abilità, può capitare facilmente di essere interrotti.','Trappola. (Secondi: 90) Ha effetto sui nemici nei dintorni. Danni perforanti inferti: 5...50. Danni ulteriori ai nemici affetti da Armatura Incrinata: 15...60. Facile interruzione.'],
2141=>['Compagnia','Abilità. Se hai meno Salute della tua mascotte vieni curato di 30...120 Punto[i] Salute. Se la tua mascotte ha meno Salute di te viene curata di 30...120 Punto[i] Salute.','Abilità. Cure ricevute se la tua Salute è inferiore a quella della tua mascotte: 30...120. Cure per la mascotte se la sua Salute è inferiore alla tua: 30...120.'],
2142=>['Aggressione Selvaggia','Abilità. Per 5...20 secondo[i], la velocità d\'attacco della tua mascotte aumenta di un 33% e provoca 3...10 danno[i] in più.','Abilità. (Secondi: 5...20) Incremento velocità d\'attacco della tua mascotte: 33%; danni da essa inferti: +3...10.'],
2143=>['Tiro Dirompente','Attacco con Arco. Se questo attacco va a segno, l\'azione dell\'obiettivo nemico viene interrotta. Se si trattava di un\'abilità infliggi +10...40 danno[i].','Attacco con Arco. Interrompe un\'azione. Effetto dell\'interruzione: +10...40 danno[i] se interrompi un\'abilità.'],
2144=>['Tiro al Volo','Attacco con Arco. Rimuove tutte le tue Preparazioni. Scocca le frecce contro l\'obiettivo nemico e un massimo di 3 nemico[i] a lui adiacente[i]. Se vanno a segno provocano +1...10 danno[i].','Attacco con Arco. Danni inferti: +1...10. Colpisce fino a 3 nemico[i] adiacenti al tuo obiettivo. Tutte le tue preparazioni vengono rimosse.'],
2145=>['Mira da Professionista','Preparazione. Per 24 secondi le tua abilità di attacco con arco costano 1...2 Punti Energia in meno e provocano 1...10 di danni in più.','Preparazione. (Secondi: 24) Dispendio energetico dei tuoi attacchi con arco: 1...2 in meno; danni inferti: +1...10.'],
2146=>['Furia Pia','Posizione. Rimuove 1 Incantesimo del Derviscio. Per 1...7 secondi la tua velocità d\'attacco aumenta di 25%. Se un incantesimo è stato rimosso, questa posizione dura il doppio del tempo.','Posizione. (1...7 secondi). Attacchi più velocemente del 25% e rimuovi 1 dei tuoi Incantesimi del Derviscio. Effetto della rimozione: questa posizione dura il doppio del tempo.'],
2147=>['Vittoria Azzoppante','Attacco con Falce. Se questo attacco colpisce un nemico, gli provoca Storpiatura per 3...8 secondi. Se hai più Salute dell\'obiettivo nemico, tutti i nemici adiacenti subiscono 10...30 danni da terra.','Attacco con Falce. (Secondi: 3...8.) Condizione inflitta all\'obiettivo nemico: Storpiatura. Se hai più Salute dell\'obiettivo nemico, tutti i nemici adiacenti subiscono 10...30 danni da terra.'],
2148=>['Arma Separante','Magia Altera-arma. Per 4...10 secondo[i] i 3 attacchi successivi dell\'obiettivo alleato hanno un 10% di penetrazione dell\'armatura e provocano Armatura Incrinata per 5...20 secondo[i].','Magia Altera-arma. (Secondi: 4...10) Condizione inflitta dai 3 attacchi successivi dell\'obiettivo alleato: Armatura Incrinata (5...20 secondo[i]); sua penetrazione armatura: 10%.'],
2149=>['Arma del Rinnovamento','Magia Altera-arma. Per 5...20 secondo[i] la prossima volta che l\'obiettivo alleato colpisce con un\'abilità d\'attacco, ottiene 1...7 Punto[i] Energia.','Magia Altera-arma. (Secondi: 5...20) Energia conseguita dall\'obiettivo alleato la prossima volta che colpisce con un\'abilità d\'attacco: 1...7.'],
2150=>['Lancia Mutilante','Attacco con Lancia. Se questo attacco colpisce un nemico affetto da Emorragia gli provoca Storpiatura per 5...20 secondo[i].','Attacco con Lancia. Condizione inflitta se l\'obiettivo nemico soffre di Emorragia: Storpiatura (5...20 secondo[i]).'],
2186=>['Sigillo della Corruzione Letale','Sigillo. L\'obiettivo nemico infligge 5...35 danni per ogni condizione presente sull\'obiettivo nemico (danni max: 130).','Sigillo. Danni inferti per ogni condizione presente sull\'obiettivo nemico: 5...35 (max 130).'],
2187=>['Potere del Maestro','Incantesimo. Per 60 secondo[i], mentre impugni un\'arma (pugnali esclusi) la tua probabilità di assestare un colpo critico aumenta di un 3...33%.','Incantesimo. (Secondi: 60) Probabilità di assestare un colpo critico mentre impugni un\'arma (pugnali esclusi): +3...33%.'],
2188=>['Contamina Difese','Fattura. Per 5...20 secondo[i], la prossima volta che l\'obiettivo nemico blocca, subisce 30...120 danno[i].','Fattura. (Secondi: 5...20) Danni inferti la prossima volta che l\'obiettivo nemico blocca: 30...120.'],
2189=>['Sguardo dell\'Angorodon','Magia. Sottrai 10...50 Punto[i] Salute all\'obiettivo nemico; se sei affetto da una condizione ottieni 3...12 Punto[i] Energia.','Magia. Sottrazione Salute: 10...50. Energia conseguita se hai una condizione: 3...12.'],
2190=>['Flusso Magnetico','Incantesimo. L\'obiettivo nemico subisce 15...75 danni. Se sei sotto Sforzo, Flusso Magnetico incanta tutti gli alleati a portata d\'orecchio per 1...5 secondi per bloccare il prossimo attacco contro di essi.','Incantesimo. Danni inferti: 15...75. (Secondi: 1...5.) Se sei sotto Sforzo, incanta tutti gli alleati a portata d\'orecchio e blocca il prossimo attacco contro di essi.'],
2191=>['Terreno Sdrucciolevole','Magia. Se l\'obiettivo o i nemici adiacenti si muovono o sono colpiti da Accecamento, essi vengono abbattuti. 50% di possibilità di fallimento con una Magia dell\'Acqua inferiore a 5.','Magia. Provoca abbattimento se il nemico è affetto da Accecamento o si sta muovendo. Colpisce i nemici adiacenti al tuo obiettivo. 50% di probabilità di fallimento con Magia dell\'Acqua inferiore al grado 4.'],
2192=>['Ghiaccio Luminoso','Magia. L\'obiettivo nemico subisce 5...50 danni da freddo. Se quel nemico è affetto da una fattura della Magia dell\'Acqua, ottieni 5 Punti Energia e 1 Punto Energia per ogni 2 gradi della Riserva di Energia.','Magia. Danni da freddo inferti: 5...50. Energia conseguita se l\'obiettivo nemico è affetto da una fattura dell\'Acqua: 5 più 1 per ogni 2 gradi della Riserva di Energia.'],
2193=>['Esplosione di Energia','Magia. L\'obiettivo nemico subisce 1...2 danni per ogni punto di Energia che possiedi (max 130 danni).','Magia. Danni inferti per ogni Punto Energia che possiedi: 1...2 (max 130).'],
2194=>['Battuta Distraente','Attacco Ravvicinato. Se Battuta Distraente va a segno, non infligge danni e interrompe l\'azione dell\'obiettivo nemico. Se l\'obiettivo nemico ha un\'Armatura Incrinata, l\'abilità viene disattivata per 30 secondo[i].','Attacco Ravvicinato. Interrompe un\'azione. Effetto dell\'interruzione: se l\'obiettivo nemico ha un\'Armatura Incrinata, disattiva l\'abilità interrotta (30 secondo[i]). Non infligge alcun danno.'],
2195=>['Colpo Simbolico','Attacco Ravvicinato. Se questo attacco va a segno infliggi +12 danno[i] per ogni Sigillo che hai equipaggiato (max. 70 danno[i]).','Attacco Ravvicinato. Danni inferti per ogni Sigillo che hai equipaggiato: +12 (max 70).'],
2196=>['Velocità del Soldato','Posizione. Per 3...18 secondo[i], la tua velocità di movimento aumenta di un 15%. Incremento velocità di movimento mentre sei sotto gli effetti di un urlo o un canto: 15%.','Posizione. (Secondo[i]: 3...18). La tua velocità di movimento aumento di un 15% e di un 15% aggiuntivo se sotto l\'effetto di un urlo o un canto.'],
2197=>['Colpo al Corpo','Attacco Ravvicinato. Se questo attacco va a segno l\'obiettivo nemico subisce +10...40 danno[i]; se è affetto da Armatura Incrinata soffre di Ferita Profonda per 0...15 secondo[i].','Attacco Ravvicinato. Danni inferti: +10...40. Condizione inflitta se l\'obiettivo nemico ha Armatura Incrinata: Ferita Profonda (0...15 secondo[i]).'],
2198=>['Tiro al Corpo','Attacco con Arco. Se questo attacco va a segno, infliggi +5...20 danno[i]; se colpisce un nemico affetto da Armatura Incrinata, ottieni 5...10 Punto[i] Energia.','Attacco con Arco. Danni inferti: +5...20. Energia conseguita se l\'obiettivo nemico soffre di Armatura Incrinata: 5...10.'],
2199=>['Sigillo della Punta Avvelenata','Sigillo. Per 60 secondo[i] il tuo prossimo attacco provoca Avvelenamento per 8...15 secondo[i].','Sigillo. (Secondi: 60) Condizione inflitta con il prossimo attacco: Veleno (8...15 secondo[i]).'],
2200=>['Sigillo della Velocità Mistica','Sigillo. Per 30 secondi lanci istantaneamente i tuoi prossimi 1...3 incantesimi su te stesso[f:"stessa"]. Gli Incantesimi Lampo non consumano l\'utilizzo di questa abilità.','Sigillo. (Secondi: 30). 1...3 dei tuoi prossimi incantesimi su di te verranno lanciati istantaneamente. Gli Incantesimi Lampo non consumano l\'utilizzo di questa abilità.'],
2201=>['Scudo di Forza','Incantesimo Lampo. Per 1...16 secondi, blocca 1 dei prossimi attacchi contro di te. Se un attacco viene bloccato, tutti i nemici adiacenti in attacco vengono abbattuti e soffrono di Debolezza per 5...20 secondi.','Incantesimo Lampo. (Secondi: 1...16). Attacchi successivi verso di te bloccati: 1. Abbatte e infligge Debolezza (5...20 secondi a tutti i nemici adiacenti in attacco.'],
2202=>['Stretta Riparatrice','Magia. L\'obiettivo (un alleato o te stesso) viene curato di 30...90 Punto[i] Salute; se è sotto gli effetti di una magia altera-arma perde una condizione.','Magia. Cure: 30...90. Rimuove una condizione se l\'obiettivo alleato è affetto da una magia altera-arma.'],
2203=>['Aura dello Spirito Sanguisuga','Abilità. Per 5...20 secondi tutti i tuoi spiriti a portata d\'orecchio infliggono 5...20 danni in meno e sottraggono 5...20 Punti Salute quando sferrano un attacco.','Abilità. (Secondi: 5...20). Tutti i tuoi spiriti a portata d\'orecchio infliggono 5...20 danni in meno e sottraggono 5...20 Punti Salute quando sferrano un attacco.'],
2204=>['Ringiovanimento','Rituale Incatenante. Crei uno Spirito di livello 1...20 che cura di 3...10 Punto[i] Salute al secondo tutti i membri della squadra a portata d\'orecchio; lo Spirito perde 3...10 Punto[i] Salute per ogni membro della squadra così curato. Questo Spirito si esaurisce dopo 30...90 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...20 (in vita per 30...90 secondo[i]). Cure al secondo per i membri della squadra a portata d\'orecchio: 3...10. Costo cure: questo Spirito perde 3...10 Punto[i] Salute.'],
2205=>['Agonia','Rituale Incatenante. Crei uno Spirito di livello 1...12 che fa perdere 3...10 Punto[i] Salute al secondo ai nemici a portata d\'orecchio; lo Spirito perde 3...10 Punto[i] Salute per ogni nemico così colpito. Questo Spirito si esaurisce dopo 30...90 secondo[i].','Rituale Incatenante. Crei uno Spirito di livello 1...12 (in vita per 30...90 secondo[i]). Salute persa ogni secondo dai nemici a portata d\'orecchio: 3...10. Questo Spirito perde 3...10 Punto[i] Salute per ogni nemico che perde Salute.'],
2206=>['Arma Spettrale','Magia Altera-arma. Per 5...20 secondo[i] il prossimo attacco dell\'obiettivo alleato non può essere bloccato.','Magia Altera-arma. (Secondi: 5...20) L\'attacco successivo dell\'obiettivo alleato non è bloccabile. Impossibile selezionare se stessi.'],
2207=>['Discorso Ispiratore','Abilità. Perdi tutta l\'adrenalina e l\'obiettivo alleato ottiene 1...8 dose[i] di adrenalina.','Abilità. Adrenalina conseguita dall\'obiettivo alleato: 1...8. Impossibile selezionare se stessi. Perdi tutta l\'adrenalina.'],
2208=>['Scudo Ardente','Abilità. Per 3...9 secondo[i], mentre utilizzi uno scudo, la prossima abilità d\'attacco diretta contro di te viene bloccata. Se si tratta di un attacco ravvicinato, l\'attaccante prende fuoco per 1...6 secondo[i].','Abilità. (Secondi: 3...9) Blocca il prossimo attacco diretto contro di te. Condizione inflitta se si trattava di un attacco ravvicinato: Bruciatura (1...6 secondo[i]). Ha effetto solo se brandisci uno scudo.'],
2209=>['Lancia Sacra','Attacco con Lancia. Se questo attacco va a segno, infliggi +5...20 danno[i]; se colpisce una creatura evocata, tutti i nemici nei dintorni subiscono 15...90 danno[i] sacro[i] e prendono fuoco per 3 secondo[i].','Attacco con Lancia. Danni inferti: +5...20. Assesta 15...90 danno[i] sacro[i] e infligge Bruciatura (3 secondo[i]) ai nemici nei dintorni se colpisci una creatura evocata.'],
2210=>['Lancia Travolgente','Attacco con Lancia. Se questo attacco va a segno infliggi +5...20 danno[i] e l\'obiettivo nemico è affetto da Stordimento per 4...10 secondo[i]. Questo attacco ha una portata ravvicinata.','Attacco Ravvicinato con Lancia. Danni inferti: +5...20. Condizione inflitta: Stordimento (4...10 secondo[i]). Attacco a portata ravvicinata.'],
2211=>['Acido Alchemico di Alkar','Magia. Lanci l\'Acido Alchemico di Alkar contro l\'obiettivo nemico. L\'obiettivo e i nemici adiacenti subiscono 40...50 danno[i]. I Distruttori ricevono 45...70 danno[i] in più e soffrono di Armatura Incrinata per 14...20 secondo[i].','Magia. Proiettile. Danni all\'obiettivo e ai nemici adiacenti: 40...50. Danni aggiuntivi ai Distruttori: 45...70. Condizione inflitta ai Distruttori: Armatura Incrinata (14...20 secondo[i]).'],
2212=>['Luce di Deldrimor','Magia. Tutti i nemici nell\'area sono colpiti da 55...80 danno[i] sacro[i]; la posizione degli oggetti nascosti viene indicata per un breve periodo di tempo sulla tua bussola. Tutti gli oggetti nascosti nell\'area vengono rivelati.','Magia. Danni sacri ai nemici nell\'area: 55...80. Rivela la posizione degli oggetti nascosti entro l\'area della bussola.'],
2213=>['Mordi Orecchio','Abilità. L\'obiettivo nemico toccato subisce 50...70 danno[i] perforante[i] e soffre di Emorragia per 15...25 secondo[i].','Abilità a Tocco. Danni perforanti: 50...70. Condizione inflitta: Emorragia (15...25 secondo[i]).'],
2214=>['Colpo Basso','Abilità. L\'obiettivo nemico subisce 45...70 danni. Se viene abbattuto, subisce 30...50 danni in più ed è affetto da Armatura Incrinata per 14...20 secondi.','Abilità a Tocco. Danni inferti: 45...70. Per gli obiettivi nemici abbattuti: Danni inferti in più: 30...50. Condizione inflitta: Armatura Incrinata (14...20 secondi).'],
2215=>['Testata del Lottatore','Abilità. Esegui una testata contro il nemico toccato provocando 45...70 danno[i] e abbattendolo se lo colpisci.','Abilità a Tocco. Danni inferti: 45...70. Provoca abbattimento.'],
2216=>['"Non Inciampate!"','Urlo. Per 3...5 secondo[i] i membri della squadra a portata d\'orecchio non possono essere abbattuti.','Urlo. (Secondi: 3...5) Impedisce l\'abbattimento. Ha effetto sui membri della squadra a portata d\'orecchio.'],
2217=>['"Per il Martello di Ural!"','Urlo. Per 30 secondi tutti i membri della squadra morti a portata d\'orecchio vengono resuscitati con Salute ed Energia massima. I membri della squadra resuscitati provocano un 25...33% in più di danno. Al termine dell\'effetto, i membri della squadra colpiti muoiono. Questa abilità non provoca Debilitazione.','Urlo. (Secondi: 30). Resusciti tutti i membri della squadra morti a portata d\'orecchio con Salute ed Energia massima. I membri della squadra resuscitati provocano un 25...33% in più di danno. I membri della squadra resuscitati muoiono al termine, ma non ricevono Debilitazione.'],
2218=>['Maestro Ubriaco','Posizione. Per 72...90 secondo[i], la velocità dei tuoi movimenti e attacchi aumenta del 10...15%. Se attivi quest\'abilità mentre sei in stato di ebbrezza la velocità dei tuoi movimenti e attacchi aumenta invece di un 25...33%.','Posizione. (Secondi: 72...90) Incremento velocità tuoi movimenti e attacchi se non sei in stato d\'ebbrezza: 10...15%. Incremento velocità tuoi movimenti e attacchi se sei in stato d\'ebbrezza: 25...33%.'],
2219=>['Arma del Grande Nano','Magia Altera-arma. Per 20 secondo[i], l\'arma dell\'obiettivo alleato provoca +15...20 danno[i] e ha un 28...40% di probabilità di abbattere.','Magia Altera-arma. (Secondi: 20) Danno da arma: +15...20. Probabilità di provocare abbattimento con gli attacchi: 28...40%. Impossibile selezionare se stessi.'],
2220=>['Armatura del Grande Nano','Incantesimo. Per 22...40 secondo[i], l\'obiettivo alleato ottiene +24 di armatura, +60 di Salute massima e +24 in più di armatura contro i Distruttori.','Incantesimo. (Secondi: 22...40) Armatura: +24. Salute massima: +60. Armatura aggiuntiva contro i Distruttori: +24.'],
2221=>['Respiro del Grande Nano','Magia. Tutti i membri della squadra vengono curati dalla Bruciatura e ricevono 50...60 Punto[i] Salute.','Magia. Rimuove Bruciatura e cura di 50...60; ha effetto sui membri della squadra.'],
2222=>['Tempesta di Neve','Magia. Crei una Tempesta di Neve nella posizione dell\'obiettivo nemico. Per 5 secondo[i], i nemici a lui adiacenti subiscono 30...40 danno[i] da freddo al secondo.','Magia. Danni da freddo inferti al secondo: 30...40 (5 secondo[i]). Colpisce i nemici adiacenti alla posizione iniziale dell\'obiettivo nemico.'],
2223=>['Mina di Polvere Nera','Trappola. Quando la Mina di Polvere Nera viene attivata, tutti i nemici nei dintorni subiscono 20...30 danno[i], vengono Accecati e sono colpiti da Emorragia per 7...10 secondo[i]. La Mina di Polvere Nera termina dopo 90 secondo[i]. Mentre attivi questa abilità è facile interromperti.','Trappola. (Secondi: 90) Ha effetto sui nemici nei dintorni. Danni inferti: 20...30. Condizioni inflitte: Accecamento e Emorragia (7...10 secondo[i]). Facile interruzione.'],
2224=>['Invoca Mursaat','Magia. Invochi un Mursaat di livello 14...20 che vive per 40...60 secondo[i] e usa Scarica Snervante. È possibile mantenere attiva una sola invocazione Asura per volta.','Magia. Invochi un Mursaat di livello 14...20 (in vita per 40...60 secondo[i]) dotato di Scarica Snervante. È possibile mantenere attiva solo 1 invocazione Asura per volta.'],
2225=>['Invoca Djinn Rubino','Magia. Invochi un Djinn Rubino di livello 14...20 che vive per 40...60 secondo[i] e usa Immolazione. È possibile mantenere attiva una sola invocazione Asura per volta.','Magia. Invochi un Djinn Rubino di livello 14...20 (in vita per 40...60 secondo[i]) dotato di Immolazione. È possibile mantenere attiva solo 1 invocazione Asura per volta.'],
2226=>['Invoca Diavoletto del Ghiaccio','Magia. Invochi un Diavoletto del Ghiaccio di livello 14...20 che vive per 40...60 secondo[i] e usa Spine di Ghiaccio. È possibile mantenere attiva una sola invocazione Asura per volta.','Magia. Invochi un Diavoletto del Ghiaccio di livello 14...20 (in vita per 40...60 secondo[i]) dotato di Spine di Ghiaccio. È possibile mantenere attiva solo 1 invocazione Asura per volta.'],
2227=>['Invoca Sciamano Naga','Magia. Invochi uno Sciamano Naga di livello 14...20 che vive per 40...60 secondo[i] e usa Sassaiola. È possibile mantenere attiva una sola invocazione Asura per volta.','Magia. Invochi uno Sciamano Naga di livello 14...20 (in vita per 40...60 secondo[i]) dotato di Sassaiola. È possibile mantenere attiva solo 1 invocazione Asura per volta.'],
2228=>['Colpo Svelto','Attacco dalla Distanza. Se questo attacco va a segno l\'obiettivo nemico subisce 18...30 danno[i]; se soffre di Armatura Incrinata subisce Emorragia per 18...30 secondo[i].','Attacco dalla Distanza. Danni inferti: 18...30. Condizione inflitta se l\'obiettivo nemico ha Armatura Incrinata: Emorragia (18...30 secondo[i]).'],
2229=>['Sigillo dell\'Infezione','Sigillo. Se l\'obiettivo nemico soffre di Emorragia diventa affetto da Malattia per 13...20 secondo[i].','Sigillo. Condizione inflitta se l\'obiettivo nemico soffre di Emorragia: Malattia (13...20 secondo[i]).'],
2230=>['Sigillo del Triptofano','Sigillo. Per 14...20 secondi i movimenti e gli attacchi dell\'obiettivo nemico e di tutti i nemici adiacenti sono più lenti di un 23...40%.','Sigillo. (Secondi: 14...20) Rallentamento velocità di movimento e d\'attacco dell\'obiettivo e dei nemici adiacenti: 23...40%.'],
2231=>['Stendardo di Battaglia del Coraggio d\'Ebano','Guardia. Conficchi nella tua posizione uno Stendardo di Battaglia del Coraggio d\'Ebano. Per 14...20 secondo[i], gli alleati nell\'area (Spiriti esclusi) ottengono +24 di armatura e +24 in più di armatura contro i Charr.','Guardia. (Secondi: 14...20) Gli alleati in questa Guardia ottengono: armatura +24 e armatura +24 contro i Charr. Non ha effetto sugli Spiriti.'],
2232=>['Stendardo di Battaglia della Saggezza d\'Ebano','Guardia. Conficchi nella tua posizione uno Stendardo di Battaglia della Saggezza d\'Ebano. Per 14...20 secondo[i], gli alleati nell\'area (Spiriti esclusi) hanno un 44...60% di probabilità di dimezzare il tempo di ricarica delle magie lanciate.','Guardia. (Secondi: 14...20) Le magie lanciate dagli alleati in questa guardia hanno un 44...60% di probabilità di ricaricarsi con velocità superiore del 50%. Non ha effetto sugli Spiriti.'],
2233=>['Stendardo di Battaglia dell\'Onore d\'Ebano','Guardia. Conficchi nella tua posizione uno Stendardo di Battaglia dell\'Onore d\'Ebano. Per 14...20 secondo[i], gli alleati nell\'area (Spiriti esclusi) provocano +8...15 danno[i] e +7...10 in più contro i Charr.','Guardia. (Secondi: 14...20) Danni inferti dagli alleati in questa Guardia: +8...15. Danni ulteriori contro i Charr: +7...10. Non ha effetto sugli Spiriti.'],
2234=>['Cecchino di Supporto dell\'Avanguardia d\'Ebano','Magia. L\'obiettivo nemico subisce 54...90 danno[i] perforante[i] e soffre di Emorragia per 5...25 secondo[i]. Questo attacco ha un 10% di probabilità di assestare 540...900 danno[i] perforante[i] in più. Se colpisce un Charr ha un 25% di probabilità di assestare 540...900 danno[i] perforante[i] in più.','Magia. Danno perforante: 54...90. Condizione inflitta: Emorragia (5...25 secondo[i]). Probabilità di assestare +540...900 danno[i] perforante[i]: 10%. Probabilità di assestare +540...900 danno[i] perforante[i] ad un Charr: 25%.'],
2235=>['Assassino di Supporto dell\'Avanguardia d\'Ebano','Magia. Evochi un Assassino dell\'Avanguardia d\'Ebano di livello 14...20 che equipaggia: Palmo di Ferro, Denti di Volpe e Colpo a Nove Code. Questo Assassino compie un Passo dell\'Ombra verso l\'obiettivo nemico; se si tratta di un nemico Charr, l\'Assassino vive 24...30 secondo[i], altrimenti ha 12...15 secondo[i] di vita.','Magia. Evochi un assassino di livello 14...20 dotato di Palmo di Ferro, Denti di Volpe e Colpo a Nove Code che compie un Passo nell\'Ombra verso questo nemico. Se il nemico è un Charr, l\'assassino vive 24...30 secondo[i]. Se non è un Charr, l\'assassino vive 12...15 secondo[i].'],
2236=>['Pozzo della Rovina','Pozzo. Sfrutta il cadavere più vicino o sacrifica il 66% della tua salute per creare lì un Pozzo delle Rovine. Per 5...30 secondo/i, ogni volta che un nemico nel Pozzo riceve danni fisici, viene colpito da armatura spaccata per 5...20 secondo/i.','Pozzo. (5...30 secondo/i.) Infligge la condizione armatura spaccata (5...20 secondo/i) a tutti i nemici nel Pozzo che subiscono danni fisici. Utilizza un cadavere fresco o sacrifica il 66% della Salute.'],
2237=>['Atrofia','Fattura. Per 3...7 secondo[i] l\'attributo primario dell\'obiettivo nemico viene ridotto a 0.','Fattura. (Secondi: 3...7) Riduce l\'attributo primario di questo nemico a 0.'],
2238=>['Lancia della Redenzione','Attacco con Lancia. Se questo attacco va a segno, infliggi +5...20 danno[i]; se non va a segno perdi una condizione.','Attacco con Lancia. Danni inferti: +5...20. Se non va a segno perdi una condizione.'],
2353=>['"Finiscilo!"','Urlo. Se la Salute dell\'obiettivo nemico è inferiore al 50% subisce 44...80 danno[i] e soffre di Armatura Incrinata e Ferita Profonda per 12...20 secondo[i].','Urlo. Danni inferti: 44...80. Condizioni inflitte: Armatura Incrinata e Ferita Profonda (12...20 secondo[i]). Ha effetto solo se la Salute dell\'obiettivo è inferiore al 50%.'],
2354=>['"Schiva Questo!"','Urlo. Per 16...20 secondo[i], il tuo prossimo attacco non può essere bloccato e provoca +14...20 danno[i].','Urlo. (Secondi: 16...20) Il tuo prossimo attacco non è bloccabile e assesta +14...20 danno[i].'],
2355=>['Sono il Più Forte!','Urlo. Provochi +14...20 danno[i] in più con 5...8 dei tuoi attacchi successivi.','Urlo. Infliggi +14...20 danno[i] con 5...8 dei tuoi attacci successivi.'],
2356=>['"Non Mi Ferma Nessuno!"','Urlo. Per 16...20 secondo[i] hai +24 di armatura e non puoi essere abbattuto né subire Storpiatura.','Urlo. (Secondi: 16...20) Armatura: +24. Non puoi essere abbattuto né affetto da Storpiatura.'],
2357=>['Tocco d\'Astuzia','Fattura. L\'obiettivo nemico toccato subisce 44...80 danno[i]; se era stato abbattuto non potrà attaccare per 5...8 secondo[i].','Fattura a Tocco. Danni inferti: 44...80. L\'obiettivo nemico non può attaccare (5...8 secondo[i]) se era stato abbattuto.'],
2358=>['"Ti Muovi Come un Nano!"','Urlo. L\'obiettivo nemico viene abbattuto e subisce 44...80 danni. Inoltre, quel nemico soffre di Storpiatura per 8...15 secondi.','Urlo. Danni inferti: 44...80. Provoca abbattimento. Condizione inflitta: Storpiatura (8...15 secondi).'],
2359=>['"Siete dei Mollaccioni!"','Urlo. L\'obiettivo nemico e i nemici a lui adiacenti soffrono di Debolezza per 8...12 secondo[i].','Urlo. Condizione inflitta: Debolezza (8...12 secondo[i]). Ha effetto anche sui nemici adiacenti.'],
2360=>['Non Fa Male','Abilità. Per 30 secondo[i] hai una Rigenerazione della Salute di +2...3. Se sei in stato di ebbrezza quando attivi questa abilità hai anche +200...300 di Salute massima.','Abilità. (Secondi: 30) Rigenerazione tua Salute: +2...3. Salute massima se sei in stato d\'ebbrezza quando attivi questa abilità: +200...300.'],
2361=>['Mazza di Mille Orsi','Attacco Ravvicinato. Se questo attacco va a segno infliggi +6...9 danno[i] per ogni nemico adiacente (max. 60 danni). Se l\'obiettivo nemico non è umano viene abbattuto.','Attacco Ravvicinato. Danni inferti per ogni nemico adiacente: +6...9 (max 60). Provoca abbattimento se l\'obiettivo nemico non è umano.'],
2374=>['Benedizione dell\'Urside','Forma d\'Élite. Perdi tutti gli effetti e assumi le sembianze dell\'orsa. Per 60 secondo[i], hai 100 di armatura e 750...800 Punto[i] Salute. Il grado di tutti i tuoi attributi scende a 0 e gli attacchi dell\'orsa si sostituiscono alle tue abilità.','Forma d\'Élite. Perdi tutti gli effetti e assumi le sembianze dell\'orsa (60 secondo[i]). Il grado di tutti i tuoi attributi scende a 0 e gli attacchi dell\'orsa si sostituiscono alle tue abilità. Armatura: 100. Salute: 750...800.'],
2379=>['Benedizione Lupesca','Forma d\'Élite. Perdi tutti gli effetti e assumi le sembianze del lupo. Per 60 secondo[i], hai 80 di armatura, 660...700 Punto[i] Salute e una Rigenerazione Salute di 2...4. Il grado di tutti i tuoi attributi scende a 0 e gli attacchi del lupo si sostituiscono alle tue abilità.','Forma d\'Élite. Perdi tutti gli effetti e assumi le sembianze del lupo (60 secondo[i]). Il grado di tutti i tuoi attributi scende a 0 e gli attacchi del lupo si sostituiscono alle tue abilità. Armatura: 80. Salute: 660...700. Rigenerazione Salute: 2...4.'],
2384=>['Benedizione del Corvo','Forma d\'Élite. Perdi tutti gli effetti e assumi le sembianze del corvo. Per 60 secondo[i], hai 80 di armatura, 660...700 Punto[i] Salute e un 20...30% di probabilità di bloccare. Il grado di tutti i tuoi attributi scende a 0 e gli attacchi del corvo si sostituiscono alle tue abilità.','Forma d\'Élite. Perdi tutti gli effetti e assumi le sembianze del corvo (60 secondo[i]). Il grado di tutti i tuoi attributi scende a 0 e gli attacchi del corvo si sostituiscono alle tue abilità. Armatura: 80. Salute: 660...700. Probabilità di blocco: 20...30%.'],
2411=>['Piega Mente','Incantesimo. Per 10...16 secondi la tua velocità di movimento aumenta di un 20...33% e il tempo di lancio delle tue magie si riduce di un 20%.','Incantesimo. (Secondi: 10...16). Incremento della tua velocità di movimento: 20...33%. Riduzione del tempo di lancio delle tue magie: 20%.'],
2412=>['Criminale Raffinato','Magia. Dura 10...20 secondo[i]; una magia a caso dell\'obiettivo nemico viene disattivata e Criminale Raffinato viene sostituito da quella magia. Ottieni 5...10 Punto[i] Energia.','Magia. (Secondi: 10...20) Disattiva una magia. Questa abilità si trasforma in quella magia. Energia conseguita: 5...10.'],
2413=>['Tecnocratese','Magia. L\'obiettivo nemico e tutti i nemici adiacenti vengono colpiti da 30...40 danno[i]. Se non è un boss, quel nemico e tutti i nemici adiacenti subiscono Stordimento per 3...5 secondo[i].','Magia. Danni all\'obiettivo e ai nemici adiacenti: 30...40. Condizione inflitta su di loro se l\'obiettivo non era un boss: Stordimento (3...5 secondo[i]).'],
2414=>['Campo Radioattivo','Guardia. Per 5 secondi, i nemici nell\'area subiscono una Degenerazione della Salute di -4...6. Quando il portale si esaurisce i nemici nell\'area soffrono di Malattia per 12...20 secondo[i].','Guardia. (Secondi: 5) Degenerazione Salute dei nemici nell\'area: -4...6. Effetto al termine: infligge Malattia (12...20 secondo[i]) ai nemici nell\'area.'],
2415=>['Scansione Asura','Fattura. Per 9...12 secondi i tuoi attacchi non possono mancare l\'obiettivo nemico. Uccidendo un nemico sotto fattura Scansione Asura rimuove un 5% di Debilitazione.','Fattura. (Secondi: 9...12). Non puoi mancare l\'obiettivo nemico. Se uccidi questo nemico, perdi un 5% di Debilitazione.'],
2416=>['Aria di Superiorità','Abilità. Per 20...30 secondo[i] ottieni un beneficio Asura a caso ogni volta che consegui esperienza uccidendo un nemico.','Abilità. (Secondi: 20...30) Ottieni un beneficio Asura a caso ogni volta che consegui esperienza uccidendo un nemico.'],
2417=>['Blocco Mentale','Incantesimo. Per 5...11 secondo[i], hai una probabilità del 50% di bloccare gli attacchi. Questo incantesimo si riapplica ogni volta che un nemico ti colpisce.','Incantesimo. (Secondi: 5...11) Tua probabilità di blocco: 50%. Rinnovo: ogni volta che vieni colpito da un nemico.'],
2418=>['Invertitore del Dolore','Fattura. Per 6...10 secondo[i], ogni volta che l\'obiettivo nemico assesta danni subisce un 100...140% del danno causato (max. 80 danni).','Fattura. (Secondi: 6...10) Restituisce un 100...140% del danno (max 80) all\'obiettivo nemico ogni volta che assesta danni.'],
2420=>['Fuga d\'Ebano','Magia. Compi un Passo nell\'Ombra verso l\'obiettivo alleato; entrambi venite curati di 70...110 Punto[i] Salute.','Magia. Cure a te e all\'obiettivo alleato: 70...110. Effetto iniziale: compi un Passo nell\'Ombra verso questo alleato. Impossibile selezionare se stessi.'],
2421=>['Trappola della Debolezza','Trappola. Quando questa Trappola viene attivata, tutti i nemici nei dintorni soffrono di Debolezza per 10...20 secondo[i] e subiscono 24...50 danno[i] da fulmine. Tutti i Charr vengono abbattuti. La trappola termina dopo 90 secondi. Mentre attivi questa abilità è facile interromperti.','Trappola. (Secondi: 90) Ha effetto sui nemici nei dintorni. Danni da fulmine inferti: 24...50. Condizione inflitta: Debolezza (10...20 secondo[i]). Abbatte i Charr. Facile interruzione.'],
2422=>['Venti','Rituale dell\'Avanguardia d\'Ebano. Crei uno Spirito di livello 4...10. Tutti i nemici nella portata hanno un 15% di probabilità di mancare l\'obiettivo con gli attacchi a distanza. Lo Spirito si esaurisce dopo 54...90 secondo[i].','Rituale dell\'Avanguardia d\'Ebano. Crei uno Spirito di livello 4...10 (in vita per 54...90 secondo[i]). Ha effetto sui nemici nella portata. Probabilità di mancare con gli attacchi dalla distanza: 15%.'],
2423=>['Stabilità dei Nani','Incantesimo. Per 24...30 secondo[i] la durata delle tue posizioni aumenta di un 55...100%. Se attivi quest\'abilità mentre sei in stato di ebbrezza non puoi essere abbattuto.','Incantesimo. (Secondi: 24...30) Incremento durata delle tue posizioni: 55...100%. Non puoi essere abbattuto se l\'attivi mentre sei in stato d\'ebbrezza.'],
2657=>['Richiamo della Fretta (PvP)','Urlo. Per 30 secondi la velocità d\'attacco della tua mascotte aumenta del 25% e la sua velocità di movimento aumenta del 25%.','Urlo. (Secondi: 30). Incremento velocità di movimento e d\'attacco della tua mascotte: 25%.'],
2734=>['Relitto Mentale (PvP)','Fattura. Per 5...40 secondi, ogni volta che il nemico viene colpito da una delle tue abilità dell\'Ipnotizzatore che non rappresenta una fattura perde 1 Punto Energia. Se l\'Energia dell\'obiettivo nemico scende a 0, il Relitto Mentale termina e il nemico subisce 15...100 danni.','Fattura. (Secondi: 5...40.) Provoca la perdita di 1 Punto Energia ogni volta che il nemico viene colpito dalle tue abilità dell\'Ipnotizzatore che non rappresentano una fattura. Se l\'Energia dell\'obiettivo nemico scende a 0, il Relitto Mentale termina e il nemico subisce 15...100 danni.'],
2803=>['Mente Ghiacciata (PvP)','Fattura d\'Élite. L\'obiettivo nemico subisce 10...60 danni da freddo. Se ha meno Energia di te, subisce 10...60 danni da freddo in più e i suoi movimenti rallentano del 90% per 1...5 secondi.','Fattura d\'Élite. Danni da freddo inferti: 10...60. Se ha meno Energia di te, quel nemico subisce 10...60 danni da freddo in più e i suoi movimenti rallentano del 90% (1...5 secondi).'],
2804=>['Shock Mentale (PvP)','Magia d\'Élite. L\'obiettivo nemico subisce 10...50 danni da fulmine. Se ha meno Energia di te, subisce un danno da fulmine ulteriore di 10...50 e viene abbattuto. Questa magia ha una penetrazione dell\'armatura del 25%.','Magia d\'Élite. Danni da fulmine inferti: 10...50. Se la tua Energia è superiore a quella dell\'obiettivo, infligge +10...50 danni da fulmine e provoca abbattimento. Penetrazione armatura: 25%.'],
2805=>['Forma di Nebbia (PvP)','Incantesimo d\'Élite. Per 10...45 secondi, subisci un 33% di danni in meno dai nemici sotto gli effetti di una fattura della Magia dell\'Acqua. Quando lanci una magia elementale, tutti gli alleati a portata d\'orecchio (Spiriti esclusi) vengono curati di un 50...250% del costo in Energia della magia. Gli alleati con una Salute superiore all\'80% non vengono curati.','Incantesimo d\'Élite. (Secondi: 10...45.) Subisci un 33% di danni in meno dai nemici colpiti da Magia dell\'Acqua. Cura gli alleati a portata d\'orecchio (Spiriti esclusi) di un 50...250% del costo in Energia delle tue magie elementali. Gli alleati con una Salute superiore all\'80% non vengono curati.'],
2806=>['Guardia contro le Ferite (PvP)','Guardia d\'Élite. Crea una Guardia contro le Ferite in questa posizione. Per 5...15 secondi, gli Alleati (Spiriti esclusi) in quest\'area ottengono +1...3 di Rigenerazione della Salute, +12...24 armatura e un +12...24 armatura aggiuntivo contro i danni elementali. Questa magia verrà disabilitata per 30 secondi.','Guardia d\'Élite. (Secondi: 5...15.) Gli alleati in questa Guardia ottengono +1...3 di Rigenerazione della Salute, +12...24 armatura e un +12...24 armatura aggiuntivo contro i danni elementali. Non ha effetto sugli Spiriti. Questa magia verrà disabilitata per 30 secondi.'],
2807=>['Cavalca il Fulmine (PvP)','Magia d\'Élite. Cavalchi il fulmine contro l\'obiettivo. Tutti i nemici adiacenti vengono accecati per 1...5 secondi. Se l\'obiettivo è un nemico, subisce 10...70 danni da fulmine. Questa magia ha una penetrazione dell\'armatura del 25%.','Magia d\'Élite. Danni da fulmine inferti: 10...70. Penetrazione armatura: 25%. Condizione inflitta a tutti i nemici adiacenti: Accecamento (1...5 secondi). Ti sposti all\'istante verso il tuo obiettivo. Gli alleati possono essere un bersaglio.'],
2808=>['Percossa Furiosa (PvP)','Attacco d\'Élite con Martello. Se Percossa Furiosa va a segno ottieni 1...3 dosi di adrenalina. Se colpisci un nemico in movimento, gli infliggi +10...40 danni e il tuo obiettivo viene abbattuto.','Attacco d\'Élite con Martello. Adrenalina se vai a segno: 1...3. Infligge +10...40 danni e provoca abbattimento se il tuo obiettivo era in movimento.'],
2809=>['Fiamma di Ossidiana','Magia. Infliggi 22...92 danni all\'obiettivo nemico. Questa magia ignora l\'armatura.','Magia. Danni inferti: 22...92.'],
2857=>['Egida (PvP)','Incantesimo. Per 1...3 secondi, i compagni di squadra dell\'obiettivo non possono essere colpiti da magie ostili e gli attacchi contro l\'obiettivo non vanno a segno.','Incantesimo. (Secondi: 1...3). Il membro della squadra preso di mira non può essere colpito da magie ostili. Gli attacchi contro questo membro della squadra falliscono. Impossibile selezionare se stessi.'],
2858=>['"In Guardia!" (PvP)','Urlo. I membri della squadra a portata d\'orecchio ottengono +5...25 di armatura per 10 secondo[i]. Questo urlo termina dopo 1...3 attacchi in arrivo.','Urlo. (Secondi: 10) Incremento armatura dei membri della squadra a portata d\'orecchio: 5...25. Termina dopo 1...3 attacchi in arrivo.'],
2859=>['Indebolimento (PvP)','Magia. L\'obiettivo è colpito dalla Debolezza per 10...30 secondo[i].','Magia. Condizione inflitta: Debolezza (10...30 secondo[i]).'],
2860=>['Rinnovamento dell\'Etere (PvP)','Incantesimo d\'Élite. Per 10 secondi, ogni volta che lanci una magia, ottieni 1...3 Punti Energia e 5...20 Punti Salute per ogni incantesimo che hai addosso.','Incantesimo d\'Élite. (Secondi: 10.) Ogni volta che lanci una magia, ottieni 1...3 Punti di Energia e 5...20 di Salute per ogni incantesimo che hai addosso.'],
2861=>['Attacco Penetrante (PvP)','Attacco con Arco. Se va a segno, questo attacco provoca +5...15 danno[i] e ha un 10% di capacità di penetrazione delle armature.','Attacco con Arco. Danni inferti: +5...15. Penetrazione armatura: 10%.'],
2862=>['Forma d\'Ombra (PvP)','Incantesimo d\'Élite. Per 5...15 secondo[i], tutte le magie ostili lanciate contro di te falliscono e tutti gli attacchi contro di te vanno a vuoto. Quando la Forma d\'Ombra termina, rimani con solo 5...50 Punto[i] Salute.','Incantesimo d\'Élite. (Secondi: 5...15) Le magie ostili lanciate contro di te falliscono e gli attacchi contro di te vanno a vuoto. Effetto al termine: resti con 5...50 Punto[i] Salute solamente.'],
2863=>['Discordia (PvP)','Magia d\'Élite. Se l\'obiettivo nemico soffre di una condizione ed è sotto gli effetti di una fattura o di un incantesimo, quell\'obiettivo subisce 30...110 danno[i].','Magia d\'Élite. Danni inferti: 30...110. Ha effetto solo se l\'obiettivo nemico soffre di una condizione ed è affetto da fattura o incantesimo.'],
2864=>['Attacco della Separazione (PvP)','Attacco con Arco. Se va a segno, questo attacco provoca +5...15 danno[i] e ha un 10% di capacità di penetrazione delle armature.','Attacco con Arco. Danni inferti: +5...15. Penetrazione armatura: 10%.'],
2866=>['Carne della Mia Carne (PvP)','Magia. Perdi la metà della Salute. Fai resuscitare il membro della squadra selezionato con la tua Salute attuale e un 5...20% di Energia.','Magia. Resuscita il membro della squadra selezionato con metà della tua Salute attuale e un 5...20% di Energia. Perdi metà della tua Salute.'],
2867=>['Ira degli Antenati (PvP)','Abilità. Per 3 secondo[i] tutti i nemici adiacenti all\'obiettivo (un alleato o te stesso) subiscono 4...50 danno[i] da fulmine al secondo.','Abilità. (Secondi: 3) Assesta 4...50 danno[i] da fulmine al secondo ai nemici adiacenti all\'obiettivo alleato.'],
2868=>['Arma a Frammentazione (PvP)','Magia Altera-arma. Per 20 secondi, l\'obiettivo alleato ha un\'Arma a Frammentazione e in 1...5 degli attacchi successivi infliggerà 5...40 danni a un massimo di 4 nemici adiacenti.','Magia Altera-arma. (Secondi: 20) Gli attacchi assestano 5...40 danno[i] a 3 nemici adiacenti. Termina dopo 1...5 attacchi.'],
2869=>['Rimedio dell\'Assassino (PvP)','Incantesimo. Per 30 secondo[i], 1...10 delle abilità d\'attacco successive usate rimuovono una condizione.','Incantesimo. (Secondi: 30) 1...10 abilità d\'attacco che usi in seguito rimuovono una condizione.'],
2871=>['Luce di Liberazione (PvP)','Magia d\'Élite. Tutti i membri della squadra vengono curati di 5...70 Punto[i] Salute. Tutte le tue Preghiere Punitive vengono disattivate per 20 secondi.','Magia d\'Élite. Cure per l\'intera squadra: 5...70. Disattiva le tue Preghiere Punitive (20 secondi).'],
2872=>['Sigillo del Patto Mortale (PvP)','Sigillo. Fai resuscitare il membro della squadra selezionato con Salute equivalente alla tua Salute attuale e un 15...100% di Energia massima; la prossima volta che quell\'alleato muore nel giro di 120 secondo[i], morirai anche tu.','Sigillo. Resuscita il membro della squadra selezionato con la tua Salute attuale e un 15...100% di Energia massima. Per 120 secondo[i] potresti morire se questo membro della squadra muore.'],
2875=>['Lancio del Predatore (PvP)','Attacco con Lancia. Se questo attacco va a segno, infliggi +5...20 danno[i]; se colpisci un nemico in movimento, gli infliggi 5...40 danno[i] in più.','Attacco con Lancia. Danni inferti: +5...20. Assesta 5...40 danno[i] in più se l\'obiettivo si sta muovendo.'],
2876=>['Inno Difensivo (PvP)','Canto d\'Élite. Per 4...10 secondo[i], ogni membro della squadra a portata d\'orecchio ha un 50% di probabilità di bloccare gli attacchi in arrivo. Questo canto termina se il compagno di squadra mette a segno un\'abilità d\'attacco.','Canto d\'Élite. (Secondi: 4...10) Probabilità di bloccare dei membri della squadra a portata d\'orecchio: 50%. Termina se colpisci con un\'abilità d\'attacco.'],
2877=>['Ballata del Ripristino (PvP)','Canto. Per 10 secondo[i], la prossima volta che ogni membro della squadra a portata d\'orecchio subisce danni, ottiene 15...75 Punto[i] Salute.','Canto. (Secondi: 10) Salute ottenuta dai membri della squadra a portata d\'orecchio la prossima volta che subiscono danni: 15...75.'],
2878=>['Canto del Ripristino (PvP)','Canto d\'Élite. Per 10 secondo[i], la prossima volta che ogni membro della squadra a portata d\'orecchio usa un\'abilità, ottiene 45...110 Punto[i] Salute.','Canto d\'Élite. (Secondi: 10) Salute conseguita dai membri della squadra a portata d\'orecchio con l\'abilità successiva: 45...110.'],
2879=>['"Arrivano!" (PvP)','Urlo d\'Élite. Per 4...10 secondi la velocità di movimento di tutti gli alleati a portata d\'orecchio aumenta di un 33% e tali alleati ottengono 5...15 Punti Salute al secondo mentre si muovono.','Urlo d\'Élite. (Secondi: 4...10). Incremento velocità di movimento di tutti gli alleati a portata d\'orecchio: 33%. Punti Salute al secondo ottenuti in movimento: 5...15.'],
2880=>['"Mai Arrendersi!" (PvP)','Urlo. Per 10 secondo[i], tutti i membri della squadra a portata d\'orecchio con Salute inferiore al 75% ottengono una Rigenerazione della Salute di +1...5.','Urlo. (Secondi: 10) Rigenerazione Salute dei membri della squadra a portata d\'orecchio: +1...5. Ha effetto solo sui membri della squadra con Salute inferiore a 75%.'],
2883=>['"Giustizia è Fatta!" (PvP)','Urlo. Per 8 secondi, quando un tuo attacco va a segno ottieni 1 dose[i] di adrenalina in più.','Urlo. (Secondi: 8) Ottieni 1 dose[i] di adrenalina in più ogni volta che un tuo attacco va a segno.'],
2884=>['Rigenerazione Mistica (PvP)','Incantesimo. Per 5...20 secondo[i] ottieni una Rigenerazione della Salute di +1...4 per ogni incantesimo presente su di te (max 3 incantesimi).','Incantesimo. (Secondi: 5...20) Rigenerazione tua Salute per ogni incantesimo presente su di te (max 3): +1...4.'],
2885=>['Indebolimento del Sangue (PvP)','Magia. L\'obiettivo nemico e tutti quelli nei dintorni soffrono di Debolezza per 1...16 secondo[i].','Magia. Condizione inflitta a questo nemico e a quelli nei dintorni: Debolezza (1...16 secondo[i]).'],
2887=>['Sigillo del Giudizio (PvP)','Sigillo d\'Élite. L\'obiettivo nemico viene buttato a terra e sia lui che tutti i nemici adiacenti subiscono 5...50 danno[i] sacro[i]. La portata di questo Sigillo è la metà del normale.','Sigillo d\'Élite a Portata Dimezzata. Abbatte l\'obiettivo. Danni sacri all\'obiettivo e ai nemici adiacenti: 5...50.'],
2891=>['Aura inarrestabile (PvP)','Incantesimo d\'Élite. Riporta in vita il membro della squadra interessato con Salute ed Energia integre. Se l\'incantesimo viene interrotto o rimosso, il membro della squadra muore e lascia dietro di sé un cadavere non più sfruttabile. Chi muore mentre gode di Aura inarrestabile non incorre in penalità (probabilità di fallimento del 50% con Favore divino pari o inferiore a 4).','Incantesimo d\'Élite. Riporta in vita il membro della squadra prescelto (Salute ed Energia integre). Fine dell\'effetto: questo alleato muore e lascia dietro di sé un cadavere non più sfruttabile. Non si incorre in penalità per la morte. Probabilità di fallimento del 50% se non si possiede almeno 5 in Favore divino).'],
2892=>['Legame dello Spirito (PvP)','Incantesimo. Dura 8 secondo[i]; ogni volta che l\'obiettivo (un alleato o te stesso) subisce più di 50 danno[i] dai 10 attacchi o magie successivi, viene curato di 30...90 Punto[i] Salute.','Incantesimo. (Secondi: 8) Cura di 30...90 ogni volta che l\'obiettivo alleato riceve più di 50 danno[i]. Termina dopo che quest\'alleato ha subito danni da 10 attacchi o magie.'],
2893=>['Arma della Protezione (PvP)','Magia Altera-arma. Per 3...8 secondo[i], l\'obiettivo alleato ottiene un\'Arma della Protezione che gli dà una Rigenerazione della Salute di +2...4 e un 50% di probabilità di blocco. Se l\'alleato attacca, l\'Arma della Protezione termina.','Magia Altera-arma. (Secondo[i]: 3...8) Rigenerazione della Salute: +2...4. Probabilità di blocco: 50%. Termina se l\'alleato attacca.'],
2895=>['Soccorso del Punitore (PvP)','Incantesimo. Per 4 secondo[i], il bonus di Favore Divino per le tue Preghiere Punitive viene raddoppiato.','Incantesimo. (Secondi: 4) Raddoppia il bonus di cura del Favore Divino per le Preghiere Punitive.'],
2925=>['Tiro del Cacciatore Indolente (PvP)','Attacco con Arco. Se questo attacco va a segno l\'obiettivo nemico subisce +5...15 danno[i]; se non sta usando un\'abilità, il Tiro del Cacciatore Indolente provoca +5...20 danno[i] aggiuntivo[i].','Attacco con Arco. Danni inferti: +5...15. Danni inferti se l\'obiettivo nemico non sta usando un\'abilità: +5...20.'],
2959=>['Destrezza dell\'Esperto (PvP)','Posizione d\'Élite. Per 1...20 secondo[i] hai una velocità d\'attacco superiore di un 15% e il grado dell\'attributo Precisione aumenta di 1.','Posizione d\'Élite. (Secondi: 1...20) Aumento tua velocità d\'attacco: 15%. Incremento grado dell\'attributo Precisione: +1.'],
2965=>['Sigillo degli Spiriti (PvP)','Sigillo d\'Élite. Ottieni 3...12 Punto[i] Energia se ti trovi nella portata d\'orecchio di uno Spirito.','Sigillo d\'Élite. Energia conseguita: 3...12. Ha effetto solo se sei a portata d\'orecchio di uno Spirito.'],
2966=>['Sigillo della Potenza Spettrale (PvP)','Sigillo d\'Élite. Gli attacchi della creatura evocata dall\'alleato selezionato infliggono 5...35 danno[i] in più. Dopo 10 secondo[i] quella creatura viene distrutta.','Sigillo d\'Élite. Danni inferti dalla creatura evocata alleata selezionata: +5...35. Quella creatura viene distrutta dopo 10 secondo[i]).'],
2969=>['Senti il Vento (PvP)','Preparazione. Per 24 secondi, le tue frecce si muovono al doppio della velocità.','Preparazione. (Secondi: 24) Le tue frecce si muovono al doppio della velocità.'],
2998=>['Fragilità (PvP)','Fattura. Per 8...20 secondi l\'obiettivo nemico e i nemici adiacenti subiscono 5...20 danni ogni volta che viene loro inflitta una nuova condizione o se ne liberano.','Fattura. Colpisce con una fattura anche i nemici adiacenti all\'obiettivo (8...20 secondi). Danni inferti ai nemici ogni volta che ogni volta che viene loro inflitta una nuova condizione o se ne liberano: 5...20.'],
2999=>['Forza dell\'Onore (PvP)','Incantesimo. Se l\'incantesimo è attivo, l\'obiettivo (un alleato o te stesso) infligge 1...5 danni in più negli attacchi ravvicinati.','Incantesimo. L\'obiettivo (un alleato o te stesso) infligge 1...5 danni in più negli attacchi ravvicinati.'],
3002=>['Resistenza del Guerriero (PvP)','Posizione d\'Élite. Per 5...35 secondi ottieni 3 Punti Energia ogni volta che sferri un attacco ravvicinato. Con la Resistenza del Guerriero, la tua Energia non può aumentare al di sopra di 10...25.','Posizione d\'Élite. (Secondi: 5...35). Ottieni 3 Punti Energia ogni volta che sferri un attacco ravvicinato. Se la tua Energia è superiore a 10...25, non ottieni alcun Punto Energia.'],
3003=>['Armatura dell\'Insensibile (PvP)','Incantesimo. Per 10...35 secondi mentre lanci i rituali incatenanti hai una riduzione del danno di base di 10.','Incantesimo. (Secondi: 10...35). Riduzione del danno base mentre lanci rituali incatenanti: 10.'],
3005=>['Unione (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...8. Ogni volta che un Alleato (Spiriti esclusi) nel suo raggio di azione subisce danni o sottrazione salute, questi vengono ridotti di 15 e lo Spirito subisce 15 di danni. Lo spirito si esaurisce dopo 30...60 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...8 (in vita per 30...60 secondi). Ogni volta che un Alleato (Spiriti esclusi) nel suo raggio di azione subisce danni o sottrazione salute, questi vengono ridotti di 15 e lo Spirito subisce 15 di danni.'],
3006=>['Canto Ombroso (PvP)','Rituale Incatenante. Crei uno spirito di livello 1...6. I suoi attacchi infliggono 5...20 danni e provocano Accecamento per 1...6 secondi. Lo spirito muore dopo 30 secondi.','Rituale Incatenante. Crei uno spirito di livello 1...6 (in vita per 30 secondi). Danni inferti: 5...20. Condizione inflitta: Accecamento (1...6 secondi).'],
3007=>['Dolore (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...8. Gli attacchi dello spirito creato infliggono 5...30 danni. Lo spirito si esaurisce dopo 30...150 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...8 (in vita per 30...150 secondi). Gli attacchi dello spirito creato infliggono 5...30 danni.'],
3008=>['Distruzione (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...10 con 30 secondi di vita. Alla morte dello spirito, tutti i nemici nell\'area subiscono 1...10 di danno per ogni secondo in cui è rimasto in vita (max 150 di danno).','Rituale Incatenante. Crea 1...10 spirito[i] di livello (in vita per 30 secondi). Alla morte, ogni spirito infligge a tutti i nemici nell\'area 1...10 danno[i] per ogni secondo in cui è rimasto in vita (max 150 di danno).'],
3009=>['Rasserenamento (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...8. Tutti i nemici nel raggio d\'azione di tale spirito impiegano il doppio di tempo per generare Adrenalina. Lo spirito si esaurisce dopo 15...45 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...8 (in vita per 15...45 secondi). Il tempo di acquisizione di Adrenalina si raddoppia per i nemici nel raggio d\'azione.'],
3010=>['Spostamento (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...10. Tutti gli alleati (spiriti esclusi) nel raggio d\'azione hanno un 75% di probabilità di bloccare gli attacchi in arrivo. Ogni volta che un attacco viene bloccato in questo modo, lo spirito subisce 60 danni. Lo spirito si esaurisce dopo 30...60 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...10 (in vita per 30...60 secondi). Probabilità di blocco per gli alleati (spiriti esclusi) nel raggio di azione: 75%. Effetto al termine: lo spirito riceve 60 danni.'],
3011=>['Preservazione (PvP)','Rituale Incatenante d\'Élite. Crea uno spirito di livello 1...10. Ogni 4 secondi questo spirito cura un alleato nell\'area (spiriti esclusi) di 10...115 Punti Salute. Lo spirito si esaurisce dopo 90 secondi.','Rituale Incatenante d\'Élite. Crea uno spirito di livello 1...10 (in vita per 90 secondi). Ogni 4 secondi questo spirito cura un alleato (spiriti esclusi) di 10...115.'],
3012=>['Vita (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...10. Quando lo spirito si esaurisce, tutti gli alleati (spiriti esclusi) nel suo raggio d\'azione vengono curati di 1...7 Punti Salute per ogni secondo di vita dello spirito. Lo spirito si esaurisce dopo 20 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...10 (in vita per 20 secondi). Ha effetto sugli alleati (spiriti esclusi) nel raggio d\'azione. Effetto al termine: cura di 1...7 per secondo di vita dello spirito.'],
3013=>['Recupero (PvP)','Rituale Incatenante. Crea uno Spirito di livello 1...10. Tutti gli alleati (Spiriti esclusi) nel raggio d\'azione ottengono una Rigenerazione della Salute di +1...3. Lo Spirito muore dopo 15...45 secondi.','Rituale Incatenante. Crea uno Spirito di livello 1...10 (in vita per 15...45 secondi). Rigenerazione Salute ottenuta da tutti gli alleati (Spiriti esclusi) nel raggio d\'azione: +1...3.'],
3014=>['Dissonanza (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...8. Lo spirito infligge 5...20 danni ed interrompe tutti quelli che vengono colpiti. Lo spirito si esaurisce dopo 10...25 secondi.','Rituale Incatenante. Crea uno Spirito di livello 1...8 (in vita per 10...25 secondi). Danno inferto dai suoi attacchi: 5...20; interrompe le azioni.'],
3015=>['Legaterra (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...10. Tutti i nemici (spiriti esclusi) abbattuti nel raggio d\'azione dello spirito creato restano a terra per almeno 3 secondi. Ogni volta che ciò accade, lo spirito perde 50...25 Punti Salute. Lo spirito si esaurisce dopo 15...45 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...10 (in vita per 15...45 secondi). Ogni volta che i nemici (spiriti esclusi) nel raggio d\'azione vengono abbattuti restano a terra per almeno 3 secondi. Costo dell\'abbattimento: lo spirito perde 50...25 Punti Salute.'],
3016=>['Riparo (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...8. Gli alleati (spiriti esclusi) nel raggio d\'azione dello spirito creato non possono perdere più del 10% della loro Salute massima a seguito di un singolo attacco. Quando lo spirito impedisce il danno, perde 75...45 Punti Salute. Lo spirito si esaurisce dopo 30...60 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...8 (in vita per 30...60 secondi). Gli alleati (spiriti esclusi) nel raggio d\'azione dello spirito creato non possono perdere più del 10% della loro Salute massima a seguito di un singolo attacco. Costo di prevenzione del danno: lo spirito perde 75...45 Punti Salute.'],
3017=>['Disincanto (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...8. Lo spirito provoca 5...20 danni e chiunque venga colpito dal suo attacco perde un incantesimo. Lo spirito si esaurisce dopo 15...40 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...8 (in vita per 15...40 secondi). Se attacca, assesta 5...20 secondi e rimuove un incantesimo.'],
3018=>['Ripristino (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...10. Quando lo spirito si esaurisce, tutti i membri della squadra nell\'area risorgono con 5...50% Punti Salute e zero Energia. Lo spirito si esaurisce dopo 30 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...10 (in vita per 30 secondi). Effetto al termine: resusciti i membri della squadra nell\'area (Salute: 5...50%; Energia: 0).'],
3019=>['Canto Sanguinario (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...8 che si esaurisce dopo 30...150 secondi. I suoi attacchi sottraggono fino a 5...25 Punti Salute.','Rituale Incatenante. Crea uno spirito di livello 1...8 (in vita per 30...150 secondi). Salute sottratta dai suoi attacchi: 5...25.'],
3020=>['Spirito Vagabondo (PvP)','Rituale Incatenante d\'Élite. Crea uno spirito di livello 1...8. Ogni volta che i suoi attacchi colpiscono un nemico fermo, lo abbattono e lo spirito perde 70...50 Punti Salute. Lo spirito si esaurisce dopo 30...60 secondi.','Rituale Incatenante d\'Élite. Crea uno spirito di livello 1...8 (in vita per 30...60 secondi). I suoi attacchi contro i nemici fermi provocano abbattimento Costo dell\'abbattimento: lo spirito perde 70...50 Punti Salute.'],
3021=>['Calore della Savana (PvP)','Magia d\'Élite. Crei Calore della Savana nella posizione dell\'obiettivo nemico. Per 5 secondi, tutti i nemici nei dintorni subiscono 5...20 danni da fuoco per ogni secondo di attività della magia.','Magia d\'Élite. Assesta 5...20 danni da fuoco per ogni secondo successivo al lancio della magia (5 secondi). Colpisce i nemici vicini alla posizione iniziale dell\'obiettivo.'],
3022=>['Sguardo della Furia (PvP)','Rituale Incatenante. Distrugge lo Spirito alleato preso di mira e crea uno Spirito della Furia di livello 1...10, i cui attacchi infliggono 5...20 danni. Lo Spirito muore dopo 30...60 secondi.','Rituale Incatenante. Distrugge uno Spirito alleato. Crea uno Spirito di livello 1...10 (in vita per 30...60 secondi). Danni inferti dai suoi attacchi: 5...20.'],
3023=>['Angoscia (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...7. I suoi attacchi infliggono 5...20 danni e provocano il doppio dei danni sui nemici affetti da fattura. Lo spirito si esaurisce dopo 15...45 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...7 (in vita per 15...45 secondi). Gli attacchi dello spirito creato infliggono 5...20 danni. Danno doppio ai nemici affetti da fattura.'],
3024=>['Autorizzazione (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...10. Tutti gli alleati nel raggio d\'azione dello spirito creato che hanno in mano un oggetto ottengono 15...45 Punti di Salute massima e 10 di Energia massima. Lo spirito si esaurisce dopo 15...60 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...10 (in vita per 15...60 secondi). Gli alleati nel raggio d\'azione dello spirito creato che hanno in mano un oggetto ottengono 15...45 Punti di Salute massima e 10 di Energia massima.'],
3025=>['Ripresa (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...10. Le condizioni che affliggono gli alleati nel raggio d\'azione dello spirito creato si esauriscono ad una velocità maggiore del 20...50%. Lo spirito si esaurisce dopo 30...60 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...10 (in vita per 30...60 secondi). Incremento velocità di esaurimento delle condizioni sugli alleati nel raggio d\'azione dello spirito creato: 20...50%.'],
3026=>['"Punta agli Occhi!" (PvP)','Urlo. Dura 10 secondi; la prossima volta che ogni alleato a portata d\'orecchio compie un attacco ci sarà un 30...75% di probabilità che sia critico.','Urlo. (Secondi: 10). Aumento probabilità degli alleati a portata d\'orecchio di assestare un colpo critico con il loro attacco successivo: +30...75%.'],
3027=>['"Preparatevi!" (PvP)','Urlo. Per 5...15 secondi i colpi che provocherebbero l\'abbattimento dell\'alleato infliggeranno 15...90 danni a tutti i nemici nei dintorni.','Urlo. (Secondi: 5...15). Previene il prossimo abbattimento; assesta 15...90 danni ad un nemico vicino all\'obiettivo alleato. Impossibile selezionare se stessi.'],
3028=>['Finale Ardente (PvP)','Eco. Dura 10...35 secondi; ogni volta che un canto o un urlo termina sull\'obiettivo alleato (spiriti esclusi) tutti i nemici adiacenti a quell\'alleato prendono fuoco per 1...5 secondi.','Eco. (Secondi: 10...35). Condizione inflitta ai nemici adiacenti ogni volta che un canto o urlo termina sull\'obiettivo alleato: Bruciatura (1...5 secondi). Impossibile selezionare gli spiriti.'],
3029=>['Ritornello Ruotalama (PvP)','Eco. Per 20 secondi l\'obiettivo alleato (spiriti esclusi) ha +10...40 di armatura contro i danni da taglio. Questa eco si rinnova ogni volta che un canto o un urlo finisce su quell\'alleato.','Eco. (Secondi: 20). Armatura dell\'obiettivo alleato contro il danno da taglio: +10...40. Rinnovo: ogni volta che un canto o un urlo termina su quell\'alleato. Impossibile selezionare gli spiriti.'],
3030=>['Sigillo del Ritorno (PvP)','Sigillo. Resuscita il compagno di squadra preso di mira con un 5...20% di Salute e un 1...4% di Energia per ogni membro della squadra a portata d\'orecchio.','Sigillo. Resuscita il membro della squadra preso di mira (5...20% di Salute e 1...4% di Energia per ogni membro della squadra a portata d\'orecchio).'],
3031=>['"Vietato Toccare!" (PvP)','Urlo. Per 20 secondi 1...5 delle abilità di tocco successive usate contro gli alleati a portata d\'orecchio falliranno.','Urlo. (Secondi: 20). 1...5 delle abilità di tocco successive usate contro gli alleati a portata d\'orecchio falliranno.'],
3032=>['"Non Muovetevi!" (PvP)','Urlo. Per 5...20 secondi tutti i membri della squadra a portata d\'orecchio ottengono +24 di armatura quando restano fermi. Termina per i membri della squadra quando sferrano un attacco.','Urlo. (Secondi: 5...20) I membri della squadra a portata d\'orecchio ottengono +24 di armatura quando restano fermi. Termina per un alleato quando sferra un attacco.'],
3033=>['"Torneremo!" (PvP)','Urlo. Per 10 secondi ogni volta che i membri della squadra che si trovano a portata d\'orecchio usano un\'abilità di resurrezione, i loro alleati caduti tornano in vita con un 10...75% in più di Salute e 5...50% in più di Energia.','Urlo. (Secondi: 10). Ogni volta che i membri della squadra a portata d\'orecchio usano un\'abilità di resurrezione, i loro alleati caduti tornano in vita con un 10...75% in più di Salute e un 5...50% in più di Energia.'],
3034=>['"Scopri la Loro Debolezza!" (PvP)','Urlo. Dura 5...20 secondi; la prossima volta che l\'obiettivo alleato sferra un attacco critico, infligge anche una Ferita Profonda per 5...20 secondi.','Urlo. (Secondi: 5...20). Condizione inflitta dall\'obiettivo alleato con il prossimo attacco critico: Ferita Profonda (5...20 secondi).'],
3035=>['"Non Datevi per Vinti!"  (PvP)','Urlo. Tutti gli alleati a portata d\'orecchio con Salute inferiore al 75% ottengono 1...10 Punti Energia.','Urlo. Energia per gli alleati a portata d\'orecchio: 1...10. Ha effetto solo sugli alleati con Salute inferiore a 75%.'],
3036=>['"Aiuto!" (PvP)','Urlo. Il bersaglio alleato (purché non sia uno spirito) ottiene 5...50 Salute. Per 1...10 secondo/i, le magie degli altri alleati indirizzate su quel personaggio vengono lanciate il 50% più velocemente.','Urlo. (1...10 secondo/i). Il bersaglio alleato non spirito ottiene 5...50 Salute, le magie degli altri alleati indirizzate su quel personaggio vengono lanciate il 50% più velocemente.'],
3037=>['"Ripieghiamo!" (PvP)','Urlo. Per 4...10 secondi tutti gli alleati a portata d\'orecchio ottengono 5...15 Punti Salute al secondo mentre si muovono e la loro velocità di movimento aumenta del 33%. Questa abilità termina su un alleato affetto da questo urlo se questi mette a segno un attacco.','Urlo. (Secondi: 4...10). Incremento velocità di movimento di tutti gli alleati a portata d\'orecchio: 33%. Salute conseguita mentre si muovono: 5...15. Termina per un alleato se un suo attacco va a segno.'],
3038=>['Agonia (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...8. Lo spirito fa perdere 3...10 Punti Salute al secondo ai nemici a portata d\'orecchio. Lo spirito perde 3...10 Punti Salute per ogni nemico così colpito. Lo spirito si esaurisce dopo 30...90 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...8 (in vita per 30...90 secondi). Salute persa ogni secondo dai nemici a portata d\'orecchio: 3...10. Lo Spirito perde 3...10 Punti Salute per ogni nemico che perde Salute.'],
3039=>['Ringiovanimento (PvP)','Rituale Incatenante. Crea uno spirito di livello 1...16. Lo spirito cura di 3...10 Punti Salute al secondo tutti i membri della squadra a portata d\'orecchio. Lo spirito perde 3...10 Punti Salute per ogni membro della squadra così curato. Lo spirito si esaurisce dopo 30...90 secondi.','Rituale Incatenante. Crea uno spirito di livello 1...16 (in vita per 30...90 secondi). Cure al secondo per i membri della squadra a portata d\'orecchio: 3...10. Costo cure: lo spirito perde 3...10 Punti Salute.'],
3040=>['Inno del Disturbo (PvP)','Canto. Per 1...10 secondi la prossima abilità d\'attacco usata da ogni alleato a portata d\'orecchio interrompe anche un\'azione.','Canto. (Secondi: 1...10). Gli alleati a portata d\'orecchio interrompono un\'azione con l\'abilità d\'attacco successiva.'],
3045=>['Conforta Animale (PvP)','Abilità. La tua mascotte viene curata di 40...120 Punti Salute. Se è morta, viene resuscitata con un 10...58% di Salute. Se disponi di Conforta Animale, la mascotte potrà viaggiare insieme a te.','Abilità. Salute ottenuta dalla tua mascotte: 40...120. La mascotte resuscita (Salute: 10...58%). Se disponi di Conforta Animale, la mascotte potrà viaggiare insieme a te.'],
3047=>['Assalto di Melandru (PvP)','Attacco con Mascotte. La tua mascotte si cimenta in un Assalto di Melandru che infligge +5...20 di danni. Se l\'attacco colpisce un nemico sotto incantesimo, tale nemico e tutti i nemici adiacenti subiscono +5...35 danni aggiuntivi.','Attacco con Mascotte. Danni inferti: +5...20. Ulteriori danni inferti all\'obiettivo e ai nemici adiacenti se il nemico è sotto incantesimo: +5...35.'],
3048=>['Coltre d\'Angoscia (PvP)','Incantesimo. Per 30...60 secondi, se la tua Salute è inferiore a un 50% hai un 75% di probabilità di bloccare gli attacchi.','Incantesimo. (Secondi: 30...60). Probabilità di blocco: 75%. Ha effetto solo se la tua Salute è inferiore a un 50%.'],
3049=>['Furia Invisibile (PvP)','Posizione. Per 15...60 secondi non puoi essere bloccato dai nemici accecati.','Posizione. (Secondi: 15...60). Non puoi essere bloccato dai nemici accecati.'],
3050=>['Legame Predatore (PvP)','Urlo. Per 5...20 secondi gli attacchi messi a segno dalla tua mascotte ti curano di 1...31 Punti Salute.','Urlo. (Secondi: 5...20). Punti Salute ottenuti ogni volta che la tua mascotte mette a segno un attacco: 1...31.'],
3051=>['Guizzo Furioso (PvP)','Attacco d\'Élite con Mascotte. La tua mascotte si cimenta in un Guizzo Furioso che infligge +3...23 di danni (bonus massimo 60) per ogni abilità di Potere sulle Belve che si sta ricaricando.','Attacco d\'Élite con Mascotte. Danni inflitti per ogni abilità di Potere sulle Belve che si sta ricaricando: +3...23 (max 60).'],
3053=>['Sigillo della Corruzione Letale (PvP)','Sigillo. Deve seguire un attacco doppio. L\'obiettivo nemico infligge 5...35 danni per ogni condizione presente sull\'obiettivo nemico (danni max: 130).','Sigillo. Danni inferti per ogni condizione presente sull\'obiettivo nemico: 5...35 (max 130). Deve seguire un attacco doppio.'],
3054=>['Masochismo (PvP)','Incantesimo. Per 30 secondi ottieni 1...3 Punti Energia ogni volta che sacrifichi Salute.','Incantesimo. (Secondi: 30). Punti Energia ottenuti ogni volta che sacrifichi Salute: 1...3.'],
3058=>['Empio Banchetto (PvP)','Magia. Sottrai fino a 10...65 Punti Salute ad un massimo di 1...4 nemici nell\'area.','Magia. Punti Salute sottratti a 1...4 nemici nell\'area intorno a te: 10...65.'],
3059=>['Sigillo dell\'Agonia (PvP)','Sigillo. Soffri di Emorragia per 25 secondi. Tutti i nemici nei dintorni subiscono 10...70 danni.','Sigillo. Danni inferti ai nemici nei dintorni: 10...70. Tu inizi a sanguinare (25 secondi).'],
3060=>['Fuga (PvP)','Posizione d\'Élite. Per 1...8 secondi la tua velocità aumenta del 33% e hai una probabilità del 75% di bloccare gli attacchi. Termina se sferri un attacco ravvicinato.','Posizione d\'Élite. (Secondi: 1...8). Incremento della tua velocità di movimento: 33%. Probabilità di blocco: 75%. Termina se sferri un attacco ravvicinato.'],
3061=>['Fiore della Morte (PvP)','Attacco Doppio[_]. Deve seguire un attacco con arma secondaria. Se va a segno, l\'obiettivo nemico subisce danni pari a +20...45 e tutti i nemici adiacenti subiscono danni pari a 20...45.','Attacco Doppio[_]. Danni inferti: +20...45. Colpisce anche i nemici adiacenti all\'obiettivo. Deve seguire un attacco con arma secondaria.'],
3062=>['Finale del Ripristino (PvP)','Eco. Per 10...35 secondi 5 dei tuoi prossimi canti o urli che terminano sull\'obiettivo (un alleato o te stesso, Spiriti esclusi) curano l\'alleato di 15...75 Punti Salute.','Eco. (Secondi: 10...35). Punti Salute conseguiti dall\'obiettivo (un alleato o te stesso) per 5 dei tuoi prossimi canti o urli che terminano su di lui: 15...75. Impossibile selezionare gli Spiriti.'],
3063=>['Mantra della Risoluzione (PvP)','Posizione. Per 5 secondi gli avversari non potranno interromperti, ma per ogni tentativo che faranno perderai 10...4 Punti Energia oppure il Mantra della Risoluzione terminerà.','Posizione. (Secondi: 5). Previene le interruzioni contro di te. Costo di prevenzione: perdi 10...4 Punti Energia oppure il Mantra della Risoluzione terminerà.'],
3141=>['Riflessi Fulminei (PvP)','Posizione. Per 5...11 secondi hai un 75% di probabilità di bloccare gli attacchi ravvicinati e proiettile e la tua velocità d\'attacco aumenta di un 33%.','Posizione. (Secondi: 5...11) Incremento della tua velocità d\'attacco: 33%. Probabilità di blocco: 75%.'],
3143=>['Percossa Rinnovatrice (PvP)','Attacco con Martello. Se Percossa Rinnovatrice va a segno, infligge +5...20 danno[i]. Se colpisci un nemico a terra, ottieni 3 Punto[i] Energia; questo attacco si ricarica istantaneamente.','Attacco con Martello. Danni inferti: +5...20. Ottieni 3 Punto[i] Energia e questo attacco si ricarica istantaneamente se il nemico è a terra.'],
3144=>['Guarigione Congiunta (PvP)','Abilità d\'Élite. Se la tua Salute o quella della tua mascotte è inferiore a un 75%, venite curati[f:"curate"] entrambi[f:"entrambe"] di 25...145 Punti Salute. Se la tua mascotte è morta, viene resuscitata con un 50% di Salute.','Abilità d\'Élite. Cure per te e la tua mascotte: 25...145. Se la mascotte è morta, viene resuscitata con il 50% di Salute. Non ha effetto se né la tua Salute né quella della tua mascotte è inferiore a un 75%.'],
3145=>['Frecce di Vetro (PvP)','Preparazione d\'Élite. Per 10...35 secondi le tue frecce infliggono +6...18 di danni se vanno a segno e provocano Emorragia per 10...20 secondi se vengono bloccate.','Preparazione d\'Élite. (Secondi: 10...35) Danni inferti con le frecce: +6...18. Condizione inflitta se vengono bloccate: Emorragia (10...20 secondi).'],
3147=>['Freccia Affilata (PvP)','Attacco con Arco. Se va a segno, infligge +5...15 di danni. Se si tratta di un colpo critico, infligge +5...30 di danni aggiuntivi.','Attacco con Arco. Danni inferti: +5...15. Infligge +5...30 di danni se si tratta di un colpo critico.'],
3148=>['Inno dell\'Invidia (PvP)','Canto. Per 10 secondi l\'abilità d\'attacco successiva utilizzata da ogni alleato a portata d\'orecchio infligge +10...20 di danni ai nemici con Salute superiore a un 50%.','Canto. (Secondi: 10) Danni inferti dagli alleati a portata d\'orecchio con l\'abilità d\'attacco successiva: +10...20. Il danno extra si applica solo ai nemici con Salute superiore a un 50%.'],
3149=>['Ritornello Riparatore (PvP)','Eco. Per 15 secondi ottieni una Rigenerazione della Salute di +2...3. L\'eco si rinnova ogni volta che un canto o un urlo termina su di te.','Eco. (Secondi: 15) Rigenerazione Salute ottenuta: +2...3. Rinnovo: ogni volta che un canto o un urlo termina su di te.'],
3151=>['Empatia (PvP)','Fattura. Per 5...15 secondi, ogni volta che l\'obiettivo nemico attacca subisce 15...45 danni.','Fattura. (Secondi: 5...15). Quando attacca, l\'obiettivo nemico subisce 15...45 danni.'],
3152=>['Angoscia Paralizzante (PvP)','Fattura d\'Élite. Per 5...20 secondi l\'obiettivo nemico si muove più lentamente di un 50% e subisce una Degenerazione della Salute di -2...6.','Fattura d\'Élite. (Secondi: 5...20). L\'obiettivo nemico si muove più lentamente di un 50% e subisce una Degenerazione Salute di -2...6.'],
3156=>['Posizione del Soldato (PvP)','Posizione d\'Élite. Per 4...10 secondo[i], la tua velocità d\'attacco aumenta di un 33% mentre sei sotto l\'influenza di un urlo o un canto.','Posizione d\'Élite. (Secondo[i]: 4...10). Incremento velocità d\'attacco mentre sei sotto gli effetti di un urlo o un canto: 33%.'],
3157=>['Glaive era Distruttiva (PvP)','Magia d\'Élite Altera-oggetto. Mantieni le ceneri di Glaive per un massimo di 30...60 secondo[i]. Mentre mantieni le ceneri di Glaive, tutte le abilità Ritualista ricevono 10% di penetrazione armatura. Quando rilasci le ceneri, tutti i nemici nell\'area subiscono 15...85 danno[i] da fulmine.','Magia d\'Élite Altera-oggetto. (Secondo[i]: 30...60). Le tue abilità Ritualista aumentano di 10% di penetrazione armatura. Rilascio: Danni da fulmine inferti a tutti i nemici nell\'area: 15...85.'],
3179=>['Mantra dei Sigilli (PvP)','Posizione. Per 10...40 secondo/i, hai +3 di armatura per ogni sigillo equipaggiato. Ogni volta che usi un sigillo, ottieni 5...60 Salute.','Posizione. (10...40 secondo/i). Hai +3 di armatura per ogni sigillo. Ottieni 5...60 Salute ogni volta che usi un sigillo.'],
3180=>['Delusioni Infrante (PvP)','Magia. Rimuovi una fattura da Ipnotizzatore dal bersaglio nemico. Se rimuovi una fattura, il bersaglio subisce 15...75 danni e tutti i nemici adiacenti subiscono il 75% di quei danni.','Magia. Rimuove una fattura da Ipnotizzatore dal bersaglio nemico. Effetto della rimozione: 15...75 danni al bersaglio e il 75% di quei danni a tutti i nemici adiacenti.'],
3181=>['Armamento Illusorio (PvP)','Incantesimo d\'Élite. Per 30 secondi i tuoi attacchi ravvicinati non colpiscono e non vanno a vuoto. L\'Armamento Illusorio infligge 20...60 danni agli obiettivi per ogni attacco ravvicinato.','Incantesimo d\'Élite. (Secondi: 30). Infligge 20...60 danni ai nemici anziché altri danni o effetti provocati dagli attacchi ravvicinati. Gli attacchi ravvicinati non colpiscono e non vanno a vuoto.'],
3183=>['Emicrania (PvP)','Fattura d\'Élite. Per 4...16 secondi l\'obiettivo nemico subisce una Degenerazione Salute di -1...8 e il tempo richiesto per l\'attivazione delle sue abilità aumenta di un 100%.','Fattura d\'Élite. (Secondi: 4...16). Degenerazione Salute causata: -1...8. Raddoppia il tempo di attivazione delle abilità.'],
3184=>['Dolore Accumulato (PvP)','Magia. L\'obiettivo nemico subisce 10...35 danni. Se l\'obiettivo nemico è sotto gli effetti di 2 o più fatture, soffre di Ferita Profonda per 5...20 secondi.','Magia. Danni inferti: 10...35. Condizione inflitta se l\'obiettivo è sotto gli effetti di 2 o più fatture: Ferita Profonda (secondi: 5...20).'],
3185=>['Instabilità Psichica (PvP)','Magia d\'Élite. Interrompe l\'azione dell\'obiettivo nemico. Se l\'azione è un\'abilità, l\'obiettivo nemico e tutti i nemici adiacenti finiscono a terra per 2...3 secondi (50% di probabilità di fallimento con Lancio Rapido di grado 4 o inferiore).','Magia d\'Élite. Interrompe un\'azione. Effetto dell\'interruzione: se l\'azione è un\'abilità, l\'obiettivo nemico e tutti i nemici adiacenti finiscono a terra per 2...3 secondi. 50% di probabilità di fallimento con Lancio Rapido inferiore al grado 5.'],
3186=>['Fardello Condiviso (PvP)','Fattura d\'Élite. Per 5...20 secondo/i, il nemico bersaglio e tutti i nemici nell\'area attaccano, scagliano incantesimi e si muovono del 33% più lentamente.','Fattura d\'Élite. Maledice anche i nemici nell\'area del tuo bersaglio (5...20 secondo/i). Questi nemici attaccano, scagliano incantesimi e si muovono del 33% più lentamente.'],
3187=>['Velocità sottratta (PvP)','Fattura d\'Élite. Per 1...10 secondi il tempo di lancio delle magie dell\'obiettivo nemico e di tutti i nemici adiacenti aumenta di un 100%. Il tempo di lancio delle tue magie contro tali nemici si riduce di un 50%.','Fattura d\'Élite. Colpisce con una fattura anche i nemici adiacenti (1...10 secondi). Raddoppia il tempo di lancio delle magie. Riduzione del tempo di lancio delle tue magie contro i nemici colpiti da fattura: 50%.'],
3188=>['Sigillo Innaturale (PvP)','Sigillo. L\'obiettivo nemico subisce 10...60 danni. Se è sotto gli effetti di una Fattura o di un Incantesimo, i nemici adiacenti subiscono 10...60 danni. Tutte le tue abilità non appartenenti alla classe dell\'Ipnotizzatore (ad eccezione dei Sigilli) vengono disattivate per 10 secondi.','Sigillo. Danni inferti: 10...60. Danni inferti ai nemici adiacenti se l\'obiettivo è sotto gli effetti di una Fattura o di un Incantesimo: 10...60. Tutte le tue abilità non appartenenti alla classe dell\'Ipnotizzatore (ad eccezione dei Sigilli) vengono disattivate (10 secondi).'],
3189=>['Dolore Spirituale (PvP)','Magia. L\'obiettivo nemico subisce 5...40 danni. Tutte le creature ostili evocate nell\'area del nemico subiscono 25...125 danni.','Magia. Danni inferti: 5...40. Danni inferti alle creature ostili invocate nell\'area dell\'obiettivo nemico: 25...125.'],
3190=>['Frustrazione (PvP)','Fattura. Per 5...20 secondi la velocità di lancio delle magie dell\'obiettivo nemico si riduce di un 50% e il nemico subisce 5...50 danni ogni volta che viene interrotto.','Fattura. (Secondi: 5...20). Provoca un rallentamento di un 50% del tempo di lancio delle magie. L\'obiettivo nemico subisce 5...50 danni ogni volta che viene interrotto.'],
3191=>['Diffidenza (PvP)','Fattura. Per 6 secondo/i, la prima magia scagliata dal bersaglio su uno dei tuoi alleati manca, e infligge 10...60 a quel nemico e il 75% di quei danni a tutti i nemici vicini.','Fattura. (6 secondo/i). La prima magia scagliata dal bersaglio su uno dei tuoi alleati non va a segno, infliggendo 10...60 a quel nemico e il 75% di quei danni a tutti i nemici vicini.'],
3192=>['Enigma dell\'Incantatore (PvP)','Fattura d\'Élite. Per 10 secondo/i, il bersaglio lancia incantesimi il 100...200% più lentamente. Se il bersaglio non è sotto l\'effetto di un incantesimo quando viene colpito dalla fattura, subisce 10...100 danni e tutti i nemici adiacenti subiscono il 75% di quei danni.','Fattura d\'Élite. Lancio degli incantesimi 100...200% più lento (10 secondo/i). Effetto iniziale: se il bersaglio non è influenzato da incantesimi, subisce 10...100 danni, e i nemici adiacenti subiscono il 75% di quei danni.'],
3193=>['Sigillo della Goffaggine (PvP)','Sigillo. Se l\'obiettivo nemico sta attaccando, questi e tutti i nemici nei dintorni vengono interrotti e subiscono 15...60 danni. Tutti i nemici che stanno utilizzando abilità d\'attacco finiscono a terra.','Sigillo. Interrompe un attacco dell\'obiettivo nemico e di tutti i nemici adiacenti. Effetto dell\'interruzione: infligge 15...60 danni e fa finire a terra i nemici che hanno attivato abilità d\'attacco.'],
3194=>['Specchio del Disincanto (PvP)','Magia. Rimuove un incantesimo dall\'obiettivo nemico. L\'incantesimo viene rimosso anche per tutti i compagni di squadra del nemico.','Magia. Rimuove un incantesimo dall\'obiettivo nemico. L\'incantesimo viene rimosso anche per i compagni di squadra del nemico.'],
3195=>['Occhio Vagante (PvP)','Fattura. Dura 4 secondi. La prossima volta che l\'obiettivo nemico sferra un attacco viene interrotto e tutti i nemici nei dintorni subiscono 10...92 danni.','Fattura. (Secondi: 4). Interrompe l\'attacco successivo dell\'obiettivo nemico. Effetto dell\'interruzione: 10...92 danni inflitti ai nemici nei dintorni.'],
3196=>['Rischio Calcolato (PvP)','Fattura. Per 3...12 secondi gli attacchi dell\'obiettivo nemico infliggono +10 danni, ma c\'è un 50% di probabilità che i danni assestati con ogni attacco si ripercuotano su di lui (max. 15...60 danni).','Fattura. L\'obiettivo nemico infligge +10 danni con gli attacchi (3...12 secondi). Per ogni attacco c\'è un 50% di probabilità che il danno (massimo 15...60) venga inflitto al nemico.'],
3204=>['Sfida al Dolore (PvP)','Posizione d\'Élite. Per 20 secondi ottieni 90...300 Punti Salute e 20 punti armatura in più.','Posizione d\'Élite. (Secondi: 20). Salute massima: +90...300. Armatura: +20.'],
3232=>['Cura Squadra (PvP)','Magia. Cura l\'intera squadra di 30...75 Punti Salute.','Magia. Cure per l\'intera squadra: 30...75.'],
3233=>['Deruba il Vincitore (PvP)','Fattura d\'Élite. Per 3...15 secondi, ogni volta che l\'obiettivo nemico attacca o lancia una magia su una creatura con meno Salute, perde 15...75 Punti Salute.','Fattura d\'Élite. (Secondi: 3...15). Punti Salute persi quando l\'obiettivo nemico attacca o lancia una magia su una creatura con meno Salute: 15...75.'],
3234=>['Visioni di Rimpianto (PvP)','Fattura d\'Élite. Per 10 secondi l\'obiettivo nemico e i nemici adiacenti subiscono 10...30 danni ogni volta che utilizzano un\'abilità e 5...40 danni aggiuntivi se non sono sotto l\'effetto di un\'altra fattura dell\'Ipnotizzatore.','Fattura d\'Élite. Colpisce con una fattura anche i nemici adiacenti all\'obiettivo (secondi: 10). Danni subiti da tali nemici: 10...30 ogni volta che utilizzano un\'abilità, più 5...40 di danni se non sono sotto l\'effetto di un\'altra fattura dell\'Ipnotizzatore.'],
3251=>['Denti di Volpe (PvP)','Attacco con Arma Secondaria. Deve seguire un attacco con arma primaria. I Denti di Volpe non possono essere bloccati e, se vanno a segno, infliggono +10...25 danni.','Attacco con Arma Secondaria. Danni inferti: +10...25. Non bloccabile. Deve seguire un attacco con arma primaria.'],
3252=>['Colpo Selvaggio (PvP)','Attacco con Arma Secondaria. Deve seguire un attacco con arma primaria. Se va a segno, infligge +10...35 di danni e rimuove qualsiasi posizione utilizzata dall\'obiettivo nemico. Questo attacco non può essere bloccato.','Attacco con Arma Secondaria. Danni inferti: +10...35. Rimuove la posizione dell\'obiettivo nemico. Non bloccabile. Deve seguire un attacco con arma primaria.'],
3263=>['Colpo Esorcizzante (PvP)','Attacco Ravvicinato. Se questo attacco va a segno, infligge 10...60 danni sacri. Infligge danno doppio alle creature evocate.','Attacco Ravvicinato. Danni sacri inferti: 10...60. Infligge danno doppio alle creature evocate.'],
3264=>['Falciata della Luna Gemella (PvP)','Attacco Ravvicinato. Perdi 1 Incantesimo del Derviscio e ottieni 10...20 Punti Salute. Se un incantesimo è stato perso in questo modo, non puoi essere bloccato[f:"bloccata"], colpisci due volte (ogni colpo infligge il 25% di danni in meno del normale), e ottieni +10...30 Punti Salute.','Attacco Ravvicinato. Incantesimi del Derviscio rimossi: 1. Punti Salute ottenuti: 10...20. Effetto della rimozione: non bloccabile, attacco doppio, ogni colpo infligge il 25% di danni in meno e +10...30 Punti Salute.'],
3265=>['Falciata Irresistibile (PvP)','Attacco con Falce. Infliggi +3...15 danno e perdi 1 Incantesimo del Derviscio. Se un incantesimo viene perso in questo modo, la Falciata Irresistibile non può essere bloccata e rimuove una posizione.','Attacco con Falce. Danni inferti: +3...15. Incantesimi del Derviscio rimossi: 1. Effetto della rimozione: non bloccabile, rimuove una posizione.'],
3266=>['Assalto Pio (PvP)','Attacco Ravvicinato. Rimuovi 1 Incantesimo del Derviscio. Se un Incantesimo del Derviscio è stato rimosso, questa abilità si ricarica più velocemente di un 75% e tutti i nemici adiacenti subiscono 15...40 danni.','Attacco Ravvicinato. Rimuove uno dei tuoi Incantesimi del Derviscio. Effetto della rimozione: l\'abilità si ricarica più velocemente di un 75% e tutti i nemici adiacenti subiscono 15...40 danni.'],
3269=>['Mani Guidate (PvP)','Incantesimo. Per 20 secondi sarà impossibile bloccare 0...3 dei tuoi prossimi attacchi. Quando attiva, questa abilità rimuove Accecamento.','Incantesimo. (Secondi: 20). 0...3 dei tuoi prossimi attacchi non possono essere bloccati. Effetto iniziale: rimuove Accecamento.'],
3270=>['Apparizione di Dwayna (PvP)','Forma d\'Élite. Per 10...90 secondi i tuoi attacchi infliggono danni sacri. Quando utilizzi un\'abilità d\'attacco del Derviscio perdi 1 fattura. Quando perdi un Incantesimo del Derviscio, vieni curato[f:"curata"] di 5...50 Punti Salute. Questa abilità verrà disabilitata per 45 secondi.','Forma d\'Élite. (Secondi: 10...90.) Infliggi danni sacri. Fatture perse utilizzando un\'abilità d\'attacco del Derviscio: 1. Curi te stesso[f:"stessa"] di 5...50 Punti Salute quando perdi un Incantesimo del Derviscio. Questa abilità verrà disabilitata per 45 secondi.'],
3271=>['Apparizione di Melandru (PvP)','Forma d\'Élite. Per 10...90 secondi, ottieni +100 Punti Salute, +30 armatura contro gli attacchi elementali e i tuoi attacchi infliggono danni da terra. Quando perdi un Incantesimo del Derviscio perdi 2 condizioni. L\'abilità viene disattivata per 45 secondi.','Forma d\'Élite. (Secondi: 10...90). Hai +100 Salute massima, +30 armatura contro gli attacchi elementali e i tuoi attacchi infliggono danni da terra. Curi te stesso[f:"stessa"] da 2 condizioni quando perdi un Incantesimo del Derviscio. L\'abilità viene disattivata per 45 secondi.'],
3272=>['Cura Mistica (PvP)','Magia. Vieni curata di 5...65 Punti Salute. Cura anche tutti i membri della squadra sotto incantesimo di 5...65 Punti Salute.','Magia. Ti cura di 5...65 Punti Salute. Punti Salute curati per tutti i membri della squadra sotto incantesimo: 5...65.'],
3273=>['Sigillo del Ritegno Pio (PvP)','Sigillo. Perdi 1 Incantesimo del Derviscio e provochi Storpiatura all\'obiettivo nemico per 5...15 secondi. Se un incantesimo è stato rimosso, la tua abilità si ricarica più velocemente del 50%.','Sigillo. (Secondi: 5...15). Condizione inflitta all\'obiettivo nemico: Storpiatura e rimuove 1 dei tuoi Incantesimi del Derviscio. Effetto della rimozione: ricarica più veloce del 50%.'],
3289=>['Sogni Febbrili (PvP)','Fattura d\'Élite. Per 5...15 secondi, ogni volta che l\'obiettivo nemico subisce una nuova condizione, tutti i nemici nell\'area risentono della stessa condizione.','Fattura d\'Élite. (Secondi: 5...15.) Anche i nemici nell\'area soffrono di qualsiasi nuova condizione acquisita dall\'obiettivo nemico.'],
3346=>['Aura di Spine (PvP)','Incantesimo Lampo. Tutti i nemici nei dintorni soffrono di Emorragia per 5...15 secondi. Per 30 secondi, questo incantesimo non ha effetto. Al termine dell\'incantesimo, tutti i nemici nei dintorni diventano storpi per 3...8 secondi.','Incantesimo Lampo. (Secondi: 30.) Effetto iniziale: condizione inflitta: Emorragia (5...15 secondi) ai nemici nei dintorni. Effetto al termine: condizione inflitta: Storpiatura (3...8 secondi) ai nemici nei dintorni.'],
3347=>['Mantello della Polvere (PvP)','Incantesimo Lampo. Infligge 10...40 danni da terra a tutti i nemici nei dintorni. Per 30 secondi i tuoi attacchi infliggono danni da terra. Al termine dell\'incantesimo, tutti i nemici nei dintorni vengono accecati per 1...4 secondi.','Incantesimo Lampo. (Secondi: 30). I tuoi attacchi assestano danni da terra. Effetto iniziale: infligge 10...40 danni da terra ai nemici nei dintorni. Effetto al termine: Condizione inflitta: Accecamento (1...4 secondi) ai nemici dei dintorni.'],
3348=>['Fretta di Lyssa (PvP)','Incantesimo Lampo. Per 3...15 secondi i tuoi Incantesimi da Derviscio si ricaricano con una velocità incrementata di un 33%. Quando attivi questo incantesimo, tutti i nemici adiacenti verranno interrotti. Al termine dell\'incantesimo, tutti i nemici adiacenti verranno interrotti. 50% di probabilità di fallimento con Preghiere del Vento inferiore al grado 5.','Incantesimo Lampo. (Secondi: 3...15). Incremento velocità di ricarica degli Incantesimi da Derviscio: 33%. Effetto iniziale: interrompe tutti i nemici adiacenti. Effetto al termine: interrompe tutti i nemici adiacenti. 50% di probabilità di fallimento con Preghiere del Vento inferiore al grado 5.'],
3365=>['Assalto Furioso (PvP)','Incantesimo Lampo d\'Élite. Dura 2...8 secondi; la tua velocità d\'attacco e la tua dose di adrenalina aumentano di un 25%.','Incantesimo Lampo d\'Élite. (Secondi: 2...8.) Velocità d\'attacco e dose di adrenalina aumentano di un 25%.'],
3366=>['Cuore della Furia (PvP)','Posizione. Per 2...10 secondi la tua velocità d\'attacco aumenta di 25%.','Posizione. (Secondi: 2...10.) Incremento della tua velocità d\'attacco: 25%.'],
3367=>['Colpo Lacerante (PvP)','Attacco d\'Élite con Falce. Se l\'attacco va a segno, l\'obiettivo nemico soffre di Emorragia per 5...20 secondi e perdi 1 Incantesimo del Derviscio. Se un incantesimo viene rimosso, l\'obiettivo nemico è affetto inoltre da Ferita Profonda per 5...20 secondi.','Attacco d\'Élite con Falce. Condizione inflitta: Emorragia (5...20 secondi). Rimuove 1 Incantesimo del Derviscio. Effetto della rimozione: Condizione inflitta: Ferita Profonda (5...20 secondi).'],
3368=>['Furia Pia (PvP)','Posizione. Rimuove 1 Incantesimo del Derviscio. Per 1...5 secondi la tua velocità d\'attacco aumenta di 25%. Se un incantesimo è stato rimosso, questa posizione dura il doppio del tempo.','Posizione. (1...5 secondi). Attacchi più velocemente del 25% e rimuovi 1 dei tuoi Incantesimi del Derviscio. Effetto della rimozione: questa posizione dura il doppio del tempo.'],
3373=>['Illusione di Velocità (PvP)','Incantesimo. Per 5...11 secondi, la tua velocità aumenta del 33%. Quando gli effetti dell\'Illusione di Velocità svaniscono, diventi storpio per 3 secondi.','Incantesimo. (Secondi: 5...11.) Aumento della tua velocità di movimento: 33%. Effetto al termine: Storpiatura (3 secondi).'],
3374=>['Illusione del Dolore (PvP)','Fattura. Per 8 secondi, l\'obiettivo nemico subisce una Degenerazione Salute di -3...10 e subisce 3...10 danni al secondo. Quando l\'effetto di Illusione del Dolore svanisce o viene rinnovato, il nemico viene curato di 36...120 Punti Salute.','Fattura. (Secondi: 8.) Degenerazione Salute causata: -3...10. Danni al secondo subiti dall\'obiettivo nemico: 3...10. Effetto al termine: il nemico viene curato di 36...120 Punti Salute. Termina se si rinnova.'],
3375=>['Aura del Ripristino (PvP)','Incantesimo. Per 60 secondi, ottieni 0...1 Punti Energia. Ogni volta che usi una magia vieni curato di un 200...400% del suo costo energetico.','Incantesimo. (60 secondi.) Ottieni 0...1 Punti Energia. Ogni volta che usi una magia vieni curato di un 200...400% del suo costo energetico.'],
3386=>['Rete del Disturbo (PvP)','Fattura. Interrompi l\'obiettivo nemico. Per 10 secondi, l\'obiettivo nemico è sotto gli effetti della fattura Rete del Disturbo. Al termine della fattura, quel nemico viene interrotto di nuovo.','Fattura. (Secondi: 10.) Effetto iniziale: interrompe un\'abilità. Effetto al termine interrompe un\'abilità.'],
3396=>['Martello Fulminante (PvP)','Magia. L\'obiettivo nemico subisce 10...100 danni da fulmine. Il Martello Fulminante ha il 25% di penetrazione dell\'armatura.','Magia. Danni da fulmine inferti: 10...100. Penetrazione armatura: 25%.'],
3397=>['Fiamma Elementale (PvP)','Incantesimo. Per 5...20 secondi, ogni volta che una fattura Elementale termina sull\'obiettivo nemico, questi prende fuoco per 1...2 secondi.','Incantesimo. (Secondi: 5...20.) Condizione inflitta ogni volta che una fattura Elementale viene applicata all\'obiettivo nemico: Bruciatura (Secondi: 1...2).'],
3398=>['Terreno Sdrucciolevole (PvP)','Magia. Se l\'obiettivo nemico è affetto da Accecamento o si sta muovendo, viene abbattuto. (50% di probabilità di fallimento con Magia dell\'Acqua di grado 4 o inferiore.)','Magia. Provoca abbattimento se il nemico è affetto da Accecamento o si sta muovendo. 50% di probabilità di fallimento se il grado di Magia dell\'Acqua è inferiore a 5.'],
3422=>['Sfera temporale','Guardia d\'Élite. Crei una sfera temporale nel luogo in cui ti trovi. Per 6...20 sec. gli alleati non-spiriti in quest\'area lanciano incantesimi più velocemente (15...20%) e ricaricano le abilità più in fretta (15...20%). Abilità PvE','Guardia d\'Élite. (6...20 sec.) Gli alleati in quest\'area lanciano incantesimi (+15...20%) e ricaricano abilità (+15...20%) più in fretta. Non riguarda gli spiriti alleati. Abilità PvE'],
3423=>['Strappa anime','Incantesimo d\'Élite. Per 3...30 sec., i tuoi attacchi costano 15...20 di salute e causano 15...20 di danno in più. Abilità PvE','Incantesimo d\'Élite. (3...30 sec.) Gli attacchi causano +15...20 di danno e costano 15...20 di salute. Abilità PvE'],
3424=>['Oltre il limite','Incantesimo d\'Élite. Quando sei sotto l\'effetto di questo sortilegio, i tuoi incantesimi sono più veloci (20...50%) e si ricaricano più in fretta (40...80%), ma accumuli costantemente Turbamento. Abilità PvE','Incantesimo d\'Élite. Lancia incantesimi (+20...50%) e ricarica (+40...80%) più in fretta. Accumulo costante di Turbamento mentre è attivo. Abilità PvE'],
3425=>['Colpo del giudizio','Attacco d\'Élite Ravvicinato. Colpisce il bersaglio e i nemici adiacenti. Ogni attacco a segno causa +13...30 di Danno sacro e respinge i nemici all\'attacco. Abilità PvE','Attacco d\'Élite Ravvicinato. Colpisce il bersaglio e nemici adiacenti e infligge +13...30 di Danno sacro. Respinge i nemici all\'attacco. Abilità PvE'],
3426=>['Mossa delle sette armi','Posizione d\'Élite. Per 3...20 sec., gli attributi delle tue armi sono aumentati di 1...15 e i tuoi attacchi sono più veloci (33 %). Abilità PvE','Posizione d\'Élite. (3...20 sec.) Attributi armi aumentati di 1...15. Attacchi più veloci (33 %). Abilità PvE'],
3427=>['"Tutti per uno!"','Urlo d\'Élite. Per 3...15 sec., tutti i membri del gruppo vicini a te o alle tue creature sferrano attacchi che infliggono +5...15 di danno aggiuntivo e ottengono +1...7 di rigenerazione salute. Abilità PvE','Urlo d\'Élite. (3...15 secondi.) Membri del gruppo vicini a te o alle tue creature infliggono +5...15 di danno e ottengono +1...7 di rigenerazione salute. Abilità PvE'],
3428=>['Ladro d\'ombre','Abilità d\'Élite. Effettua un Passo dell\'ombra verso un nemico. Per 5...20 sec. gli attributi del nemico sono ridotti di 1...5 e i tuoi attributi aumentati di 1...5. Questa abilità conta come un Attacco principale. Abilità PvE','Abilità d\'Élite. Effettua un Passo dell\'ombra verso un nemico. Per 5...20 sec., riduce gli attributi del nemico di 1...5 e aumenta i tuoi di 1...5. Conta come un Attacco principale. Abilità PvE'],
3429=>['Armi delle tre forge','Magia d\'Élite Altera-arma. Per 3...20 sec., ogni non-spirito alleato a portata d\'orecchio ottiene gli effetti di un Incantesimo d\'arma casuale. Abilità PvE','Magia d\'Élite Altera-arma. (3...20 sec.) Gli alleati a portata d\'orecchio ottengono effetti di un Incantesimo d\'arma casuale. Non riguarda gli spiriti alleati. Abilità PvE'],
3430=>['Voto di rivoluzione','Incantesimo d\'Élite. Aumenta per 3...10 sec. la rigenerazione energia di +1...6. Quest\'abilità si rinnova ogni volta che usi un\'abilità non-derviscia. Abilità PvE','Incantesimo d\'Élite. (3...10 sec.) Ottieni +1...6 rigenerazione energia. Rinnovo: a ogni uso di un\'abilità non-derviscia. Abilità PvE'],
3431=>['Motivo eroico','Eco d\'Élite. Per 3...15 sec., tutti gli attributi dell\'alleato non-spirito bersaglio aumentano di +1...3. Questa eco si rinnova ogni volta che un canto o grido raggiunge l\'alleato. Abilità PvE','Eco d\'Élite. (3...15 sec.) +1...3 a tutti gli attributi dell\'alleato bersaglio. Rinnovo: ogni volta che un canto o grido raggiunge l\'alleato. Non riguarda gli spiriti. Abilità PvE'],
3437=>['Falce del contadino (PvP)','Attacco con Falce. Se questo attacco va a segno provochi +5...35 danno[i]. Se colpisci più di un nemico questo attacco si ricarica all\'istante.','Attacco con Falce. Danni inferti: +5...35. Si ricarica all\'istante se colpisci più di un nemico.'],
3442=>['Lancio Potente (PvP)','Attacco con Lancia. La velocità della tua lancia viene triplicata. Se va a segno infliggi +10...40 danno[i].','Attacco con Lancia. Danni inferti: +10...40. La velocità di movimento di questa lancia si triplica.'],
3443=>['Frenesia','Posizione. Per 8 secondi i tuoi attacchi sono più veloci del 33%, ma subisci il 200...150% dei danni.','Posizione. (8 secondi) I tuoi attacchi sono più veloci del 33%. Subisci il 200...150% dei danni.'],
3444=>['Cento Lame','Abilità d\'Élite. Per 15 second[i], ogni volta che attacchi con una spada, tutti i nemici adiacenti subiscono 10...30 danno[i] da taglio.','Abilità d\'Élite. (Secondo[i]: 15) Danni da taglio inferti a tutti i nemici adiacenti: 10...30 ogni volta che attacchi con una spada.'],
3445=>['Rinnovamento della Natura','Rituale della Natura. Create a level 1...10 spirit. For 30...240 seconds, enchantments and hexes cast by non-spirit creatures take 50...75% longer to cast, and it costs twice as much Energy to maintain enchantments. This spirit dies after 30...240 seconds.','Rituale della Natura. Creates a level 1...10 spirit (30...240 second lifespan). For creatures in range, enchantments and Hexes take 50...75% longer to cast and it costs twice as much Energy to maintain enchantments. Does not affect spirits.'],
3446=>['Soul Ignition','Incantesimo. While you maintain this enchantment, reduce Overcast at a rate of 1...2 per second. You and all adjacent foes are afflicted with burning while this enchantment is active.','Incantesimo. Reduce Overcast by 1...2 per second. You and all adjacent foes are afflicted with burning.'],
3447=>['Preoccupazione del Fannullone','Fattura. Dopo 3 secondi il bersaglio nemico subisce 20...100 danni e tutti i nemici adiacenti subiscono il 75% di quei danni. Se il bersaglio riesce a utilizzare un\'abilità, Wastrel\'s Worry termina prematuramente e non infligge danni.','Fattura. (3 secondi) Fine dell\'effetto: provoca 20...100 danni al bersaglio e il 75% di quei danni ai nemici adiacenti. Nessun effetto; termina prima se il bersaglio usa un\'abilità.'],
3448=>['Pace e Armonia','Incantesimo d\'Élite. L\'obiettivo (un alleato o te stesso) perde 0...4 condizione[i] e fattura[e]. Per 1...3 secondo[i], le condizioni e le fatture su quell\'alleato si esauriscono con velocità superiore del 90%. Tutte le tue Preghiere Punitive vengono disattivate per 20 secondi.','Incantesimo d\'Élite. L\'obiettivo (un alleato o te stesso) perde 0...4 condizione[i] e fattura[e]. Incremento velocità di esaurimento condizioni e fatture su quell\'alleato: 90% (1...3 secondo[i]). Disattiva le tue Preghiere Punitive (20 secondi).'],
3449=>['Colpo del Protettore','Attacco Ravvicinato. Se questo attacco colpisce un nemico in movimento, infliggi 10...40 danno[i] in più.','Attacco Ravvicinato. Danni aggiuntivi se il nemico si sta muovendo: +10...40.'],
3450=>['Tiro Azzoppante','Attacco con Arco d\'Élite. Se Tiro Azzoppante va a segno, l\'obiettivo diventa Storpio per 4...14 secondo[i]. Questo attacco non può essere bloccato.','Attacco con Arco d\'Élite. Non bloccabile. Condizione inflitta: Storpiatura (4...14 secondo[i]).'],
3451=>['Urlo di Otyugh','Urlo. Per 5...15 secondo[i], la tua mascotte ottiene +24 di armatura e non può essere bloccata.','Urlo. (Secondi: 5...15) La tua mascotte ha +24 di armatura e non può essere bloccata.'],
3452=>['Coltre Ombrosa','Fattura d\'Élite. Per 2...7 secondo[i], l\'obiettivo nemico non può essere colpito da alcun incantesimo.','Fattura d\'Élite. (Secondi: 2...7) L\'obiettivo nemico non può ricevere incantesimi.'],
3453=>['Slancio','Posizione. Per 3 secondo/i corri più veloce del 50%. Ogni 2 punti in Arti delle Ombre riduce la ricarica di 1 secondo/i (max 6 secondi).','Posizione. (3 secondo/i) Ti muovi più veloce del 50%. Ogni 2 punti in Arti delle Ombre riduce la ricarica di 1 secondo/i (max 6 secondi).'],
3454=>['Guardiano Scudo','Incantesimo. Per 1...4 secondi, tutti i membri della squadra a portata d\'orecchio hanno un 75% di probabilità di bloccare gli attacchi. Quando un attacco viene bloccato, tutti gli alleati a portata d\'orecchio vengono curati di 10...35 punti e il Guardiano Scudo termina.','Incantesimo. (Secondi: 1...4.) I membri della squadra a portata d\'orecchio hanno un 75% di probabilità di bloccare gli attacchi. Effetto del blocco: gli alleati a portata d\'orecchio vengono curati di 10...35 punti e il Guardiano Scudo termina.'],
3455=>['Colpo Propizio','Attacco con Martello. Se Colpo Propizio va a segno, infliggi +5...20 danno[i] e ottieni 2...4 Punto[i] Energia. Se il nemico è affetto da Debolezza, questo attacco non è bloccabile.','Attacco con Martello. Danni inferti: +5...20. Ottieni 2...4 Punto[i] Energia. Non bloccabile se l\'obiettivo nemico è affetto da Debolezza.'],
3456=>['"Vigliacco!"','Urlo d\'Élite. Se l\'obiettivo nemico si sta muovendo viene abbattuto.','Urlo d\'Élite. Provoca abbattimento se l\'obiettivo nemico si sta muovendo.'],
3457=>['Difesa del Protettore','Abilità. Per 4...8 secondo[i], gli alleati adiacenti a te hanno una probabilità del 75% di bloccare gli attacchi. La Difesa del Protettore termina se ti sposti.','Abilità. (Secondi: 4...8) Probabilità di blocco degli alleati adiacenti a te: 75%. Termina se ti muovi.'],
3458=>['Ira Primordiale','Posizione d\'Élite. Per 1...9 secondo/i attacchi più veloci del 33%, movimento del 33, ma subisci il 200...150% dei danni.','Posizione d\'Élite. (1...9 secondo/i) Attacchi più veloci del 33%, movimento del 33. Subisci il 200...150% dei danni.'],
3459=>['Tiro di Melandru','Attacco con Arco d\'Élite. Se il Tiro di Melandru va a segno, l\'obiettivo inizia a sanguinare per 5...25 secondi. Se colpisce un nemico in movimento o abbattuto, tale nemico subisce 10...25 danni e soffre di Storpiatura per 5...15 secondi.','Attacco con Arco d\'Élite. Condizione inflitta: Emorragia (5...25 secondi). Per obiettivi nemici in movimento o abbattuti: Danni inferti: +10...25. Condizione inflitta: Storpiatura (5...15 secondi).'],
3460=>['Tranquillità','Rituale della Natura. Crei uno Spirito di livello 1...10. Gli incantesimi lanciati dalle creature nella sua portata (Spiriti esclusi) si esauriscono un 10...30% più velocemente. Lo Spirito si esaurisce dopo 15...120 secondo[i].','Rituale della Natura. Crei uno Spirito di livello 1...10 (in vita per 15...120 secondo[i]). Riduzione durata degli incantesimi sulle creature nella portata: 10...30%. Non ha effetto sugli Spiriti.'],
3461=>['Distorsione dell\'Anima','Abilità d\'Élite. Per 5...45 secondo/i i tuoi Rituali incatenanti costano 15 punti Energia in meno (minimo 5) e la ricarica si riduce del 25...50%. Distorsione dell\'Anima termina dopo 1...3 Rituale/i incatenante/i.','Abilità d\'Élite. (5...45 secondo/i) I Rituali incatenanti costano 15 punti Energia in meno (minimo 5) e la ricarica si riduce del 25...50%. Termina dopo 1...3 Rituale/i incatenante/i.'],
3462=>['Arma Guidata','Magia Altera-arma. Per 4...10 secondo[i], gli attacchi dell\'obiettivo (un alleato o te stesso) non possono essere bloccati.','Magia Altera-arma. (Secondi: 4...10) Gli attacchi non sono bloccabili.'],
3463=>['Burla','Magia d\'Élite. Se l\'obiettivo nemico ha attivato un\'abilità, lui e gli altri nemici nell\'area vengono interrotti e tu sottrai 0...5 Punti Energia a tutti i nemici nell\'area.','Magia d\'Élite. Interrompe un\'abilità. Effetto dell\'interruzione: interrompe anche gli altri nemici nell\'area e tu sottrai 0...5 Punti Energia a tutti i nemici nell\'area.'],
3464=>['Flagellazione','Posizione. Per 1...15 secondo/i attacchi più veloci del 33% ma movimento più lento del 33%. Termina quando usi un\'abilità di attacco a distanza.','Posizione. (1...15 secondo/i) Attacchi più veloci del 33%. Termina quando usi un\'abilità di attacco a distanza. Movimento più lento del 33%.'],
3465=>['Colpo con Carica','Posizione d\'Élite. Per 1...10 secondo[i], la tua velocità di corsa aumenta di un 33%; il tuo prossimo colpo ravvicinato messo a segno infligge +10...80 danno[i] e la posizione termina. Questa posizione termina se utilizzi un\'abilità.','Posizione d\'Élite. (Secondi: 1...10) Incremento velocità di movimento: 33%. Danni inferti dal tuo prossimo attacco ravvicinato: +10...80. Termina se colpisci o usi un\'abilità.'],
3466=>['Calore Infuriante','Rituale della Natura d\'Élite. Create a level 1...10 spirit. Non-spirit creatures within its range gain adrenaline 33...66% as fast. This spirit dies after 30...120 seconds.','Rituale della Natura d\'Élite. Creates a level 1...10 spirit (30...120 second lifespan). Adrenaline gain increased by 33...66% for creatures in range.'],
3467=>['Corruzione Mistica','Incantesimo Lampo. Tutti i nemici adiacenti vengono colpiti da Malattia per 2...6 secondi. Per 20 secondi non si verificano effetti. La durata della Malattia è raddoppiata se sei sotto incantesimo quando attivi questa abilità. Al termine dell\'incantesimo, tutti i membri della squadra a portata d\'orecchio sono curati da Malattia.','Incantesimo Lampo. (Secondi: 20). Effetto iniziale: tutti i nemici adiacenti vengono colpiti da Malattia (2...6 secondi). La durata è doppia se sei già sotto incantesimo. Effetto al termine: i membri della squadra a portata d\'orecchio sono curati da Malattia.'],
3468=>['Stretta del Predatore','Incantesimo Lampo. Per 5...20 secondo/i gli attacchi in mischia contro i nemici in movimento li azzoppano per 2...9 secondo/i. Quando lanci questo incantesimo, perdi la condizione di Azzoppato e 1 altra condizione. Questo incantesimo termina quando infliggi Azzoppato 1...3 volte.','Incantesimo Lampo. (5...20 secondo/i) Gli attacchi in mischia contro i nemici in movimento li azzoppano. Effetto iniziale: perdi la condizione di Azzoppato e 1 altra condizione. Termina infliggendo Azzoppato 1...3 volte.'],
3469=>['Mantello del Miraggio','Incantesimo Lampo. Per 1...7 secondi hai un 30...60% di probabilità di bloccare gli attacchi in arrivo. Quando lanci questo incantesimo, tutti i nemici nei dintorni subiscono 10...40 danni da terra.','Incantesimo Lampo. (Secondi: 1...7). Probabilità di blocco: 30...60%. Effetto iniziale: danni da terra ai nemici nei dintorni: 10...40.'],
3470=>['Stabilità Effimera','Incantesimo Lampo. Per 2...8 secondi, la tua velocità di attacco aumenta di un 25% e non puoi finire a terra. L\'incantesimo finisce prematuramente se impedisce un abbattimento.','Incantesimo Lampo. (Secondi: 2...8). Aumento velocità di attacco: 25% e non puoi finire a terra. Termina se viene impedito un abbattimento.'],
3471=>['Ripristino Pio','Magia. Ottieni 80...150 Punti Salute e perdi 1 Incantesimo del Derviscio. Fatture perse se un incantesimo è stato rimosso in questo modo: 1.','Magia. Ottieni 80...150 Punti Salute e perdi 1 Incantesimo del Derviscio. Effetto della rimozione: perdi 1 fatture.'],
3472=>['Carica Vorticosa','Incantesimo Lampo. Per 1...6 secondi, la tua velocità di movimento aumenta di un 33%. La prossima volta che colpisci un nemico, tutti i nemici nei dintorni subiscono 10...50 danni da freddo e questo incantesimo termina.','Incantesimo Lampo. (Secondi: 1...6). Aumento della tua velocità di movimento: 33%. Danni da freddo inferti a tutti i nemici nei dintorni la prossima volta che colpisci un nemico: 10...50 e l\'incantesimo termina.'],
3473=>['Affetta Aura','Attacco Ravvicinato. Se questo attacco va a segno, infliggi Emorragia per 5...15 secondi. Se sei sotto incantesimo, infliggi inoltre Armatura Incrinata per 1...10 secondi.','Attacco Ravvicinato. Condizione inflitta: Emorragia (5...15 secondi). Infligge inoltre Armatura Incrinata (1...10 secondi) se sei sotto incantesimo.'],
];}
